const DIAMOND_ITEM_COST = 5;

const DIAMOND_REFERRAL_SIGNUP_REWARD = 10;

const DIAMOND_REFERRAL_PLUS_SIGNUP_REWARD = 12;

const DIAMOND_DAILY_REWARD = 1;

const REFERRAL_ALPHABET = 'abcdefghjkmnpqrstuvwxyz23456789';

let decorationCatalogCache = { expiresAt: 0, items: [], r2Configured: false };

const DECORATION_R2_PREFIX = 'decorations/';

function normalizeReferralCode(value) {
    const code = String(value || '').trim().toLowerCase();
    return /^[a-z0-9_-]{4,24}$/.test(code) ? code : '';
}

function randomReferralCode(length = 8) {
    const bytes = crypto.getRandomValues(new Uint8Array(length));
    return [...bytes].map(value => REFERRAL_ALPHABET[value % REFERRAL_ALPHABET.length]).join('');
}

function diamondDayKey(now = Date.now()) {
    return new Date(now).toISOString().slice(0, 10);
}

function nextDiamondClaimAt(now = Date.now()) {
    const d = new Date(now);
    return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate() + 1);
}

function cleanDecorationFile(value) {
    const file = String(value || '').trim();
    if (!file || file.includes('/') || file.includes('\\') || !/^[^\u0000-\u001f]+\.png$/i.test(file))
        return '';
    return file.slice(0, 120);
}

function decorationNameFromFile(file) {
    return String(file || '').replace(/\.png$/i, '').replace(/[_-]+/g, ' ').replace(/\s+/g, ' ').trim();
}

function frontendOrigin(env) {
    const raw = String(env.FRONTEND_ORIGIN || 'https://orbytechat.pages.dev').trim();
    try {
        return new URL(raw).origin;
    }
    catch {
        return 'https://orbytechat.pages.dev';
    }
}

function apiOriginFromUrl(url, env) {
    if (url?.origin)
        return url.origin;
    const configured = String(env.API_PUBLIC_ORIGIN || '').trim();
    try {
        return configured ? new URL(configured).origin : '';
    }
    catch {
        return '';
    }
}

async function listDecorationFilesFromR2(env) {
    if (!env.DECORATIONS || typeof env.DECORATIONS.list !== 'function')
        return [];
    const files = [];
    let cursor;
    do {
        const page = await env.DECORATIONS.list({
            prefix: DECORATION_R2_PREFIX,
            cursor,
            limit: 1000,
        });
        for (const object of page.objects || []) {
            const key = String(object.key || '');
            const file = cleanDecorationFile(key.slice(DECORATION_R2_PREFIX.length));
            if (file && key === `${DECORATION_R2_PREFIX}${file}`)
                files.push(file);
        }
        cursor = page.truncated ? page.cursor : undefined;
    } while (cursor);
    return [...new Set(files)].sort((a, b) => a.localeCompare(b));
}

async function getDecorationCatalog(env, force = false, apiOrigin = '') {
    const r2Configured = Boolean(env.DECORATIONS && typeof env.DECORATIONS.list === 'function');
    if (!force && decorationCatalogCache.expiresAt > Date.now() && decorationCatalogCache.r2Configured === r2Configured) {
        return decorationCatalogCache.items;
    }
    let files = [];
    if (r2Configured) {
        try {
            files = await listDecorationFilesFromR2(env);
        }
        catch (error) {
            console.warn('Could not list R2 avatar decorations', error);
        }
    }
    const base = String(apiOrigin || env.API_PUBLIC_ORIGIN || '').replace(/\/+$/, '');
    const items = files.map(file => ({
        type: 'decoration',
        id: file,
        name: decorationNameFromFile(file),
        price: DIAMOND_ITEM_COST,
        image_url: `${base}/api/decorations/file/${encodeURIComponent(file)}`,
    }));
    items.unshift({
        type: 'badge',
        id: 'diamonds',
        name: 'Diamonds',
        price: DIAMOND_ITEM_COST,
        image_url: `${frontendOrigin(env)}/assets/badges/diamonds.png`,
    });
    decorationCatalogCache = {
        expiresAt: Date.now() + 5 * 60 * 1000,
        items,
        r2Configured,
    };
    return items;
}

async function serveDecorationFile(env, encodedFile) {
    if (!env.DECORATIONS || typeof env.DECORATIONS.get !== 'function') {
        return json({ error: 'Decoration R2 binding is not configured', code: 'DECORATIONS_R2_NOT_CONFIGURED' }, 503);
    }
    let decoded = '';
    try {
        decoded = decodeURIComponent(String(encodedFile || ''));
    }
    catch {
        return json({ error: 'Invalid decoration filename' }, 400);
    }
    const file = cleanDecorationFile(decoded);
    if (!file || file !== decoded)
        return json({ error: 'Decoration not found' }, 404);
    const object = await env.DECORATIONS.get(`${DECORATION_R2_PREFIX}${file}`);
    if (!object)
        return json({ error: 'Decoration not found' }, 404);
    const headers = new Headers();
    object.writeHttpMetadata?.(headers);
    headers.set('Content-Type', 'image/png');
    headers.delete('Content-Disposition');
    headers.set('Cache-Control', 'public, max-age=3600, stale-while-revalidate=86400');
    if (object.httpEtag)
        headers.set('ETag', object.httpEtag);
    headers.set('X-Content-Type-Options', 'nosniff');
    return new Response(object.body, { headers });
}

async function awardDiamonds(db, userId, amount, options = {}) {
    const value = Math.floor(Number(amount));
    if (!Number.isFinite(value) || value <= 0)
        throw new Error('INVALID_DIAMOND_AMOUNT');
    const target = await db.prepare('SELECT id,referred_by_user_id FROM users WHERE id=? LIMIT 1').bind(userId).first();
    if (!target)
        throw new Error('USER_NOT_FOUND');
    const now = Date.now();
    const statements = [
        db.prepare('UPDATE users SET diamonds=COALESCE(diamonds,0)+? WHERE id=?').bind(value, userId),
        db.prepare('INSERT INTO diamond_transactions(id,user_id,amount,kind,source_user_id,notes,created_at) VALUES(?,?,?,?,?,?,?)')
            .bind(prefixedId('dia'), userId, value, String(options.kind || 'reward'), options.sourceUserId || null, cleanText(options.notes || '', 500, true), now),
    ];
    let referralPayout = 0;
    if (options.commissionable !== false && target.referred_by_user_id && target.referred_by_user_id !== userId) {
        const inviter = await db.prepare('SELECT id,referral_commission_remainder FROM users WHERE id=? LIMIT 1').bind(target.referred_by_user_id).first();
        if (inviter) {
            const totalTenths = Math.max(0, Number(inviter.referral_commission_remainder || 0)) + value;
            referralPayout = Math.floor(totalTenths / 10);
            const remainder = totalTenths % 10;
            statements.push(db.prepare('UPDATE users SET referral_commission_remainder=?,diamonds=COALESCE(diamonds,0)+? WHERE id=?').bind(remainder, referralPayout, inviter.id));
            if (referralPayout > 0) {
                statements.push(db.prepare('INSERT INTO diamond_transactions(id,user_id,amount,kind,source_user_id,notes,created_at) VALUES(?,?,?,?,?,?,?)')
                    .bind(prefixedId('dia'), inviter.id, referralPayout, 'referral_commission', userId, '10% referral earnings', now));
            }
        }
    }
    await db.batch(statements);
    const balance = await db.prepare('SELECT diamonds FROM users WHERE id=?').bind(userId).first();
    return { amount: value, balance: Math.max(0, Number(balance?.diamonds || 0)), referral_payout: referralPayout };
}

async function generateUserReferralCode(env, user) {
    const current = await env.DB.prepare('SELECT referral_code FROM users WHERE id=?').bind(user.id).first();
    if (current?.referral_code)
        return json({ ok: true, code: current.referral_code, referral_url: `${frontendOrigin(env)}/?ref=${encodeURIComponent(current.referral_code)}` });
    for (let attempt = 0; attempt < 12; attempt++) {
        const code = randomReferralCode(8);
        try {
            await env.DB.prepare('UPDATE users SET referral_code=? WHERE id=? AND referral_code IS NULL').bind(code, user.id).run();
            const row = await env.DB.prepare('SELECT referral_code FROM users WHERE id=?').bind(user.id).first();
            if (row?.referral_code)
                return json({ ok: true, code: row.referral_code, referral_url: `${frontendOrigin(env)}/?ref=${encodeURIComponent(row.referral_code)}` });
        }
        catch (error) {
            if (!String(error?.message || error).toLowerCase().includes('unique'))
                throw error;
        }
    }
    return json({ error: 'Could not generate a referral code. Try again.' }, 503);
}

async function getDiamondOverview(env, user, url) {
    const row = await env.DB.prepare(`SELECT u.diamonds,u.referral_code,u.referral_commission_remainder,u.equipped_decoration,
      ref.username AS referrer_username,ref.discriminator AS referrer_discriminator,
      (SELECT COUNT(*) FROM users invited WHERE invited.referred_by_user_id=u.id) AS referral_count,
      (SELECT COALESCE(SUM(amount),0) FROM diamond_transactions dt WHERE dt.user_id=u.id AND dt.kind='referral_commission') AS referral_commission_earned,
      (SELECT claimed_at FROM daily_diamond_claims dc WHERE dc.user_id=u.id ORDER BY claimed_at DESC LIMIT 1) AS last_daily_claim
    FROM users u LEFT JOIN users ref ON ref.id=u.referred_by_user_id WHERE u.id=?`).bind(user.id).first();
    const ownedRows = await env.DB.prepare('SELECT item_type,item_id,purchased_at FROM user_shop_items WHERE user_id=? ORDER BY purchased_at').bind(user.id).all();
    const catalog = await getDecorationCatalog(env, url?.searchParams?.get('refresh') === '1', apiOriginFromUrl(url, env));
    const badges = new Set(parseBadgeList(user.badges));
    const owned = (ownedRows.results || []).map(item => ({ type: item.item_type, id: item.item_id, purchased_at: item.purchased_at }));
    if (badges.has('diamonds') && !owned.some(item => item.type === 'badge' && item.id === 'diamonds'))
        owned.push({ type: 'badge', id: 'diamonds', purchased_at: null });
    const todayClaim = await env.DB.prepare('SELECT claimed_at FROM daily_diamond_claims WHERE user_id=? AND claim_day=?').bind(user.id, diamondDayKey()).first();
    const plus = await getPlusStatus(env.DB, user.id);
    return json({
        balance: Math.max(0, Number(row?.diamonds || 0)),
        plus_week: { active: Boolean(plus.active), available: !plus.active, gift_available: true, cost: PLUS_DIAMOND_WEEK_COST, days: PLUS_DIAMOND_WEEK_DAYS, label: '7 days of Plus' },
        referral_code: row?.referral_code || '',
        referral_url: row?.referral_code ? `${frontendOrigin(env)}/?ref=${encodeURIComponent(row.referral_code)}` : '',
        referral_count: Number(row?.referral_count || 0),
        referral_commission_earned: Number(row?.referral_commission_earned || 0),
        referral_remainder_tenths: Number(row?.referral_commission_remainder || 0),
        referred_by: row?.referrer_username ? `${row.referrer_username}#${row.referrer_discriminator}` : null,
        daily_available: !todayClaim,
        next_daily_claim_at: todayClaim ? nextDiamondClaimAt() : Date.now(),
        equipped_decoration: row?.equipped_decoration || '',
        owned,
        catalog,
        decoration_source: 'r2',
        r2_configured: Boolean(env.DECORATIONS && typeof env.DECORATIONS.list === 'function'),
    });
}

async function claimDailyDiamond(env, user) {
    const now = Date.now(), day = diamondDayKey(now);
    const result = await env.DB.prepare('INSERT OR IGNORE INTO daily_diamond_claims(user_id,claim_day,claimed_at) VALUES(?,?,?)').bind(user.id, day, now).run();
    if (!Number(result?.meta?.changes || 0))
        return json({ error: 'You already claimed today’s free Diamond', code: 'DAILY_ALREADY_CLAIMED', next_claim_at: nextDiamondClaimAt(now) }, 409);
    try {
        const reward = await awardDiamonds(env.DB, user.id, DIAMOND_DAILY_REWARD, { kind: 'daily_claim', notes: 'Daily free Diamond', commissionable: true });
        return json({ ok: true, reward: DIAMOND_DAILY_REWARD, balance: reward.balance, next_claim_at: nextDiamondClaimAt(now) });
    }
    catch (error) {
        await env.DB.prepare('DELETE FROM daily_diamond_claims WHERE user_id=? AND claim_day=?').bind(user.id, day).run();
        throw error;
    }
}

async function purchaseDiamondItem(request, env, user) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const type = String(body.type || body.item_type || '');
    const id = type === 'decoration' ? cleanDecorationFile(body.id || body.item_id) : String(body.id || body.item_id || '');
    if (!['decoration', 'badge'].includes(type) || !id)
        return json({ error: 'Invalid shop item' }, 400);
    const catalog = await getDecorationCatalog(env, false, String(env.API_PUBLIC_ORIGIN || ''));
    const item = catalog.find(entry => entry.type === type && entry.id === id);
    if (!item)
        return json({ error: 'This item is not available in the shop' }, 404);
    const already = await env.DB.prepare('SELECT 1 FROM user_shop_items WHERE user_id=? AND item_type=? AND item_id=?').bind(user.id, type, id).first();
    if (already)
        return json({ error: 'You already own this item' }, 409);
    const current = await env.DB.prepare('SELECT diamonds,badges FROM users WHERE id=?').bind(user.id).first();
    if (Number(current?.diamonds || 0) < DIAMOND_ITEM_COST)
        return json({ error: `You need ${DIAMOND_ITEM_COST} Diamonds to buy this item`, code: 'NOT_ENOUGH_DIAMONDS' }, 409);
    const now = Date.now(), statements = [
        env.DB.prepare('UPDATE users SET diamonds=diamonds-? WHERE id=? AND diamonds>=?').bind(DIAMOND_ITEM_COST, user.id, DIAMOND_ITEM_COST),
        env.DB.prepare('INSERT INTO user_shop_items(user_id,item_type,item_id,purchased_at) VALUES(?,?,?,?)').bind(user.id, type, id, now),
        env.DB.prepare('INSERT INTO diamond_transactions(id,user_id,amount,kind,notes,created_at) VALUES(?,?,?,?,?,?)').bind(prefixedId('dia'), user.id, -DIAMOND_ITEM_COST, 'shop_purchase', `${type}:${id}`, now),
    ];
    let badges = parseBadgeList(current?.badges);
    if (type === 'badge' && id === 'diamonds') {
        badges = [...new Set([...badges, 'diamonds'])];
        statements.push(env.DB.prepare('UPDATE users SET badges=? WHERE id=?').bind(JSON.stringify(badges), user.id));
    }
    if (type === 'decoration')
        statements.push(env.DB.prepare('UPDATE users SET equipped_decoration=? WHERE id=?').bind(id, user.id));
    await env.DB.batch(statements);
    const updated = await env.DB.prepare('SELECT diamonds,equipped_decoration,badges FROM users WHERE id=?').bind(user.id).first();
    return json({ ok: true, item, balance: Number(updated?.diamonds || 0), equipped_decoration: updated?.equipped_decoration || '', badges: parseBadgeList(updated?.badges) });
}

async function giftDiamonds(request, env, user) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const username = cleanText(body.username || body.recipient_username || '', 32, true).trim().replace(/^@/, '');
    const amount = Math.floor(Number(body.amount || 0));
    const note = cleanText(body.note || '', 160, true).trim();
    if (!username)
        return json({ error: 'Enter a recipient username' }, 400);
    if (!Number.isFinite(amount) || amount < 1 || amount > 10000)
        return json({ error: 'Gift amount must be between 1 and 10,000 Diamonds' }, 400);
    const recipient = await env.DB.prepare(`SELECT id,username,discriminator,display_name,account_status,role FROM users WHERE lower(username)=lower(?) LIMIT 1`).bind(username).first();
    if (!recipient)
        return json({ error: 'No Orbyte user has that username' }, 404);
    if (String(recipient.id) === String(user.id))
        return json({ error: 'You cannot gift Diamonds to yourself' }, 400);
    if (String(recipient.id) === String(SYSTEM_USER_ID))
        return json({ error: 'The Orbyte system account cannot receive gifts' }, 403);
    if (/banned|suspended|disabled/i.test(String(recipient.account_status || '')))
        return json({ error: 'This account cannot receive Diamond gifts right now' }, 409);
    const sender = await env.DB.prepare('SELECT diamonds,username,display_name FROM users WHERE id=?').bind(user.id).first();
    if (Number(sender?.diamonds || 0) < amount)
        return json({ error: `You only have ${Math.max(0, Number(sender?.diamonds || 0))} Diamonds`, code: 'NOT_ENOUGH_DIAMONDS' }, 409);
    const now = Date.now(), giftId = prefixedId('gift');
    const debit = await env.DB.prepare('UPDATE users SET diamonds=diamonds-? WHERE id=? AND diamonds>=? RETURNING diamonds').bind(amount, user.id, amount).first();
    if (!debit)
        return json({ error: 'Your Diamond balance changed. Refresh and try again.', code: 'NOT_ENOUGH_DIAMONDS' }, 409);
    try {
        await env.DB.batch([
            env.DB.prepare('UPDATE users SET diamonds=COALESCE(diamonds,0)+? WHERE id=?').bind(amount, recipient.id),
            env.DB.prepare('INSERT INTO diamond_transactions(id,user_id,amount,kind,source_user_id,notes,created_at) VALUES(?,?,?,?,?,?,?)').bind(prefixedId('dia'), user.id, -amount, 'gift_sent', recipient.id, JSON.stringify({ gift_id: giftId, note }), now),
            env.DB.prepare('INSERT INTO diamond_transactions(id,user_id,amount,kind,source_user_id,notes,created_at) VALUES(?,?,?,?,?,?,?)').bind(prefixedId('dia'), recipient.id, amount, 'gift_received', user.id, JSON.stringify({ gift_id: giftId, note }), now)
        ]);
    }
    catch (error) {
        try {
            await env.DB.prepare('UPDATE users SET diamonds=COALESCE(diamonds,0)+? WHERE id=?').bind(amount, user.id).run();
        }
        catch { }
        throw error;
    }
    try {
        const senderName = String(sender?.display_name || sender?.username || 'Someone');
        await sendSystemDm(env.DB, recipient.id, { kind: 'diamonds_gift', color: '#f0b232', title: `${senderName} sent you ${amount} Diamond${amount === 1 ? '' : 's'}!`, description: note ? `Gift note: ${note}` : 'A Diamond gift was added to your Orbyte wallet.' });
    }
    catch (error) {
        console.warn('Could not send Diamond gift DM', error);
    }
    return json({ ok: true, amount, balance: Number(debit.diamonds || 0), recipient: { id: recipient.id, username: recipient.username, display_name: recipient.display_name || recipient.username } });
}

async function equipAvatarDecoration(request, env, user) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const id = body.id === null || body.id === '' ? null : cleanDecorationFile(body.id || body.item_id);
    if (id) {
        const owned = await env.DB.prepare("SELECT 1 FROM user_shop_items WHERE user_id=? AND item_type='decoration' AND item_id=?").bind(user.id, id).first();
        if (!owned)
            return json({ error: 'You do not own this decoration' }, 403);
        const catalog = await getDecorationCatalog(env);
        if (!catalog.some(item => item.type === 'decoration' && item.id === id))
            return json({ error: 'This decoration is no longer available' }, 404);
    }
    await env.DB.prepare('UPDATE users SET equipped_decoration=? WHERE id=?').bind(id, user.id).run();
    return json({ ok: true, equipped_decoration: id || '' });
}

async function adminGiveDiamonds(request, env, admin, targetUserId) {
    if (targetUserId === SYSTEM_USER_ID)
        return json({ error: 'The Orbyte system account cannot receive Diamonds' }, 403);
    const hierarchy = await guardAccountManagementTarget(env, admin, targetUserId, 'modify');
    if (hierarchy.error)
        return hierarchy.error;
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const amount = Math.floor(Number(body.amount || 0));
    const reason = cleanText(body.reason || '', 500, true).trim();
    if (!Number.isFinite(amount) || amount < 1 || amount > 100000)
        return json({ error: 'Amount must be between 1 and 100,000 Diamonds' }, 400);
    if (!reason)
        return json({ error: 'A reason is required' }, 400);
    const target = await env.DB.prepare('SELECT id,username,discriminator FROM users WHERE id=?').bind(targetUserId).first();
    if (!target)
        return json({ error: 'User not found' }, 404);
    const reward = await awardDiamonds(env.DB, targetUserId, amount, { kind: 'admin_grant', sourceUserId: admin.id, notes: reason, commissionable: true });
    const now = Date.now();
    await env.DB.prepare('INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at) VALUES(?,?,?,?,?,?)').bind(prefixedId('act'), admin.id, 'diamonds_grant', targetUserId, JSON.stringify({ amount, reason }), now).run();
    try {
        await sendSystemDm(env.DB, targetUserId, { kind: 'diamonds_grant', color: '#f0b232', title: `You received ${amount} Diamond${amount === 1 ? '' : 's'}!`, description: `Orbyte staff added ${amount} Diamond${amount === 1 ? '' : 's'} to your account.\n\nReason: ${reason}` });
    }
    catch (error) {
        console.warn('Could not send Diamond grant DM', error);
    }
    return json({ ok: true, amount, balance: reward.balance, referral_payout: reward.referral_payout });
}

function getWebPushClientConfig(env) {
    const values = {
        apiKey: String(env.FIREBASE_WEB_API_KEY || '').trim(),
        authDomain: String(env.FIREBASE_WEB_AUTH_DOMAIN || '').trim(),
        projectId: String(env.FCM_PROJECT_ID || env.FIREBASE_WEB_PROJECT_ID || '').trim(),
        storageBucket: String(env.FIREBASE_WEB_STORAGE_BUCKET || '').trim(),
        messagingSenderId: String(env.FCM_MESSAGING_SENDER_ID || '').trim(),
        appId: String(env.FIREBASE_WEB_APP_ID || '').trim(),
        vapidKey: String(env.FCM_WEB_VAPID_PUBLIC_KEY || '').trim()
    };
    const required = {
        FIREBASE_WEB_API_KEY: values.apiKey,
        FCM_PROJECT_ID: values.projectId,
        FCM_MESSAGING_SENDER_ID: values.messagingSenderId,
        FIREBASE_WEB_APP_ID: values.appId,
        FCM_WEB_VAPID_PUBLIC_KEY: values.vapidKey
    };
    const missing = Object.entries(required).filter(([, value]) => !value).map(([name]) => name);
    return json({ configured: missing.length === 0, missing, ...values }, 200, { 'Cache-Control': 'private, max-age=300' });
}

function pushConfig(env) { const projectId = String(env.FCM_PROJECT_ID || '').trim(), clientEmail = String(env.FCM_CLIENT_EMAIL || '').trim(), privateKey = String(env.FCM_PRIVATE_KEY || '').replace(/\\n/g, '\n').trim(); return { projectId, clientEmail, privateKey, configured: Boolean(projectId && clientEmail && privateKey) }; }

