async function createViolationAppeal(request, env, user, violationId) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const captchaError = await requireCaptcha(request, env, body.captcha_token, 'appeal');
    if (captchaError)
        return captchaError;
    const reason = cleanText(body?.reason || '', 1500, true);
    if (reason.length < 20)
        return json({ error: 'Please explain your appeal in at least 20 characters' }, 400);
    const violation = await env.DB.prepare(`
    SELECT id, user_id, status FROM violations WHERE id = ? AND user_id = ? LIMIT 1
  `).bind(violationId, user.id).first();
    if (!violation)
        return json({ error: 'Violation not found' }, 404);
    if (['overturned', 'reversed', 'expired'].includes(violation.status)) {
        return json({ error: 'This violation can no longer be appealed' }, 409);
    }
    const existing = await env.DB.prepare(`
    SELECT id, status FROM violation_appeals WHERE violation_id = ? LIMIT 1
  `).bind(violationId).first();
    if (existing)
        return json({ error: 'An appeal has already been submitted for this violation' }, 409);
    const now = Date.now();
    const id = prefixedId('apl');
    await env.DB.batch([
        env.DB.prepare(`
      INSERT INTO violation_appeals (
        id, violation_id, user_id, reason, status, resolution,
        reviewed_by, created_at, updated_at
      ) VALUES (?, ?, ?, ?, 'pending', '', NULL, ?, ?)
    `).bind(id, violationId, user.id, reason, now, now),
        env.DB.prepare(`UPDATE violations SET status = 'appealed' WHERE id = ?`).bind(violationId),
    ]);
    try {
        await sendSystemDm(env.DB, user.id, { kind: 'appeal_submitted', color: '#f0b232', dedupeKey: `appeal-submitted:${id}`, title: 'Thanks for submitting an appeal', description: 'We will review your appeal (typically within 48 hours) and update you on our decision.', actions: [{ label: 'safety hub', action: 'safety_hub' }] });
    }
    catch (error) {
        console.warn('Could not send appeal confirmation DM', error);
    }
    try {
        const violationInfo = await env.DB.prepare('SELECT violation_type FROM violations WHERE id = ? LIMIT 1').bind(violationId).first();
        await sendVerifiedAccountEmail(env, user.id, {
            type: 'appeal_status',
            status: 'pending',
            violation_type: violationInfo?.violation_type || 'Community Guidelines violation',
            resolution: 'Your appeal was submitted and is waiting for review.',
        });
    }
    catch (error) {
        console.warn('Could not send appeal submission email', error);
    }
    return json({ id, status: 'pending' }, 201);
}

async function adminListAppeals(env, url) {
    const status = url.searchParams.get('status') || 'pending';
    const allowed = ['pending', 'reviewing', 'accepted', 'rejected', 'all'];
    if (!allowed.includes(status))
        return json({ error: 'Invalid status' }, 400);
    const where = status === 'all' ? '' : 'WHERE a.status = ?';
    const stmt = env.DB.prepare(`
    SELECT a.id, a.violation_id, a.user_id, a.reason, a.status, a.resolution,
           a.reviewed_by, a.created_at, a.updated_at,
           v.violation_type, v.severity, CASE WHEN COALESCE(v.restriction_mask, 0) > 0 THEN 'account_limitation' ELSE v.action END AS action, v.reason AS violation_reason,
           v.report_id, v.status AS violation_status,
           u.username, u.discriminator, u.display_name
    FROM violation_appeals a
    JOIN violations v ON v.id = a.violation_id
    JOIN users u ON u.id = a.user_id
    ${where}
    ORDER BY CASE a.status WHEN 'pending' THEN 0 WHEN 'reviewing' THEN 1 ELSE 2 END,
             a.created_at ASC
    LIMIT 200
  `);
    const result = status === 'all' ? await stmt.all() : await stmt.bind(status).all();
    return json({ appeals: result.results || [] });
}

async function reconcileAcceptedAppealAccess(env, appeal, now = Date.now()) {
    const remainingRestriction = await env.DB.prepare(`
    SELECT action, COALESCE(restriction_until, expires_at) AS ends_at
    FROM violations
    WHERE user_id = ?
      AND status IN ('active', 'appealed')
      AND COALESCE(restriction_mask, 0) = 0
      AND action IN ('timeout', 'suspension', 'ban')
      AND (
        action = 'ban'
        OR COALESCE(restriction_until, expires_at) IS NULL
        OR COALESCE(restriction_until, expires_at) > ?
      )
    ORDER BY CASE action WHEN 'ban' THEN 3 WHEN 'suspension' THEN 2 ELSE 1 END DESC,
             COALESCE(restriction_until, expires_at, 9223372036854775807) DESC
    LIMIT 1
  `).bind(appeal.user_id, now).first();
    if (!remainingRestriction) {
        await env.DB.prepare(`
      UPDATE users
      SET account_status = CASE
            WHEN account_status IN ('banned','suspended') THEN 'active'
            ELSE account_status
          END,
          suspension_until = NULL
      WHERE id = ?
    `).bind(appeal.user_id).run();
    }
    else if (String(remainingRestriction.action) === 'ban') {
        await env.DB.prepare(`UPDATE users SET account_status='banned', suspension_until=NULL WHERE id=?`)
            .bind(appeal.user_id).run();
    }
    else {
        await env.DB.prepare(`UPDATE users SET account_status='suspended', suspension_until=? WHERE id=?`)
            .bind(remainingRestriction.ends_at || null, appeal.user_id).run();
    }
    if (String(appeal.violation_type || '').toLowerCase() === 'minimum age requirements') {
        try {
            await env.DB.prepare(`
        UPDATE users
        SET minimum_age_status='reactivated',
            minimum_age_reactivated_at=?,
            minimum_age_restricted_at=NULL,
            minimum_age_email_delete_at=NULL
        WHERE id=?
      `).bind(now, appeal.user_id).run();
        }
        catch (error) {
            console.warn('Could not clear minimum-age metadata after accepted appeal', error);
        }
    }
    const user = await env.DB.prepare('SELECT account_status, suspension_until FROM users WHERE id=? LIMIT 1')
        .bind(appeal.user_id).first();
    return { account_status: user?.account_status || null, suspension_until: user?.suspension_until || null };
}

async function adminUpdateAppeal(request, env, admin, appealId) {
    const body = await readJson(request) || {};
    const status = String(body.status || '');
    const resolution = cleanText(body.resolution || '', 1500, true);
    if (!['reviewing', 'accepted', 'rejected'].includes(status)) {
        return json({ error: 'Invalid appeal status' }, 400);
    }
    if (['accepted', 'rejected'].includes(status) && !resolution) {
        return json({ error: 'A decision note is required' }, 400);
    }
    const appeal = await env.DB.prepare(`
    SELECT a.*, v.action, v.report_id, v.expires_at, v.restriction_until, v.restriction_mask,
           v.violation_type, v.status AS violation_status
    FROM violation_appeals a
    JOIN violations v ON v.id = a.violation_id
    WHERE a.id = ? LIMIT 1
  `).bind(appealId).first();
    if (!appeal)
        return json({ error: 'Appeal not found' }, 404);
    if (['accepted', 'rejected'].includes(appeal.status)) {
        if (appeal.status === 'accepted' && status === 'accepted') {
            const now = Date.now();
            await env.DB.batch([
                env.DB.prepare(`UPDATE violations SET status='overturned', reversed_at=COALESCE(reversed_at, ?) WHERE id=?`).bind(now, appeal.violation_id),
                env.DB.prepare(`UPDATE account_limitations SET status='reversed', updated_at=? WHERE violation_id=? AND status='active'`).bind(now, appeal.violation_id),
            ]);
            const restored = await reconcileAcceptedAppealAccess(env, appeal, now);
            await recomputeUserSafetyCache(env.DB, appeal.user_id, now);
            return json({ ok: true, status: 'accepted', reconciled: true, account_status: restored.account_status, suspension_until: restored.suspension_until });
        }
        return json({ error: 'This appeal already has a final decision' }, 409);
    }
    const now = Date.now();
    const violationStatus = status === 'accepted'
        ? 'overturned'
        : status === 'rejected'
            ? (appeal.expires_at && Number(appeal.expires_at) <= now ? 'expired' : 'active')
            : 'appealed';
    const statements = [
        env.DB.prepare(`
      UPDATE violation_appeals
      SET status = ?, resolution = ?, reviewed_by = ?, updated_at = ?
      WHERE id = ?
    `).bind(status, resolution, admin.id, now, appealId),
        env.DB.prepare(`
      UPDATE violations
      SET status = ?, reversed_at = CASE WHEN ? = 'overturned' THEN ? ELSE reversed_at END
      WHERE id = ?
    `).bind(violationStatus, violationStatus, now, appeal.violation_id),
        env.DB.prepare(`
      INSERT INTO admin_actions (id, admin_id, action, target_user_id, report_id, notes, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).bind(prefixedId('act'), admin.id, `appeal_${status}`, appeal.user_id, appeal.report_id || null, resolution, now),
    ];
    if (status === 'accepted') {
        statements.push(env.DB.prepare(`
      UPDATE account_limitations
      SET status = 'reversed', updated_at = ?
      WHERE violation_id = ? AND status = 'active'
    `).bind(now, appeal.violation_id));
    }
    await env.DB.batch(statements);
    if (status === 'accepted') {
        await reconcileAcceptedAppealAccess(env, appeal, now);
    }
    await recomputeUserSafetyCache(env.DB, appeal.user_id, now);
    if (['accepted', 'rejected'].includes(status)) {
        try {
            const violation = await env.DB.prepare('SELECT violation_type FROM violations WHERE id = ? LIMIT 1')
                .bind(appeal.violation_id).first();
            await sendSystemDm(env.DB, appeal.user_id, {
                kind: status === 'accepted' ? 'appeal_accepted' : 'appeal_rejected',
                color: status === 'accepted' ? '#23a55a' : '#da373c',
                dedupeKey: `appeal-decision:${appealId}:${status}`,
                title: `An update on your appeal for ${violation?.violation_type || 'a policy violation'}`,
                description: status === 'accepted'
                    ? 'We reversed this violation. It is now shown under Expired Violations and no longer affects your account standing or feature access.'
                    : `We kept this violation. ${resolution}`,
                actions: [{ label: 'safety hub', action: 'safety_hub' }],
            });
        }
        catch (error) {
            console.warn('Could not send appeal decision DM', error);
        }
    }
    try {
        const violation = await env.DB.prepare('SELECT violation_type FROM violations WHERE id = ? LIMIT 1')
            .bind(appeal.violation_id).first();
        await sendVerifiedAccountEmail(env, appeal.user_id, {
            type: 'appeal_status',
            status,
            violation_type: violation?.violation_type || 'Community Guidelines violation',
            resolution: resolution || (status === 'reviewing' ? 'Your appeal is now being reviewed.' : ''),
        });
    }
    catch (error) {
        console.warn('Could not send appeal status email', error);
    }
    let account_status = null;
    if (status === 'accepted') {
        try {
            const restored = await env.DB.prepare('SELECT account_status, suspension_until FROM users WHERE id = ? LIMIT 1').bind(appeal.user_id).first();
            account_status = restored?.account_status || null;
        }
        catch { }
    }
    return json({ ok: true, status, account_status });
}

const MANUAL_BADGES = Object.freeze(['beta_tester', 'bug_hunter', 'contributor', 'reporter']);

const ADMIN_ANNOUNCEMENT_AUDIENCES = new Set([
    'all',
    'staff',
    'admins',
    'moderators',
    'support',
    'plus',
    'non_plus',
]);

function adminAnnouncementAudienceSql(audience, now) {
    const common = `
    FROM users u
    WHERE u.id NOT IN (?,?,?)
      AND NOT EXISTS (
        SELECT 1 FROM bot_applications ba WHERE ba.bot_user_id=u.id
      )
  `;
    if (audience === 'staff') {
        return {
            sql: `${common}
        AND (
          u.role IN ('owner','admin','moderator')
          OR EXISTS(SELECT 1 FROM support_staff ss WHERE ss.user_id=u.id)
        )`,
            extra: [],
        };
    }
    if (audience === 'admins') {
        return {
            sql: `${common} AND u.role IN ('owner','admin')`,
            extra: [],
        };
    }
    if (audience === 'moderators') {
        return {
            sql: `${common} AND u.role='moderator'`,
            extra: [],
        };
    }
    if (audience === 'support') {
        return {
            sql: `${common}
        AND EXISTS(SELECT 1 FROM support_staff ss WHERE ss.user_id=u.id)`,
            extra: [],
        };
    }
    if (audience === 'plus') {
        return {
            sql: `${common}
        AND EXISTS(
          SELECT 1 FROM user_entitlements ue
          WHERE ue.user_id=u.id
            AND ue.tier='plus'
            AND (ue.expires_at IS NULL OR ue.expires_at>?)
        )`,
            extra: [now],
        };
    }
    if (audience === 'non_plus') {
        return {
            sql: `${common}
        AND NOT EXISTS(
          SELECT 1 FROM user_entitlements ue
          WHERE ue.user_id=u.id
            AND ue.tier='plus'
            AND (ue.expires_at IS NULL OR ue.expires_at>?)
        )`,
            extra: [now],
        };
    }
    return { sql: common, extra: [] };
}

function normalizeAnnouncementAudience(value) {
    const audience = String(value || 'all').trim().toLowerCase();
    return ADMIN_ANNOUNCEMENT_AUDIENCES.has(audience) ? audience : '';
}

async function adminAnnouncementCount(env, url) {
    const audience = normalizeAnnouncementAudience(url.searchParams.get('audience'));
    if (!audience)
        return json({ error: 'Invalid announcement audience' }, 400);
    const now = Date.now();
    const query = adminAnnouncementAudienceSql(audience, now);
    const row = await env.DB.prepare(`SELECT COUNT(*) AS count ${query.sql}`)
        .bind(SYSTEM_USER_ID, BYTE_USER_ID, WEBHOOK_USER_ID, ...query.extra).first();
    return json({
        audience,
        count: Number(row?.count || 0),
    });
}

async function adminSendAnnouncementBatch(request, env, owner) {
    const body = await readJson(request) || {};
    const audience = normalizeAnnouncementAudience(body.audience);
    if (!audience)
        return json({ error: 'Invalid announcement audience' }, 400);
    const title = cleanText(body.title || '', 120, true).trim();
    const message = cleanText(body.message || '', 1800, true).trim();
    if (!title)
        return json({ error: 'Announcement title is required' }, 400);
    if (!message)
        return json({ error: 'Announcement message is required' }, 400);
    const campaignId = cleanText(body.campaign_id || '', 80, false).trim() || prefixedId('announce');
    if (!/^announce_[A-Za-z0-9_-]+$/.test(campaignId)) {
        return json({ error: 'Invalid announcement campaign id' }, 400);
    }
    const cursor = cleanText(body.cursor || '', 128, false).trim();
    const now = Date.now();
    const query = adminAnnouncementAudienceSql(audience, now);
    const cursorClause = cursor ? ' AND u.id>?' : '';
    const limit = 30;
    const rows = await env.DB.prepare(`
    SELECT u.id
    ${query.sql}
    ${cursorClause}
    ORDER BY u.id ASC
    LIMIT ?
  `).bind(SYSTEM_USER_ID, BYTE_USER_ID, WEBHOOK_USER_ID, ...query.extra, ...(cursor ? [cursor] : []), limit).all();
    const targets = rows.results || [];
    let delivered = 0;
    for (const target of targets) {
        try {
            await sendSystemDm(env.DB, target.id, {
                kind: 'announcement',
                color: '#5865f2',
                dedupeKey: `admin-announcement:${campaignId}:${target.id}`,
                title,
                description: message,
                actions: [],
            });
            delivered++;
        }
        catch (error) {
            console.warn('Could not send admin announcement', campaignId, target.id, String(error?.message || error));
        }
    }
    const nextCursor = targets.length ? String(targets[targets.length - 1].id) : '';
    const done = targets.length < limit;
    if (!cursor) {
        try {
            await env.DB.prepare(`
        INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at)
        VALUES(?,?,?,?,?,?)
      `).bind(prefixedId('act'), owner.id, 'system_announcement', owner.id, JSON.stringify({ campaign_id: campaignId, audience, title, message_length: message.length }), now).run();
        }
        catch (error) {
            console.warn('Could not audit admin announcement', String(error?.message || error));
        }
    }
    return json({
        ok: true,
        campaign_id: campaignId,
        audience,
        delivered,
        cursor: nextCursor,
        done,
    });
}

async function adminListUsers(env, url) {
    const query = cleanText(url.searchParams.get('query') || '', 80).trim();
    const like = `%${query.replace(/[\%_]/g, '\\$&')}%`;
    const result = query
        ? await env.DB.prepare(`
        SELECT users.*,
          EXISTS(SELECT 1 FROM user_entitlements ue WHERE ue.user_id=users.id AND ue.tier='plus' AND (ue.expires_at IS NULL OR ue.expires_at>?)) AS plus_active,
          EXISTS(SELECT 1 FROM support_staff ss WHERE ss.user_id=users.id) AS support_active
        FROM users
        WHERE id=? OR username LIKE ? ESCAPE '\' COLLATE NOCASE OR display_name LIKE ? ESCAPE '\' COLLATE NOCASE
           OR (username || '#' || discriminator) LIKE ? ESCAPE '\' COLLATE NOCASE
        ORDER BY CASE role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 WHEN 'moderator' THEN 2 ELSE 3 END, created_at ASC
        LIMIT 100
      `).bind(Date.now(), query, like, like, like).all()
        : await env.DB.prepare(`
        SELECT users.*,
          EXISTS(SELECT 1 FROM user_entitlements ue WHERE ue.user_id=users.id AND ue.tier='plus' AND (ue.expires_at IS NULL OR ue.expires_at>?)) AS plus_active,
          EXISTS(SELECT 1 FROM support_staff ss WHERE ss.user_id=users.id) AS support_active
        FROM users
        ORDER BY CASE role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 WHEN 'moderator' THEN 2 ELSE 3 END, created_at DESC
        LIMIT 100
      `).bind(Date.now()).all();
    return json({ users: (result.results || []).map(row => ({ ...row, role: rawAccountRole(row), badges: parseBadgeList(row.badges) })), manual_badges: MANUAL_BADGES });
}

async function adminUpdateUserBadges(request, env, admin, targetUserId) {
    if (targetUserId === SYSTEM_USER_ID)
        return json({ error: 'The Orbyte system account cannot be modified' }, 403);
    const hierarchy = await guardAccountManagementTarget(env, admin, targetUserId, 'modify');
    if (hierarchy.error)
        return hierarchy.error;
    const body = await readJson(request);
    if (!Array.isArray(body?.badges))
        return json({ error: 'Badges must be an array' }, 400);
    const selectedManual = [...new Set(body.badges.map(String).filter(id => MANUAL_BADGES.includes(id)))];
    const target = await env.DB.prepare(`
    SELECT u.id,u.badges, EXISTS(SELECT 1 FROM support_staff ss WHERE ss.user_id=u.id) AS support_active
    FROM users u WHERE u.id=?
  `).bind(targetUserId).first();
    if (!target)
        return json({ error: 'User not found' }, 404);
    const protectedBadges = parseBadgeList(target.badges).filter(id => !MANUAL_BADGES.includes(id) && id !== 'support' && id !== 'plus');
    const badges = [...new Set([...selectedManual, ...protectedBadges])];
    if (target.support_active)
        badges.push('support');
    const now = Date.now();
    await env.DB.batch([
        env.DB.prepare('UPDATE users SET badges=? WHERE id=?').bind(JSON.stringify(badges), targetUserId),
        env.DB.prepare('INSERT INTO admin_actions (id,admin_id,action,target_user_id,notes,created_at) VALUES (?,?,?,?,?,?)').bind(prefixedId('act'), admin.id, 'badges_update', targetUserId, JSON.stringify(badges), now),
    ]);
    return json({ ok: true, badges });
}

async function adminUpdateUserRole(request, env, admin, targetUserId) {
    if (targetUserId === SYSTEM_USER_ID)
        return json({ error: 'The Orbyte system account cannot be modified' }, 403);
    const body = await readJson(request);
    const role = String(body?.role || '').trim().toLowerCase();
    if (role === 'owner') {
        return json({
            error: 'Owner can only be granted or removed directly in the D1 database',
            code: 'OWNER_DATABASE_ONLY'
        }, 403);
    }
    if (!['user', 'support', 'moderator', 'admin'].includes(role)) {
        return json({ error: 'Invalid account role' }, 400);
    }
    const guard = await guardAccountManagementTarget(env, admin, targetUserId, 'change the role of');
    if (guard.error)
        return guard.error;
    const target = guard.target;
    const allowed = allowedRoleAssignments(admin);
    if (!allowed.has(role)) {
        const actorRole = effectiveAccountRole(admin);
        return json({
            error: actorRole === 'moderator'
                ? 'Moderators can only assign Support or Regular user'
                : actorRole === 'admin'
                    ? 'Administrators can only assign Moderator, Support, or Regular user. Only the owner can grant Administrator.'
                    : 'This role change is not allowed',
            code: 'ROLE_HIERARCHY_DENIED'
        }, 403);
    }
    const requestedRank = ACCOUNT_STAFF_RANK[role] ?? 0;
    if (requestedRank >= accountStaffRank(admin)) {
        return json({
            error: 'You cannot grant a role equal to or higher than your own',
            code: 'ROLE_HIERARCHY_DENIED'
        }, 403);
    }
    if (['admin', 'moderator'].includes(role)) {
        const conflict = await findProtectedIdentityConflict(env.DB, targetUserId, target.username, target.display_name);
        if (conflict)
            return json({ error: `This account must change its name before becoming staff because it conflicts with ${conflict}.` }, 409);
    }
    const targetFull = await env.DB.prepare('SELECT badges FROM users WHERE id=? LIMIT 1').bind(targetUserId).first();
    const now = Date.now();
    const badges = parseBadgeList(targetFull?.badges).filter(id => id !== 'support' && id !== 'plus');
    if (role === 'support')
        badges.push('support');
    const statements = [
        env.DB.prepare('DELETE FROM support_staff WHERE user_id=?').bind(targetUserId),
        env.DB.prepare('UPDATE users SET role=?,badges=? WHERE id=?')
            .bind(role === 'support' ? 'user' : role, JSON.stringify([...new Set(badges)]), targetUserId),
        env.DB.prepare('INSERT INTO admin_actions (id,admin_id,action,target_user_id,notes,created_at) VALUES (?,?,?,?,?,?)')
            .bind(prefixedId('act'), admin.id, 'account_role_update', targetUserId, JSON.stringify({
            from: effectiveAccountRole(target),
            to: role,
            actor_role: effectiveAccountRole(admin)
        }), now),
    ];
    if (role === 'support') {
        statements.splice(1, 0, env.DB.prepare('INSERT INTO support_staff(user_id,granted_by,granted_at) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET granted_by=excluded.granted_by,granted_at=excluded.granted_at').bind(targetUserId, admin.id, now));
    }
    await env.DB.batch(statements);
    return json({ ok: true, role, support_active: role === 'support' });
}

async function adminResetUserName(request, env, admin, targetUserId) {
    if (targetUserId === SYSTEM_USER_ID)
        return json({ error: 'The Orbyte system account cannot be modified' }, 403);
    const hierarchy = await guardAccountManagementTarget(env, admin, targetUserId, 'reset the username of');
    if (hierarchy.error)
        return hierarchy.error;
    const body = await readJson(request) || {};
    const reason = cleanText(body.reason || 'Username reset by an administrator', 500, true);
    const target = await env.DB.prepare('SELECT id,username,discriminator,display_name FROM users WHERE id=? LIMIT 1').bind(targetUserId).first();
    if (!target)
        return json({ error: 'User not found' }, 404);
    const replacementUsername = 'OrbyteUser';
    let replacementDiscriminator = null;
    for (let attempt = 0; attempt < 100; attempt += 1) {
        const value = String(secureRandomIndex(10000)).padStart(4, '0');
        const exists = await env.DB.prepare('SELECT 1 FROM users WHERE username=? COLLATE NOCASE AND discriminator=? AND id!=? LIMIT 1')
            .bind(replacementUsername, value, targetUserId).first();
        if (!exists) {
            replacementDiscriminator = value;
            break;
        }
    }
    if (!replacementDiscriminator)
        return json({ error: 'Could not generate an available replacement tag' }, 503);
    const previousTag = `${target.username}#${target.discriminator}`;
    const nextTag = `${replacementUsername}#${replacementDiscriminator}`;
    const now = Date.now();
    await env.DB.batch([
        env.DB.prepare('UPDATE users SET username=?,discriminator=?,display_name=? WHERE id=?')
            .bind(replacementUsername, replacementDiscriminator, replacementUsername, targetUserId),
        env.DB.prepare('INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at) VALUES(?,?,?,?,?,?)')
            .bind(prefixedId('act'), admin.id, 'reset_username', targetUserId, `${previousTag} -> ${nextTag}. ${reason}`, now),
    ]);
    try {
        await sendSystemDm(env.DB, targetUserId, {
            kind: 'violation',
            color: '#DA373C',
            dedupeKey: `name-reset:${targetUserId}:${now}`,
            title: 'Your Orbyte name was reset',
            description: `An administrator reset your username and display name.\n\nReason: ${reason}\n\nYour new tag is **${nextTag}**. You can review the rules in Orbyte.`,
            actions: [{ label: 'View rules', action: 'guidelines' }],
        });
    }
    catch (error) {
        console.warn('Could not send username-reset system DM', error);
    }
    return json({ ok: true, user: { id: targetUserId, username: replacementUsername, discriminator: replacementDiscriminator, display_name: replacementUsername } });
}

async function adminListReports(env, url) {
    const status = url.searchParams.get('status') || 'open';
    const allowed = ['open', 'reviewing', 'resolved', 'dismissed', 'all'];
    if (!allowed.includes(status))
        return json({ error: 'Invalid status' }, 400);
    const where = status === 'all' ? '' : 'WHERE r.status = ?';
    const stmt = env.DB.prepare(`
    SELECT
      r.*,
      reporter.username AS reporter_username,
      reporter.discriminator AS reporter_discriminator,
      CASE
        WHEN r.target_type = 'user' THEN target_user.username
        WHEN r.target_type = 'message' THEN message_user.username
        ELSE server_target.name
      END AS target_username,
      CASE
        WHEN r.target_type = 'user' THEN target_user.discriminator
        WHEN r.target_type = 'message' THEN message_user.discriminator
        ELSE ''
      END AS target_discriminator,
      COALESCE(m.content, dm.content) AS message_content,
      COALESCE(m.user_id, dm.user_id) AS message_author_id,
      CASE
        WHEN dm.id IS NOT NULL THEN 'dm'
        WHEN m.id IS NOT NULL THEN 'channel'
        ELSE NULL
      END AS message_scope
    FROM reports r
    JOIN users reporter ON reporter.id = r.reporter_id
    LEFT JOIN users target_user ON r.target_type = 'user' AND target_user.id = r.target_id
    LEFT JOIN messages m ON r.target_type = 'message' AND m.id = r.target_id
    LEFT JOIN dm_messages dm ON r.target_type = 'message' AND dm.id = r.target_id
    LEFT JOIN users message_user ON message_user.id = COALESCE(m.user_id, dm.user_id)
    LEFT JOIN servers server_target ON r.target_type='server' AND server_target.id=r.target_id
    ${where}
    ORDER BY r.created_at DESC
    LIMIT 200
  `);
    const result = status === 'all' ? await stmt.all() : await stmt.bind(status).all();
    return json({ reports: result.results || [] });
}

async function adminUpdateReport(request, env, admin, reportId) {
    const body = await readJson(request);
    const status = body?.status;
    const resolution = cleanText(body?.resolution || '', 1000, true);
    if (!['reviewing', 'resolved', 'dismissed'].includes(status))
        return json({ error: 'Invalid status' }, 400);
    const report = await env.DB.prepare(`
    SELECT r.*, reporter.username AS reporter_username,
      reporter.discriminator AS reporter_discriminator,
      reporter.display_name AS reporter_display_name
    FROM reports r
    JOIN users reporter ON reporter.id = r.reporter_id
    WHERE r.id = ?
    LIMIT 1
  `).bind(reportId).first();
    if (!report)
        return json({ error: 'Report not found' }, 404);
    const now = Date.now();
    await env.DB.batch([
        env.DB.prepare(`
      UPDATE reports SET status = ?, resolution = ?, assigned_admin_id = ?, updated_at = ? WHERE id = ?
    `).bind(status, resolution, admin.id, now, reportId),
        env.DB.prepare(`
      INSERT INTO admin_actions (id, admin_id, action, target_user_id, report_id, notes, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).bind(prefixedId('act'), admin.id, `report_${status}`, report.target_type === 'user' ? report.target_id : null, reportId, resolution, now),
    ]);
    if (status === 'resolved' && report.reporter_id) {
        const reportedContent = cleanText(report.target_snapshot || (report.target_type === 'message' ? 'Reported message' :
            report.target_type === 'server' ? 'Reported server' : 'Reported account'), 1800, true);
        const quoted = reportedContent.split(/\r?\n/).map(line => `> ${line || ' '}`).join('\n');
        const reporterTag = `${report.reporter_username || 'user'}#${report.reporter_discriminator || '0000'}`;
        const description = `Hello, ${reporterTag}, we have reviewed your recent report, and confirmed that the content you identified broke our rules and we have taken action.\n\nReported content:\n${quoted}`;
        try {
            const reporterRow = await env.DB.prepare('SELECT badges FROM users WHERE id = ? LIMIT 1').bind(report.reporter_id).first();
            if (reporterRow) {
                const reporterBadges = new Set(parseBadgeList(reporterRow.badges));
                if (!reporterBadges.has('reporter')) {
                    reporterBadges.add('reporter');
                    await env.DB.prepare('UPDATE users SET badges = ? WHERE id = ?').bind(JSON.stringify([...reporterBadges]), report.reporter_id).run();
                }
            }
        }
        catch (error) {
            console.warn('Could not award reporter badge', error);
        }
        try {
            await sendSystemDm(env.DB, report.reporter_id, {
                kind: 'report_accepted',
                color: '#23A55A',
                dedupeKey: `report-accepted:${report.id}`,
                title: 'Thank you for helping keep Orbyte safe!',
                description,
            });
        }
        catch (error) {
            console.warn('Could not send accepted-report system DM', error);
        }
        try {
            await sendVerifiedAccountEmail(env, report.reporter_id, {
                type: 'report_accepted',
                report_type: report.target_type,
                reported_content: reportedContent,
                resolution: resolution || '',
            });
        }
        catch (error) {
            console.warn('Could not send accepted-report email', error);
        }
    }
    return json({ ok: true });
}

async function buildViolationEvidenceSnapshot(env, reportId, targetUserId, note = '') {
    let report = null;
    if (reportId) {
        try {
            report = await env.DB.prepare(`
        SELECT target_type, target_id, target_snapshot
        FROM reports WHERE id = ? LIMIT 1
      `).bind(reportId).first();
        }
        catch (error) {
            console.warn('Could not load violation report evidence', error);
        }
    }
    const targetType = String(report?.target_type || '').toLowerCase();
    const targetId = String(report?.target_id || '').trim();
    if (targetType === 'message' && targetId) {
        try {
            let row = await env.DB.prepare(`
        SELECT m.id, m.content, m.created_at,
               u.username, u.discriminator, u.display_name, u.avatar_url,
               c.name AS channel_name, s.name AS server_name, s.icon_url AS server_icon_url,
               'channel' AS message_type
        FROM messages m
        JOIN users u ON u.id = m.user_id
        JOIN channels c ON c.id = m.channel_id
        JOIN servers s ON s.id = c.server_id
        WHERE m.id = ? LIMIT 1
      `).bind(targetId).first();
            if (!row) {
                row = await env.DB.prepare(`
          SELECT m.id, m.content, m.created_at,
                 u.username, u.discriminator, u.display_name, u.avatar_url,
                 'Direct Message' AS channel_name, '' AS server_name, '' AS server_icon_url,
                 'dm' AS message_type
          FROM dm_messages m
          JOIN users u ON u.id = m.user_id
          WHERE m.id = ? LIMIT 1
        `).bind(targetId).first();
            }
            if (row) {
                return JSON.stringify({
                    kind: 'message',
                    message_type: row.message_type || 'channel',
                    message_id: row.id,
                    server_name: row.server_name || '',
                    server_icon_url: row.server_icon_url || '',
                    channel_name: row.channel_name || '',
                    author_name: row.display_name || row.username || 'User',
                    author_tag: row.username ? `${row.username}#${row.discriminator || '0000'}` : '',
                    author_avatar_url: row.avatar_url || '',
                    content: cleanText(row.content || report?.target_snapshot || '', 1800, true),
                    sent_at: Number(row.created_at || Date.now()),
                });
            }
        }
        catch (error) {
            console.warn('Could not build message violation evidence', error);
        }
        const snapshot = cleanText(report?.target_snapshot || '', 1800, true);
        if (snapshot) {
            try {
                const target = await env.DB.prepare(`
          SELECT username, discriminator, display_name, avatar_url
          FROM users WHERE id = ? LIMIT 1
        `).bind(targetUserId).first();
                return JSON.stringify({
                    kind: 'message',
                    message_type: 'channel',
                    message_id: targetId,
                    author_name: target?.display_name || target?.username || 'Reviewed message',
                    author_tag: target?.username ? `${target.username}#${target.discriminator || '0000'}` : '',
                    author_avatar_url: target?.avatar_url || '',
                    content: snapshot,
                    sent_at: Date.now(),
                });
            }
            catch { }
        }
    }
    if (targetType === 'server' && targetId) {
        try {
            const server = await env.DB.prepare('SELECT id, name, icon_url, owner_id FROM servers WHERE id = ? LIMIT 1')
                .bind(targetId).first();
            return JSON.stringify({
                kind: 'server',
                server_id: targetId,
                server_name: server?.name || report?.target_snapshot || 'Reviewed server',
                server_icon_url: server?.icon_url || '',
                recipient_role: server?.owner_id && String(server.owner_id) === String(targetUserId) ? 'owner' : 'member',
                content: cleanText(report?.target_snapshot || '', 1800, true),
            });
        }
        catch (error) {
            console.warn('Could not build server violation evidence', error);
        }
    }
    if ((targetType === 'user' || targetType === 'profile') && targetUserId) {
        try {
            const target = await env.DB.prepare(`
        SELECT id, username, discriminator, display_name, avatar_url, about
        FROM users WHERE id = ? LIMIT 1
      `).bind(targetUserId).first();
            const snapshot = cleanText(report?.target_snapshot || target?.about || '', 1800, true);
            return JSON.stringify({
                kind: 'profile',
                profile_user_id: targetUserId,
                profile_name: target?.display_name || target?.username || 'Your profile',
                profile_tag: target?.username ? `${target.username}#${target.discriminator || '0000'}` : '',
                profile_avatar_url: target?.avatar_url || '',
                content: snapshot,
                reviewed_at: Date.now(),
            });
        }
        catch (error) {
            console.warn('Could not build profile violation evidence', error);
        }
    }
    const snapshot = cleanText(report?.target_snapshot || '', 1800, true);
    if (snapshot) {
        try {
            const target = await env.DB.prepare(`
        SELECT username, discriminator, display_name, avatar_url
        FROM users WHERE id = ? LIMIT 1
      `).bind(targetUserId).first();
            return JSON.stringify({
                kind: 'message',
                author_name: target?.display_name || target?.username || 'Reviewed activity',
                author_tag: target?.username ? `${target.username}#${target.discriminator || '0000'}` : '',
                author_avatar_url: target?.avatar_url || '',
                content: snapshot,
                sent_at: Date.now(),
            });
        }
        catch { }
    }
    return '';
}

async function adminCreateViolation(request, env, admin, targetUserId) {
    if (targetUserId === SYSTEM_USER_ID) {
        return json({ error: 'The Orbyte system account cannot receive violations' }, 403);
    }
    const body = await readJson(request) || {};
    const violationType = cleanText(body.violation_title || body.violation_type || body.reason || 'Community Guidelines violation', 80);
    const severity = String(body.severity || 'medium');
    const reason = violationType;
    const legacyAction = String(body.action || 'warning').toLowerCase();
    let accountAction = String(body.account_action || '').toLowerCase();
    if (!accountAction) {
        if (['warning', 'suspension', 'ban'].includes(legacyAction))
            accountAction = legacyAction;
        else if (legacyAction === 'timeout')
            accountAction = 'suspension';
        else
            accountAction = 'warning';
    }
    const reportId = body.report_id || null;
    const requestedDuration = Number(body.restriction_duration_hours ?? body.duration_hours ?? 24);
    const suspensionDuration = Number(body.suspension_duration_hours ?? body.duration_hours ?? 24);
    const restrictionMask = parseAccountRestrictionMask(body.restrictions ?? body.limitations ?? body.limitation_types);
    const applyLimitation = body.apply_limitation === true || legacyAction === 'account_limitation';
    const deleteReportedMessage = body.delete_reported_message === true || legacyAction === 'message_removed';
    const moderatorNote = cleanText(body.moderator_note || '', 1800, true);
    if (!['low', 'medium', 'high', 'critical'].includes(severity)) {
        return json({ error: 'Invalid severity' }, 400);
    }
    if (!['warning', 'suspension', 'ban'].includes(accountAction)) {
        return json({ error: 'Invalid account action' }, 400);
    }
    if (!reason)
        return json({ error: 'Reason is required' }, 400);
    if (applyLimitation && !restrictionMask) {
        return json({ error: 'Choose at least one feature to limit' }, 400);
    }
    if (applyLimitation && ![1, 24, 72, 168, 744].includes(requestedDuration)) {
        return json({ error: 'Choose 1 hour, 1 day, 3 days, 7 days, or 31 days' }, 400);
    }
    if (accountAction === 'suspension' && ![1, 24, 72, 168, 744].includes(suspensionDuration)) {
        return json({ error: 'Choose a valid suspension duration' }, 400);
    }
    const hierarchy = await guardAccountManagementTarget(env, admin, targetUserId, 'act on');
    if (hierarchy.error)
        return hierarchy.error;
    const target = hierarchy.target;
    let report = null;
    if (reportId) {
        report = await env.DB.prepare(`
      SELECT id, target_type, target_id, target_snapshot
      FROM reports WHERE id = ? LIMIT 1
    `).bind(reportId).first();
    }
    let removal = null;
    let removalAttachments = [];
    if (deleteReportedMessage) {
        if (!report || String(report.target_type || '').toLowerCase() !== 'message' || !report.target_id) {
            return json({ error: 'Content removal is only available for reports that target a message' }, 400);
        }
        const messageId = String(report.target_id);
        let row = await env.DB.prepare(`
      SELECT m.id, m.user_id, m.channel_id, m.deleted_at, c.server_id
      FROM messages m JOIN channels c ON c.id = m.channel_id
      WHERE m.id = ? LIMIT 1
    `).bind(messageId).first();
        let messageType = 'channel';
        if (!row) {
            row = await env.DB.prepare(`
        SELECT id, user_id, conversation_id, deleted_at
        FROM dm_messages WHERE id = ? LIMIT 1
      `).bind(messageId).first();
            messageType = 'dm';
        }
        if (!row)
            return json({ error: 'The reported message could not be found, so it was not deleted' }, 404);
        if (String(row.user_id) !== String(targetUserId)) {
            return json({ error: 'The reported message does not belong to the selected user' }, 400);
        }
        removal = {
            type: messageType,
            id: messageId,
            alreadyDeleted: Boolean(row.deleted_at),
            channelId: row.channel_id || null,
            serverId: row.server_id || null,
        };
        if (!removal.alreadyDeleted) {
            try {
                removalAttachments = await listStoredAttachments(env.DB, messageType, messageId);
            }
            catch (error) {
                console.warn('Could not list attachments for moderated message removal', error);
            }
        }
    }
    const now = Date.now();
    const violationDays = violationLifetimeDays(severity);
    const standingExpiresAt = accountAction === 'ban' ? null : now + violationDays * 24 * 60 * 60 * 1000;
    const restrictionUntil = applyLimitation ? now + requestedDuration * 60 * 60 * 1000 : null;
    const suspensionUntil = accountAction === 'suspension' ? now + suspensionDuration * 60 * 60 * 1000 : null;
    const violationId = prefixedId('vio');
    const evidenceText = await buildViolationEvidenceSnapshot(env, reportId, targetUserId, '');
    const contentRemoved = Boolean(removal);
    const removedContentType = removal?.type || null;
    const removedContentId = removal?.id || null;
    const contentRemovedAt = contentRemoved ? now : null;
    let storedAction = 'warning';
    if (accountAction === 'ban')
        storedAction = 'ban';
    else if (accountAction === 'suspension')
        storedAction = 'suspension';
    else if (applyLimitation)
        storedAction = 'timeout';
    else if (contentRemoved)
        storedAction = 'message_removed';
    const actionNotes = [reason];
    if (contentRemoved)
        actionNotes.push('reported message removed');
    if (applyLimitation)
        actionNotes.push(`limited features mask ${restrictionMask}`);
    if (accountAction === 'suspension')
        actionNotes.push(`suspended ${suspensionDuration}h`);
    if (accountAction === 'ban')
        actionNotes.push('permanently suspended');
    const statements = [
        env.DB.prepare(`
      INSERT INTO violations (
        id, user_id, report_id, violation_type, severity, reason, action, evidence_text, moderator_note,
        status, expires_at, restriction_mask, restriction_until, suspension_until,
        content_removed, removed_content_type, removed_content_id, content_removed_at,
        reversed_at, created_by, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?, ?, ?, ?, ?, ?, ?, ?, NULL, ?, ?)
    `).bind(violationId, targetUserId, reportId, violationType, severity, reason, storedAction, evidenceText, moderatorNote, standingExpiresAt, applyLimitation ? restrictionMask : 0, restrictionUntil, suspensionUntil, contentRemoved ? 1 : 0, removedContentType, removedContentId, contentRemovedAt, admin.id, now),
        env.DB.prepare(`
      INSERT INTO admin_actions (id, admin_id, action, target_user_id, report_id, notes, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).bind(prefixedId('act'), admin.id, storedAction, targetUserId, reportId, actionNotes.join(' · '), now),
    ];
    if (applyLimitation) {
        statements.push(env.DB.prepare(`
      INSERT INTO account_limitations (
        id, user_id, violation_id, limitation_mask, status, expires_at,
        created_by, created_at, updated_at
      ) VALUES (?, ?, ?, ?, 'active', ?, ?, ?, ?)
    `).bind(prefixedId('lim'), targetUserId, violationId, restrictionMask, restrictionUntil, admin.id, now, now));
    }
    if (removal && !removal.alreadyDeleted) {
        const table = removal.type === 'dm' ? 'dm_messages' : 'messages';
        statements.push(env.DB.prepare(`UPDATE ${table} SET deleted_at = ? WHERE id = ? AND deleted_at IS NULL`).bind(now, removal.id));
        statements.push(env.DB.prepare('DELETE FROM notifications WHERE message_id = ?').bind(removal.id));
        statements.push(env.DB.prepare('DELETE FROM message_attachments WHERE message_type = ? AND message_id = ?').bind(removal.type, removal.id));
    }
    if (accountAction === 'suspension') {
        statements.push(env.DB.prepare(`
      UPDATE users SET account_status = 'suspended', suspension_until = ? WHERE id = ?
    `).bind(suspensionUntil, targetUserId));
        statements.push(env.DB.prepare('DELETE FROM sessions WHERE user_id = ?').bind(targetUserId));
    }
    else if (accountAction === 'ban') {
        statements.push(env.DB.prepare(`
      UPDATE users SET account_status = 'banned', suspension_until = NULL WHERE id = ?
    `).bind(targetUserId));
        statements.push(env.DB.prepare('DELETE FROM sessions WHERE user_id = ?').bind(targetUserId));
    }
    await env.DB.batch(statements);
    if (removal && !removal.alreadyDeleted) {
        try {
            await deleteStoredAttachments(env, removalAttachments);
        }
        catch (error) {
            console.warn('Could not remove moderated message attachments from R2', error);
        }
        if (removal.type === 'channel' && removal.serverId && removal.channelId) {
            try {
                await queueBotEventForServer(env.DB, removal.serverId, 'message_delete', {
                    message_id: removal.id,
                    channel_id: removal.channelId,
                    server_id: removal.serverId,
                    deleted_by: admin.id,
                }, { channelId: removal.channelId });
            }
            catch (error) {
                console.warn('Could not dispatch moderated message_delete bot event', error);
            }
        }
    }
    await recomputeUserSafetyCache(env.DB, targetUserId, now);
    try {
        const targetUser = await env.DB.prepare('SELECT username, discriminator FROM users WHERE id = ? LIMIT 1')
            .bind(targetUserId).first();
        const resultLines = [];
        if (contentRemoved)
            resultLines.push('The reported message was removed.');
        if (applyLimitation)
            resultLines.push(accountRestrictionSummary(restrictionMask, restrictionUntil));
        if (accountAction === 'suspension')
            resultLines.push(`Your account is suspended until ${new Date(suspensionUntil).toISOString()}.`);
        if (accountAction === 'ban')
            resultLines.push('Your account has been permanently suspended.');
        const resultText = resultLines.length ? `\n\n${resultLines.join('\n')}` : '';
        await sendSystemDm(env.DB, targetUserId, {
            kind: 'violation',
            color: '#da373c',
            dedupeKey: `violation:${violationId}`,
            title: `You broke the rules for ${violationType}`,
            description: `Hello, ${targetUser?.username || 'user'}#${targetUser?.discriminator || '0000'}, it looks like your behavior broke our rules, and we have decided to take action.${resultText}\n\nYou can review the action and submit an appeal in your Safety Hub.`,
            actions: [{ label: 'safety hub', action: 'safety_hub' }],
        });
    }
    catch (error) {
        console.warn('Could not send violation DM', error);
    }
    try {
        const emailActions = [];
        if (contentRemoved)
            emailActions.push('Content removal');
        if (applyLimitation)
            emailActions.push('Account limitation');
        if (accountAction === 'suspension')
            emailActions.push('Suspension');
        if (accountAction === 'ban')
            emailActions.push('Permanent suspension');
        if (!emailActions.length)
            emailActions.push('Warning');
        await sendVerifiedAccountEmail(env, targetUserId, {
            type: 'violation',
            violation_type: violationType,
            severity,
            reason,
            action: emailActions.join(' + '),
            content_removed: contentRemoved,
            restriction_summary: applyLimitation ? accountRestrictionSummary(restrictionMask, restrictionUntil) : '',
            restriction_until: restrictionUntil,
            suspension_until: suspensionUntil,
            standing_expires_at: standingExpiresAt,
        });
    }
    catch (error) {
        console.warn('Could not send violation email', error);
    }
    return json({
        id: violationId,
        expires_at: standingExpiresAt,
        content_removed: contentRemoved,
        removed_content_type: removedContentType,
        removed_content_id: removedContentId,
        restriction_mask: applyLimitation ? restrictionMask : 0,
        restriction_until: restrictionUntil,
        suspension_until: suspensionUntil,
        account_action: accountAction,
    }, 201);
}

async function hydrateMessageSocial(db, messageType, messages) {
    if (!messages.length)
        return messages;
    const ids = messages.map(m => String(m.id || '')).filter(Boolean);
    const byId = new Map(messages.map(m => [String(m.id), m]));
    for (const message of messages) {
        message.reactions = [];
        message.reply = null;
    }
    for (let offset = 0; offset < ids.length; offset += 70) {
        const chunk = ids.slice(offset, offset + 70);
        const marks = chunk.map(() => '?').join(',');
        const reactions = await db.prepare(`SELECT message_id,emoji,COUNT(*) AS count,GROUP_CONCAT(user_id) AS user_ids FROM message_reactions WHERE message_type=? AND message_id IN (${marks}) GROUP BY message_id,emoji ORDER BY MIN(created_at)`).bind(messageType, ...chunk).all();
        for (const row of reactions.results || []) {
            const m = byId.get(String(row.message_id));
            if (m)
                m.reactions.push({ emoji: row.emoji, count: Number(row.count || 0), user_ids: String(row.user_ids || '').split(',').filter(Boolean) });
        }
    }
    const replyIds = [...new Set(messages.map(m => String(m.reply_to_id || '')).filter(Boolean))];
    if (replyIds.length) {
        const table = messageType === 'dm' ? 'dm_messages' : 'messages';
        for (let offset = 0; offset < replyIds.length; offset += 70) {
            const chunk = replyIds.slice(offset, offset + 70);
            const marks = chunk.map(() => '?').join(',');
            const rows = await db.prepare(`SELECT m.id,m.content,m.deleted_at,u.display_name,u.username FROM ${table} m JOIN users u ON u.id=m.user_id WHERE m.id IN (${marks})`).bind(...chunk).all();
            const map = new Map((rows.results || []).map(r => [String(r.id), r]));
            for (const m of messages) {
                const r = map.get(String(m.reply_to_id || ''));
                if (r)
                    m.reply = { id: r.id, display_name: r.display_name || r.username, content: r.deleted_at ? '[Deleted message]' : cleanText(r.content || '[Attachment]', 180, true) };
            }
        }
    }
    const userIds = [...new Set(messages.map(message => String(message.user_id || '')).filter(Boolean))];
    if (userIds.length) {
        for (let offset = 0; offset < userIds.length; offset += 70) {
            const chunk = userIds.slice(offset, offset + 70), marks = chunk.map(() => '?').join(',');
            const bots = await db.prepare(`SELECT id,name,bot_user_id,bot_type FROM bot_applications WHERE bot_user_id IN (${marks})`).bind(...chunk).all();
            const byUser = new Map((bots.results || []).map(bot => [String(bot.bot_user_id), bot]));
            for (const message of messages) {
                const bot = byUser.get(String(message.user_id || ''));
                if (bot) {
                    message.is_bot = 1;
                    message.bot_id = bot.id;
                    message.bot_name = bot.name;
                    message.bot_type = bot.bot_type;
                }
            }
        }
    }
    return messages;
}

async function addMessageReaction(request, env, user, type, messageId) {
    const body = await readJson(request);
    const emoji = cleanText(body?.emoji || '', 128);
    if (!emoji)
        return json({ error: 'Choose a reaction' }, 400);
    const table = type === 'dm' ? 'dm_messages' : 'messages';
    const message = await env.DB.prepare(`SELECT * FROM ${table} WHERE id=? AND deleted_at IS NULL`).bind(messageId).first();
    if (!message)
        return json({ error: 'Message not found' }, 404);
    if (type === 'dm' && !(await isDmParticipant(env.DB, user.id, message.conversation_id)))
        return json({ error: 'Message not found' }, 404);
    if (type === 'dm') {
        const peer = await env.DB.prepare('SELECT user_id FROM dm_participants WHERE conversation_id=? AND user_id!=? LIMIT 1').bind(message.conversation_id, user.id).first();
        if (peer?.user_id && await usersBlocked(env.DB, user.id, peer.user_id))
            return json({ error: 'Reactions are unavailable because one of you blocked the other user' }, 403);
    }
    if (type === 'channel' && !(await hasChannelPermission(env.DB, user.id, message.channel_id, PERMISSIONS.VIEW_CHANNEL)))
        return json({ error: 'Message not found' }, 404);
    await env.DB.prepare('INSERT OR IGNORE INTO message_reactions (message_type,message_id,user_id,emoji,created_at) VALUES (?,?,?,?,?)').bind(type, messageId, user.id, emoji, Date.now()).run();
    if (type === 'channel') {
        const channel = await env.DB.prepare('SELECT server_id FROM channels WHERE id=?').bind(message.channel_id).first();
        if (channel) {
            const actor = await botGatewayPublicUser(env.DB, user.id);
            await queueBotEventForServer(env.DB, channel.server_id, 'reaction_add', { message_id: messageId, channel_id: message.channel_id, server_id: channel.server_id, emoji, user: actor }, { channelId: message.channel_id });
        }
    }
    return json({ ok: true });
}

async function removeMessageReaction(request, env, user, type, messageId) {
    const body = await readJson(request);
    const emoji = cleanText(body?.emoji || '', 128);
    if (!emoji)
        return json({ error: 'Choose a reaction' }, 400);
    const table = type === 'dm' ? 'dm_messages' : 'messages';
    const message = await env.DB.prepare(`SELECT * FROM ${table} WHERE id=? AND deleted_at IS NULL`).bind(messageId).first();
    if (!message)
        return json({ error: 'Message not found' }, 404);
    if (type === 'dm' && !(await isDmParticipant(env.DB, user.id, message.conversation_id)))
        return json({ error: 'Message not found' }, 404);
    if (type === 'channel' && !(await hasChannelPermission(env.DB, user.id, message.channel_id, PERMISSIONS.VIEW_CHANNEL)))
        return json({ error: 'Message not found' }, 404);
    await env.DB.prepare('DELETE FROM message_reactions WHERE message_type=? AND message_id=? AND user_id=? AND emoji=?').bind(type, messageId, user.id, emoji).run();
    if (type === 'channel') {
        const channel = await env.DB.prepare('SELECT server_id FROM channels WHERE id=?').bind(message.channel_id).first();
        if (channel) {
            const actor = await botGatewayPublicUser(env.DB, user.id);
            await queueBotEventForServer(env.DB, channel.server_id, 'reaction_remove', { message_id: messageId, channel_id: message.channel_id, server_id: channel.server_id, emoji, user: actor }, { channelId: message.channel_id });
        }
    }
    return json({ ok: true });
}

async function adminGetUserProfile(env, admin, userId) {
    const user = await env.DB.prepare(`SELECT id,username,discriminator,display_name,avatar_url,equipped_decoration,diamonds,banner_image_url,banner_color_1,banner_color_2,about,role,account_status,suspension_until,created_at,email,email_verified FROM users WHERE id=?`).bind(userId).first();
    if (!user)
        return json({ error: 'User not found' }, 404);
    const [violations, servers, friends] = await Promise.all([
        env.DB.prepare('SELECT id,violation_type,severity,reason,action,status,evidence_text,moderator_note,content_removed,removed_content_type,removed_content_id,content_removed_at,restriction_mask,restriction_until,suspension_until,created_at,expires_at FROM violations WHERE user_id=? ORDER BY created_at DESC LIMIT 50').bind(userId).all(),
        env.DB.prepare('SELECT s.id,s.name,sm.joined_at,(s.owner_id=? ) AS is_owner FROM server_members sm JOIN servers s ON s.id=sm.server_id WHERE sm.user_id=? ORDER BY sm.joined_at DESC LIMIT 100').bind(userId, userId).all(),
        env.DB.prepare("SELECT COUNT(*) AS count FROM friendships WHERE status='accepted' AND (requester_id=? OR addressee_id=?)").bind(userId, userId).first()
    ]);
    return json({ user: { ...user, email_verified: Boolean(user.email_verified) }, violations: violations.results || [], servers: servers.results || [], friend_count: Number(friends?.count || 0) });
}

async function adminEnforceServerReport(request, env, admin, serverId) {
    const body = await readJson(request) || {};
    const actions = Array.isArray(body.actions) ? body.actions : [];
    const ownerPunishment = body.owner_punishment || { action: (body.punish_scope ? 'warning' : 'none'), duration_hours: 168 };
    const memberPunishment = body.member_punishment || { action: body.punish_scope === 'all' ? 'warning' : 'none', duration_hours: 24 };
    const allowed = new Set(['none', 'warning', 'suspension', 'ban']);
    if (!allowed.has(String(ownerPunishment.action)) || !allowed.has(String(memberPunishment.action)))
        return json({ error: 'Invalid account punishment' }, 400);
    const violationTitle = cleanText(body.violation_title || body.title || body.reason || 'Community Guidelines violation', 80);
    const evidenceNote = cleanText(body.evidence_text || body.details || '', 1400, true);
    const reportId = body.report_id || null;
    if (!violationTitle)
        return json({ error: 'Violation title is required' }, 400);
    const server = await env.DB.prepare('SELECT id,name,owner_id,icon_url,banner_url FROM servers WHERE id=?').bind(serverId).first();
    if (!server)
        return json({ error: 'Server not found' }, 404);
    if (reportId) {
        const report = await env.DB.prepare('SELECT id,target_type,target_id FROM reports WHERE id=? LIMIT 1').bind(reportId).first();
        if (!report)
            return json({ error: 'Report not found' }, 404);
        if (String(report.target_type) !== 'server' || String(report.target_id) !== String(serverId)) {
            return json({ error: 'This report does not target this server' }, 400);
        }
    }
    const now = Date.now(), statements = [], violations = [], protectedTargets = [];
    const actionNotices = [];
    if (actions.includes('disable_invites')) {
        statements.push(env.DB.prepare('DELETE FROM server_invites WHERE server_id=?').bind(serverId));
        actionNotices.push('All server invites were removed.');
    }
    if (actions.includes('reset_name')) {
        statements.push(env.DB.prepare("UPDATE servers SET name='Community Server' WHERE id=?").bind(serverId));
        actionNotices.push("The server's name was reset.");
    }
    if (actions.includes('delete_server'))
        actionNotices.push('The server was deleted.');
    const members = (await env.DB.prepare('SELECT sm.user_id FROM server_members sm LEFT JOIN bot_applications b ON b.bot_user_id=sm.user_id WHERE sm.server_id=? AND b.id IS NULL AND sm.user_id!=?').bind(serverId, SYSTEM_USER_ID).all()).results || [];
    const targets = members.map(x => ({ uid: x.user_id, isOwner: String(x.user_id) === String(server.owner_id) }));
    if (!targets.some(x => x.isOwner) && server.owner_id)
        targets.push({ uid: server.owner_id, isOwner: true });
    for (const target of targets) {
        if ([SYSTEM_USER_ID, BYTE_USER_ID, WEBHOOK_USER_ID].includes(String(target.uid || '')))
            continue;
        const targetAccount = await accountManagementTarget(env, target.uid);
        if (!targetAccount) {
            protectedTargets.push({ user_id: target.uid, reason: 'user_not_found' });
            continue;
        }
        const targetRole = effectiveAccountRole(targetAccount);
        if (targetRole === 'owner' ||
            String(target.uid) === String(admin.id) ||
            accountStaffRank(admin) <= accountStaffRank(targetAccount)) {
            protectedTargets.push({ user_id: target.uid, role: targetRole, reason: 'staff_hierarchy' });
            continue;
        }
        const config = target.isOwner ? ownerPunishment : memberPunishment;
        const action = String(config.action || 'none');
        const limitationMask = parseAccountRestrictionMask(config.limitations || config.restrictions || []);
        if (action === 'none' && !limitationMask)
            continue;
        const duration = Math.max(1, Math.min(Number(config.duration_hours) || 24, 8760));
        const limitationDuration = Math.max(1, Math.min(Number(config.limitation_duration_hours) || 24, 744));
        const severity = action === 'ban' ? 'critical' : action === 'suspension' ? 'high' : 'medium';
        const expiresAt = action === 'ban' ? null : now + violationLifetimeDays(severity) * 86400000;
        const suspensionUntil = action === 'suspension' ? now + duration * 3600000 : null;
        const limitationUntil = limitationMask ? now + limitationDuration * 3600000 : null;
        const restrictionUntil = limitationUntil || suspensionUntil;
        const violationId = prefixedId('vio');
        const storedAction = action === 'none' && limitationMask ? 'timeout' : action;
        const evidence = JSON.stringify({ kind: 'server', server_id: server.id, server_name: server.name, server_icon_url: server.icon_url || '', content: [...actionNotices, evidenceNote].filter(Boolean).join('\n'), actions, recipient_role: target.isOwner ? 'owner' : 'member' });
        statements.push(env.DB.prepare(`INSERT INTO violations(id,user_id,report_id,violation_type,severity,reason,action,evidence_text,status,expires_at,restriction_mask,restriction_until,reversed_at,created_by,created_at) VALUES(?,?,?,?,?,?,?,?, 'active',?,?,?,NULL,?,?)`).bind(violationId, target.uid, reportId, violationTitle, severity, violationTitle, storedAction, evidence, expiresAt, limitationMask, restrictionUntil, admin.id, now));
        if (limitationMask) {
            statements.push(env.DB.prepare(`INSERT INTO account_limitations(id,user_id,violation_id,limitation_mask,status,expires_at,created_by,created_at,updated_at) VALUES(?,?,?,?,'active',?,?,?,?)`).bind(prefixedId('lim'), target.uid, violationId, limitationMask, limitationUntil, admin.id, now, now));
        }
        if (action === 'suspension') {
            statements.push(env.DB.prepare("UPDATE users SET account_status='suspended',suspension_until=? WHERE id=?").bind(suspensionUntil, target.uid));
            statements.push(env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(target.uid));
        }
        if (action === 'ban') {
            statements.push(env.DB.prepare("UPDATE users SET account_status='banned',suspension_until=NULL WHERE id=?").bind(target.uid));
            statements.push(env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(target.uid));
        }
        violations.push({ uid: target.uid, violationId, isOwner: target.isOwner, action, severity, restrictionUntil, limitationMask, limitationUntil });
    }
    let deletedServerAttachments = [];
    if (actions.includes('delete_server')) {
        try {
            const attachmentRows = await env.DB.prepare(`
        SELECT ma.storage_key
        FROM message_attachments ma
        JOIN messages m ON m.id=ma.message_id
        JOIN channels c ON c.id=m.channel_id
        WHERE ma.message_type='channel' AND c.server_id=?
      `).bind(serverId).all();
            deletedServerAttachments = attachmentRows.results || [];
        }
        catch (error) {
            console.warn('Could not list server attachments before enforcement delete', error);
        }
        statements.push(env.DB.prepare("DELETE FROM message_reactions WHERE message_type='channel' AND message_id IN (SELECT id FROM messages WHERE channel_id IN (SELECT id FROM channels WHERE server_id=?))").bind(serverId));
        statements.push(env.DB.prepare(`
      DELETE FROM message_attachments
      WHERE message_type='channel'
        AND message_id IN (
          SELECT m.id FROM messages m
          JOIN channels c ON c.id=m.channel_id
          WHERE c.server_id=?
        )
    `).bind(serverId));
        statements.push(env.DB.prepare('DELETE FROM servers WHERE id=?').bind(serverId));
    }
    statements.push(env.DB.prepare('INSERT INTO admin_actions (id,admin_id,action,target_user_id,report_id,notes,created_at) VALUES (?,?,?,?,?,?,?)').bind(prefixedId('act'), admin.id, `server_enforcement:${actions.join(',') || 'violations'}`, server.owner_id, reportId, `owner=${ownerPunishment.action}; members=${memberPunishment.action}; ${violationTitle}`, now));
    if (statements.length) {
        const D1_BATCH_SIZE = 20;
        for (let offset = 0; offset < statements.length; offset += D1_BATCH_SIZE) {
            const chunk = statements.slice(offset, offset + D1_BATCH_SIZE);
            try {
                await env.DB.batch(chunk);
            }
            catch (error) {
                console.error('Server enforcement batch failed', {
                    serverId,
                    reportId,
                    offset,
                    chunkSize: chunk.length,
                    totalStatements: statements.length,
                    message: String(error?.message || error)
                });
                const detail = String(error?.message || error);
                return json({
                    error: `Server enforcement failed in database batch ${Math.floor(offset / D1_BATCH_SIZE) + 1}: ${detail}`,
                    code: 'SERVER_ENFORCEMENT_DB_FAILED',
                    detail,
                    failed_batch: Math.floor(offset / D1_BATCH_SIZE) + 1
                }, 500);
            }
        }
    }
    for (const item of violations) {
        await recomputeUserSafetyCache(env.DB, item.uid, now);
        try {
            await sendSystemDm(env.DB, item.uid, { kind: 'violation', color: '#da373c', dedupeKey: `server-violation:${item.violationId}`, title: `${item.isOwner ? 'Your server' : 'A server you joined'} broke the rules for ${violationTitle}`, description: [...actionNotices, item.action === 'ban' ? 'Your account was permanently suspended.' : item.action === 'suspension' ? `Your account was suspended until ${new Date(item.restrictionUntil).toISOString()}.` : item.action === 'warning' ? 'Your account received a warning.' : '', item.limitationMask ? accountRestrictionSummary(item.limitationMask, item.limitationUntil) : '', evidenceNote].filter(Boolean).join('\n\n'), actions: [{ label: 'Safety Hub', action: 'safety_hub' }] });
        }
        catch (error) {
            console.warn('Could not send server enforcement DM', error);
        }
    }
    if (actions.includes('delete_server') && deletedServerAttachments.length) {
        try {
            await deleteStoredAttachments(env, deletedServerAttachments);
        }
        catch (error) {
            console.warn('Could not remove deleted-server attachments from R2', error);
        }
    }
    return json({
        ok: true,
        affected_users: violations.length,
        skipped_protected_users: protectedTargets,
        owner_action: ownerPunishment.action,
        member_action: memberPunishment.action,
        server_actions: actionNotices
    });
}

let v240SchemaReady = null;

async function ensureV240Schema(db) {
    if (!v240SchemaReady) {
        v240SchemaReady = (async () => {
            const iconColumn = await db.prepare(`
        SELECT name FROM pragma_table_info('server_roles') WHERE name = 'icon_url' LIMIT 1
      `).first();
            if (!iconColumn) {
                try {
                    await db.prepare('ALTER TABLE server_roles ADD COLUMN icon_url TEXT').run();
                }
                catch (error) {
                    if (!/duplicate column name/i.test(String(error?.message || error)))
                        throw error;
                }
            }
        })().catch(error => {
            v240SchemaReady = null;
            throw error;
        });
    }
    return v240SchemaReady;
}

let notificationSchemaReady = null;

async function ensureNotificationSchema(db) {
    if (!notificationSchemaReady) {
        notificationSchemaReady = (async () => {
            const statements = [
                `CREATE TABLE IF NOT EXISTS server_notification_settings (
          server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE,
          user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          level TEXT NOT NULL DEFAULT 'mentions'
            CHECK (level IN ('mentions', 'all', 'mute')),
          updated_at INTEGER NOT NULL,
          PRIMARY KEY (server_id, user_id)
        )`,
                `CREATE INDEX IF NOT EXISTS server_notification_settings_user_idx
         ON server_notification_settings(user_id, level)`,
                `CREATE TABLE IF NOT EXISTS notifications (
          id TEXT PRIMARY KEY,
          user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          type TEXT NOT NULL CHECK (type IN ('dm', 'mention', 'role', 'everyone', 'server_message')),
          actor_id TEXT REFERENCES users(id) ON DELETE SET NULL,
          server_id TEXT,
          channel_id TEXT,
          dm_id TEXT,
          message_id TEXT,
          title TEXT NOT NULL,
          body TEXT NOT NULL DEFAULT '',
          created_at INTEGER NOT NULL,
          read_at INTEGER
        )`,
                `CREATE INDEX IF NOT EXISTS notifications_user_unread_idx
         ON notifications(user_id, read_at, created_at DESC)`,
                `CREATE INDEX IF NOT EXISTS notifications_server_unread_idx
         ON notifications(user_id, server_id, read_at, created_at DESC)`,
                `CREATE INDEX IF NOT EXISTS notifications_channel_unread_idx
         ON notifications(user_id, channel_id, read_at, created_at DESC)`,
                `CREATE INDEX IF NOT EXISTS notifications_dm_unread_idx
         ON notifications(user_id, dm_id, read_at, created_at DESC)`,
                `CREATE UNIQUE INDEX IF NOT EXISTS notifications_message_user_unique
         ON notifications(message_id, user_id) WHERE message_id IS NOT NULL`,
            ];
            for (const statement of statements)
                await db.prepare(statement).run();
        })().catch(error => {
            notificationSchemaReady = null;
            throw error;
        });
    }
    return notificationSchemaReady;
}

let callSchemaReady = null;

async function ensureCallSchema(db) {
    if (!callSchemaReady) {
        callSchemaReady = (async () => {
            const typeColumn = await db.prepare(`
        SELECT name FROM pragma_table_info('channels') WHERE name = 'type' LIMIT 1
      `).first();
            if (!typeColumn) {
                try {
                    await db.prepare(`
            ALTER TABLE channels
            ADD COLUMN type TEXT NOT NULL DEFAULT 'text'
            CHECK (type IN ('text', 'voice'))
          `).run();
                }
                catch (error) {
                    if (!/duplicate column name/i.test(String(error?.message || error)))
                        throw error;
                }
            }
            const statements = [
                `CREATE INDEX IF NOT EXISTS channels_server_type_position_idx
         ON channels(server_id, type, position)`,
                `CREATE TABLE IF NOT EXISTS call_sessions (
          id TEXT PRIMARY KEY,
          room_id TEXT NOT NULL UNIQUE,
          dm_id TEXT NOT NULL REFERENCES dm_conversations(id) ON DELETE CASCADE,
          caller_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          callee_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          status TEXT NOT NULL DEFAULT 'ringing'
            CHECK (status IN ('ringing', 'active', 'rejected', 'missed', 'ended')),
          created_at INTEGER NOT NULL,
          answered_at INTEGER,
          ended_at INTEGER,
          expires_at INTEGER NOT NULL,
          CHECK (caller_id != callee_id)
        )`,
                `CREATE INDEX IF NOT EXISTS call_sessions_callee_status_idx
         ON call_sessions(callee_id, status, created_at DESC)`,
                `CREATE INDEX IF NOT EXISTS call_sessions_caller_status_idx
         ON call_sessions(caller_id, status, created_at DESC)`,
                `CREATE INDEX IF NOT EXISTS call_sessions_dm_created_idx
         ON call_sessions(dm_id, created_at DESC)`,
                `CREATE UNIQUE INDEX IF NOT EXISTS call_sessions_one_open_dm_idx
         ON call_sessions(dm_id) WHERE status IN ('ringing', 'active')`,
                `CREATE TABLE IF NOT EXISTS call_participants (
          room_id TEXT NOT NULL,
          user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          display_name TEXT NOT NULL,
          avatar_url TEXT NOT NULL DEFAULT '',
          muted INTEGER NOT NULL DEFAULT 0 CHECK (muted IN (0, 1)),
          camera INTEGER NOT NULL DEFAULT 0 CHECK (camera IN (0, 1)),
          screen INTEGER NOT NULL DEFAULT 0 CHECK (screen IN (0, 1)),
          joined_at INTEGER NOT NULL,
          last_seen INTEGER NOT NULL,
          PRIMARY KEY (room_id, user_id)
        )`,
                `CREATE INDEX IF NOT EXISTS call_participants_room_seen_idx
         ON call_participants(room_id, last_seen DESC)`,
                `CREATE TABLE IF NOT EXISTS call_signals (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          room_id TEXT NOT NULL,
          sender_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          recipient_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          signal_type TEXT NOT NULL CHECK (signal_type IN ('offer', 'answer', 'ice')),
          payload TEXT NOT NULL,
          created_at INTEGER NOT NULL
        )`,
                `CREATE INDEX IF NOT EXISTS call_signals_recipient_poll_idx
         ON call_signals(room_id, recipient_id, id)`,
                `CREATE INDEX IF NOT EXISTS call_signals_created_idx
         ON call_signals(created_at)`,
                `CREATE TABLE IF NOT EXISTS dm_read_states (
          conversation_id TEXT NOT NULL REFERENCES dm_conversations(id) ON DELETE CASCADE,
          user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
          last_read_at INTEGER NOT NULL DEFAULT 0,
          PRIMARY KEY (conversation_id, user_id)
        )`,
                `CREATE INDEX IF NOT EXISTS dm_read_states_user_idx
         ON dm_read_states(user_id, last_read_at DESC)`,
            ];
            for (const statement of statements)
                await db.prepare(statement).run();
        })().catch(error => {
            callSchemaReady = null;
            throw error;
        });
    }
    return callSchemaReady;
}

const CALL_PARTICIPANT_TIMEOUT_MS = 45 * 1000;

const CALL_SIGNAL_TTL_MS = 2 * 60 * 1000;

async function createCallTicket(request, env, user) {
    const body = await readJson(request);
    const kind = String(body?.kind || '');
    const targetId = String(body?.target_id || '');
    if (kind !== 'voice')
        return json({ error: 'Only server voice rooms can be joined directly' }, 400);
    const channel = await env.DB.prepare(`
    SELECT id, server_id, name, type FROM channels WHERE id = ? LIMIT 1
  `).bind(targetId).first();
    if (!channel || channel.type !== 'voice')
        return json({ error: 'Voice channel not found' }, 404);
    if (!(await hasChannelPermission(env.DB, user.id, channel.id, PERMISSIONS.VIEW_CHANNEL))) {
        return json({ error: 'You cannot connect to this voice channel' }, 403);
    }
    const roomId = `voice:${channel.id}`;
    return json({ room_id: roomId, kind: 'voice', title: channel.name });
}

async function getCallIceServers(env, user = null) {
    const fallback = {
        iceServers: [{
                urls: [
                    'stun:stun.cloudflare.com:3478',
                    'stun:stun.l.google.com:19302',
                ],
            }],
        turn_configured: false,
        relay_available: false,
        warning: 'TURN_NOT_CONFIGURED',
    };
    if (!env.TURN_KEY_ID || !env.TURN_KEY_API_TOKEN)
        return json(fallback);
    try {
        const response = await fetch(`https://rtc.live.cloudflare.com/v1/turn/keys/${encodeURIComponent(env.TURN_KEY_ID)}/credentials/generate-ice-servers`, {
            method: 'POST',
            headers: {
                Authorization: `Bearer ${env.TURN_KEY_API_TOKEN}`,
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({ ttl: 86400 }),
        });
        if (!response.ok) {
            const details = await response.text().catch(() => '');
            throw new Error(`TURN credential request failed (${response.status})${details ? `: ${details.slice(0, 240)}` : ''}`);
        }
        const data = await response.json();
        if (!Array.isArray(data.iceServers))
            throw new Error('TURN response did not contain iceServers');
        const iceServers = data.iceServers.map(server => {
            const urls = (Array.isArray(server.urls) ? server.urls : [server.urls])
                .filter(Boolean)
                .filter(url => !/(?:stun|turn):[^?]+:53(?:\?|$)/i.test(String(url)));
            return { ...server, urls };
        }).filter(server => Array.isArray(server.urls) && server.urls.length);
        const relayAvailable = iceServers.some(server => server.urls.some(url => /^turns?:/i.test(String(url))) &&
            server.username && server.credential);
        if (!relayAvailable)
            throw new Error('TURN response did not contain usable relay credentials');
        return json({
            iceServers,
            turn_configured: true,
            relay_available: true,
            credential_ttl_seconds: 86400,
        });
    }
    catch (error) {
        console.warn('TURN credential generation failed; using STUN only', {
            user_id: user?.id || null,
            message: error?.message || String(error),
        });
        return json({
            ...fallback,
            warning: 'TURN_CREDENTIAL_GENERATION_FAILED',
        });
    }
}

async function startDmCall(env, user, dmId, ctx) {
    if (!(await isDmParticipant(env.DB, user.id, dmId)))
        return json({ error: 'DM not found' }, 404);
    const peer = await env.DB.prepare('SELECT user_id FROM dm_participants WHERE conversation_id=? AND user_id!=? LIMIT 1').bind(dmId, user.id).first();
    if (peer?.user_id && await usersBlocked(env.DB, user.id, peer.user_id))
        return json({ error: 'Calls are unavailable because one of you blocked the other user' }, 403);
    await expireRingingCalls(env.DB);
    const other = await env.DB.prepare(`
    SELECT u.id, u.username, u.discriminator, u.username_migrated, u.previous_username_tag, u.display_name, u.display_name_style, u.avatar_url,u.equipped_decoration
    FROM dm_participants p
    JOIN users u ON u.id = p.user_id
    WHERE p.conversation_id = ? AND p.user_id != ? AND u.account_status = 'active'
    LIMIT 1
  `).bind(dmId, user.id).first();
    if (!other)
        return json({ error: 'The other DM participant is unavailable' }, 404);
    if (other.id === SYSTEM_USER_ID)
        return json({ error: 'The Orbyte system account cannot join calls' }, 403);
    const existing = await env.DB.prepare(`
    SELECT id, status FROM call_sessions
    WHERE dm_id = ? AND status IN ('ringing','active')
    ORDER BY created_at DESC LIMIT 1
  `).bind(dmId).first();
    if (existing)
        return json({ error: 'There is already an active call in this DM', call_id: existing.id }, 409);
    const now = Date.now();
    const id = prefixedId('call');
    const roomId = `dmcall:${id}`;
    try {
        await env.DB.prepare(`
      INSERT INTO call_sessions (
        id, room_id, dm_id, caller_id, callee_id, status, created_at, expires_at
      ) VALUES (?, ?, ?, ?, ?, 'ringing', ?, ?)
    `).bind(id, roomId, dmId, user.id, other.id, now, now + 45000).run();
    }
    catch (error) {
        if (String(error?.message || error).toLowerCase().includes('unique')) {
            return json({ error: 'There is already an active call in this DM' }, 409);
        }
        throw error;
    }
    const callerName = String(user.display_name || user.username || 'Someone');
    schedulePush(ctx, env, [other.id], {
        title: `${callerName} started a call`,
        body: `${callerName} started a call. Click the notification to join`,
        data: {
            kind: 'call',
            call_id: id,
            dm_id: dmId,
            caller_id: user.id,
            caller_name: callerName,
            url: `https://orbytechat.pages.dev/mobile.html?join_call=${encodeURIComponent(id)}`
        }
    });
    return json({
        call: { id, room_id: roomId, dm_id: dmId, status: 'ringing', caller_id: user.id, callee_id: other.id, created_at: now },
        peer: other,
    }, 201);
}

async function getIncomingCalls(env, user) {
    await expireRingingCalls(env.DB);
    const result = await env.DB.prepare(`
    SELECT c.id, c.room_id, c.dm_id, c.status, c.created_at, c.expires_at,
           u.id AS caller_id, u.username, u.discriminator, u.display_name, u.avatar_url, u.equipped_decoration
    FROM call_sessions c
    JOIN users u ON u.id = c.caller_id
    WHERE c.callee_id = ? AND c.status = 'ringing' AND c.expires_at > ?
    ORDER BY c.created_at DESC
    LIMIT 3
  `).bind(user.id, Date.now()).all();
    return json({ calls: result.results || [] });
}

async function getCallStatus(env, user, callId) {
    await expireRingingCalls(env.DB);
    const call = await readCallForUser(env.DB, callId, user.id);
    if (!call)
        return json({ error: 'Call not found' }, 404);
    return json({ call });
}

async function updateCallState(env, user, callId, action) {
    const call = await readCallForUser(env.DB, callId, user.id);
    if (!call)
        return json({ error: 'Call not found' }, 404);
    const now = Date.now();
    if (action === 'accept') {
        if (call.callee_id !== user.id)
            return json({ error: 'Only the recipient can accept this call' }, 403);
        if (call.status !== 'ringing' || call.expires_at <= now) {
            await expireRingingCalls(env.DB);
            return json({ error: 'This call is no longer ringing' }, 409);
        }
        await env.DB.prepare(`
      UPDATE call_sessions SET status = 'active', answered_at = ? WHERE id = ? AND status = 'ringing'
    `).bind(now, callId).run();
        return json({ ok: true, room_id: call.room_id, call: { ...call, status: 'active', answered_at: now } });
    }
    if (action === 'reject') {
        if (call.callee_id !== user.id)
            return json({ error: 'Only the recipient can reject this call' }, 403);
        if (call.status === 'ringing') {
            await env.DB.prepare(`UPDATE call_sessions SET status = 'rejected', ended_at = ? WHERE id = ?`).bind(now, callId).run();
        }
        return json({ ok: true });
    }
    if (action === 'end') {
        if (!['ended', 'rejected', 'missed'].includes(call.status)) {
            await env.DB.prepare(`UPDATE call_sessions SET status = 'ended', ended_at = ? WHERE id = ?`).bind(now, callId).run();
        }
        await env.DB.batch([
            env.DB.prepare('DELETE FROM call_participants WHERE room_id = ?').bind(call.room_id),
            env.DB.prepare('DELETE FROM call_signals WHERE room_id = ?').bind(call.room_id),
        ]);
        return json({ ok: true });
    }
    return json({ error: 'Unknown call action' }, 400);
}

async function expireRingingCalls(db) {
    const now = Date.now();
    await db.batch([
        db.prepare(`
      UPDATE call_sessions SET status = 'missed', ended_at = ?
      WHERE status = 'ringing' AND expires_at <= ?
    `).bind(now, now),
        db.prepare(`
      UPDATE call_sessions SET status = 'ended', ended_at = ?
      WHERE status = 'active' AND created_at < ?
    `).bind(now, now - 6 * 60 * 60 * 1000),
        db.prepare('DELETE FROM call_participants WHERE last_seen < ?').bind(now - CALL_PARTICIPANT_TIMEOUT_MS),
        db.prepare('DELETE FROM call_signals WHERE created_at < ?').bind(now - CALL_SIGNAL_TTL_MS),
    ]);
}

async function readCallForUser(db, callId, userId) {
    return db.prepare(`
    SELECT id, room_id, dm_id, caller_id, callee_id, status,
           created_at, answered_at, ended_at, expires_at
    FROM call_sessions
    WHERE id = ? AND (caller_id = ? OR callee_id = ?)
    LIMIT 1
  `).bind(callId, userId, userId).first();
}

async function callRoomAccess(db, userId, roomId) {
    const voiceMatch = roomId.match(/^voice:(chn_[A-Za-z0-9]+)$/);
    if (voiceMatch) {
        const channel = await db.prepare('SELECT id, name, type FROM channels WHERE id = ? LIMIT 1').bind(voiceMatch[1]).first();
        if (!channel || channel.type !== 'voice')
            return null;
        if (!(await hasChannelPermission(db, userId, channel.id, PERMISSIONS.VIEW_CHANNEL)))
            return null;
        return { kind: 'voice', title: channel.name, channel_id: channel.id };
    }
    const dmMatch = roomId.match(/^dmcall:(call_[A-Za-z0-9]+)$/);
    if (dmMatch) {
        const call = await db.prepare(`
      SELECT id, room_id, dm_id, caller_id, callee_id, status, expires_at
      FROM call_sessions
      WHERE id = ? AND room_id = ? AND (caller_id = ? OR callee_id = ?)
      LIMIT 1
    `).bind(dmMatch[1], roomId, userId, userId).first();
        if (!call || !['ringing', 'active'].includes(call.status))
            return null;
        if (call.callee_id === userId && call.status !== 'active')
            return null;
        if (call.status === 'ringing' && call.expires_at <= Date.now())
            return null;
        return { kind: 'dm', call };
    }
    return null;
}

async function cleanupCallRoom(db, roomId) {
    const now = Date.now();
    await db.batch([
        db.prepare('DELETE FROM call_participants WHERE room_id = ? AND last_seen < ?').bind(roomId, now - CALL_PARTICIPANT_TIMEOUT_MS),
        db.prepare('DELETE FROM call_signals WHERE room_id = ? AND created_at < ?').bind(roomId, now - CALL_SIGNAL_TTL_MS),
    ]);
}

async function joinCallRoom(request, env, user, roomId) {
    const access = await callRoomAccess(env.DB, user.id, roomId);
    if (!access)
        return json({ error: 'You cannot join this call room' }, 403);
    await cleanupCallRoom(env.DB, roomId);
    const existing = await env.DB.prepare(`
    SELECT 1 FROM call_participants WHERE room_id = ? AND user_id = ? LIMIT 1
  `).bind(roomId, user.id).first();
    if (!existing) {
        const count = await env.DB.prepare(`
      SELECT COUNT(*) AS count FROM call_participants WHERE room_id = ?
    `).bind(roomId).first();
        if (Number(count?.count || 0) >= 8)
            return json({ error: 'This call is full' }, 429);
    }
    const now = Date.now();
    await env.DB.prepare(`
    DELETE FROM call_signals WHERE room_id = ? AND recipient_id = ?
  `).bind(roomId, user.id).run();
    await env.DB.prepare(`
    INSERT INTO call_participants (
      room_id, user_id, display_name, avatar_url, muted, camera, screen, joined_at, last_seen
    ) VALUES (?, ?, ?, ?, 0, 0, 0, ?, ?)
    ON CONFLICT(room_id, user_id) DO UPDATE SET
      display_name = excluded.display_name,
      avatar_url = excluded.avatar_url,
      muted = 0,
      camera = 0,
      screen = 0,
      joined_at = excluded.joined_at,
      last_seen = excluded.last_seen
  `).bind(roomId, user.id, user.display_name, user.avatar_url || '', now, now).run();
    const participantsResult = await env.DB.prepare(`
    SELECT user_id, display_name, avatar_url, muted, camera, screen, joined_at
    FROM call_participants
    WHERE room_id = ? AND last_seen >= ?
    ORDER BY joined_at ASC
  `).bind(roomId, now - CALL_PARTICIPANT_TIMEOUT_MS).all();
    return json({
        ok: true,
        self_id: user.id,
        room_id: roomId,
        kind: access.kind,
        cursor: 0,
        participants: (participantsResult.results || []).map(publicD1Participant),
    });
}

async function pollCallRoom(request, env, user, roomId, url) {
    const access = await callRoomAccess(env.DB, user.id, roomId);
    if (!access)
        return json({ error: 'Call room is no longer available' }, 403);
    const membership = await env.DB.prepare(`
    SELECT last_seen FROM call_participants WHERE room_id = ? AND user_id = ? LIMIT 1
  `).bind(roomId, user.id).first();
    if (!membership)
        return json({ error: 'Join the call room first', rejoin: true }, 409);
    const after = Math.max(0, Number(url.searchParams.get('after') || 0) || 0);
    const now = Date.now();
    if (now - Number(membership.last_seen || 0) >= 5000) {
        await env.DB.prepare(`
      UPDATE call_participants SET last_seen = ? WHERE room_id = ? AND user_id = ?
    `).bind(now, roomId, user.id).run();
    }
    if (Math.floor(now / 10000) !== Math.floor(Number(membership.last_seen || 0) / 10000)) {
        await cleanupCallRoom(env.DB, roomId);
    }
    const [participantsResult, signalsResult] = await Promise.all([
        env.DB.prepare(`
      SELECT user_id, display_name, avatar_url, muted, camera, screen, joined_at
      FROM call_participants
      WHERE room_id = ? AND last_seen >= ?
      ORDER BY joined_at ASC
    `).bind(roomId, now - CALL_PARTICIPANT_TIMEOUT_MS).all(),
        env.DB.prepare(`
      SELECT id, sender_id, signal_type, payload
      FROM call_signals
      WHERE room_id = ? AND recipient_id = ? AND id > ?
      ORDER BY id ASC
      LIMIT 100
    `).bind(roomId, user.id, after).all(),
    ]);
    let cursor = after;
    const signals = [];
    for (const row of signalsResult.results || []) {
        cursor = Math.max(cursor, Number(row.id || 0));
        let payload = {};
        try {
            payload = JSON.parse(row.payload || '{}');
        }
        catch { }
        const signal = { type: row.signal_type, from: row.sender_id };
        if (row.signal_type === 'ice')
            signal.candidate = payload.candidate || null;
        else
            signal.description = payload.description || null;
        signals.push(signal);
    }
    return json({
        ok: true,
        cursor,
        participants: (participantsResult.results || []).map(publicD1Participant),
        signals,
    });
}

async function sendCallRoomSignal(request, env, user, roomId) {
    const access = await callRoomAccess(env.DB, user.id, roomId);
    if (!access)
        return json({ error: 'Call room is no longer available' }, 403);
    const sender = await env.DB.prepare(`
    SELECT 1 FROM call_participants WHERE room_id = ? AND user_id = ? LIMIT 1
  `).bind(roomId, user.id).first();
    if (!sender)
        return json({ error: 'Join the call room first' }, 409);
    const body = await readJson(request);
    const type = String(body?.type || '');
    const targetId = String(body?.to || '');
    if (!['offer', 'answer', 'ice'].includes(type))
        return json({ error: 'Invalid call signal' }, 400);
    if (!targetId || targetId === user.id)
        return json({ error: 'Invalid signal recipient' }, 400);
    const recipient = await env.DB.prepare(`
    SELECT 1 FROM call_participants
    WHERE room_id = ? AND user_id = ? AND last_seen >= ?
    LIMIT 1
  `).bind(roomId, targetId, Date.now() - CALL_PARTICIPANT_TIMEOUT_MS).first();
    if (!recipient)
        return json({ error: 'The participant is no longer connected' }, 404);
    const payload = type === 'ice'
        ? { candidate: body?.candidate || null }
        : { description: body?.description || null };
    const encoded = JSON.stringify(payload);
    if (encoded.length > 90000)
        return json({ error: 'Call signal is too large' }, 413);
    await env.DB.prepare(`
    INSERT INTO call_signals (room_id, sender_id, recipient_id, signal_type, payload, created_at)
    VALUES (?, ?, ?, ?, ?, ?)
  `).bind(roomId, user.id, targetId, type, encoded, Date.now()).run();
    return json({ ok: true }, 201);
}

async function updateCallParticipantState(request, env, user, roomId) {
    const access = await callRoomAccess(env.DB, user.id, roomId);
    if (!access)
        return json({ error: 'Call room is no longer available' }, 403);
    const body = await readJson(request);
    const result = await env.DB.prepare(`
    UPDATE call_participants
    SET muted = ?, camera = ?, screen = ?, last_seen = ?
    WHERE room_id = ? AND user_id = ?
  `).bind(body?.muted ? 1 : 0, body?.camera ? 1 : 0, body?.screen ? 1 : 0, Date.now(), roomId, user.id).run();
    if (!Number(result.meta?.changes || 0))
        return json({ error: 'Join the call room first' }, 409);
    return json({ ok: true });
}

async function leaveCallRoom(env, user, roomId) {
    await env.DB.batch([
        env.DB.prepare('DELETE FROM call_participants WHERE room_id = ? AND user_id = ?').bind(roomId, user.id),
        env.DB.prepare('DELETE FROM call_signals WHERE room_id = ? AND (sender_id = ? OR recipient_id = ?)').bind(roomId, user.id, user.id),
    ]);
    return json({ ok: true });
}

function publicD1Participant(row) {
    return {
        user_id: row.user_id,
        display_name: row.display_name,
        avatar_url: row.avatar_url,
        muted: Boolean(row.muted),
        camera: Boolean(row.camera),
        screen: Boolean(row.screen),
        joined_at: Number(row.joined_at || 0),
    };
}

async function deleteAccount(request, env, user) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const password = String(body.password || '');
    const confirmation = String(body.confirmation || '').trim().toUpperCase();
    if (confirmation !== 'DELETE')
        return json({ error: 'Type DELETE to confirm account deletion' }, 400);
    if (!(await verifyPassword(password, user.password_salt, user.password_hash)))
        return json({ error: 'Password is incorrect' }, 403);
    const now = Date.now();
    const deletedUsername = `deleted_${user.id.replace(/[^a-z0-9]/gi, '').slice(-12)}_${now.toString(36)}`.slice(0, 32);
    const salt = randomBase64(16);
    const passwordHash = await hashPassword(randomBase64Url(48), salt);
    const ownedServers = await env.DB.prepare('SELECT id FROM servers WHERE owner_id=?').bind(user.id).all();
    for (const server of ownedServers.results || []) {
        try {
            await deleteServer(env, user, server.id);
        }
        catch (error) {
            console.warn('Could not delete owned server during account deletion', server.id, error);
        }
    }
    await env.DB.batch([
        env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM friendships WHERE requester_id=? OR addressee_id=?').bind(user.id, user.id),
        env.DB.prepare('DELETE FROM user_blocks WHERE blocker_id=? OR blocked_id=?').bind(user.id, user.id),
        env.DB.prepare('DELETE FROM server_member_roles WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM server_members WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM notifications WHERE user_id=? OR actor_id=?').bind(user.id, user.id),
        env.DB.prepare('DELETE FROM typing_states WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM user_presence WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM email_verifications WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM password_reset_codes WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM support_staff WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM user_entitlements WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM user_onboarding WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM dm_requests WHERE target_user_id=? OR sender_user_id=?').bind(user.id, user.id),
        env.DB.prepare('DELETE FROM user_shop_items WHERE user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM daily_diamond_claims WHERE user_id=?').bind(user.id),
        env.DB.prepare('UPDATE diamond_transactions SET source_user_id=NULL WHERE source_user_id=?').bind(user.id),
        env.DB.prepare('DELETE FROM diamond_transactions WHERE user_id=?').bind(user.id),
        env.DB.prepare('UPDATE users SET referred_by_user_id=NULL WHERE referred_by_user_id=?').bind(user.id),
        env.DB.prepare(`UPDATE users SET username=?,discriminator='0000',display_name='Deleted User',password_hash=?,password_salt=?,about='',avatar_url='',banner_color_1='#1E1F22',banner_color_2='#1E1F22',banner_image_url='',profile_gradient_angle=135,badges='[]',email=NULL,email_verified=0,role='user',account_status='banned',suspension_until=NULL,limitation_mask=0,limitation_next_expiry=NULL,standing_level=0,standing_next_expiry=NULL,dm_privacy_mode='smart',diamonds=0,referral_code=NULL,referred_by_user_id=NULL,referral_commission_remainder=0,equipped_decoration=NULL,age_band=NULL,age_16_at=NULL,age_18_at=NULL,age_declared_at=NULL WHERE id=?`).bind(deletedUsername, passwordHash, salt, user.id),
    ]);
    return json({ ok: true, deleted: true });
}

async function hydrateThreadSummaries(db, messages) {
    if (!messages?.length)
        return messages;
    const ids = [...new Set(messages.map(x => String(x.id || '')).filter(Boolean))];
    if (!ids.length)
        return messages;
    const found = [];
    for (let offset = 0; offset < ids.length; offset += 70) {
        const chunk = ids.slice(offset, offset + 70), marks = chunk.map(() => '?').join(',');
        const rows = await db.prepare(`SELECT t.id,t.parent_message_id,t.name,t.updated_at,(SELECT COUNT(*) FROM thread_messages tm WHERE tm.thread_id=t.id AND tm.deleted_at IS NULL) AS thread_count FROM message_threads t WHERE t.parent_message_id IN (${marks}) AND t.archived_at IS NULL`).bind(...chunk).all();
        found.push(...(rows.results || []));
    }
    const map = new Map(found.map(row => [String(row.parent_message_id), row]));
    for (const message of messages) {
        const thread = map.get(String(message.id));
        message.thread_id = thread?.id || null;
        message.thread_name = thread?.name || '';
        message.thread_count = Number(thread?.thread_count || 0);
        message.thread_updated_at = Number(thread?.updated_at || 0);
    }
    return messages;
}

async function threadWithAccess(db, userId, threadId, send = false) {
    const thread = await db.prepare(`SELECT t.*,c.server_id,c.name AS channel_name,m.content AS parent_content,m.user_id AS parent_user_id,u.display_name AS parent_display_name,u.username AS parent_username,u.discriminator AS parent_discriminator FROM message_threads t JOIN channels c ON c.id=t.channel_id JOIN messages m ON m.id=t.parent_message_id JOIN users u ON u.id=m.user_id WHERE t.id=? AND t.archived_at IS NULL LIMIT 1`).bind(threadId).first();
    if (!thread)
        return null;
    const permission = send ? PERMISSIONS.SEND_MESSAGES : PERMISSIONS.VIEW_CHANNEL;
    if (!(await hasChannelPermission(db, userId, thread.channel_id, permission)))
        return null;
    return thread;
}

async function createMessageThread(request, env, user, messageId) {
    const parent = await env.DB.prepare(`SELECT m.id,m.channel_id,m.content,c.server_id FROM messages m JOIN channels c ON c.id=m.channel_id WHERE m.id=? AND m.deleted_at IS NULL LIMIT 1`).bind(messageId).first();
    if (!parent || !(await hasChannelPermission(env.DB, user.id, parent.channel_id, PERMISSIONS.SEND_MESSAGES)))
        return json({ error: 'Message not found or you cannot create a thread here' }, 404);
    const existing = await env.DB.prepare('SELECT id FROM message_threads WHERE parent_message_id=? LIMIT 1').bind(messageId).first();
    if (existing)
        return getMessageThread(env, user, existing.id);
    const body = await readJson(request) || {};
    const fallback = String(parent.content || 'Thread').replace(/\s+/g, ' ').trim().slice(0, 60) || 'Thread';
    const name = cleanText(body.name || fallback, 80).trim();
    if (!name)
        return json({ error: 'Enter a thread name' }, 400);
    const id = prefixedId('thr'), now = Date.now();
    await env.DB.prepare('INSERT INTO message_threads(id,channel_id,parent_message_id,name,created_by,created_at,updated_at) VALUES(?,?,?,?,?,?,?)').bind(id, parent.channel_id, messageId, name, user.id, now, now).run();
    return getMessageThread(env, user, id, 201);
}

async function getMessageThread(env, user, threadId, status = 200) {
    const thread = await threadWithAccess(env.DB, user.id, threadId, false);
    if (!thread)
        return json({ error: 'Thread not found' }, 404);
    const count = await env.DB.prepare('SELECT COUNT(*) AS count FROM thread_messages WHERE thread_id=? AND deleted_at IS NULL').bind(threadId).first();
    return json({ thread: { ...thread, message_count: Number(count?.count || 0) } }, status);
}

async function listChannelThreads(env, user, channelId) {
    if (!(await hasChannelPermission(env.DB, user.id, channelId, PERMISSIONS.VIEW_CHANNEL)))
        return json({ error: 'Channel not found' }, 404);
    const rows = await env.DB.prepare(`SELECT t.id,t.channel_id,t.parent_message_id,t.name,t.created_by,t.created_at,t.updated_at,u.display_name AS creator_name,(SELECT COUNT(*) FROM thread_messages tm WHERE tm.thread_id=t.id AND tm.deleted_at IS NULL) AS message_count FROM message_threads t JOIN users u ON u.id=t.created_by WHERE t.channel_id=? AND t.archived_at IS NULL ORDER BY t.updated_at DESC LIMIT 100`).bind(channelId).all();
    return json({ threads: rows.results || [] });
}

async function listThreadMessages(env, user, threadId, url) {
    const thread = await threadWithAccess(env.DB, user.id, threadId, false);
    if (!thread)
        return json({ error: 'Thread not found' }, 404);
    const before = Number(url.searchParams.get('before') || Date.now() + 1);
    const rows = await env.DB.prepare(`SELECT tm.id,tm.thread_id,tm.content,tm.reply_to_id,tm.created_at,tm.edited_at,u.id AS user_id,u.username,u.discriminator,u.username_migrated,u.previous_username_tag,u.display_name,u.display_name_style,u.avatar_url,u.equipped_decoration,u.role AS account_role FROM thread_messages tm JOIN users u ON u.id=tm.user_id WHERE tm.thread_id=? AND tm.deleted_at IS NULL AND tm.created_at<? ORDER BY tm.created_at DESC LIMIT 100`).bind(threadId, before).all();
    return json({ messages: (rows.results || []).reverse(), thread });
}

async function createThreadMessage(request, env, user, threadId) {
    if (accountHasLimit(user, 1))
        return accountLimitResponse(user, 'MESSAGING_LIMITED', 'Sending messages is temporarily limited on this account');
    const thread = await threadWithAccess(env.DB, user.id, threadId, true);
    if (!thread)
        return json({ error: 'Thread not found or you cannot reply' }, 404);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const content = cleanText(body.content || '', 2000, true);
    if (!content.trim())
        return json({ error: 'Message cannot be empty' }, 400);
    const now = Date.now(), id = prefixedId('tmsg');
    await env.DB.batch([env.DB.prepare('INSERT INTO thread_messages(id,thread_id,user_id,content,created_at) VALUES(?,?,?,?,?)').bind(id, threadId, user.id, content, now), env.DB.prepare('UPDATE message_threads SET updated_at=? WHERE id=?').bind(now, threadId)]);
    return json({ message: { id, thread_id: threadId, user_id: user.id, username: user.username, discriminator: user.discriminator, display_name: user.display_name, avatar_url: user.avatar_url || '', account_role: user.role, content, created_at: now, edited_at: null } }, 201);
}

async function deleteThreadMessage(env, user, messageId) {
    const message = await env.DB.prepare('SELECT tm.id,tm.user_id,tm.thread_id FROM thread_messages tm WHERE tm.id=? AND tm.deleted_at IS NULL').bind(messageId).first();
    if (!message)
        return json({ error: 'Thread message not found' }, 404);
    const thread = await threadWithAccess(env.DB, user.id, message.thread_id, false);
    if (!thread)
        return json({ error: 'Thread not found' }, 404);
    if (message.user_id !== user.id && !hasModeratorAccess(user))
        return json({ error: 'You can only delete your own thread messages' }, 403);
    await env.DB.prepare('UPDATE thread_messages SET deleted_at=? WHERE id=?').bind(Date.now(), messageId).run();
    return json({ ok: true });
}

function describeLoginDevice(userAgent) {
    const ua = String(userAgent || '').toLowerCase();
    const os = ua.includes('iphone') ? 'iPhone' : ua.includes('ipad') ? 'iPad' : ua.includes('android') ? 'Android device' : ua.includes('windows') ? 'Windows device' : ua.includes('mac os') || ua.includes('macintosh') ? 'Mac' : ua.includes('linux') ? 'Linux device' : 'device';
    const browser = ua.includes('edg/') ? 'Edge' : ua.includes('chrome/') && !ua.includes('edg/') ? 'Chrome' : ua.includes('safari/') && !ua.includes('chrome/') ? 'Safari' : ua.includes('firefox/') ? 'Firefox' : 'browser';
    return `${browser} on ${os}`;
}

function publicSessionId(tokenHash) { return String(tokenHash || '').slice(0, 20); }

async function listAccountSessions(request, env, user) {
    const raw = getAuthToken(request) || '', currentHash = raw ? await sha256(raw) : '';
    try {
        const ua = String(request.headers.get('User-Agent') || '').slice(0, 500), name = cleanText(describeLoginDevice(ua) || 'This device', 100, true).trim();
        if (currentHash)
            await env.DB.prepare(`INSERT INTO session_devices(token_hash,user_id,device_name,user_agent,created_at)
      VALUES(?,?,?,?,?) ON CONFLICT(token_hash) DO UPDATE SET user_id=excluded.user_id,device_name=excluded.device_name,user_agent=excluded.user_agent`)
                .bind(currentHash, user.id, name, ua, Date.now()).run();
        await env.DB.prepare('DELETE FROM session_devices WHERE user_id=? AND token_hash NOT IN (SELECT token_hash FROM sessions WHERE user_id=?)').bind(user.id, user.id).run();
    }
    catch (error) {
        console.warn('Could not refresh session device metadata', error);
    }
    const rows = await env.DB.prepare(`SELECT s.token_hash,s.created_at,s.expires_at,sd.device_name,sd.user_agent
    FROM sessions s LEFT JOIN session_devices sd ON sd.token_hash=s.token_hash
    WHERE s.user_id=? AND s.expires_at>? ORDER BY CASE WHEN s.token_hash=? THEN 0 ELSE 1 END,s.created_at DESC`)
        .bind(user.id, Date.now(), currentHash).all();
    const sessions = (rows.results || []).map(row => ({
        id: publicSessionId(row.token_hash),
        current: String(row.token_hash) === currentHash,
        device_name: String(row.device_name || 'Older Orbyte session'),
        created_at: Number(row.created_at || 0),
        expires_at: Number(row.expires_at || 0),
    }));
    return json({ ok: true, sessions });
}

async function logoutAccountSession(request, env, user, sessionId) {
    const id = String(sessionId || '').toLowerCase();
    if (!/^[a-f0-9]{12,32}$/.test(id))
        return json({ error: 'Invalid session' }, 400);
    const currentRaw = getAuthToken(request) || '', currentHash = currentRaw ? await sha256(currentRaw) : '';
    const row = await env.DB.prepare('SELECT token_hash FROM sessions WHERE user_id=? AND substr(token_hash,1,20)=? LIMIT 1').bind(user.id, id.slice(0, 20)).first();
    if (!row)
        return json({ error: 'Session not found' }, 404);
    if (String(row.token_hash) === currentHash)
        return json({ error: 'Use Log out to end the session on this device' }, 400);
    await env.DB.batch([
        env.DB.prepare('DELETE FROM sessions WHERE user_id=? AND token_hash=?').bind(user.id, row.token_hash),
        env.DB.prepare('DELETE FROM session_devices WHERE user_id=? AND token_hash=?').bind(user.id, row.token_hash),
    ]);
    return json({ ok: true, session_id: publicSessionId(row.token_hash) });
}

async function logoutOtherAccountSessions(request, env, user) {
    const currentRaw = getAuthToken(request) || '', currentHash = currentRaw ? await sha256(currentRaw) : '';
    if (!currentHash)
        return json({ error: 'Current session could not be identified' }, 400);
    const result = await env.DB.prepare('DELETE FROM sessions WHERE user_id=? AND token_hash!=?').bind(user.id, currentHash).run();
    await env.DB.prepare('DELETE FROM session_devices WHERE user_id=? AND token_hash!=?').bind(user.id, currentHash).run();
    return json({ ok: true, logged_out: Number(result.meta?.changes || 0) });
}

let accountPasswordFollowupSchemaPromise = null;

async function hasAccountPasswordFollowupSchema(db) {
    if (!accountPasswordFollowupSchemaPromise) {
        accountPasswordFollowupSchemaPromise = db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='account_password_followups' LIMIT 1")
            .first().then(row => Boolean(row?.name)).catch(() => false);
    }
    return accountPasswordFollowupSchemaPromise;
}

async function scheduleAccountPasswordFollowup(db, userId, signupSessionHash, createdAt = Date.now()) {
    if (!(await hasAccountPasswordFollowupSchema(db)))
        return false;
    const dueAt = Number(createdAt || Date.now()) + 12 * 60 * 60 * 1000;
    await db.prepare(`INSERT INTO account_password_followups(
      user_id,due_at,signup_session_hash,verified_at,last_failed_at,reset_used_at,created_at,updated_at
    ) VALUES(?,?,?,NULL,NULL,NULL,?,?)
    ON CONFLICT(user_id) DO NOTHING`)
        .bind(userId, dueAt, String(signupSessionHash || ''), Number(createdAt || Date.now()), Number(createdAt || Date.now())).run();
    return true;
}

async function accountPasswordFollowupRow(env, userId) {
    if (!(await hasAccountPasswordFollowupSchema(env.DB)))
        return null;
    return env.DB.prepare(`SELECT user_id,due_at,signup_session_hash,verified_at,last_failed_at,reset_used_at,created_at,updated_at
    FROM account_password_followups WHERE user_id=? LIMIT 1`).bind(userId).first();
}

async function requestSessionTokenHash(request) {
    const token = getAuthToken(request);
    return token ? await sha256(token) : '';
}

function publicPasswordFollowup(row, currentSessionHash = '') {
    if (!row)
        return { enabled: true, scheduled: false, required: false };
    const now = Date.now(), dueAt = Number(row.due_at || 0), verified = Boolean(row.verified_at);
    const originalSession = Boolean(currentSessionHash && row.signup_session_hash && timingSafeEqual(String(currentSessionHash), String(row.signup_session_hash)));
    return {
        enabled: true, scheduled: true, required: !verified && dueAt > 0 && now >= dueAt, due_at: dueAt || null,
        verified_at: row.verified_at ? Number(row.verified_at) : null,
        incorrect_attempted: Boolean(row.last_failed_at),
        can_reset_without_email: !verified && !row.reset_used_at && Boolean(row.last_failed_at) && originalSession,
        original_signup_session: originalSession,
        reset_used: Boolean(row.reset_used_at)
    };
}

async function getAccountPasswordFollowup(request, env, user) {
    if (!(await hasAccountPasswordFollowupSchema(env.DB)))
        return json({ enabled: false, scheduled: false, required: false, migration_required: true }, 200, { 'Cache-Control': 'no-store' });
    const row = await accountPasswordFollowupRow(env, user.id);
    return json(publicPasswordFollowup(row, await requestSessionTokenHash(request)), 200, { 'Cache-Control': 'no-store' });
}

async function verifyAccountPasswordFollowup(request, env, user) {
    if (!(await hasAccountPasswordFollowupSchema(env.DB)))
        return json({ error: 'Password follow-up is not available until the R199.3 D1 migration is applied', code: 'PASSWORD_FOLLOWUP_MIGRATION_REQUIRED' }, 503);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const password = String(body.password || '');
    if (!password)
        return json({ error: 'Enter your password' }, 400);
    const row = await accountPasswordFollowupRow(env, user.id);
    if (!row)
        return json({ ok: true, required: false, scheduled: false });
    if (row.verified_at)
        return json({ ok: true, required: false, verified: true, verified_at: Number(row.verified_at) });
    if (Number(row.due_at || 0) > Date.now())
        return json({ error: 'This password check is not due yet', code: 'PASSWORD_FOLLOWUP_NOT_DUE', due_at: Number(row.due_at) }, 409);
    const allowed = await checkRateLimit(env.DB, `password-followup:${user.id}`, 12, 60 * 60 * 1000);
    if (!allowed)
        return json({ error: 'Too many password attempts. Try again later.' }, 429);
    const valid = await verifyPassword(password, user.password_salt, user.password_hash);
    const now = Date.now(), sessionHash = await requestSessionTokenHash(request);
    if (valid) {
        await env.DB.prepare('UPDATE account_password_followups SET verified_at=?,updated_at=? WHERE user_id=? AND verified_at IS NULL').bind(now, now, user.id).run();
        return json({ ok: true, required: false, verified: true, verified_at: now });
    }
    await env.DB.prepare('UPDATE account_password_followups SET last_failed_at=?,updated_at=? WHERE user_id=? AND verified_at IS NULL').bind(now, now, user.id).run();
    const refreshed = await accountPasswordFollowupRow(env, user.id);
    return json({
        error: 'That password is not correct.', code: 'PASSWORD_FOLLOWUP_INCORRECT', incorrect: true,
        ...publicPasswordFollowup(refreshed, sessionHash)
    }, 401, { 'Cache-Control': 'no-store' });
}

async function resetAccountPasswordFollowup(request, env, user) {
    if (!(await hasAccountPasswordFollowupSchema(env.DB)))
        return json({ error: 'Password follow-up is not available until the R199.3 D1 migration is applied', code: 'PASSWORD_FOLLOWUP_MIGRATION_REQUIRED' }, 503);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const next = String(body.new_password || '');
    if (next.length < 8 || next.length > 128)
        return json({ error: 'New password must be 8–128 characters' }, 400);
    const row = await accountPasswordFollowupRow(env, user.id);
    if (!row || row.verified_at || Number(row.due_at || 0) > Date.now())
        return json({ error: 'The 12-hour password check is not available for this account', code: 'PASSWORD_FOLLOWUP_NOT_AVAILABLE' }, 409);
    if (row.reset_used_at)
        return json({ error: 'The one-time no-email password reset has already been used', code: 'PASSWORD_FOLLOWUP_RESET_USED' }, 409);
    if (!row.last_failed_at)
        return json({ error: 'Enter the password you remember first. The one-time reset appears only after an incorrect attempt.', code: 'PASSWORD_FOLLOWUP_TRY_PASSWORD_FIRST' }, 409);
    const currentHash = await requestSessionTokenHash(request);
    if (!currentHash || !row.signup_session_hash || !timingSafeEqual(String(currentHash), String(row.signup_session_hash))) {
        return json({ error: 'For security, the one-time no-email reset is available only in the original signed-in session that created this account.', code: 'PASSWORD_FOLLOWUP_ORIGINAL_SESSION_REQUIRED' }, 403);
    }
    const now = Date.now(), salt = randomBase64(16), hash = await hashPassword(next, salt);
    const claim = await env.DB.prepare(`UPDATE account_password_followups
    SET reset_used_at=?,verified_at=?,updated_at=?
    WHERE user_id=? AND verified_at IS NULL AND reset_used_at IS NULL AND last_failed_at IS NOT NULL`)
        .bind(now, now, now, user.id).run();
    if (!Number(claim.meta?.changes || 0))
        return json({ error: 'The one-time password reset is no longer available', code: 'PASSWORD_FOLLOWUP_RESET_USED' }, 409);
    try {
        await env.DB.batch([
            env.DB.prepare('UPDATE users SET password_hash=?,password_salt=? WHERE id=?').bind(hash, salt, user.id),
            env.DB.prepare('DELETE FROM sessions WHERE user_id=? AND token_hash!=?').bind(user.id, currentHash),
        ]);
    }
    catch (error) {
        try {
            await env.DB.prepare('UPDATE account_password_followups SET reset_used_at=NULL,verified_at=NULL,updated_at=? WHERE user_id=? AND reset_used_at=?').bind(Date.now(), user.id, now).run();
        }
        catch { }
        throw error;
    }
    return json({ ok: true, required: false, verified: true, reset_used: true }, 200, { 'Cache-Control': 'no-store' });
}

async function changePassword(request, env, user) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const current = String(body.current_password || ''), next = String(body.new_password || '');
    if (!current)
        return json({ error: 'Enter your current password' }, 400);
    if (next.length < 8 || next.length > 128)
        return json({ error: 'New password must be 8-128 characters' }, 400);
    if (!(await verifyPassword(current, user.password_salt, user.password_hash)))
        return json({ error: 'Current password is incorrect' }, 403);
    if (current === next)
        return json({ error: 'Choose a different password' }, 400);
    const salt = randomBase64(16), hash = await hashPassword(next, salt), token = getAuthToken(request), tokenHash = token ? await sha256(token) : '';
    const statements = [env.DB.prepare('UPDATE users SET password_hash=?,password_salt=? WHERE id=?').bind(hash, salt, user.id)];
    if (tokenHash)
        statements.push(env.DB.prepare('DELETE FROM sessions WHERE user_id=? AND token_hash!=?').bind(user.id, tokenHash));
    else
        statements.push(env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(user.id));
    await env.DB.batch(statements);
    try {
        await sendSystemDm(env.DB, user.id, { kind: 'password_changed', color: '#23a55a', dedupeKey: `password:${user.id}:${crypto.randomUUID()}`, title: 'Your Orbyte password was changed', description: 'Your password was changed successfully and other signed-in sessions were logged out. If you did not make this change, contact Orbyte staff immediately.' });
    }
    catch (error) {
        console.warn('Could not send password-change DM', error);
    }
    try {
        await sendVerifiedAccountEmail(env, user.id, { type: 'password_changed' });
    }
    catch (error) {
        console.warn('Could not send password-change email', error);
    }
    return json({ ok: true, other_sessions_logged_out: true });
}

function effectiveChannelKind(channel) {
    return String(channel?.channel_kind || channel?.type || 'text').toLowerCase();
}

function normalizeServerTag(value) {
    const tag = String(value || '').trim().toUpperCase();
    return /^[A-Z]{1,5}$/.test(tag) ? tag : null;
}

function normalizeServerTagBadge(value) {
    const badge = String(value || '').trim();
    if (!badge)
        return '';
    if (badge.length > 24 || /[<>]/.test(badge))
        return null;
    return badge;
}

async function listUserServerTags(env, user) {
    const rows = await env.DB.prepare(`
    SELECT s.id AS server_id,s.name AS server_name,s.icon_url,s.server_tag,s.server_tag_badge,
           CASE WHEN d.listed=1 THEN 1 ELSE 0 END AS discoverable
    FROM server_members sm
    JOIN servers s ON s.id=sm.server_id
    LEFT JOIN server_discovery d ON d.server_id=s.id
    WHERE sm.user_id=? AND COALESCE(s.server_tag,'')!=''
    ORDER BY s.name COLLATE NOCASE
  `).bind(user.id).all();
    return json({ tags: rows.results || [], active_server_id: user.active_server_tag_id || null });
}

async function setActiveServerTag(request, env, user) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const serverId = body.server_id ? String(body.server_id) : null;
    if (serverId) {
        const row = await env.DB.prepare(`SELECT s.server_tag FROM servers s JOIN server_members sm ON sm.server_id=s.id WHERE s.id=? AND sm.user_id=? LIMIT 1`).bind(serverId, user.id).first();
        if (!row || !normalizeServerTag(row.server_tag))
            return json({ error: 'You cannot use that server tag' }, 403);
    }
    await env.DB.prepare('UPDATE users SET active_server_tag_id=? WHERE id=?').bind(serverId, user.id).run();
    return json({ ok: true, active_server_id: serverId });
}

async function updateServerTag(request, env, user, serverId) {
    if (!(await hasServerPermission(env.DB, user.id, serverId, PERMISSIONS.MANAGE_SERVER)))
        return json({ error: 'Manage Server permission required' }, 403);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const raw = String(body.tag || '').trim();
    const tag = raw ? normalizeServerTag(raw) : '';
    if (raw && !tag)
        return json({ error: 'Server tags use 1-5 letters' }, 400);
    const badge = normalizeServerTagBadge(body.badge);
    if (badge === null)
        return json({ error: 'Choose one short emoji badge' }, 400);
    await env.DB.prepare('UPDATE servers SET server_tag=?,server_tag_badge=? WHERE id=?').bind(tag, badge, serverId).run();
    if (!tag)
        await env.DB.prepare('UPDATE users SET active_server_tag_id=NULL WHERE active_server_tag_id=?').bind(serverId).run();
    return json({ ok: true, server_id: serverId, tag, badge });
}

async function getServerTagPreview(env, user, serverId) {
    const row = await env.DB.prepare(`
    SELECT s.id,s.name,s.icon_url,s.banner_url,s.server_tag,s.server_tag_badge,d.description,
      CASE WHEN d.listed=1 THEN 1 ELSE 0 END AS discoverable,
      EXISTS(SELECT 1 FROM server_members mine WHERE mine.server_id=s.id AND mine.user_id=?) AS joined,
      (SELECT COUNT(*) FROM server_members sm LEFT JOIN bot_applications b ON b.bot_user_id=sm.user_id WHERE sm.server_id=s.id AND b.id IS NULL) AS member_count
    FROM servers s LEFT JOIN server_discovery d ON d.server_id=s.id WHERE s.id=? LIMIT 1
  `).bind(user.id, serverId).first();
    if (!row || !normalizeServerTag(row.server_tag))
        return json({ error: 'Server tag not found' }, 404);
    return json({ server: { ...row, discoverable: Boolean(row.discoverable), joined: Boolean(row.joined), member_count: Number(row.member_count || 0) } });
}

async function hydrateServerTags(db, messages) {
    if (!messages?.length)
        return messages;
    const ids = [...new Set(messages.map(m => String(m.user_id || '')).filter(Boolean))];
    if (!ids.length)
        return messages;
    const map = new Map();
    for (let offset = 0; offset < ids.length; offset += 75) {
        const chunk = ids.slice(offset, offset + 75), marks = chunk.map(() => '?').join(',');
        const rows = await db.prepare(`SELECT u.id AS user_id,s.id AS server_tag_server_id,s.name AS server_tag_server_name,s.server_tag,s.server_tag_badge,
      CASE WHEN d.listed=1 THEN 1 ELSE 0 END AS server_tag_discoverable,
      EXISTS(SELECT 1 FROM server_members sm WHERE sm.server_id=s.id AND sm.user_id=u.id) AS still_member
      FROM users u LEFT JOIN servers s ON s.id=u.active_server_tag_id LEFT JOIN server_discovery d ON d.server_id=s.id
      WHERE u.id IN (${marks})`).bind(...chunk).all();
        for (const row of rows.results || [])
            if (row.still_member && normalizeServerTag(row.server_tag))
                map.set(String(row.user_id), row);
    }
    for (const message of messages) {
        const tag = map.get(String(message.user_id));
        if (tag)
            Object.assign(message, tag);
    }
    return messages;
}

async function hydrateRoleAppearance(db, channelId, messages) {
    if (!messages?.length)
        return messages;
    const channel = await db.prepare('SELECT server_id FROM channels WHERE id=? LIMIT 1').bind(channelId).first();
    if (!channel)
        return messages;
    const ids = [...new Set(messages.map(m => String(m.user_id || '')).filter(Boolean))];
    if (!ids.length)
        return messages;
    const map = new Map();
    for (let offset = 0; offset < ids.length; offset += 75) {
        const chunk = ids.slice(offset, offset + 75), marks = chunk.map(() => '?').join(',');
        const rows = await db.prepare(`SELECT smr.user_id,sr.name AS role_name,sr.color AS role_color,sr.color_2 AS role_color_2,sr.gradient_angle AS role_gradient_angle,sr.icon_url AS role_icon_url
      FROM server_member_roles smr JOIN server_roles sr ON sr.id=smr.role_id
      WHERE smr.server_id=? AND smr.user_id IN (${marks}) AND sr.is_default=0
      ORDER BY smr.user_id,sr.position DESC,sr.created_at ASC`).bind(channel.server_id, ...chunk).all();
        for (const row of rows.results || [])
            if (!map.has(String(row.user_id)))
                map.set(String(row.user_id), row);
    }
    for (const message of messages) {
        const role = map.get(String(message.user_id));
        if (role)
            Object.assign(message, role);
    }
    return messages;
}

async function requireChannelKind(db, userId, channelId, kind) {
    const channel = await db.prepare('SELECT id,server_id,type,channel_kind,name FROM channels WHERE id=? LIMIT 1').bind(channelId).first();
    if (!channel || effectiveChannelKind(channel) !== kind || !(await hasChannelPermission(db, userId, channelId, PERMISSIONS.VIEW_CHANNEL)))
        return null;
    return channel;
}

async function listForumPosts(env, user, channelId) {
    const channel = await requireChannelKind(env.DB, user.id, channelId, 'forum');
    if (!channel)
        return json({ error: 'Forum channel not found' }, 404);
    const rows = await env.DB.prepare(`SELECT p.id,p.channel_id,p.title,p.content,p.locked,p.created_at,p.updated_at,
    u.id AS user_id,u.username,u.discriminator,u.username_migrated,u.previous_username_tag,u.display_name,u.display_name_style,u.avatar_url,u.equipped_decoration,
    (SELECT COUNT(*) FROM forum_post_messages m WHERE m.post_id=p.id AND m.deleted_at IS NULL) AS reply_count
    FROM forum_posts p JOIN users u ON u.id=p.author_id WHERE p.channel_id=? ORDER BY p.updated_at DESC LIMIT 100`).bind(channelId).all();
    return json({ posts: rows.results || [] });
}

async function createForumPost(request, env, user, channelId) {
    const channel = await requireChannelKind(env.DB, user.id, channelId, 'forum');
    if (!channel)
        return json({ error: 'Forum channel not found' }, 404);
    if (!(await hasChannelPermission(env.DB, user.id, channelId, PERMISSIONS.SEND_MESSAGES)))
        return json({ error: 'You cannot create forum posts here' }, 403);
    const body = await readJson(request);
    const title = cleanText(body?.title || '', 100).trim(), content = cleanText(body?.content || '', 4000, true).trim();
    if (title.length < 2)
        return json({ error: 'Post title must be at least 2 characters' }, 400);
    if (!content)
        return json({ error: 'Post content is required' }, 400);
    const id = prefixedId('frm'), now = Date.now();
    await env.DB.prepare('INSERT INTO forum_posts(id,channel_id,author_id,title,content,created_at,updated_at) VALUES(?,?,?,?,?,?,?)').bind(id, channelId, user.id, title, content, now, now).run();
    return json({ ok: true, id, created_at: now }, 201);
}

async function forumPostWithAccess(db, userId, postId) {
    const post = await db.prepare(`SELECT p.*,c.server_id,c.type,c.channel_kind FROM forum_posts p JOIN channels c ON c.id=p.channel_id WHERE p.id=? LIMIT 1`).bind(postId).first();
    if (!post || effectiveChannelKind(post) !== 'forum' || !(await hasChannelPermission(db, userId, post.channel_id, PERMISSIONS.VIEW_CHANNEL)))
        return null;
    return post;
}

async function listForumPostMessages(env, user, postId) {
    const post = await forumPostWithAccess(env.DB, user.id, postId);
    if (!post)
        return json({ error: 'Forum post not found' }, 404);
    const rows = await env.DB.prepare(`SELECT m.id,m.post_id,m.content,m.created_at,u.id AS user_id,u.username,u.discriminator,u.username_migrated,u.previous_username_tag,u.display_name,u.display_name_style,u.avatar_url,u.equipped_decoration
    FROM forum_post_messages m JOIN users u ON u.id=m.author_id WHERE m.post_id=? AND m.deleted_at IS NULL ORDER BY m.created_at LIMIT 300`).bind(postId).all();
    return json({ post, messages: rows.results || [] });
}

async function createForumPostMessage(request, env, user, postId) {
    const post = await forumPostWithAccess(env.DB, user.id, postId);
    if (!post)
        return json({ error: 'Forum post not found' }, 404);
    if (post.locked)
        return json({ error: 'This post is locked' }, 403);
    if (!(await hasChannelPermission(env.DB, user.id, post.channel_id, PERMISSIONS.SEND_MESSAGES)))
        return json({ error: 'You cannot reply here' }, 403);
    const body = await readJson(request), content = cleanText(body?.content || '', 2000, true).trim();
    if (!content)
        return json({ error: 'Reply cannot be empty' }, 400);
    const id = prefixedId('fmsg'), now = Date.now();
    await env.DB.batch([env.DB.prepare('INSERT INTO forum_post_messages(id,post_id,author_id,content,created_at) VALUES(?,?,?,?,?)').bind(id, postId, user.id, content, now), env.DB.prepare('UPDATE forum_posts SET updated_at=? WHERE id=?').bind(now, postId)]);
    return json({ ok: true, id, created_at: now }, 201);
}

async function deleteForumPost(env, user, postId) {
    const post = await forumPostWithAccess(env.DB, user.id, postId);
    if (!post)
        return json({ error: 'Forum post not found' }, 404);
    const canManage = post.author_id === user.id || await hasServerPermission(env.DB, user.id, post.server_id, PERMISSIONS.MANAGE_CHANNELS);
    if (!canManage)
        return json({ error: 'You cannot delete this post' }, 403);
    await env.DB.prepare('DELETE FROM forum_posts WHERE id=?').bind(postId).run();
    return json({ ok: true });
}

async function listCalendarEvents(env, user, channelId, url) {
    const channel = await requireChannelKind(env.DB, user.id, channelId, 'calendar');
    if (!channel)
        return json({ error: 'Calendar channel not found' }, 404);
    const from = Math.max(0, Number(url.searchParams.get('from') || Date.now() - 30 * 86400000));
    const to = Math.max(from, Number(url.searchParams.get('to') || Date.now() + 366 * 86400000));
    const rows = await env.DB.prepare(`SELECT e.id,e.channel_id,e.title,e.description,e.starts_at,e.ends_at,e.created_at,u.id AS creator_id,u.username,u.discriminator,u.display_name,u.avatar_url,u.equipped_decoration
    FROM calendar_events e JOIN users u ON u.id=e.creator_id WHERE e.channel_id=? AND e.starts_at BETWEEN ? AND ? ORDER BY e.starts_at LIMIT 500`).bind(channelId, from, to).all();
    const effective = await getEffectiveChannelPermissions(env.DB, user.id, channelId);
    return json({ events: rows.results || [], can_create: Boolean(effective & PERMISSIONS.CREATE_CALENDAR_EVENTS), permission: PERMISSIONS.CREATE_CALENDAR_EVENTS });
}

async function createCalendarEvent(request, env, user, channelId) {
    const channel = await requireChannelKind(env.DB, user.id, channelId, 'calendar');
    if (!channel)
        return json({ error: 'Calendar channel not found' }, 404);
    if (!(await hasChannelPermission(env.DB, user.id, channelId, PERMISSIONS.CREATE_CALENDAR_EVENTS)))
        return json({ error: 'Create Calendar Events permission required' }, 403);
    const body = await readJson(request);
    const title = cleanText(body?.title || '', 100).trim(), description = cleanText(body?.description || '', 2000, true).trim();
    const startsAt = Number(body?.starts_at || 0), endsAt = body?.ends_at ? Number(body.ends_at) : null;
    if (title.length < 2)
        return json({ error: 'Event title must be at least 2 characters' }, 400);
    if (!Number.isFinite(startsAt) || startsAt < Date.now() - 365 * 86400000)
        return json({ error: 'Choose a valid event date' }, 400);
    if (endsAt && endsAt < startsAt)
        return json({ error: 'The event end must be after its start' }, 400);
    const id = prefixedId('evt'), now = Date.now();
    await env.DB.prepare('INSERT INTO calendar_events(id,channel_id,creator_id,title,description,starts_at,ends_at,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(id, channelId, user.id, title, description, startsAt, endsAt, now).run();
    return json({ ok: true, id, created_at: now }, 201);
}

async function deleteCalendarEvent(env, user, eventId) {
    const event = await env.DB.prepare(`SELECT e.*,c.server_id,c.type,c.channel_kind FROM calendar_events e JOIN channels c ON c.id=e.channel_id WHERE e.id=? LIMIT 1`).bind(eventId).first();
    if (!event || effectiveChannelKind(event) !== 'calendar' || !(await hasChannelPermission(env.DB, user.id, event.channel_id, PERMISSIONS.VIEW_CHANNEL)))
        return json({ error: 'Event not found' }, 404);
    const canDelete = event.creator_id === user.id || await hasChannelPermission(env.DB, user.id, event.channel_id, PERMISSIONS.MANAGE_CHANNELS);
    if (!canDelete)
        return json({ error: 'You cannot delete this event' }, 403);
    await env.DB.prepare('DELETE FROM calendar_events WHERE id=?').bind(eventId).run();
    return json({ ok: true });
}

function cleanDiscoveryTags(value) {
    const raw = Array.isArray(value) ? value : String(value || '').split(',');
    return [...new Set(raw.map(tag => cleanText(tag, 24).trim().toLowerCase()).filter(tag => /^[a-z0-9 _-]{2,24}$/.test(tag)))].slice(0, 5);
}

async function listDiscoveryServers(env, user, url) {
    if (isYoungTeen(user))
        return ageRestrictionResponse('Public Server Discovery is unavailable in Teen Safety Mode. You can still join servers through direct invites.');
    const query = cleanText(url.searchParams.get('query') || '', 80).trim();
    const like = `%${query.replace(/[\%_]/g, '\$&')}%`;
    const now = Date.now(), oldEnoughAt = now - 3 * 86400000;
    const searchClause = query ? ` AND (s.name LIKE ? ESCAPE '\\' COLLATE NOCASE OR d.description LIKE ? ESCAPE '\\' COLLATE NOCASE OR d.tags_json LIKE ? ESCAPE '\\' COLLATE NOCASE)` : '';
    const sql = `SELECT s.id,s.name,s.icon_url,s.banner_url,d.description,d.tags_json,d.updated_at,
    SUM(CASE WHEN member_bot.id IS NULL THEN 1 ELSE 0 END) AS member_count,
    MAX(CASE WHEN mine.user_id IS NOT NULL THEN 1 ELSE 0 END) AS joined,
    0 AS plus_bypass
    FROM server_discovery d
    JOIN servers s ON s.id=d.server_id
    JOIN server_members sm ON sm.server_id=s.id
    LEFT JOIN bot_applications member_bot ON member_bot.bot_user_id=sm.user_id
    LEFT JOIN server_members mine ON mine.server_id=s.id AND mine.user_id=?
    WHERE d.listed=1 AND s.created_at<=?${searchClause}
    GROUP BY s.id
    HAVING SUM(CASE WHEN member_bot.id IS NULL THEN 1 ELSE 0 END)>=10
    ORDER BY member_count DESC,d.updated_at DESC LIMIT 60`;
    const args = query ? [user.id, oldEnoughAt, like, like, like] : [user.id, oldEnoughAt];
    const result = await env.DB.prepare(sql).bind(...args).all();
    return json({ servers: (result.results || []).map(row => ({ ...row, member_count: Number(row.member_count || 0), joined: Boolean(row.joined), plus_bypass: false, tags: parseJsonArray(row.tags_json) })), minimum_members: 10, minimum_server_age_days: 3 });
}

async function getServerDiscovery(env, user, serverId) {
    if (!(await isServerMember(env.DB, user.id, serverId)))
        return json({ error: 'Server not found' }, 404);
    const [row, count, server] = await Promise.all([
        env.DB.prepare('SELECT listed,description,tags_json,updated_at FROM server_discovery WHERE server_id=?').bind(serverId).first(),
        env.DB.prepare('SELECT COUNT(*) AS count FROM server_members sm LEFT JOIN bot_applications b ON b.bot_user_id=sm.user_id WHERE sm.server_id=? AND b.id IS NULL').bind(serverId).first(),
        env.DB.prepare('SELECT owner_id,created_at FROM servers WHERE id=?').bind(serverId).first()
    ]);
    const members = Number(count?.count || 0);
    return json({ discovery: { listed: Boolean(row?.listed), description: row?.description || '', tags: parseJsonArray(row?.tags_json), updated_at: row?.updated_at || null, member_count: members, eligible: members >= 10 && Number(server?.created_at || 0) <= Date.now() - 3 * 86400000, plus_bypass: false, minimum_members: 10, minimum_server_age_days: 3, server_created_at: Number(server?.created_at || 0), can_manage: await hasServerPermission(env.DB, user.id, serverId, PERMISSIONS.MANAGE_SERVER) } });
}

async function updateServerDiscovery(request, env, user, serverId) {
    if (isYoungTeen(user))
        return ageRestrictionResponse('Teen Safety Mode cannot publish servers in public discovery');
    if (!(await hasServerPermission(env.DB, user.id, serverId, PERMISSIONS.MANAGE_SERVER)))
        return json({ error: 'Manage Server permission required' }, 403);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const listed = Boolean(body.listed), description = cleanText(body.description || '', 300, true).trim(), tags = cleanDiscoveryTags(body.tags);
    const [count, server] = await Promise.all([
        env.DB.prepare('SELECT COUNT(*) AS count FROM server_members sm LEFT JOIN bot_applications b ON b.bot_user_id=sm.user_id WHERE sm.server_id=? AND b.id IS NULL').bind(serverId).first(),
        env.DB.prepare('SELECT owner_id,created_at FROM servers WHERE id=?').bind(serverId).first()
    ]);
    if (!server)
        return json({ error: 'Server not found' }, 404);
    const members = Number(count?.count || 0);
    const serverAgeMs = Date.now() - Number(server.created_at || 0);
    const plusBypass = false;
    if (listed && members < 10)
        return json({ error: `A server needs at least 10 members before it can be listed. This server has ${members}.`, code: 'DISCOVERY_MEMBER_REQUIREMENT' }, 409);
    if (listed && serverAgeMs < 3 * 86400000)
        return json({ error: `A server must be at least 3 days old before it can be listed in Discovery.`, code: 'DISCOVERY_AGE_REQUIREMENT', eligible_at: Number(server.created_at || 0) + 3 * 86400000 }, 409);
    if (listed && description.length < 20)
        return json({ error: 'Add a discovery description of at least 20 characters' }, 400);
    await env.DB.prepare(`INSERT INTO server_discovery(server_id,listed,description,tags_json,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(server_id) DO UPDATE SET listed=excluded.listed,description=excluded.description,tags_json=excluded.tags_json,updated_at=excluded.updated_at`).bind(serverId, listed ? 1 : 0, description, JSON.stringify(tags), Date.now()).run();
    await logServerAudit(env.DB, serverId, user.id, 'discovery.update', 'server', serverId, { listed, tags });
    return json({ ok: true, listed, member_count: members, plus_bypass: plusBypass, tags });
}

async function joinDiscoveredServer(request, env, user, serverId) {
    if (isYoungTeen(user))
        return ageRestrictionResponse('Public Server Discovery is unavailable in Teen Safety Mode. Ask for a direct server invite instead.');
    if (accountHasLimit(user, 2))
        return accountLimitResponse(user, 'SERVER_ACCESS_LIMITED', 'Joining and creating servers is temporarily limited on this account');
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const captchaError = await requireCaptcha(request, env, body.captcha_token, 'join_server');
    if (captchaError)
        return captchaError;
    const row = await env.DB.prepare(`SELECT s.id,s.owner_id,s.created_at,(SELECT COUNT(*) FROM server_members sm LEFT JOIN bot_applications b ON b.bot_user_id=sm.user_id WHERE sm.server_id=s.id AND b.id IS NULL) AS member_count FROM servers s JOIN server_discovery d ON d.server_id=s.id WHERE s.id=? AND d.listed=1`).bind(serverId).first();
    if (!row)
        return json({ error: 'This server is not available in discovery' }, 404);
    if (await isServerBanned(env.DB, serverId, user.id))
        return json({ error: 'You are banned from this server', code: 'SERVER_BANNED', server_id: serverId }, 403);
    if (Number(row.member_count || 0) < 10 || Number(row.created_at || 0) > Date.now() - 3 * 86400000)
        return json({ error: 'This server is not available in discovery' }, 404);
    const existing = await isServerMember(env.DB, user.id, serverId);
    if (!existing) {
        const requirementFailure = await serverJoinRequirementFailure(env.DB, user, serverId);
        if (requirementFailure)
            return json(requirementFailure, 403);
    }
    const now = Date.now();
    await env.DB.prepare("INSERT OR IGNORE INTO server_members(server_id,user_id,role,joined_at) VALUES (?,?,'member',?)").bind(serverId, user.id, now).run();
    const onboarding = await env.DB.prepare('SELECT enabled FROM server_onboarding_settings WHERE server_id=?').bind(serverId).first();
    return json({ ok: true, server_id: serverId, onboarding_required: Boolean(onboarding?.enabled && !existing) });
}

function normalizeEmojiName(value) { const name = String(value || '').trim().toLowerCase(); return /^[a-z0-9_]{2,32}$/.test(name) ? name : null; }

async function listUserEmojis(env, user) {
    const rows = await env.DB.prepare(`
    SELECT ce.id,ce.server_id,ce.name,ce.image_url,ce.created_by,ce.created_at,
           s.name AS server_name,s.icon_url AS server_icon_url
    FROM custom_emojis ce
    JOIN servers s ON s.id=ce.server_id
    WHERE s.owner_id=? OR EXISTS(
      SELECT 1 FROM server_members sm WHERE sm.server_id=ce.server_id AND sm.user_id=?
    )
    ORDER BY LOWER(s.name),LOWER(ce.name)
    LIMIT 1000
  `).bind(user.id, user.id).all();
    return json({ emojis: rows.results || [] });
}

async function resolveCustomEmojis(env, user, url) {
    const ids = [...new Set(String(url.searchParams.get('ids') || '').split(',').map(x => x.trim()).filter(x => /^emo_[a-z0-9]+$/i.test(x)))].slice(0, 100);
    if (!ids.length)
        return json({ emojis: [] });
    const placeholders = ids.map(() => '?').join(',');
    const rows = await env.DB.prepare(`SELECT id,name,image_url FROM custom_emojis WHERE id IN (${placeholders})`).bind(...ids).all();
    return json({ emojis: rows.results || [] });
}

async function listServerEmojis(env, user, serverId) {
    if (!(await isServerMember(env.DB, user.id, serverId)))
        return json({ error: 'Server not found' }, 404);
    const rows = await env.DB.prepare('SELECT id,server_id,name,image_url,created_by,created_at FROM custom_emojis WHERE server_id=? ORDER BY name').bind(serverId).all();
    const canManage = await hasServerPermission(env.DB, user.id, serverId, PERMISSIONS.MANAGE_SERVER);
    return json({ emojis: rows.results || [], can_manage: canManage });
}

async function createServerEmoji(request, env, user, serverId, url) {
    if (accountHasLimit(user, 4))
        return accountLimitResponse(user, 'UPLOADS_LIMITED', 'File uploads are temporarily limited on this account');
    if (!(await hasServerPermission(env.DB, user.id, serverId, PERMISSIONS.MANAGE_SERVER)))
        return json({ error: 'Manage Server permission required' }, 403);
    if (!env.MEDIA)
        return json({ error: 'R2 media binding is not configured' }, 503);
    const server = await env.DB.prepare('SELECT owner_id FROM servers WHERE id=?').bind(serverId).first();
    if (!server)
        return json({ error: 'Server not found' }, 404);
    const emojiLimit = 50;
    const count = await env.DB.prepare('SELECT COUNT(*) AS count FROM custom_emojis WHERE server_id=?').bind(serverId).first();
    if (Number(count?.count || 0) >= emojiLimit)
        return json({ error: `This server already has the maximum of ${emojiLimit} custom emojis` }, 409);
    const name = normalizeEmojiName(url.searchParams.get('name'));
    if (!name)
        return json({ error: 'Emoji names use 2-32 lowercase letters, numbers, or underscores' }, 400);
    const contentType = request.headers.get('Content-Type') || '';
    if (!/^image\/(png|jpeg|webp|gif)$/i.test(contentType))
        return json({ error: 'Use a PNG, JPEG, WebP, or GIF image' }, 400);
    const buffer = await request.arrayBuffer();
    if (!buffer.byteLength || buffer.byteLength > 512 * 1024)
        return json({ error: 'Custom emoji must be 512 KB or smaller' }, 413);
    const id = prefixedId('emo'), extension = contentType.split('/')[1].replace('jpeg', 'jpg'), key = `emojis/${serverId}/${id}.${extension}`, imageUrl = `/media/${key}`;
    await env.MEDIA.put(key, buffer, { httpMetadata: { contentType, cacheControl: 'public, max-age=31536000, immutable' } });
    try {
        await env.DB.prepare('INSERT INTO custom_emojis(id,server_id,name,image_url,storage_key,created_by,created_at) VALUES(?,?,?,?,?,?,?)').bind(id, serverId, name, imageUrl, key, user.id, Date.now()).run();
    }
    catch (error) {
        try {
            await env.MEDIA.delete(key);
        }
        catch { }
        if (String(error).toLowerCase().includes('unique'))
            return json({ error: 'That emoji name is already used in this server' }, 409);
        throw error;
    }
    return json({ ok: true, emoji: { id, server_id: serverId, name, image_url: imageUrl } }, 201);
}

async function deleteServerEmoji(env, user, serverId, emojiId) {
    if (!(await hasServerPermission(env.DB, user.id, serverId, PERMISSIONS.MANAGE_SERVER)))
        return json({ error: 'Manage Server permission required' }, 403);
    const emoji = await env.DB.prepare('SELECT storage_key FROM custom_emojis WHERE id=? AND server_id=?').bind(emojiId, serverId).first();
    if (!emoji)
        return json({ error: 'Emoji not found' }, 404);
    await env.DB.prepare('DELETE FROM custom_emojis WHERE id=? AND server_id=?').bind(emojiId, serverId).run();
    if (env.MEDIA && emoji.storage_key)
        try {
            await env.MEDIA.delete(emoji.storage_key);
        }
        catch { }
    return json({ ok: true });
}

function normalizeBotPrefix(value) { const prefix = String(value || '!').trim().slice(0, 5); return prefix && !/\s/.test(prefix) ? prefix : null; }

function normalizeBotCommandName(value) { const name = String(value || '').trim().toLowerCase(); return /^[a-z0-9_-]{1,32}$/.test(name) ? name : null; }

function publicBotApplication(row) { return { id: row.id, owner_id: row.owner_id, bot_user_id: row.bot_user_id, name: row.name, description: row.description || '', bot_type: row.bot_type, prefix: row.prefix, token_hint: row.token_hint || '', avatar_url: row.avatar_url || '', created_at: Number(row.created_at || 0), updated_at: Number(row.updated_at || 0) }; }

async function ownedBot(env, user, botId) { return env.DB.prepare('SELECT * FROM bot_applications WHERE id=? AND owner_id=?').bind(botId, user.id).first(); }

async function listDeveloperBots(env, user) { const rows = await env.DB.prepare('SELECT * FROM bot_applications WHERE owner_id=? ORDER BY created_at DESC').bind(user.id).all(); return json({ bots: (rows.results || []).map(publicBotApplication) }); }

async function createDeveloperBot(request, env, user) {
    const body = await readJson(request);
    const name = cleanText(body?.name || '', 32).trim(), description = cleanText(body?.description || '', 180, true), botType = body?.bot_type === 'external' ? 'external' : 'visual', prefix = normalizeBotPrefix(body?.prefix || '!');
    if (name.length < 2)
        return json({ error: 'Bot name must be at least 2 characters' }, 400);
    if (canonicalIdentityText(name).includes('discord'))
        return json({ error: 'Bot names cannot impersonate Discord' }, 409);
    if (!prefix)
        return json({ error: 'Prefix must be 1-5 characters without spaces' }, 400);
    const base = normalizeUsername(name.replace(/\s+/g, '_')) || 'OrbyteBot';
    const identityError = await validateProtectedIdentity(env.DB, null, 'user', base, name);
    if (identityError)
        return json({ error: identityError }, 409);
    const discriminator = await findAvailableDiscriminator(env.DB, base);
    if (!discriminator)
        return json({ error: 'Could not allocate a bot tag' }, 503);
    const id = prefixedId('bot'), botUserId = prefixedId('usr'), token = `orb_bot_${randomBase64Url(36)}`, tokenHash = await sha256(token), now = Date.now(), salt = randomBase64(16), passwordHash = await hashPassword(randomBase64Url(64), salt);
    await env.DB.batch([
        env.DB.prepare(`INSERT INTO users(id,username,discriminator,display_name,password_hash,password_salt,about,banner_color_1,banner_color_2,role,account_status,created_at) VALUES(?,?,?,?,?,?,?,?,?,'user','active',?)`).bind(botUserId, base, discriminator, name, passwordHash, salt, description || 'Orbyte bot account.', '#5865f2', '#3b3f8f', now),
        env.DB.prepare('INSERT INTO bot_applications(id,owner_id,bot_user_id,name,description,bot_type,prefix,token_hash,token_hint,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)').bind(id, user.id, botUserId, name, description, botType, prefix, tokenHash, token.slice(-6), now, now)
    ]);
    return json({ ok: true, bot: { id, bot_user_id: botUserId, name, description, bot_type: botType, prefix, token_hint: token.slice(-6), created_at: now, updated_at: now }, token }, 201);
}

async function updateDeveloperBot(request, env, user, botId) {
    const bot = await ownedBot(env, user, botId);
    if (!bot)
        return json({ error: 'Bot not found' }, 404);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const name = cleanText(body.name ?? bot.name, 32).trim(), description = cleanText(body.description ?? bot.description, 180, true), prefix = normalizeBotPrefix(body.prefix ?? bot.prefix);
    if (name.length < 2 || !prefix)
        return json({ error: 'Invalid bot name or prefix' }, 400);
    if (canonicalIdentityText(name).includes('discord'))
        return json({ error: 'Bot names cannot impersonate Discord' }, 409);
    await env.DB.batch([env.DB.prepare('UPDATE bot_applications SET name=?,description=?,prefix=?,updated_at=? WHERE id=?').bind(name, description, prefix, Date.now(), botId), env.DB.prepare('UPDATE users SET display_name=?,about=? WHERE id=?').bind(name, description || 'Orbyte bot account.', bot.bot_user_id)]);
    return json({ ok: true });
}

