        return json({ error: 'Bot not found' }, 404);
    const body = await readJson(request), name = normalizeBotCommandName(body?.name), description = cleanText(body?.description || '', 100), response = cleanText(body?.response_text || '', 1900, true), enablePrefix = body?.enable_prefix !== false, enableSlash = body?.enable_slash !== false;
