async function listServerBotCommands(env, user, serverId) { if (!(await isServerMember(env.DB, user.id, serverId)))
    return json({ error: 'Server not found' }, 404); const rows = await env.DB.prepare(`SELECT c.id,c.name,c.description,c.enable_prefix,c.enable_slash,b.id AS bot_id,b.name AS bot_name,b.prefix,b.bot_type FROM bot_server_installs i JOIN bot_applications b ON b.id=i.bot_id JOIN server_members bot_member ON bot_member.server_id=i.server_id AND bot_member.user_id=b.bot_user_id JOIN users bot_user ON bot_user.id=b.bot_user_id JOIN bot_commands c ON c.bot_id=b.id WHERE i.server_id=? AND i.enabled=1 AND c.enabled=1 ORDER BY c.name,b.name`).bind(serverId).all(); return json({ commands: rows.results || [] }); }

async function requireBot(request, env) { const auth = request.headers.get('Authorization') || ''; const match = auth.match(/^(?:Bot|Bearer)\s+(.+)$/i); if (!match)
    return json({ error: 'Bot token required' }, 401); const token = match[1].trim(); const bot = await env.DB.prepare('SELECT * FROM bot_applications WHERE token_hash=?').bind(await sha256(token)).first(); if (!bot)
    return json({ error: 'Invalid bot token' }, 401); try {
    await env.DB.prepare(`INSERT INTO user_presence(user_id,last_seen_at,status) VALUES(?,?,'online') ON CONFLICT(user_id) DO UPDATE SET last_seen_at=excluded.last_seen_at,status='online'`).bind(bot.bot_user_id, Date.now()).run();
}
catch { } return bot; }

async function botGatewaySetAvatar(request, env, bot) {
    if (!env.MEDIA || typeof env.MEDIA.put !== 'function')
        return json({ error: 'MEDIA R2 binding is not configured' }, 503);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const contentType = String(body.content_type || '').toLowerCase();
    if (!['image/png', 'image/jpeg', 'image/gif', 'image/webp'].includes(contentType))
        return json({ error: 'Bot avatars must be PNG, JPEG, GIF, or WebP' }, 400);
    let bytes;
    try {
        const binary = atob(String(body.data || ''));
        bytes = new Uint8Array(binary.length);
        for (let i = 0; i < binary.length; i++)
            bytes[i] = binary.charCodeAt(i);
    }
    catch {
        return json({ error: 'Invalid avatar data' }, 400);
    }
    if (!bytes.byteLength || bytes.byteLength > 2 * 1024 * 1024)
        return json({ error: 'Bot avatars must be 2 MB or smaller' }, 413);
    const extension = contentType === 'image/jpeg' ? 'jpg' : contentType.split('/')[1];
    const key = `bot-avatars/${bot.id}/${crypto.randomUUID()}.${extension}`;
    await env.MEDIA.put(key, bytes, { httpMetadata: { contentType, cacheControl: 'public, max-age=31536000, immutable' } });
    const avatarUrl = `/media/${key}`;
    const existing = await env.DB.prepare('SELECT avatar_url FROM users WHERE id=? LIMIT 1').bind(bot.bot_user_id).first();
    await env.DB.prepare('UPDATE users SET avatar_url=? WHERE id=?').bind(avatarUrl, bot.bot_user_id).run();
    const old = String(existing?.avatar_url || '');
    if (old.startsWith('/media/bot-avatars/'))
        try {
            await env.MEDIA.delete(old.slice('/media/'.length));
        }
        catch { }
    return json({ ok: true, avatar_url: avatarUrl });
}

async function botGatewayRemoveAvatar(env, bot) {
    const existing = await env.DB.prepare('SELECT avatar_url FROM users WHERE id=? LIMIT 1').bind(bot.bot_user_id).first();
    await env.DB.prepare("UPDATE users SET avatar_url='' WHERE id=?").bind(bot.bot_user_id).run();
    const old = String(existing?.avatar_url || '');
    if (env.MEDIA && old.startsWith('/media/bot-avatars/'))
        try {
            await env.MEDIA.delete(old.slice('/media/'.length));
        }
        catch { }
    return json({ ok: true, avatar_url: '' });
}

function botGatewayMe(bot) { return json({ bot: publicBotApplication(bot) }); }

async function botGatewayEvents(env, bot, url) { if (Math.random() < 0.02)
    env.DB.prepare('DELETE FROM bot_events WHERE created_at<?').bind(Date.now() - 7 * 24 * 60 * 60 * 1000).run().catch(() => { }); const after = Math.max(0, Number(url.searchParams.get('after') || 0) || 0); const rows = await env.DB.prepare('SELECT id,event_type,payload_json,created_at FROM bot_events WHERE bot_id=? AND id>? ORDER BY id ASC LIMIT 100').bind(bot.id, after).all(); let cursor = after; const events = (rows.results || []).map(row => { cursor = Math.max(cursor, Number(row.id || 0)); let payload = {}; try {
    payload = JSON.parse(row.payload_json || '{}');
}
catch { } return { id: Number(row.id), type: row.event_type, payload, created_at: Number(row.created_at || 0) }; }); return json({ events, cursor }); }

async function botGatewayRegisterCommands(request, env, bot) { const body = await readJson(request), commands = Array.isArray(body?.commands) ? body.commands.slice(0, 100) : null; if (!commands)
    return json({ error: 'Commands must be an array' }, 400); const now = Date.now(), statements = [env.DB.prepare('DELETE FROM bot_commands WHERE bot_id=?').bind(bot.id)], seen = new Set(); for (const raw of commands) {
    const name = normalizeBotCommandName(raw?.name);
    if (!name || seen.has(name))
        continue;
    seen.add(name);
    const ep = raw.enable_prefix !== false, es = raw.enable_slash !== false;
    if (!ep && !es)
        continue;
    statements.push(env.DB.prepare('INSERT INTO bot_commands(id,bot_id,name,description,enable_prefix,enable_slash,response_text,enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,\'\',1,?,?)').bind(prefixedId('cmd'), bot.id, name, cleanText(raw.description || '', 100), ep ? 1 : 0, es ? 1 : 0, now, now));
} await env.DB.batch(statements); return json({ ok: true, registered: statements.length - 1 }); }

async function botGatewaySendMessage(request, env, bot) {
    const allowed = await checkRateLimit(env.DB, `bot-send:${bot.id}`, 60, 60 * 1000);
    if (!allowed)
        return json({ error: 'Bot message rate limit exceeded' }, 429);
    const body = await readJson(request), channelId = String(body?.channel_id || ''), dmId = String(body?.dm_id || ''), content = cleanText(body?.content || '', 2000, true), replyTo = String(body?.reply_to_id || '').trim() || null;
    if (!content.trim() || (!channelId && !dmId))
        return json({ error: 'channel_id or dm_id and content are required' }, 400);
    if (dmId) {
        const participant = await env.DB.prepare(`SELECT p.user_id FROM dm_participants p JOIN account_bot_installs i ON i.user_id=p.user_id AND i.bot_id=? AND i.enabled=1 AND i.dm_commands=1 WHERE p.conversation_id=? LIMIT 1`).bind(bot.id, dmId).first();
        if (!participant)
            return json({ error: 'This bot is not available in that DM' }, 403);
        if (replyTo) {
            const target = await env.DB.prepare('SELECT 1 FROM dm_messages WHERE id=? AND conversation_id=? AND deleted_at IS NULL').bind(replyTo, dmId).first();
            if (!target)
                return json({ error: 'Reply message not found' }, 404);
        }
        const id = prefixedId('dmsg'), now = Date.now();
        await env.DB.batch([
            env.DB.prepare('INSERT INTO dm_messages(id,conversation_id,user_id,content,reply_to_id,created_at) VALUES(?,?,?,?,?,?)').bind(id, dmId, bot.bot_user_id, content, replyTo, now),
            env.DB.prepare('UPDATE dm_conversations SET updated_at=? WHERE id=?').bind(now, dmId)
        ]);
        return json({ ok: true, id, created_at: now, dm_id: dmId }, 201);
    }
    const channel = await env.DB.prepare('SELECT c.id,c.name,c.server_id,s.name AS server_name FROM channels c JOIN servers s ON s.id=c.server_id WHERE c.id=? AND COALESCE(c.type,\'text\')!=\'voice\'').bind(channelId).first();
    if (!channel)
        return json({ error: 'Channel not found' }, 404);
    const install = await env.DB.prepare('SELECT 1 FROM bot_server_installs WHERE bot_id=? AND server_id=? AND enabled=1').bind(bot.id, channel.server_id).first();
    if (!install)
        return json({ error: 'This bot is not installed in that server' }, 403);
    if (!(await hasChannelPermission(env.DB, bot.bot_user_id, channelId, PERMISSIONS.SEND_MESSAGES)))
        return json({ error: 'The bot cannot send messages in that channel' }, 403);
    if (replyTo) {
        const target = await env.DB.prepare('SELECT 1 FROM messages WHERE id=? AND channel_id=? AND deleted_at IS NULL').bind(replyTo, channelId).first();
        if (!target)
            return json({ error: 'Reply message not found' }, 404);
    }
    const id = prefixedId('msg'), now = Date.now();
    await env.DB.prepare('INSERT INTO messages(id,channel_id,user_id,content,reply_to_id,created_at) VALUES(?,?,?,?,?,?)').bind(id, channelId, bot.bot_user_id, content, replyTo, now).run();
    try {
        const actor = await env.DB.prepare('SELECT * FROM users WHERE id=?').bind(bot.bot_user_id).first();
        if (actor)
            await createServerMessageNotifications(env.DB, { messageId: id, channel, actor, content, createdAt: now, includesEveryone: false });
    }
    catch (error) {
        console.warn('Could not create bot message notifications', error);
    }
    return json({ ok: true, id, created_at: now }, 201);
}

async function botGatewayActor(env, bot) {
    const row = await env.DB.prepare('SELECT * FROM users WHERE id=? LIMIT 1').bind(bot.bot_user_id).first();
    return row ? { ...row, is_bot: 1, bot_id: bot.id } : null;
}

async function botGatewayRequireServer(env, bot, serverId) {
    const row = await env.DB.prepare(`SELECT s.* FROM bot_server_installs i JOIN servers s ON s.id=i.server_id WHERE i.bot_id=? AND i.server_id=? AND i.enabled=1 LIMIT 1`).bind(bot.id, serverId).first();
    if (!row)
        return json({ error: 'This bot is not installed in that server' }, 403);
    const actor = await botGatewayActor(env, bot);
    if (!actor)
        return json({ error: 'Bot user account not found' }, 500);
    return { server: row, actor };
}

async function botGatewayBootstrap(env, bot) {
    const actor = await botGatewayActor(env, bot);
    if (!actor)
        return json({ error: 'Bot user account not found' }, 500);
    const serverRows = await env.DB.prepare(`SELECT s.*,(SELECT COUNT(*) FROM server_members sm WHERE sm.server_id=s.id) AS member_count FROM bot_server_installs i JOIN servers s ON s.id=i.server_id WHERE i.bot_id=? AND i.enabled=1 ORDER BY i.added_at`).bind(bot.id).all();
    const servers = serverRows.results || [], serverIds = servers.map(x => x.id);
    let channels = [], roles = [];
    if (serverIds.length) {
        const marks = serverIds.map(() => '?').join(',');
        const ch = await env.DB.prepare(`SELECT c.*,COALESCE(ccl.category_id,'') AS category_id FROM channels c LEFT JOIN channel_category_links ccl ON ccl.channel_id=c.id WHERE c.server_id IN (${marks}) ORDER BY c.server_id,c.position,c.created_at`).bind(...serverIds).all();
        for (const row of ch.results || [])
            if (await hasChannelPermission(env.DB, bot.bot_user_id, row.id, PERMISSIONS.VIEW_CHANNEL))
                channels.push(row);
        const rr = await env.DB.prepare(`SELECT * FROM server_roles WHERE server_id IN (${marks}) ORDER BY server_id,position`).bind(...serverIds).all();
        roles = rr.results || [];
    }
    return json({ bot: publicBotApplication(bot), user: { ...actor, is_bot: 1, bot_id: bot.id }, servers, channels, roles });
}

