function normalizeBotButtonColor(value) { const c = String(value || 'gray').toLowerCase(); return ['green', 'blue', 'red', 'gray', 'purple'].includes(c) ? c : 'gray'; }

function normalizeBotButtonCustomId(value) { const id = String(value || '').trim(); return /^[A-Za-z0-9_.:-]{1,100}$/.test(id) ? id : ''; }

async function findBotOwnedMessage(env, bot, messageId) {
    const channel = await env.DB.prepare(`SELECT 'channel' AS message_type,m.id,m.content,m.user_id,m.channel_id,c.server_id,NULL AS dm_id FROM messages m JOIN channels c ON c.id=m.channel_id WHERE m.id=? AND m.deleted_at IS NULL LIMIT 1`).bind(messageId).first();
    if (channel) {
        if (String(channel.user_id) !== String(bot.bot_user_id))
            return null;
        const access = await botGatewayRequireServer(env, bot, channel.server_id);
        if (access instanceof Response)
            return null;
        return channel;
    }
    const dm = await env.DB.prepare(`SELECT 'dm' AS message_type,m.id,m.content,m.user_id,NULL AS channel_id,NULL AS server_id,m.conversation_id AS dm_id FROM dm_messages m WHERE m.id=? AND m.deleted_at IS NULL LIMIT 1`).bind(messageId).first();
    if (dm && String(dm.user_id) === String(bot.bot_user_id))
        return dm;
    return null;
}

async function botGatewayAddButton(request, env, bot, messageId) {
    const message = await findBotOwnedMessage(env, bot, messageId);
    if (!message)
        return json({ error: 'Bot message not found' }, 404);
    const body = await readJson(request) || {}, title = cleanText(body.title || 'Button', 80).trim(), customId = normalizeBotButtonCustomId(body.custom_id), color = normalizeBotButtonColor(body.color), disabled = body.disabled ? 1 : 0;
    if (!title || !customId)
        return json({ error: 'Button title and a valid custom_id are required' }, 400);
    const existing = await env.DB.prepare('SELECT id,position FROM bot_message_buttons WHERE message_id=? AND custom_id=? LIMIT 1').bind(messageId, customId).first();
    if (!existing) {
        const count = await env.DB.prepare('SELECT COUNT(*) AS n FROM bot_message_buttons WHERE message_id=?').bind(messageId).first();
        if (Number(count?.n || 0) >= 5)
            return json({ error: 'A message can have up to 5 buttons' }, 400);
    }
    const id = existing?.id || prefixedId('btn'), position = existing ? Number(existing.position || 0) : Number((await env.DB.prepare('SELECT COALESCE(MAX(position),-1)+1 AS p FROM bot_message_buttons WHERE message_id=?').bind(messageId).first())?.p || 0), now = Date.now();
    await env.DB.prepare(`INSERT INTO bot_message_buttons(id,bot_id,message_type,message_id,custom_id,title,color,position,disabled,created_at) VALUES(?,?,?,?,?,?,?,?,?,?) ON CONFLICT(message_id,custom_id) DO UPDATE SET title=excluded.title,color=excluded.color,disabled=excluded.disabled`).bind(id, bot.id, message.message_type, messageId, customId, title, color, position, disabled, now).run();
    return json({ ok: true, button: { id, message_id: messageId, custom_id: customId, title, color, position, disabled: Boolean(disabled) } }, 201);
}

async function botGatewayRemoveButton(env, bot, messageId, customId) { const message = await findBotOwnedMessage(env, bot, messageId); if (!message)
    return json({ error: 'Bot message not found' }, 404); await env.DB.prepare('DELETE FROM bot_message_buttons WHERE bot_id=? AND message_id=? AND (custom_id=? OR id=?)').bind(bot.id, messageId, customId, customId).run(); return json({ ok: true }); }

async function listMessageComponents(env, user, url) {
    const ids = String(url.searchParams.get('ids') || '').split(',').map(x => x.trim()).filter(Boolean).slice(0, 100);
    if (!ids.length)
        return json({ components: [] });
    const marks = ids.map(() => '?').join(',');
    const rows = await env.DB.prepare(`SELECT id,bot_id,message_type,message_id,custom_id,title,color,position,disabled FROM bot_message_buttons WHERE message_id IN (${marks}) ORDER BY message_id,position,created_at`).bind(...ids).all();
    const accessCache = new Map(), components = [];
    for (const row of rows.results || []) {
        let allowed = accessCache.get(`${row.message_type}:${row.message_id}`);
        if (allowed === undefined) {
            if (row.message_type === 'channel') {
                const msg = await env.DB.prepare('SELECT m.channel_id,c.server_id FROM messages m JOIN channels c ON c.id=m.channel_id WHERE m.id=? AND m.deleted_at IS NULL LIMIT 1').bind(row.message_id).first();
                allowed = Boolean(msg && await hasChannelPermission(env.DB, user.id, msg.channel_id, PERMISSIONS.VIEW_CHANNEL));
            }
            else {
                const msg = await env.DB.prepare('SELECT conversation_id FROM dm_messages WHERE id=? AND deleted_at IS NULL LIMIT 1').bind(row.message_id).first();
                allowed = Boolean(msg && await isDmParticipant(env.DB, user.id, msg.conversation_id));
            }
            accessCache.set(`${row.message_type}:${row.message_id}`, allowed);
        }
        if (allowed)
            components.push({ ...row, disabled: Boolean(row.disabled) });
    }
    return json({ components });
}

async function clickMessageComponent(env, user, buttonId) {
    const row = await env.DB.prepare('SELECT * FROM bot_message_buttons WHERE id=? LIMIT 1').bind(buttonId).first();
    if (!row)
        return json({ error: 'Button not found' }, 404);
    if (row.disabled)
        return json({ error: 'This button is disabled' }, 409);
    const allowed = await checkRateLimit(env.DB, `button:${user.id}:${buttonId}`, 12, 10 * 1000);
    if (!allowed)
        return json({ error: 'You are clicking that button too quickly' }, 429);
    let message = null, payload = {};
    if (row.message_type === 'channel') {
        message = await env.DB.prepare('SELECT m.id,m.content,m.channel_id,c.server_id FROM messages m JOIN channels c ON c.id=m.channel_id WHERE m.id=? AND m.deleted_at IS NULL LIMIT 1').bind(row.message_id).first();
        if (!message || !(await hasChannelPermission(env.DB, user.id, message.channel_id, PERMISSIONS.VIEW_CHANNEL)))
            return json({ error: 'Message not found' }, 404);
        payload = { channel_id: message.channel_id, server_id: message.server_id };
    }
    else {
        message = await env.DB.prepare('SELECT id,content,conversation_id AS dm_id FROM dm_messages WHERE id=? AND deleted_at IS NULL LIMIT 1').bind(row.message_id).first();
        if (!message || !(await isDmParticipant(env.DB, user.id, message.dm_id)))
            return json({ error: 'Message not found' }, 404);
        payload = { dm_id: message.dm_id };
    }
    const author = { id: user.id, username: user.username, discriminator: user.discriminator, display_name: user.display_name, avatar_url: user.avatar_url || '' };
    const eventPayload = { custom_id: row.custom_id, button: { id: row.id, custom_id: row.custom_id, title: row.title, color: row.color }, message_id: row.message_id, message: { id: row.message_id, content: message.content || '', ...payload }, author, ...payload };
    await env.DB.prepare('INSERT INTO bot_events(bot_id,event_type,payload_json,created_at) VALUES(?,?,?,?)').bind(row.bot_id, 'button_click', JSON.stringify(eventPayload), Date.now()).run();
    return json({ ok: true, queued: true });
}

