async function getDatabaseRepairStatus(db) {
    const required = {
        users: ['limitation_mask', 'limitation_next_expiry', 'standing_level', 'standing_next_expiry', 'game_xp', 'game_level', 'game_total_xp', 'game_total_damage', 'game_attacks', 'game_next_attack_at', 'game_coins', 'game_cooldown_upgrade', 'game_xp_upgrade', 'game_double_click_upgrade'],
        violations: ['restriction_mask', 'restriction_until', 'reversed_at'],
        account_limitations: ['id', 'user_id', 'violation_id', 'limitation_mask', 'status', 'expires_at'],
        support_staff: ['user_id', 'granted_at'],
        support_requests: ['id', 'user_id', 'subject', 'status', 'created_at', 'updated_at'],
        support_messages: ['id', 'request_id', 'author_id', 'message', 'created_at'],
        support_articles: ['id', 'slug', 'title', 'markdown', 'status', 'author_id', 'created_at', 'updated_at'],
        password_reset_codes: ['user_id', 'email', 'code_hash', 'attempts', 'expires_at', 'created_at'],
        dm_requests: ['conversation_id', 'target_user_id', 'sender_user_id', 'status', 'created_at', 'updated_at'],
        message_threads: ['id', 'channel_id', 'parent_message_id', 'name', 'created_by', 'created_at', 'updated_at'],
        thread_messages: ['id', 'thread_id', 'user_id', 'content', 'created_at'],
        server_audit_logs: ['id', 'server_id', 'action', 'details_json', 'created_at'],
        server_resources: ['id', 'server_id', 'title', 'content', 'position'],
        server_onboarding_settings: ['server_id', 'enabled', 'welcome_title', 'welcome_message'],
        server_onboarding_questions: ['id', 'server_id', 'prompt', 'position'],
        server_onboarding_options: ['id', 'question_id', 'label', 'position'],
        server_onboarding_completions: ['server_id', 'user_id', 'completed_at'],
        game_bosses: ['id', 'max_health', 'health', 'round', 'status', 'started_at', 'updated_at'],
        game_challenges: ['id', 'user_id', 'sequence_json', 'expires_at', 'used_at'],
        game_attacks: ['id', 'user_id', 'boss_round', 'damage', 'xp_awarded', 'created_at'],
        bot_message_buttons: ['id', 'bot_id', 'message_type', 'message_id', 'custom_id', 'title', 'color', 'position', 'disabled', 'created_at'],
    };
    const missing = [];
    for (const [table, columns] of Object.entries(required)) {
        const found = await getTableColumnSet(db, table);
        if (!found.size) {
            missing.push({ table, missing: ['<table>'] });
            continue;
        }
        const missingColumns = columns.filter(column => !found.has(column));
        if (missingColumns.length)
            missing.push({ table, missing: missingColumns });
    }
    return { ok: missing.length === 0, missing };
}

async function adminDatabaseStatus(env) {
    const status = await getDatabaseRepairStatus(env.DB);
    return json({ repaired: status.ok, ...status });
}

function errorResponse(error, errorId) {
    const message = String(error?.message || error || 'Unknown error');
    const lower = message.toLowerCase();
    if (lower.includes('too many sql variables') || lower.includes('too many bound parameters')) {
        return json({ error: 'The request contained too many items. Try a smaller request.', code: 'DB_PARAMETER_LIMIT', error_id: errorId }, 400);
    }
    if (lower.includes('no such table') || lower.includes('no such column') || lower.includes('has no column')) {
        return json({ error: 'The database schema is incomplete. Run the latest D1 migration and redeploy the Worker.', code: 'DB_SCHEMA_INCOMPLETE', error_id: errorId }, 503);
    }
    if (lower.includes('database is locked') || lower.includes('database is busy') || lower.includes('temporarily unavailable') || lower.includes('network connection lost')) {
        return json({ error: 'The database is temporarily busy. Please try again.', code: 'DB_TEMPORARY_ERROR', error_id: errorId }, 503);
    }
    if (lower.includes('unique constraint') || lower.includes('constraint failed')) {
        if (lower.includes('users.username') || lower.includes('idx_users_unique_migrated_username')) {
            return json({ error: 'That username is already taken.', code: 'USERNAME_TAKEN', taken: true, error_id: errorId }, 409);
        }
        if (lower.includes('users.username, users.discriminator') || lower.includes('username, discriminator')) {
            return json({ error: 'The internal account identifier collided. Please try creating the account again.', code: 'ACCOUNT_IDENTIFIER_COLLISION', retryable: true, error_id: errorId }, 409);
        }
        if (lower.includes('users.referral_code') || lower.includes('idx_users_referral_code')) {
            return json({ error: 'A referral code collision occurred. Please try again.', code: 'REFERRAL_CODE_COLLISION', retryable: true, error_id: errorId }, 409);
        }
        return json({ error: 'A database value conflicted with existing data. Try again, or use a different username.', code: 'DB_CONSTRAINT', error_id: errorId }, 409);
    }
    return json({ error: 'Internal server error', code: 'INTERNAL_ERROR', error_id: errorId }, 500);
}

function isMinimumAgeRestricted(user) {
    return Boolean(user && (user.minimum_age_restricted_at || String(user.minimum_age_status || '') === 'restricted'));
}

function hasActiveAccountRestriction(user) {
    if (!user)
        return false;
    if (user.account_status === 'banned' || user.account_status === 'pending_parent')
        return true;
    if (user.account_status !== 'suspended')
        return false;
    return !user.suspension_until || Number(user.suspension_until) > Date.now();
}

async function requireUser(request, env) {
    const token = getAuthToken(request);
    if (!token)
        return json({ error: 'Not authenticated' }, 401);
    const tokenHash = await sha256(token);
    const user = await env.DB.prepare(`
    SELECT u.*
    FROM sessions s
    JOIN users u ON u.id = s.user_id
    WHERE s.token_hash = ? AND s.expires_at > ?
    LIMIT 1
  `).bind(tokenHash, Date.now()).first();
    if (!user)
        return json({ error: 'Session expired' }, 401);
    if (user.account_status === 'suspended' && user.suspension_until && Number(user.suspension_until) <= Date.now()) {
        await env.DB.prepare(`UPDATE users SET account_status='active', suspension_until=NULL WHERE id=?`).bind(user.id).run();
        user.account_status = 'active';
        user.suspension_until = null;
    }
    return user;
}

async function createSession(db, userId, request = null) {
    const rawToken = randomBase64Url(32);
    const tokenHash = await sha256(rawToken);
    const now = Date.now();
    const maxAge = 30 * 24 * 60 * 60;
    await db.prepare(`
    INSERT INTO sessions (token_hash, user_id, expires_at, created_at)
    VALUES (?, ?, ?, ?)
  `).bind(tokenHash, userId, now + maxAge * 1000, now).run();
    try {
        const ua = String(request?.headers?.get?.('User-Agent') || '').slice(0, 500);
        const deviceName = cleanText(describeLoginDevice(ua) || 'Orbyte device', 100, true).trim();
        await db.prepare(`INSERT INTO session_devices(token_hash,user_id,device_name,user_agent,created_at)
      VALUES(?,?,?,?,?) ON CONFLICT(token_hash) DO UPDATE SET user_id=excluded.user_id,device_name=excluded.device_name,user_agent=excluded.user_agent`)
            .bind(tokenHash, userId, deviceName, ua, now).run();
    }
    catch (error) {
        console.warn('Could not save session device metadata', error);
    }
    return { token: rawToken, token_hash: tokenHash };
}

