async function findAvailableDiscriminator(db, username) {
    for (let i = 0; i < 30; i++) {
        const discriminator = String(Math.floor(Math.random() * 10000)).padStart(4, '0');
        const exists = await db.prepare(`
      SELECT 1 FROM users WHERE username = ? COLLATE NOCASE AND discriminator = ? LIMIT 1
    `).bind(username, discriminator).first();
        if (!exists)
            return discriminator;
    }
    return null;
}

async function checkRateLimit(db, key, limit, windowMs) {
    const now = Date.now();
    const result = await db.prepare(`
    INSERT INTO rate_limits (key, count, window_started_at)
    VALUES (?, 1, ?)
    ON CONFLICT(key) DO UPDATE SET
      count = CASE
        WHEN ? - rate_limits.window_started_at >= ? THEN 1
        ELSE rate_limits.count + 1
      END,
      window_started_at = CASE
        WHEN ? - rate_limits.window_started_at >= ? THEN ?
        ELSE rate_limits.window_started_at
      END
    WHERE (? - rate_limits.window_started_at >= ?) OR rate_limits.count < ?
  `).bind(key, now, now, windowMs, now, windowMs, now, now, windowMs, limit).run();
    return Number(result.meta?.changes || 0) > 0;
}

function parseBadgeList(value) {
    if (Array.isArray(value))
        return value;
    if (!value)
        return [];
    try {
        const parsed = JSON.parse(value);
        return Array.isArray(parsed) ? parsed : [];
    }
    catch {
        return String(value).split(',').map(x => x.trim()).filter(Boolean);
    }
}

async function enrichedPublicUser(db, user, includePrivate = false) {
    const community = await db.prepare(`
    SELECT 1
    FROM servers s
    WHERE s.owner_id = ?
      AND (SELECT COUNT(*) FROM server_members sm WHERE sm.server_id = s.id) >= 25
    LIMIT 1
  `).bind(user.id).first();
    const earnedBadges = new Set(parseBadgeList(user.badges));
    const role = rawAccountRole(user);
    if (['owner', 'admin', 'moderator', 'staff'].includes(role))
        earnedBadges.add('staff');
    if (role === 'support')
        earnedBadges.add('support');
    if (String(user.id) === 'usr_byte_ai' || Number(user.is_ai || 0) === 1)
        earnedBadges.add('ai');
    if (Number(user.created_at || 0) > 0 && Date.now() - Number(user.created_at) >= 365 * 24 * 60 * 60 * 1000)
        earnedBadges.add('anniversary');
    if (community)
        earnedBadges.add('community_builder');
    const plus = await getPlusStatus(db, user.id);
    if (plus.active)
        earnedBadges.add('plus');
    if (String(user.previous_username_tag || '').trim())
        earnedBadges.add('previous_name');
    if (Number(user.game_level || 0) >= 1)
        earnedBadges.add('game');
    const hiddenBadges = new Set(parseBadgeList(user.hidden_badges));
    const earned = [...earnedBadges];
    const visible = earned.filter(id => !hiddenBadges.has(id));
    const data = publicUser(user, includePrivate);
    data.plus = plus;
    if (!plus.active && !includePrivate)
        data.profile_background_url = '';
    if (!plus.active && includePrivate && data.profile_background_url)
        data.profile_background_plus_locked = true;
    data.account_safety = accountSafetyFromUser(user);
    data.badges = visible;
    data.badges_are_final = true;
    data.created_at = user.created_at || null;
    if (includePrivate) {
        data.earned_badges = earned;
        data.hidden_badges = [...hiddenBadges].filter(id => earnedBadges.has(id));
    }
    return data;
}

function publicUser(user, includePrivate = false) {
    const data = {
        id: user.id,
        username: user.username,
        discriminator: user.discriminator,
        username_migrated: Boolean(user.username_migrated),
        previous_username_tag: user.previous_username_tag || '',
        display_name: user.display_name,
        display_name_style: publicDisplayNameStyle(user.display_name_style),
        avatar_url: user.avatar_url || '',
        equipped_decoration: user.equipped_decoration || '',
        about: user.about || '',
        banner_color_1: user.banner_color_1 || '#5865f2',
        banner_color_2: user.banner_color_2 || '#3b3f8f',
        banner_image_url: user.banner_image_url || '',
        profile_gradient_angle: Number(user.profile_gradient_angle || 135),
        profile_theme_enabled: user.profile_theme_enabled === undefined || user.profile_theme_enabled === null ? true : Number(user.profile_theme_enabled) !== 0,
        profile_background_url: user.profile_background_url || '',
        profile_background_dim: Math.max(0, Math.min(75, Number(user.profile_background_dim ?? 28))),
        profile_background_effect: normalizeProfileBackgroundEffect(user.profile_background_effect),
        profile_frame_url: user.profile_frame_url || '',
        profile_frame_x: Math.max(-60, Math.min(60, Number(user.profile_frame_x || 0))),
        profile_frame_y: Math.max(-60, Math.min(60, Number(user.profile_frame_y || 0))),
        profile_frame_scale: Math.max(.35, Math.min(3, Number(user.profile_frame_scale || 1))),
        role: rawAccountRole(user),
        badges: parseBadgeList(user.badges),
        created_at: user.created_at || null,
        plus: user.plus || null,
        game_level: Math.max(0, Number(user.game_level || 0)),
    };
    if (includePrivate) {
        data.email = user.email;
        data.email_verified = Boolean(user.email_verified);
        data.dm_privacy_mode = user.dm_privacy_mode || 'smart';
        data.diamonds = Math.max(0, Number(user.diamonds || 0));
        data.hidden_badges = parseBadgeList(user.hidden_badges);
        data.game_xp = Math.max(0, Number(user.game_xp || 0));
        data.game_total_xp = Math.max(0, Number(user.game_total_xp || 0));
        data.game_total_damage = Math.max(0, Number(user.game_total_damage || 0));
        data.game_attacks = Math.max(0, Number(user.game_attacks || 0));
        data.game_next_attack_at = Number(user.game_next_attack_at || 0) || null;
        data.age_safety = ageSafetyFromUser(user);
    }
    return data;
}

async function readMessagePayload(request, maxBytes = 25 * 1024 * 1024) {
    const contentType = String(request.headers.get('Content-Type') || '').toLowerCase();
    if (contentType.includes('multipart/form-data')) {
        let form;
        try {
            form = await request.formData();
        }
        catch {
            return { error: 'Could not read the attachment upload', status: 400, content: '', files: [] };
        }
        const content = cleanText(form.get('content') || '', 2000, true);
        const files = form.getAll('files').filter(isUploadedFile);
        if (files.length > 4)
            return { error: 'You can attach up to 4 files', status: 400, content, files: [] };
        for (const file of files) {
            if (!Number.isFinite(file.size) || file.size <= 0)
                return { error: 'Empty files cannot be uploaded', status: 400, content, files: [] };
            if (file.size > maxBytes)
                return { error: `Each attachment must be ${Math.round(maxBytes / 1024 / 1024)} MB or smaller`, status: 413, content, files: [] };
        }
        return { content, files, reply_to_id: String(form.get('reply_to_id') || '').trim() || null };
    }
    const body = await readJson(request);
    return { content: cleanText(body?.content || '', 2000, true), files: [], reply_to_id: String(body?.reply_to_id || '').trim() || null };
}

function isUploadedFile(value) {
    return Boolean(value && typeof value === 'object' && typeof value.name === 'string' && typeof value.size === 'number' && typeof value.stream === 'function');
}

function normalizeAttachmentFileName(value) {
    let name = String(value || 'attachment')
        .replace(/[\/\\]/g, '_')
        .replace(/[\u0000-\u001f\u007f]/g, '')
        .trim();
    if (!name || name === '.' || name === '..')
        name = 'attachment';
    if (name.length > 180) {
        const dot = name.lastIndexOf('.');
        const extension = dot > 0 && name.length - dot <= 16 ? name.slice(dot) : '';
        name = name.slice(0, Math.max(1, 180 - extension.length)) + extension;
    }
    return name;
}

function normalizeAttachmentContentType(value) {
    const type = String(value || '').split(';', 1)[0].trim().toLowerCase();
    return /^[a-z0-9!#$&^_.+-]+\/[a-z0-9!#$&^_.+-]+$/.test(type) ? type : 'application/octet-stream';
}

function attachmentExtension(fileName) {
    const match = String(fileName || '').toLowerCase().match(/\.([a-z0-9]{1,10})$/);
    return match ? `.${match[1]}` : '';
}

function isInlineAttachmentType(contentType) {
    return /^(image\/(png|jpeg|gif|webp)|audio\/(mpeg|ogg|wav|webm|mp4|aac|flac)|video\/(mp4|webm|ogg|quicktime))$/i.test(String(contentType || ''));
}

async function storeMessageAttachments(env, messageType, messageId, userId, files, createdAt, maxBytes = 25 * 1024 * 1024) {
    if (!files.length)
        return [];
    if (!env.MEDIA)
        throw new Error('MEDIA_NOT_CONFIGURED');
    if (files.length > 4)
        throw new Error('TOO_MANY_ATTACHMENTS');
    const stored = [];
    try {
        for (const file of files) {
            if (file.size > maxBytes)
                throw new Error('ATTACHMENT_TOO_LARGE');
            const id = prefixedId('att');
            const fileName = normalizeAttachmentFileName(file.name);
            const contentType = normalizeAttachmentContentType(file.type);
            const storageKey = `attachments/${messageType}/${messageId}/${id}${attachmentExtension(fileName)}`;
            await env.MEDIA.put(storageKey, file.stream(), {
                httpMetadata: { contentType, cacheControl: 'public, max-age=604800, immutable' },
                customMetadata: {
                    file_name: fileName,
                    content_type: contentType,
                    uploader_id: String(userId),
                    attachment_id: id,
                },
            });
            stored.push({
                id,
                message_id: messageId,
                file_name: fileName,
                file_size: Number(file.size),
                content_type: contentType,
                storage_key: storageKey,
                created_at: createdAt,
            });
        }
        return stored;
    }
    catch (error) {
        await deleteStoredAttachments(env, stored);
        throw error;
    }
}

function attachmentInsertStatements(db, messageType, messageId, uploaderId, attachments) {
    return attachments.map(attachment => db.prepare(`
    INSERT INTO message_attachments
      (id, message_type, message_id, uploader_id, file_name, file_size, content_type, storage_key, created_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).bind(attachment.id, messageType, messageId, uploaderId, attachment.file_name, attachment.file_size, attachment.content_type, attachment.storage_key, attachment.created_at));
}

function publicAttachmentRows(attachments) {
    return attachments.map(attachment => ({
        id: attachment.id,
        file_name: attachment.file_name,
        file_size: Number(attachment.file_size || 0),
        content_type: attachment.content_type || 'application/octet-stream',
        url: `/media/${attachment.storage_key}`,
        created_at: Number(attachment.created_at || 0),
    }));
}

function attachmentNotificationText(attachments) {
    if (!attachments.length)
        return '';
    return attachments.length === 1 ? `Sent an attachment: ${attachments[0].file_name}` : `Sent ${attachments.length} attachments`;
}

async function listStoredAttachments(db, messageType, messageId) {
    const result = await db.prepare('SELECT storage_key FROM message_attachments WHERE message_type=? AND message_id=?').bind(messageType, messageId).all();
    return result.results || [];
}

async function deleteStoredAttachments(env, attachments) {
    if (!env.MEDIA || !attachments?.length)
        return;
    const keys = [...new Set(attachments.map(item => item.storage_key).filter(Boolean))];
    if (!keys.length)
        return;
    try {
        await env.MEDIA.delete(keys);
    }
    catch (error) {
        console.warn('Could not delete one or more attachment objects', error);
        for (const key of keys) {
            try {
                await env.MEDIA.delete(key);
            }
            catch { }
        }
    }
}

function canonicalIdentityName(value) {
    const confusables = {
        'а': 'a', 'ɑ': 'a', 'α': 'a', 'е': 'e', 'ε': 'e', 'ё': 'e', 'і': 'i', 'ї': 'i', 'ι': 'i', 'ӏ': 'i', 'о': 'o', 'ο': 'o', 'р': 'p', 'ρ': 'p', 'с': 'c', 'ϲ': 'c', 'у': 'y', 'γ': 'y', 'х': 'x', 'χ': 'x', 'к': 'k', 'κ': 'k', 'м': 'm', 'м': 'm', 'т': 't', 'ν': 'v', 'в': 'b', 'н': 'h'
    };
    return String(value || '').normalize('NFKD').toLowerCase().replace(/[\u0300-\u036f]/g, '').split('').map(ch => confusables[ch] || ch).join('').replace(/[^a-z0-9]/g, '');
}

async function findProtectedIdentityConflict(db, userId, username, displayName) {
    const candidates = new Set([canonicalIdentityName(username), canonicalIdentityName(displayName)].filter(name => name.length >= 3));
    if (!candidates.size)
        return null;
    const result = await db.prepare("SELECT id,username,display_name FROM users WHERE role IN ('owner','admin','moderator','staff') AND id!=? AND account_status!='banned'").bind(userId || '').all();
    for (const row of result.results || []) {
        const protectedNames = [canonicalIdentityName(row.username), canonicalIdentityName(row.display_name)];
        if (protectedNames.some(name => name && candidates.has(name)))
            return `${row.display_name} (${row.username})`;
    }
    return null;
}

async function validateProtectedIdentity(db, userId, role, username, displayName) {
    const staff = ['owner', 'admin', 'moderator', 'staff'].includes(String(role || '').toLowerCase());
    const names = [canonicalIdentityName(username), canonicalIdentityName(displayName)].filter(Boolean);
    const reserved = new Set(['orbyte', 'administrator', 'admin', 'moderator', 'trustandsafety', 'trustsafety', 'officialorbyte']);
    if (!staff && names.some(name => reserved.has(name) || name.startsWith('orbyte') || name.includes('trustandsafety') || name.includes('officialorbyte'))) {
        return 'That name is reserved for official Orbyte accounts.';
    }
    const conflict = await findProtectedIdentityConflict(db, userId, username, displayName);
    if (conflict)
        return staff ? `Another staff account already uses that protected identity (${conflict}).` : `That identity is protected because it could be mistaken for Orbyte staff (${conflict}).`;
    return null;
}

