async function getOnboardingStatus(env, user) {
    await ensureOnboardingRow(env.DB, user.id);
    const [onboarding, friendship, officialServer] = await Promise.all([
        env.DB.prepare(`
      SELECT *
      FROM user_onboarding
      WHERE user_id = ?
      LIMIT 1
    `).bind(user.id).first(),
        env.DB.prepare(`
      SELECT 1 AS completed
      FROM friendships
      WHERE status = 'accepted'
        AND (requester_id = ? OR addressee_id = ?)
      LIMIT 1
    `).bind(user.id, user.id).first(),
        getOfficialServer(env.DB),
    ]);
    let officialMembership = null;
    if (officialServer?.server_id) {
        officialMembership = await env.DB.prepare(`
      SELECT 1 AS completed
      FROM server_members
      WHERE server_id = ? AND user_id = ?
      LIMIT 1
    `).bind(officialServer.server_id, user.id).first();
    }
    const friendComplete = Boolean(friendship || onboarding?.friend_task_completed_at);
    const officialServerComplete = Boolean(officialMembership || onboarding?.official_server_task_completed_at);
    const profileComplete = Boolean(onboarding?.profile_task_completed_at);
    const now = Date.now();
    const updates = [];
    if (friendComplete && !onboarding?.friend_task_completed_at) {
        updates.push(env.DB.prepare(`
        UPDATE user_onboarding
        SET friend_task_completed_at=?, updated_at=?
        WHERE user_id=?
      `).bind(now, now, user.id));
    }
    if (officialServerComplete && !onboarding?.official_server_task_completed_at) {
        updates.push(env.DB.prepare(`
        UPDATE user_onboarding
        SET official_server_task_completed_at=?, updated_at=?
        WHERE user_id=?
      `).bind(now, now, user.id));
    }
    if (updates.length)
        await env.DB.batch(updates);
    return json({
        onboarding: {
            tutorial_seen: Boolean(onboarding?.tutorial_seen_at),
            tasks: {
                add_friend: friendComplete,
                join_official_server: officialServerComplete,
                customize_profile: profileComplete,
            },
            official_server: {
                invite_code: OFFICIAL_SERVER_INVITE,
                invite_url: 'https://orbytechat.pages.dev/invites/kyrkat',
                server_id: officialServer?.server_id || null,
                channel_id: officialServer?.channel_id || null,
            },
            promotion: {
                days: 0,
                claimed: true,
                retired: true,
            },
            completed: friendComplete && officialServerComplete && profileComplete,
        },
    });
}

