const PLUS_GIFT_DURATIONS = new Map([
    [7, '1 week'],
    [14, '2 weeks'],
    [30, '1 month'],
    [90, '3 months'],
    [180, '6 months'],
    [365, '12 months'],
]);

const PLUS_GIFT_MONTHS = new Map([[1, 30], [3, 90], [12, 365]]);

const PLUS_MONTHLY_DIAMONDS = 50;

const PLUS_DIAMOND_WEEK_COST = 10;

const PLUS_DIAMOND_WEEK_DAYS = 7;

const PLUS_DIAMOND_WEEK_SOURCE = 'diamonds_week';

function isDiamondWeekSource(value) {
    return String(value || '').trim().toLowerCase().startsWith(PLUS_DIAMOND_WEEK_SOURCE);
}

const PLUS_CHECKOUT_URL = 'https://orbyte.mysellauth.com';

function normalizeGiftCode(value) {
    return String(value || '').trim().replace(/[^A-Za-z0-9_-]/g, '').slice(0, 80).toUpperCase();
}

function createGiftCode() {
    const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    const bytes = new Uint8Array(16);
    crypto.getRandomValues(bytes);
    return Array.from(bytes, byte => alphabet[byte % alphabet.length]).join('');
}

function giftMonthsFromDays(days) {
    const value = Number(days || 0);
    if (value === 30)
        return 1;
    if (value === 90)
        return 3;
    if (value === 365)
        return 12;
    return 0;
}

function addUtcMonths(timestamp, months) {
    const input = new Date(Number(timestamp || Date.now()));
    const day = input.getUTCDate();
    const target = new Date(Date.UTC(input.getUTCFullYear(), input.getUTCMonth() + Number(months || 0), 1, input.getUTCHours(), input.getUTCMinutes(), input.getUTCSeconds(), input.getUTCMilliseconds()));
    const lastDay = new Date(Date.UTC(target.getUTCFullYear(), target.getUTCMonth() + 1, 0)).getUTCDate();
    target.setUTCDate(Math.min(day, lastDay));
    return target.getTime();
}

function primaryFrontendOrigin(env) {
    const values = String(env.FRONTEND_ORIGIN || '').split(',').map(value => value.trim()).filter(Boolean);
    return values.find(value => /^https?:\/\//i.test(value)) || 'https://orbytechat.pages.dev';
}

async function syncPlusMonthlyRewards(db, userId, knownPlus = null) {
    const plus = knownPlus || await getPlusStatus(db, userId);
    if (!plus.active)
        return { awarded: 0, next_reward_at: null };
    if (isDiamondWeekSource(plus.source)) {
        return { awarded: 0, next_reward_at: null };
    }
    const now = Date.now();
    let state = null;
    try {
        state = await db.prepare('SELECT user_id,next_reward_at,last_reward_at,total_awarded FROM plus_monthly_rewards WHERE user_id=?').bind(userId).first();
    }
    catch (error) {
        if (!String(error?.message || error).toLowerCase().includes('no such table'))
            throw error;
        return { awarded: 0, next_reward_at: null };
    }
    if (!state) {
        const reward = await awardDiamonds(db, userId, PLUS_MONTHLY_DIAMONDS, {
            kind: 'plus_monthly', commissionable: false, notes: 'Orbyte Plus monthly benefit'
        });
        const next = addUtcMonths(now, 1);
        await db.prepare(`INSERT INTO plus_monthly_rewards(user_id,next_reward_at,last_reward_at,total_awarded,updated_at) VALUES(?,?,?,?,?)`)
            .bind(userId, next, now, PLUS_MONTHLY_DIAMONDS, now).run();
        return { awarded: PLUS_MONTHLY_DIAMONDS, next_reward_at: next, balance: reward.balance };
    }
    let next = Number(state.next_reward_at || 0);
    if (!next)
        next = addUtcMonths(Number(state.last_reward_at || now), 1);
    let due = 0;
    while (next <= now && (plus.expires_at === null || next < Number(plus.expires_at)) && due < 24) {
        due += 1;
        next = addUtcMonths(next, 1);
    }
    if (!due)
        return { awarded: 0, next_reward_at: next };
    const amount = due * PLUS_MONTHLY_DIAMONDS;
    const reward = await awardDiamonds(db, userId, amount, {
        kind: 'plus_monthly', commissionable: false,
        notes: due === 1 ? 'Orbyte Plus monthly benefit' : `Orbyte Plus monthly benefits (${due} months)`
    });
    await db.prepare(`UPDATE plus_monthly_rewards SET next_reward_at=?,last_reward_at=?,total_awarded=COALESCE(total_awarded,0)+?,updated_at=? WHERE user_id=?`)
        .bind(next, now, amount, now, userId).run();
    return { awarded: amount, next_reward_at: next, balance: reward.balance };
}

async function scheduledPlusMonthlyRewards(env) {
    try {
        const now = Date.now();
        const rows = await env.DB.prepare(`SELECT user_id,tier,expires_at,source,updated_at FROM user_entitlements WHERE tier='plus' AND (expires_at IS NULL OR expires_at>?) ORDER BY updated_at LIMIT 1000`).bind(now).all();
        for (const row of rows.results || []) {
            try {
                const plus = { active: true, tier: 'plus', expires_at: row.expires_at || null, source: row.source || 'manual', attachment_limit: 50 * 1024 * 1024, emoji_limit: 50 };
                await syncPlusMonthlyRewards(env.DB, row.user_id, plus);
            }
            catch (error) {
                console.warn('Could not grant scheduled Plus Diamonds', row.user_id, error);
            }
        }
    }
    catch (error) {
        if (!String(error?.message || error).toLowerCase().includes('no such table'))
            console.warn('Plus monthly reward maintenance failed', error);
    }
}

async function adminCreatePlusGift(request, env, admin) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    let months = Number(body.duration_months || body.months || 0);
    if (!months && body.duration_days)
        months = giftMonthsFromDays(body.duration_days);
    if (![1, 3, 12].includes(months))
        return json({ error: 'Duration must be 1, 3, or 12 months' }, 400);
    const days = PLUS_GIFT_MONTHS.get(months);
    const amount = Math.max(1, Math.min(100, Math.floor(Number(body.amount || 1)) || 1));
    const now = Date.now();
    const origin = primaryFrontendOrigin(env).replace(/\/$/, '');
    const gifts = [];
    for (let index = 0; index < amount; index++) {
        let code = '';
        for (let attempt = 0; attempt < 8; attempt++) {
            const candidate = createGiftCode();
            const exists = await env.DB.prepare('SELECT code FROM plus_gifts WHERE upper(code)=?').bind(candidate).first();
            if (!exists) {
                code = candidate;
                break;
            }
        }
        if (!code)
            return json({ error: 'Could not generate enough unique gift codes' }, 500);
        await env.DB.prepare(`INSERT INTO plus_gifts(code,duration_days,created_by,created_at) VALUES(?,?,?,?)`).bind(code, days, admin.id, now).run();
        gifts.push({
            code, duration_months: months, duration_days: days,
            duration_label: `${months} month${months === 1 ? '' : 's'}`,
            created_at: now, redeemed: false, url: `${origin}/gifts/${encodeURIComponent(code)}`
        });
    }
    await env.DB.prepare(`INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at) VALUES(?,?,?,?,?,?)`)
        .bind(prefixedId('act'), admin.id, 'plus_gift_generate', null, `${amount} key(s) · ${months} month(s)`, now).run();
    return json({ gifts, codes: gifts.map(gift => gift.code), amount, duration_months: months }, 201);
}

async function adminListPlusGifts(env, url) {
    const page = Math.max(1, Math.floor(Number(url?.searchParams?.get('page') || 1)) || 1);
    const limit = 10, offset = (page - 1) * limit;
    const totalRow = await env.DB.prepare('SELECT COUNT(*) AS total FROM plus_gifts').first();
    const total = Number(totalRow?.total || 0), pages = Math.max(1, Math.ceil(total / limit));
    const safePage = Math.min(page, pages), safeOffset = (safePage - 1) * limit;
    const rows = await env.DB.prepare(`
    SELECT pg.code,pg.duration_days,pg.created_at,pg.redeemed_at,pg.revoked_at,pg.gift_message,
           creator.username AS creator_username,creator.display_name AS creator_display_name,
           redeemer.username AS redeemer_username,redeemer.display_name AS redeemer_display_name,
           redeemer.discriminator AS redeemer_discriminator
    FROM plus_gifts pg
    JOIN users creator ON creator.id=pg.created_by
    LEFT JOIN users redeemer ON redeemer.id=pg.redeemed_by
    ORDER BY pg.created_at DESC LIMIT ? OFFSET ?
  `).bind(limit, safeOffset).all();
    const origin = primaryFrontendOrigin(env).replace(/\/$/, '');
    return json({ gifts: (rows.results || []).map(row => {
            const months = giftMonthsFromDays(row.duration_days);
            return {
                ...row,
                duration_months: months || null,
                duration_label: months ? `${months} month${months === 1 ? '' : 's'}` : (PLUS_GIFT_DURATIONS.get(Number(row.duration_days)) || `${row.duration_days} days`),
                redeemed: Boolean(row.redeemed_at),
                url: `${origin}/gifts/${encodeURIComponent(row.code)}`,
            };
        }), pagination: { page: safePage, limit, total, pages } });
}

async function adminAssignPlusGifts(request, env, admin) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const identifier = String(body.identifier || body.user || '').trim();
    if (!identifier)
        return json({ error: 'Enter a username, email, or user ID' }, 400);
    const target = await env.DB.prepare(`SELECT id,username,display_name,email FROM users WHERE id=? OR username=? COLLATE NOCASE OR email=? COLLATE NOCASE LIMIT 1`).bind(identifier, identifier, identifier).first();
    if (!target)
        return json({ error: 'User not found' }, 404);
    const months = Number(body.duration_months || body.months || 0);
    if (![1, 3, 12].includes(months))
        return json({ error: 'Duration must be 1, 3, or 12 months' }, 400);
    const amount = Math.max(1, Math.min(20, Math.floor(Number(body.amount || 1)) || 1)), days = PLUS_GIFT_MONTHS.get(months), now = Date.now();
    const message = String(body.message || '').replace(/\r\n?/g, '\n').trim().slice(0, 500), origin = primaryFrontendOrigin(env).replace(/\/$/, '');
    const gifts = [];
    for (let i = 0; i < amount; i++) {
        let code = '';
        for (let attempt = 0; attempt < 12; attempt++) {
            const candidate = createGiftCode();
            if (!(await env.DB.prepare('SELECT 1 FROM plus_gifts WHERE upper(code)=? LIMIT 1').bind(candidate).first())) {
                code = candidate;
                break;
            }
        }
        if (!code)
            return json({ error: 'Could not create a unique gift code' }, 500);
        await env.DB.prepare(`INSERT INTO plus_gifts(code,duration_days,created_by,created_at,gift_message) VALUES(?,?,?,?,?)`).bind(code, days, target.id, now, message).run();
        gifts.push({ code, duration_months: months, duration_label: `${months} month${months === 1 ? '' : 's'}`, message, url: `${origin}/gifts/${encodeURIComponent(code)}` });
    }
    await env.DB.prepare(`INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at) VALUES(?,?,?,?,?,?)`).bind(prefixedId('act'), admin.id, 'plus_gift_assign', target.id, `${amount} gift(s) · ${months} month(s)`, now).run();
    return json({ ok: true, user: { id: target.id, username: target.username, display_name: target.display_name }, gifts }, 201);
}

async function getPublicPlusGiftPreviewData(env, rawCode) {
    const code = normalizeGiftCode(rawCode);
    if (!code)
        return null;
    const row = await env.DB.prepare(`
    SELECT pg.code,pg.duration_days,pg.created_at,pg.gift_message,pg.created_by,
           pg.redeemed_at,pg.revoked_at,
           u.username AS giver_username,u.display_name AS giver_display_name,u.avatar_url AS giver_avatar_url
    FROM plus_gifts pg
    LEFT JOIN users u ON u.id=pg.created_by
    WHERE upper(pg.code)=?
    LIMIT 1
  `).bind(code).first();
    if (!row)
        return null;
    const months = giftMonthsFromDays(row.duration_days);
    const origin = primaryFrontendOrigin(env).replace(/\/$/, '');
    const giverName = String(row.giver_display_name || row.giver_username || 'Someone').trim() || 'Someone';
    return { gift: {
            code: row.code,
            duration_months: months || null,
            duration_days: Number(row.duration_days),
            duration_label: months ? `${months} month${months === 1 ? '' : 's'}` : (PLUS_GIFT_DURATIONS.get(Number(row.duration_days)) || `${row.duration_days} days`),
            available: !row.redeemed_at && !row.revoked_at,
            redeemed: Boolean(row.redeemed_at), revoked: Boolean(row.revoked_at),
            created_at: Number(row.created_at || 0),
            url: `${origin}/gifts/${encodeURIComponent(row.code)}`,
            message: String(row.gift_message || '').slice(0, 500),
            giver: {
                name: giverName,
                username: String(row.giver_username || ''),
                avatar_url: String(row.giver_avatar_url || '')
            }
        } };
}

