async function updatePlusGiftMessage(request, env, user, rawCode) {
    const code = normalizeGiftCode(rawCode);
    if (!code)
        return json({ error: 'Invalid gift code' }, 400);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const message = String(body.message || '').replace(/\r\n/g, '\n').trim().slice(0, 500);
    const gift = await env.DB.prepare(`SELECT code,created_by,redeemed_at,revoked_at FROM plus_gifts WHERE upper(code)=? LIMIT 1`).bind(code).first();
    if (!gift)
        return json({ error: 'Gift not found' }, 404);
    if (String(gift.created_by) !== String(user.id))
        return json({ error: 'Only the person who created this gift can change its message' }, 403);
    if (gift.redeemed_at || gift.revoked_at)
        return json({ error: 'This gift can no longer be edited' }, 409);
    await env.DB.prepare(`UPDATE plus_gifts SET gift_message=? WHERE upper(code)=?`).bind(message, code).run();
    const updated = await getPublicPlusGiftPreviewData(env, code);
    return json({ ok: true, gift: updated?.gift || null }, 200, { 'Cache-Control': 'no-store, max-age=0' });
}

