async function revokePlusGift(env, user, rawCode) {
    const code = normalizeGiftCode(rawCode);
    if (!code)
        return json({ error: 'Invalid gift code' }, 400);
    const gift = await env.DB.prepare('SELECT code,created_by,redeemed_at,revoked_at FROM plus_gifts WHERE upper(code)=? LIMIT 1').bind(code).first();
    if (!gift)
        return json({ error: 'Gift not found' }, 404);
    if (gift.created_by !== user.id)
        return json({ error: 'You can only revoke gifts in your inventory' }, 403);
    if (gift.redeemed_at)
        return json({ error: 'A claimed gift cannot be revoked' }, 409);
    if (gift.revoked_at)
        return json({ ok: true, revoked: true });
    const now = Date.now();
    await env.DB.prepare('UPDATE plus_gifts SET revoked_at=? WHERE upper(code)=? AND redeemed_at IS NULL AND revoked_at IS NULL').bind(now, code).run();
    return json({ ok: true, revoked: true, revoked_at: now });
}

async function redeemPlusGift(env, user, rawCode) {
    const code = normalizeGiftCode(rawCode);
    if (!code)
        return json({ error: 'Invalid gift code' }, 400);
    const gift = await env.DB.prepare(`SELECT code,duration_days,created_by,source,redeemed_by,redeemed_at,revoked_at FROM plus_gifts WHERE upper(code)=?`).bind(code).first();
    if (!gift)
        return json({ error: 'Gift not found' }, 404);
    if (gift.revoked_at)
        return json({ error: 'This gift has been revoked' }, 409);
    if (gift.redeemed_at)
        return json({ error: gift.redeemed_by === user.id ? 'You already redeemed this gift' : 'This gift has already been redeemed' }, 409);
    const diamondGift = isDiamondWeekSource(gift.source);
    if (diamondGift && String(gift.created_by) === String(user.id))
        return json({ error: 'A Plus gift bought with Diamonds must be given to another Orbyte user.', code: 'DIAMOND_GIFT_SELF_REDEEM' }, 409);
    const current = await getPlusStatus(env.DB, user.id);
    if (current.active && current.expires_at === null)
        return json({ error: 'Your Orbyte Plus membership is already permanent' }, 409);
    if (diamondGift && current.active)
        return json({ error: 'This 7-day Diamond gift can be claimed after your current Plus period expires.', code: 'PLUS_ALREADY_ACTIVE' }, 409);
    const now = Date.now();
    const base = current.active && Number(current.expires_at || 0) > now ? Number(current.expires_at) : now;
    const months = giftMonthsFromDays(gift.duration_days);
    const expiresAt = months ? addUtcMonths(base, months) : base + Number(gift.duration_days) * 86400000;
    const result = await env.DB.prepare(`UPDATE plus_gifts SET redeemed_by=?,redeemed_at=? WHERE upper(code)=? AND redeemed_at IS NULL AND revoked_at IS NULL`)
        .bind(user.id, now, code).run();
    if (!Number(result.meta?.changes || 0))
        return json({ error: 'This gift was redeemed by someone else' }, 409);
    if (!current.active) {
        try {
            await env.DB.prepare('DELETE FROM plus_monthly_rewards WHERE user_id=?').bind(user.id).run();
        }
        catch { }
    }
    await env.DB.batch([
        env.DB.prepare(`INSERT INTO user_entitlements(user_id,tier,expires_at,source,started_at,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET tier=excluded.tier,expires_at=excluded.expires_at,source=excluded.source,started_at=CASE WHEN excluded.tier='plus' THEN CASE WHEN user_entitlements.tier='plus' THEN COALESCE(user_entitlements.started_at,excluded.started_at) ELSE excluded.started_at END ELSE NULL END,updated_at=excluded.updated_at`).bind(user.id, 'plus', expiresAt, diamondGift ? PLUS_DIAMOND_WEEK_SOURCE : `gift:${gift.code}`, now, now),
        env.DB.prepare(`INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at) VALUES(?,?,?,?,?,?)`).bind(prefixedId('act'), user.id, 'plus_gift_redeem', user.id, `${months || gift.duration_days}${months ? ' month(s)' : ' days'} · ${gift.code}`, now),
    ]);
    const plus = await getPlusStatus(env.DB, user.id);
    const monthly = await syncPlusMonthlyRewards(env.DB, user.id, plus);
    return json({
        ok: true, duration_months: months || null, duration_days: Number(gift.duration_days),
        duration_label: months ? `${months} month${months === 1 ? '' : 's'}` : PLUS_GIFT_DURATIONS.get(Number(gift.duration_days)),
        plus, diamonds_awarded: Number(monthly.awarded || 0), diamond_balance: monthly.balance,
    });
}

function plusTrialDurationLabel(days) {
    const value = Number(days || 0);
    if (value === 7)
        return '1 week';
    if (value === 14)
        return '2 weeks';
    if (value === 30)
        return '1 month';
    if (value === 90)
        return '3 months';
    return `${value} days`;
}

function normalizePlusTrialScope(value) {
    const scope = String(value || '').trim().toLowerCase();
    return ['all', 'never', 'inactive'].includes(scope) ? scope : '';
}

async function getPublicPlusTrialPreview(env, rawToken) {
    const token = String(rawToken || '').trim();
    if (!token || token.length > 256)
        return json({ error: 'Trial link is invalid' }, 400, { 'Cache-Control': 'no-store' });
    await ensureRuntimeCompatibility(env.DB);
    const row = await env.DB.prepare(`
    SELECT pto.id,pto.duration_days,pto.status,pto.expires_at,pto.claimed_at,
           u.username,u.display_name
    FROM plus_trial_offers pto JOIN users u ON u.id=pto.user_id
    WHERE pto.token_hash=? LIMIT 1
  `).bind(await sha256(token)).first();
    if (!row)
        return json({ error: 'Trial link was not found' }, 404, { 'Cache-Control': 'no-store' });
    const now = Date.now(), available = row.status === 'pending' && !row.claimed_at && Number(row.expires_at || 0) > now;
    return json({ trial: {
            id: row.id, duration_days: Number(row.duration_days), duration_label: plusTrialDurationLabel(row.duration_days),
            available, expired: Number(row.expires_at || 0) <= now, claimed: Boolean(row.claimed_at),
            username: row.username || '', display_name: row.display_name || row.username || 'Orbyte user'
        } }, 200, { 'Cache-Control': 'no-store' });
}

async function getPendingPlusTrial(env, user) {
    const now = Date.now();
    const row = await env.DB.prepare(`
    SELECT id,campaign_id,duration_days,created_at,expires_at
    FROM plus_trial_offers
    WHERE user_id=? AND status='pending' AND claimed_at IS NULL AND expires_at>?
    ORDER BY created_at DESC LIMIT 1
  `).bind(user.id, now).first();
    if (!row)
        return json({ offer: null });
    return json({ offer: { ...row, duration_days: Number(row.duration_days), duration_label: plusTrialDurationLabel(row.duration_days) } });
}

async function activatePlusTrialOffer(env, user, offer) {
    const current = await getPlusStatus(env.DB, user.id);
    if (current.active)
        return json({ error: 'This trial is for accounts without active Orbyte Plus' }, 409);
    const now = Date.now();
    if (offer.status !== 'pending' || offer.claimed_at || Number(offer.expires_at || 0) <= now)
        return json({ error: 'This Plus trial is no longer available' }, 409);
    const claimed = await env.DB.prepare(`UPDATE plus_trial_offers SET status='claimed',claimed_at=? WHERE id=? AND user_id=? AND status='pending' AND claimed_at IS NULL AND expires_at>?`).bind(now, offer.id, user.id, now).run();
    if (!Number(claimed.meta?.changes || 0))
        return json({ error: 'This Plus trial is no longer available' }, 409);
    const expiresAt = now + Number(offer.duration_days) * 86400000;
    try {
        await env.DB.prepare('DELETE FROM plus_monthly_rewards WHERE user_id=?').bind(user.id).run();
    }
    catch { }
    await env.DB.batch([
        env.DB.prepare(`INSERT INTO user_entitlements(user_id,tier,expires_at,source,started_at,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET tier=excluded.tier,expires_at=excluded.expires_at,source=excluded.source,started_at=CASE WHEN excluded.tier='plus' THEN CASE WHEN user_entitlements.tier='plus' THEN COALESCE(user_entitlements.started_at,excluded.started_at) ELSE excluded.started_at END ELSE NULL END,updated_at=excluded.updated_at`).bind(user.id, 'plus', expiresAt, `trial:${offer.campaign_id}`, now, now),
        env.DB.prepare(`INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at) VALUES(?,?,?,?,?,?)`).bind(prefixedId('act'), user.id, 'plus_trial_claim', user.id, `${plusTrialDurationLabel(offer.duration_days)} trial · ${offer.campaign_id}`, now),
    ]);
    const plus = await getPlusStatus(env.DB, user.id), monthly = await syncPlusMonthlyRewards(env.DB, user.id, plus);
    return json({ ok: true, plus, duration_days: Number(offer.duration_days), duration_label: plusTrialDurationLabel(offer.duration_days), diamonds_awarded: Number(monthly.awarded || 0), diamond_balance: monthly.balance });
}

async function claimPlusTrialByToken(env, user, rawToken) {
    const token = String(rawToken || '').trim();
    if (!token || token.length > 256)
        return json({ error: 'Trial link is invalid' }, 400);
    const offer = await env.DB.prepare(`SELECT id,campaign_id,user_id,duration_days,status,expires_at,claimed_at FROM plus_trial_offers WHERE token_hash=? LIMIT 1`).bind(await sha256(token)).first();
    if (!offer)
        return json({ error: 'Trial link was not found' }, 404);
    if (String(offer.user_id) !== String(user.id))
        return json({ error: 'This Plus trial belongs to another Orbyte account' }, 403);
    return activatePlusTrialOffer(env, user, offer);
}

async function claimPlusTrialByOffer(env, user, offerId) {
    const offer = await env.DB.prepare(`SELECT id,campaign_id,user_id,duration_days,status,expires_at,claimed_at FROM plus_trial_offers WHERE id=? AND user_id=? LIMIT 1`).bind(String(offerId || ''), user.id).first();
    if (!offer)
        return json({ error: 'Plus trial not found' }, 404);
    return activatePlusTrialOffer(env, user, offer);
}

async function dismissPlusTrialOffer(env, user, offerId) {
    await env.DB.prepare(`UPDATE plus_trial_offers SET popup_dismissed_at=? WHERE id=? AND user_id=? AND status='pending'`).bind(Date.now(), String(offerId || ''), user.id).run();
    return json({ ok: true });
}

async function plusTrialCandidateRows(env, scope, inactiveDays) {
    const now = Date.now(), cutoff = now - Math.max(1, Number(inactiveDays || 90)) * 86400000;
    const rows = await env.DB.prepare(`
    SELECT u.id,u.username,u.discriminator,u.display_name,u.email,u.email_verified,u.account_status,
      (SELECT MAX(value) FROM (
        SELECT MAX(CASE WHEN ue.tier='plus' OR ue.source!='manual' THEN COALESCE(ue.expires_at,ue.updated_at) END) AS value FROM user_entitlements ue WHERE ue.user_id=u.id
        UNION ALL SELECT MAX(pg.redeemed_at) FROM plus_gifts pg WHERE pg.redeemed_by=u.id
        UNION ALL SELECT MAX(pt.claimed_at) FROM plus_trial_offers pt WHERE pt.user_id=u.id
        UNION ALL SELECT MAX(aa.created_at) FROM admin_actions aa WHERE aa.target_user_id=u.id AND aa.action IN ('plus_grant','plus_gift_redeem','plus_trial_claim')
      )) AS last_plus_at,
      EXISTS(SELECT 1 FROM user_entitlements cur WHERE cur.user_id=u.id AND cur.tier='plus' AND (cur.expires_at IS NULL OR cur.expires_at>?)) AS plus_active
    FROM users u
    WHERE u.id NOT IN (?,?,?) AND COALESCE(u.account_status,'active') NOT IN ('banned','disabled','deleted')
    ORDER BY u.created_at ASC LIMIT 5000
  `).bind(now, SYSTEM_USER_ID, BYTE_USER_ID, WEBHOOK_USER_ID).all();
    return (rows.results || []).filter(row => {
        if (Number(row.plus_active || 0))
            return false;
        const last = Number(row.last_plus_at || 0);
        if (scope === 'never')
            return !last;
        if (scope === 'inactive')
            return Boolean(last && last < cutoff);
        return true;
    });
}

async function sendPlusTrialCampaignEmails(env, campaignId, mailRows) {
    let sent = 0;
    for (const item of mailRows) {
        let errorText = '';
        try {
            if (!item.email || !Number(item.email_verified || 0))
                throw new Error('No verified email');
            await sendAppsScriptEmail(env, {
                type: 'plus_trial', to: String(item.email).trim().toLowerCase(), username: item.username || '', display_name: item.display_name || item.username || 'Orbyte user',
                trial_duration_label: plusTrialDurationLabel(item.duration_days), action_url: item.claim_url, button_text: 'Claim your Plus'
            });
            sent += 1;
            await env.DB.prepare(`UPDATE plus_trial_offers SET email_sent_at=?,email_error='' WHERE id=?`).bind(Date.now(), item.offer_id).run();
        }
        catch (error) {
            errorText = String(error?.message || error || 'Email failed').slice(0, 240);
            await env.DB.prepare(`UPDATE plus_trial_offers SET email_error=? WHERE id=?`).bind(errorText, item.offer_id).run();
        }
    }
    await env.DB.prepare(`UPDATE plus_trial_campaigns SET email_sent_count=? WHERE id=?`).bind(sent, campaignId).run();
}

async function adminCreatePlusTrialCampaign(request, env, admin, ctx) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const scope = normalizePlusTrialScope(body.scope);
    if (!scope)
        return json({ error: 'Choose all users, users who never had Plus, or users who have not had Plus recently' }, 400);
    const durationDays = Number(body.duration_days || 0);
    if (![7, 14, 30, 90].includes(durationDays))
        return json({ error: 'Trial duration must be 1 week, 2 weeks, 1 month, or 3 months' }, 400);
    const inactiveDays = Math.max(1, Math.min(3650, Math.floor(Number(body.inactive_days || 90)) || 90));
    const candidates = await plusTrialCandidateRows(env, scope, inactiveDays);
    if (!candidates.length)
        return json({ error: 'No eligible users matched this trial campaign' }, 409);
    const now = Date.now(), campaignId = prefixedId('ptrial'), claimExpires = now + 14 * 86400000, origin = primaryFrontendOrigin(env).replace(/\/$/, '');
    await env.DB.prepare(`INSERT INTO plus_trial_campaigns(id,created_by,scope,inactive_days,duration_days,created_at,target_count,email_sent_count) VALUES(?,?,?,?,?,?,?,0)`).bind(campaignId, admin.id, scope, inactiveDays, durationDays, now, candidates.length).run();
    const mailRows = [];
    for (const candidate of candidates) {
        const rawToken = randomBase64Url(32), offerId = prefixedId('pto');
        await env.DB.prepare(`INSERT OR IGNORE INTO plus_trial_offers(id,campaign_id,user_id,token_hash,duration_days,status,created_at,expires_at,email_error) VALUES(?,?,?,?,?,'pending',?,?,'')`).bind(offerId, campaignId, candidate.id, await sha256(rawToken), durationDays, now, claimExpires).run();
        mailRows.push({ ...candidate, offer_id: offerId, duration_days: durationDays, claim_url: `${origin}/plus-trial/${encodeURIComponent(rawToken)}` });
    }
    const emailEligible = mailRows.filter(row => row.email && Number(row.email_verified || 0)).length;
    const task = sendPlusTrialCampaignEmails(env, campaignId, mailRows);
    if (ctx?.waitUntil)
        ctx.waitUntil(task);
    else
        task.catch(error => console.error('Plus trial email campaign failed', error));
    await env.DB.prepare(`INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at) VALUES(?,?,?,?,?,?)`).bind(prefixedId('act'), admin.id, 'plus_trial_campaign', null, `${scope} · ${plusTrialDurationLabel(durationDays)} · ${candidates.length} user(s)`, now).run();
    return json({ ok: true, campaign: { id: campaignId, scope, inactive_days: inactiveDays, duration_days: durationDays, duration_label: plusTrialDurationLabel(durationDays), target_count: candidates.length, email_eligible_count: emailEligible, created_at: now } }, 201);
}

async function adminListPlusTrialCampaigns(env) {
    const campaigns = await env.DB.prepare(`SELECT id,scope,inactive_days,duration_days,created_at,target_count,email_sent_count FROM plus_trial_campaigns ORDER BY created_at DESC LIMIT 50`).all();
    return json({ campaigns: (campaigns.results || []).map(row => ({ ...row, duration_label: plusTrialDurationLabel(row.duration_days) })) });
}

async function adminBanByUsername(request, env, admin) {
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const username = normalizeUsername(body.username);
    const reason = cleanText(body.reason || 'Banned by an administrator', 1000, true);
    if (!username)
        return json({ error: 'Username is required' }, 400);
    if (!reason)
        return json({ error: 'Reason is required' }, 400);
    const target = await env.DB.prepare(`
    SELECT id,username,discriminator,display_name,role,account_status
    FROM users
    WHERE lower(username)=lower(?)
    LIMIT 1
  `).bind(username).first();
    if (!target)
        return json({ error: 'User not found' }, 404);
    if (target.id === SYSTEM_USER_ID)
        return json({ error: 'The Orbyte system account cannot be banned' }, 403);
    const hierarchy = await guardAccountManagementTarget(env, admin, target.id, 'ban');
    if (hierarchy.error)
        return hierarchy.error;
    if (target.account_status === 'banned')
        return json({ error: 'That account is already banned' }, 409);
    const now = Date.now();
    const violationId = prefixedId('vio');
    await env.DB.batch([
        env.DB.prepare(`
      INSERT INTO violations(
        id,user_id,report_id,violation_type,severity,reason,action,evidence_text,
        status,expires_at,created_by,created_at
      ) VALUES(?,?,NULL,'Administrative ban','critical',?,'ban','',
        'active',NULL,?,?)
    `).bind(violationId, target.id, reason, admin.id, now),
        env.DB.prepare(`
      UPDATE users SET account_status='banned',suspension_until=NULL WHERE id=?
    `).bind(target.id),
        env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(target.id),
        env.DB.prepare(`
      INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at)
      VALUES(?,?,?,?,?,?)
    `).bind(prefixedId('act'), admin.id, 'ban_by_username', target.id, reason, now),
    ]);
    try {
        await sendSystemDm(env.DB, target.id, {
            kind: 'violation',
            color: '#da373c',
            dedupeKey: `violation:${violationId}`,
            title: 'Your account was banned',
            description: `${reason}\n\nYou can review this action and submit an appeal from Account Standing.`,
            actions: [{ label: 'Account Standing', action: 'safety_hub' }],
        });
    }
    catch (error) {
        console.warn('Could not send ban system DM', error);
    }
    return json({
        ok: true,
        user: {
            id: target.id,
            username: target.username,
            discriminator: target.discriminator,
            display_name: target.display_name,
            account_status: 'banned',
        },
        violation_id: violationId,
    });
}

const SELLAUTH_API_BASE = 'https://api.sellauth.com';

function sellAuthPlusConfig(env) {
    const sharedProduct = String(env.SELLAUTH_PLUS_PRODUCT_ID || '').trim();
    const currency = String(env.SELLAUTH_PLUS_CURRENCY || 'EUR').trim().toUpperCase().slice(0, 6) || 'EUR';
    const storefrontUrl = (() => {
        const raw = String(env.SELLAUTH_STOREFRONT_URL || PLUS_CHECKOUT_URL || 'https://orbyte.mysellauth.com').trim();
        try {
            const parsed = new URL(raw);
            if (parsed.protocol !== 'https:')
                return 'https://orbyte.mysellauth.com';
            return `${parsed.origin}${parsed.pathname.replace(/\/$/, '')}`;
        }
        catch {
            return 'https://orbyte.mysellauth.com';
        }
    })();
    const makePlan = (months, label, defaultPrice, defaultBadge = '') => {
        const prefix = `SELLAUTH_PLUS_${months}M`;
        const productId = String(env[`${prefix}_PRODUCT_ID`] || sharedProduct || '').trim();
        const variantId = String(env[`${prefix}_VARIANT_ID`] || '').trim();
        const price = String(env[`${prefix}_PRICE`] || defaultPrice).trim();
        const badge = String(env[`${prefix}_BADGE`] || defaultBadge).trim().slice(0, 40);
        return { months, label, productId, variantId, price, badge };
    };
    const plans = [
        makePlan(12, '1 Year', '€9.99', '2 MONTHS FREE'),
        makePlan(3, '3 Months', '€2.99', ''),
        makePlan(1, '1 Month', '€0.99', ''),
    ];
    const apiKey = String(env.SELLAUTH_API_KEY || '').trim();
    const shopId = String(env.SELLAUTH_SHOP_ID || '').trim();
    const webhookSecret = String(env.SELLAUTH_WEBHOOK_SECRET || '').trim();
    return {
        apiKey, shopId, webhookSecret, currency, plans, storefrontUrl,
        checkoutMode: 'product_embed',
        apiVerificationConfigured: Boolean(apiKey && shopId),
        configured: Boolean(webhookSecret &&
            plans.every(plan => plan.productId && plan.variantId)),
    };
}

function sellAuthReceiptEmail(env, purchaseId, customerEmail = '') {
    const sink = String(env.SELLAUTH_RECEIPT_SINK_EMAIL || '').trim().toLowerCase();
    if (!sink)
        return String(customerEmail || '').trim().toLowerCase();
    const match = sink.match(/^([^@]+)@(gmail\.com|googlemail\.com)$/i);
    if (!match)
        return String(customerEmail || '').trim().toLowerCase();
    const token = String(purchaseId || '').replace(/[^a-z0-9]/gi, '').slice(-32) || String(Date.now());
    return `${match[1]}+orbyte-${token}@${match[2].toLowerCase()}`;
}

function buildSellAuthCheckoutLink(config, plan, email = '') {
    const url = new URL(`${config.storefrontUrl.replace(/\/$/, '')}/checkout-link`);
    url.searchParams.set('cart[0][productId]', String(plan.productId));
    url.searchParams.set('cart[0][variantId]', String(plan.variantId));
    url.searchParams.set('cart[0][quantity]', '1');
    if (config.currency)
        url.searchParams.set('currency', String(config.currency).toUpperCase());
    if (email)
        url.searchParams.set('email', String(email).trim().toLowerCase());
    return url.href;
}

function buildSellAuthProductEmbedUrl(config, plan, email = '') {
    const base = config.storefrontUrl.replace(/\/$/, '');
    const url = new URL(`${base}/embed/product/${encodeURIComponent(String(plan.productId))}`);
    url.searchParams.set('embed', '1');
    url.searchParams.set('quantity', '1');
    url.searchParams.set('variant', String(plan.variantId));
    if (email)
        url.searchParams.set('email', String(email).trim().toLowerCase());
    return url.href;
}

function sellAuthJsonId(value) {
    const raw = String(value == null ? '' : value).trim();
    if (/^\d+$/.test(raw) && raw.length < 16)
        return Number(raw);
    return raw;
}

function sellAuthDeepValue(obj, paths) {
    for (const path of paths) {
        let current = obj;
        let ok = true;
        for (const part of path.split('.')) {
            if (current == null || !(part in Object(current))) {
                ok = false;
                break;
            }
            current = current[part];
        }
        if (ok && current !== undefined && current !== null && String(current).trim() !== '')
            return current;
    }
    return null;
}

function sellAuthCheckoutUrl(payload) {
    const value = sellAuthDeepValue(payload, [
        'url', 'checkout_url', 'checkoutUrl', 'data.url', 'data.checkout_url', 'data.checkoutUrl',
        'checkout.url', 'data.checkout.url'
    ]);
    if (!value)
        return '';
    try {
        const parsed = new URL(String(value));
        return parsed.protocol === 'https:' ? parsed.href : '';
    }
    catch {
        return '';
    }
}

function sellAuthInvoiceId(payload) {
    const value = sellAuthDeepValue(payload, [
        'invoice_id', 'invoiceId', 'invoice.id', 'data.invoice_id', 'data.invoiceId', 'data.invoice.id',
        'order.invoice_id', 'data.order.invoice_id'
    ]);
    return value == null ? '' : String(value).trim().slice(0, 160);
}

function sellAuthReference(payload, checkoutUrl = '') {
    const value = sellAuthDeepValue(payload, [
        'reference', 'reference_id', 'unique_id', 'uid', 'checkout_id', 'checkoutId',
        'data.reference', 'data.reference_id', 'data.unique_id', 'data.uid', 'data.checkout_id'
    ]);
    if (value != null && String(value).trim())
        return String(value).trim().slice(0, 180);
    if (checkoutUrl) {
        try {
            const parsed = new URL(checkoutUrl);
            const parts = parsed.pathname.split('/').filter(Boolean);
            const tail = parts[parts.length - 1] || '';
            if (tail && tail.length <= 180)
                return tail;
        }
        catch { }
    }
    return '';
}

function sellAuthStatusText(payload) {
    const value = sellAuthDeepValue(payload, [
        'payment_status', 'status', 'invoice.status', 'data.payment_status', 'data.status', 'data.invoice.status',
        'order.status', 'data.order.status'
    ]);
    return String(value || '').trim().toLowerCase().replace(/[\s-]+/g, '_');
}

function sellAuthInvoicePaid(payload) {
    const bool = sellAuthDeepValue(payload, [
        'paid', 'is_paid', 'completed', 'invoice.paid', 'data.paid', 'data.is_paid', 'data.completed',
        'data.invoice.paid'
    ]);
    if (bool === true || bool === 1 || String(bool).toLowerCase() === 'true')
        return true;
    const status = sellAuthStatusText(payload);
    return ['paid', 'completed', 'complete', 'fulfilled', 'delivered', 'success', 'succeeded'].includes(status);
}

function sellAuthEmail(payload) {
    const value = sellAuthDeepValue(payload, [
        'email', 'customer_email', 'buyer_email', 'invoice.email', 'invoice.customer.email', 'customer.email',
        'data.email', 'data.customer_email', 'data.buyer_email', 'data.invoice.email', 'data.invoice.customer.email',
        'data.customer.email', 'order.email', 'order.customer.email', 'data.order.email', 'data.order.customer.email',
        'item.email', 'item.customer_email'
    ]);
    return String(value || '').trim().toLowerCase().slice(0, 254);
}

function sellAuthItems(payload) {
    const candidates = [
        payload?.items, payload?.products, payload?.cart, payload?.order_items,
        payload?.invoice?.items, payload?.invoice?.products,
        payload?.data?.items, payload?.data?.products, payload?.data?.cart,
        payload?.data?.invoice?.items, payload?.data?.invoice?.products,
        payload?.order?.items, payload?.data?.order?.items,
    ];
    return candidates.find(Array.isArray) || [];
}

function sellAuthProductIdentity(payload) {
    const item = sellAuthItems(payload)[0] || payload?.item || payload?.data?.item || payload?.product_item || payload?.data?.product_item || {};
    const product = sellAuthDeepValue(item, [
        'product_id', 'productId', 'product.id', 'product.id_str',
        'product.id_string', 'productIdString'
    ]) ?? sellAuthDeepValue(payload, [
        'product_id', 'productId', 'product.id', 'data.product_id', 'data.productId', 'data.product.id',
        'item.product_id', 'item.productId', 'item.product.id'
    ]);
    const variant = sellAuthDeepValue(item, [
        'variant_id', 'variantId', 'variant.id', 'price_id', 'priceId'
    ]) ?? sellAuthDeepValue(payload, [
        'variant_id', 'variantId', 'variant.id', 'data.variant_id', 'data.variantId', 'data.variant.id',
        'item.variant_id', 'item.variantId', 'item.variant.id'
    ]);
    return {
        productId: product == null ? '' : String(product).trim(),
        variantId: variant == null ? '' : String(variant).trim(),
    };
}

async function sellAuthApiRequest(env, method, path, body = null) {
    const config = sellAuthPlusConfig(env);
    if (!config.apiKey || !config.shopId) {
        const error = new Error('SellAuth is not configured');
        error.code = 'SELLAUTH_NOT_CONFIGURED';
        throw error;
    }
    const response = await fetch(`${SELLAUTH_API_BASE}${path}`, {
        method,
        headers: {
            'Authorization': `Bearer ${config.apiKey}`,
            'Accept': 'application/json',
            ...(body ? { 'Content-Type': 'application/json' } : {}),
        },
        ...(body ? { body: JSON.stringify(body) } : {}),
    });
    const raw = await response.text();
    let data = {};
    try {
        data = raw ? JSON.parse(raw) : {};
    }
    catch {
        data = { raw: raw.slice(0, 1000) };
    }
    if (!response.ok) {
        const message = String(sellAuthDeepValue(data, ['message', 'error', 'errors.0.message', 'data.message']) ||
            `SellAuth request failed (${response.status})`);
        const error = new Error(message);
        error.code = 'SELLAUTH_REQUEST_FAILED';
        error.status = response.status;
        throw error;
    }
    return data;
}

async function ensurePlusPurchaseSchema(db) {
    await db.prepare(`CREATE TABLE IF NOT EXISTS plus_purchases (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    intent TEXT NOT NULL,
    duration_months INTEGER NOT NULL,
    product_id TEXT NOT NULL,
    variant_id TEXT NOT NULL,
    email TEXT NOT NULL DEFAULT '',
    sellauth_email TEXT NOT NULL DEFAULT '',
    status TEXT NOT NULL DEFAULT 'pending',
    sellauth_invoice_id TEXT,
    sellauth_reference TEXT,
    checkout_url TEXT NOT NULL DEFAULT '',
    gift_code TEXT,
    created_at INTEGER NOT NULL,
    paid_at INTEGER,
    fulfilled_at INTEGER,
    orbyte_email_sent_at INTEGER,
    updated_at INTEGER NOT NULL
  )`).run();
    try {
        await db.prepare(`ALTER TABLE plus_purchases ADD COLUMN sellauth_email TEXT NOT NULL DEFAULT ''`).run();
    }
    catch { }
    try {
        await db.prepare(`ALTER TABLE plus_purchases ADD COLUMN orbyte_email_sent_at INTEGER`).run();
    }
    catch { }
    await db.prepare(`CREATE UNIQUE INDEX IF NOT EXISTS idx_plus_purchases_invoice
    ON plus_purchases(sellauth_invoice_id)
    WHERE sellauth_invoice_id IS NOT NULL AND sellauth_invoice_id != ''`).run();
    await db.prepare(`CREATE INDEX IF NOT EXISTS idx_plus_purchases_user_status
    ON plus_purchases(user_id,status,created_at DESC)`).run();
    await db.prepare(`CREATE INDEX IF NOT EXISTS idx_plus_purchases_reference
    ON plus_purchases(sellauth_reference)`).run();
}

function publicPlusPurchase(row, plus = null, monthly = null) {
    if (!row)
        return null;
    const origin = 'https://orbytechat.pages.dev';
    return {
        id: row.id,
        intent: row.intent,
        duration_months: Number(row.duration_months || 0),
        status: String(row.status || 'pending'),
        checkout_url: String(row.checkout_url || ''),
        gift_code: row.gift_code || null,
        gift_url: row.gift_code ? `${origin}/gifts/${encodeURIComponent(row.gift_code)}` : null,
        created_at: Number(row.created_at || 0),
        paid_at: row.paid_at ? Number(row.paid_at) : null,
        fulfilled_at: row.fulfilled_at ? Number(row.fulfilled_at) : null,
        ...(plus ? { plus } : {}),
        ...(monthly ? {
            diamonds_awarded: Number(monthly.awarded || 0),
            diamond_balance: monthly.balance,
            next_reward_at: monthly.next_reward_at || null,
        } : {}),
    };
}

async function createUniquePaidGiftCode(env, purchaserId, months, now) {
    const days = PLUS_GIFT_MONTHS.get(Number(months));
    if (!days)
        throw new Error('Unsupported gift duration');
    for (let attempt = 0; attempt < 12; attempt++) {
        const code = createGiftCode();
        const existing = await env.DB.prepare('SELECT code FROM plus_gifts WHERE upper(code)=?').bind(code).first();
        if (existing)
            continue;
        await env.DB.prepare(`INSERT INTO plus_gifts(code,duration_days,created_by,created_at) VALUES(?,?,?,?)`)
            .bind(code, days, purchaserId, now).run();
        return code;
    }
    throw new Error('Could not create a unique gift code');
}

async function sendOrbytePlusPurchaseEmail(env, row) {
    if (!row || Number(row.orbyte_email_sent_at || 0) > 0 || !isEmail(String(row.email || '')))
        return row;
    try {
        const user = await env.DB.prepare(`SELECT username,display_name FROM users WHERE id=? LIMIT 1`).bind(row.user_id).first();
        const displayName = user?.display_name || user?.username || 'Orbyte user';
        const months = Number(row.duration_months || 0);
        const duration = months === 12 ? '1 year' : months === 3 ? '3 months' : '1 month';
        const origin = primaryFrontendOrigin(env).replace(/\/$/, '');
        if (row.intent === 'gift') {
            const giftUrl = row.gift_code ? `${origin}/gifts/${encodeURIComponent(row.gift_code)}` : origin;
            await sendAppsScriptEmail(env, {
                type: 'plus', to: String(row.email).trim().toLowerCase(), display_name: displayName,
                subject: 'Your Orbyte Plus gift is ready', kicker: 'ORBYTE PLUS GIFT', title: 'Your Plus gift is ready!',
                intro: `Hey, ${displayName}`, body: `Your ${duration} Orbyte Plus gift is ready to share.`,
                action_label: 'Open gift', action_url: giftUrl, badge: 'GIFT', footer: ''
            });
        }
        else {
            await sendAppsScriptEmail(env, {
                type: 'plus_welcome', to: String(row.email).trim().toLowerCase(), display_name: displayName,
                subject: 'Orbyte Plus activated', kicker: 'ORBYTE PLUS', title: 'Plus activated!',
                intro: `Hey, ${displayName}`, body: `Your ${duration} Orbyte Plus purchase is active. Thanks for supporting Orbyte.`,
                action_label: 'Open Plus Home', action_url: origin, badge: 'PLUS', footer: ''
            });
        }
        const sentAt = Date.now();
        await env.DB.prepare(`UPDATE plus_purchases SET orbyte_email_sent_at=? WHERE id=? AND orbyte_email_sent_at IS NULL`).bind(sentAt, row.id).run();
        return env.DB.prepare('SELECT * FROM plus_purchases WHERE id=? LIMIT 1').bind(row.id).first();
    }
    catch (error) {
        console.warn('Could not send Orbyte Plus purchase email through Apps Script', row.id, String(error?.message || error));
        return row;
    }
}

async function fulfillSellAuthPlusPurchase(env, purchase, verifiedInvoice = null) {
    if (!purchase)
        return null;
    await ensurePlusPurchaseSchema(env.DB);
    let currentRow = await env.DB.prepare('SELECT * FROM plus_purchases WHERE id=? LIMIT 1').bind(purchase.id).first();
    if (!currentRow)
        return null;
    if (currentRow.status === 'fulfilled')
        return sendOrbytePlusPurchaseEmail(env, currentRow);
    const now = Date.now();
    if (currentRow.status === 'processing' && now - Number(currentRow.updated_at || 0) < 60000)
        return currentRow;
    if (currentRow.status === 'processing') {
        await env.DB.prepare(`UPDATE plus_purchases SET status='paid',updated_at=? WHERE id=? AND status='processing'`)
            .bind(now, currentRow.id).run();
    }
    const lock = await env.DB.prepare(`UPDATE plus_purchases
    SET status='processing',paid_at=COALESCE(paid_at,?),updated_at=?
    WHERE id=? AND status IN ('pending','paid')`)
        .bind(now, now, currentRow.id).run();
    if (!Number(lock.meta?.changes || 0)) {
        return env.DB.prepare('SELECT * FROM plus_purchases WHERE id=?').bind(currentRow.id).first();
    }
    try {
        if (currentRow.intent === 'gift') {
            const code = currentRow.gift_code || await createUniquePaidGiftCode(env, currentRow.user_id, currentRow.duration_months, now);
            await env.DB.prepare(`UPDATE plus_purchases SET status='fulfilled',gift_code=?,fulfilled_at=?,updated_at=? WHERE id=?`)
                .bind(code, now, now, currentRow.id).run();
        }
        else {
            const current = await getPlusStatus(env.DB, currentRow.user_id);
            if (!(current.active && current.expires_at === null)) {
                const base = current.active && Number(current.expires_at || 0) > now ? Number(current.expires_at) : now;
                const expiresAt = addUtcMonths(base, Number(currentRow.duration_months || 0));
                if (!current.active) {
                    try {
                        await env.DB.prepare('DELETE FROM plus_monthly_rewards WHERE user_id=?').bind(currentRow.user_id).run();
                    }
                    catch { }
                }
                await env.DB.prepare(`INSERT INTO user_entitlements(user_id,tier,expires_at,source,started_at,updated_at)
          VALUES(?,?,?,?,?,?)
          ON CONFLICT(user_id) DO UPDATE SET
            tier=excluded.tier,
            expires_at=excluded.expires_at,
            source=excluded.source,
            started_at=CASE
              WHEN user_entitlements.tier='plus' THEN COALESCE(user_entitlements.started_at,excluded.started_at)
              ELSE excluded.started_at
            END,
            updated_at=excluded.updated_at`)
                    .bind(currentRow.user_id, 'plus', expiresAt, `sellauth:${currentRow.id}`, now, now).run();
                const plus = await getPlusStatus(env.DB, currentRow.user_id);
                await syncPlusMonthlyRewards(env.DB, currentRow.user_id, plus);
            }
            await env.DB.prepare(`UPDATE plus_purchases SET status='fulfilled',fulfilled_at=?,updated_at=? WHERE id=?`)
                .bind(now, now, currentRow.id).run();
        }
    }
    catch (error) {
        await env.DB.prepare(`UPDATE plus_purchases SET status='paid',updated_at=? WHERE id=? AND status='processing'`)
            .bind(Date.now(), currentRow.id).run().catch(() => { });
        throw error;
    }
    const finalRow = await env.DB.prepare('SELECT * FROM plus_purchases WHERE id=? LIMIT 1').bind(currentRow.id).first();
    return sendOrbytePlusPurchaseEmail(env, finalRow);
}

async function findSellAuthPurchaseForPayload(env, payload) {
    await ensurePlusPurchaseSchema(env.DB);
    const invoiceId = sellAuthInvoiceId(payload);
    if (invoiceId) {
        const exact = await env.DB.prepare(`SELECT * FROM plus_purchases
      WHERE sellauth_invoice_id=? LIMIT 1`).bind(invoiceId).first();
        if (exact)
            return exact;
    }
    const reference = String(sellAuthDeepValue(payload, [
        'reference', 'reference_id', 'unique_id', 'uid', 'checkout_id',
        'data.reference', 'data.reference_id', 'data.unique_id', 'data.uid', 'data.checkout_id'
    ]) || '').trim();
    if (reference) {
        const exact = await env.DB.prepare(`SELECT * FROM plus_purchases
      WHERE sellauth_reference=? LIMIT 1`).bind(reference).first();
        if (exact)
            return exact;
    }
    const email = sellAuthEmail(payload);
    const identity = sellAuthProductIdentity(payload);
    if (email && identity.productId) {
        if (identity.variantId) {
            const row = await env.DB.prepare(`SELECT * FROM plus_purchases
        WHERE lower(COALESCE(NULLIF(sellauth_email,''),email))=? AND product_id=? AND variant_id=?
          AND status IN ('pending','paid','processing')
          AND created_at>?
        ORDER BY created_at DESC LIMIT 1`)
                .bind(email, String(identity.productId), String(identity.variantId), Date.now() - 7 * 86400000).first();
            if (row)
                return row;
        }
        const row = await env.DB.prepare(`SELECT * FROM plus_purchases
      WHERE lower(COALESCE(NULLIF(sellauth_email,''),email))=? AND product_id=?
        AND status IN ('pending','paid','processing')
        AND created_at>?
      ORDER BY created_at DESC LIMIT 1`)
            .bind(email, String(identity.productId), Date.now() - 7 * 86400000).first();
        if (row)
            return row;
    }
    return null;
}

async function fetchSellAuthInvoice(env, invoiceId) {
    if (!invoiceId)
        return null;
    const config = sellAuthPlusConfig(env);
    return sellAuthApiRequest(env, 'GET', `/v1/shops/${encodeURIComponent(config.shopId)}/invoices/${encodeURIComponent(invoiceId)}`);
}

async function reconcileSellAuthPlusPurchase(env, purchase) {
    if (!purchase || purchase.status === 'fulfilled')
        return purchase;
    if (!purchase.sellauth_invoice_id)
        return purchase;
    try {
        const invoice = await fetchSellAuthInvoice(env, purchase.sellauth_invoice_id);
        if (!sellAuthInvoicePaid(invoice))
            return purchase;
        return await fulfillSellAuthPlusPurchase(env, purchase, invoice);
    }
    catch (error) {
        console.warn('SellAuth invoice reconciliation failed', purchase.id, String(error?.message || error));
        return purchase;
    }
}

async function getSellAuthPlusCheckoutConfig(env, user) {
    await ensurePlusPurchaseSchema(env.DB);
    const config = sellAuthPlusConfig(env);
    const account = await env.DB.prepare('SELECT email,email_verified,diamonds FROM users WHERE id=? LIMIT 1').bind(user.id).first();
    const plus = await getPlusStatus(env.DB, user.id);
    return json({
        configured: config.configured,
        checkout_mode: 'product_embed',
        checkout_api_required: false,
        embedded_checkout: true,
        webhook_configured: Boolean(config.webhookSecret),
        api_verification_configured: config.apiVerificationConfigured,
        currency: config.currency,
        storefront_url: config.storefrontUrl,
        shop_id: config.shopId || null,
        default_email: Number(account?.email_verified || 0) ? String(account?.email || '') : '',
        plus,
        diamond_balance: Math.max(0, Number(account?.diamonds || 0)),
        diamond_week: { available: !plus.active, gift_available: true, cost: PLUS_DIAMOND_WEEK_COST, days: PLUS_DIAMOND_WEEK_DAYS, label: '7 days of Plus' },
        plans: config.plans.map(plan => ({
            months: plan.months, label: plan.label, price: plan.price, badge: plan.badge,
            product_id: plan.productId || null, variant_id: plan.variantId || null,
            checkout_ready: Boolean(plan.productId && plan.variantId)
        })),
    }, 200, { 'Cache-Control': 'no-store' });
}

async function purchasePlusWeekWithDiamonds(env, user) {
    const allowed = await checkRateLimit(env.DB, `plus-diamond-week:${user.id}`, 6, 5 * 60 * 1000);
    if (!allowed)
        return json({ error: 'Too many Plus pass attempts. Try again in a few minutes.' }, 429);
    const current = await getPlusStatus(env.DB, user.id);
    if (current.active) {
        return json({ error: 'You already have active Orbyte Plus. The 7-day Diamond pass can be bought after it expires.', code: 'PLUS_ALREADY_ACTIVE' }, 409);
    }
    const now = Date.now();
    const expiresAt = now + PLUS_DIAMOND_WEEK_DAYS * 86400000;
    const source = PLUS_DIAMOND_WEEK_SOURCE;
    const debit = await env.DB.prepare('UPDATE users SET diamonds=diamonds-? WHERE id=? AND diamonds>=? RETURNING diamonds')
        .bind(PLUS_DIAMOND_WEEK_COST, user.id, PLUS_DIAMOND_WEEK_COST).first();
    if (!debit) {
        const wallet = await env.DB.prepare('SELECT diamonds FROM users WHERE id=? LIMIT 1').bind(user.id).first();
        return json({
            error: `You need ${PLUS_DIAMOND_WEEK_COST} Diamonds for a 7-day Plus pass`,
            code: 'NOT_ENOUGH_DIAMONDS',
            balance: Math.max(0, Number(wallet?.diamonds || 0)),
            cost: PLUS_DIAMOND_WEEK_COST
        }, 409);
    }
    try {
        try {
            await env.DB.prepare('DELETE FROM plus_monthly_rewards WHERE user_id=?').bind(user.id).run();
        }
        catch { }
        await env.DB.batch([
            env.DB.prepare(`INSERT INTO user_entitlements(user_id,tier,expires_at,source,started_at,updated_at)
        VALUES(?,?,?,?,?,?)
        ON CONFLICT(user_id) DO UPDATE SET
          tier='plus',
          expires_at=excluded.expires_at,
          source=excluded.source,
          started_at=CASE WHEN user_entitlements.tier='plus' THEN COALESCE(user_entitlements.started_at,excluded.started_at) ELSE excluded.started_at END,
          updated_at=excluded.updated_at`)
                .bind(user.id, 'plus', expiresAt, source, now, now),
            env.DB.prepare('INSERT INTO diamond_transactions(id,user_id,amount,kind,notes,created_at) VALUES(?,?,?,?,?,?)')
                .bind(prefixedId('dia'), user.id, -PLUS_DIAMOND_WEEK_COST, 'plus_week_purchase', `${PLUS_DIAMOND_WEEK_DAYS}-day Orbyte Plus pass`, now),
            env.DB.prepare('INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at) VALUES(?,?,?,?,?,?)')
                .bind(prefixedId('act'), user.id, 'plus_diamond_week_purchase', user.id, `${PLUS_DIAMOND_WEEK_DAYS} days · ${PLUS_DIAMOND_WEEK_COST} Diamonds`, now),
        ]);
    }
    catch (error) {
        try {
            await env.DB.prepare('UPDATE users SET diamonds=COALESCE(diamonds,0)+? WHERE id=?').bind(PLUS_DIAMOND_WEEK_COST, user.id).run();
        }
        catch { }
        throw error;
    }
    const plus = await getPlusStatus(env.DB, user.id);
    return json({
        ok: true,
        plus,
        days: PLUS_DIAMOND_WEEK_DAYS,
        cost: PLUS_DIAMOND_WEEK_COST,
        balance: Math.max(0, Number(debit.diamonds || 0)),
        monthly_diamonds_included: !isDiamondWeekSource(plus.source),
    }, 200, { 'Cache-Control': 'no-store' });
}

async function purchasePlusWeekGiftWithDiamonds(env, user) {
    const allowed = await checkRateLimit(env.DB, `plus-diamond-week-gift:${user.id}`, 8, 5 * 60 * 1000);
    if (!allowed)
        return json({ error: 'Too many Plus gift attempts. Try again in a few minutes.' }, 429);
    const now = Date.now();
    const debit = await env.DB.prepare('UPDATE users SET diamonds=diamonds-? WHERE id=? AND diamonds>=? RETURNING diamonds')
        .bind(PLUS_DIAMOND_WEEK_COST, user.id, PLUS_DIAMOND_WEEK_COST).first();
    if (!debit) {
        const wallet = await env.DB.prepare('SELECT diamonds FROM users WHERE id=? LIMIT 1').bind(user.id).first();
        return json({
            error: `You need ${PLUS_DIAMOND_WEEK_COST} Diamonds for a 7-day Plus gift`,
            code: 'NOT_ENOUGH_DIAMONDS',
            balance: Math.max(0, Number(wallet?.diamonds || 0)),
            cost: PLUS_DIAMOND_WEEK_COST
        }, 409);
    }
    let code = '';
    try {
        for (let attempt = 0; attempt < 16; attempt++) {
            const candidate = createGiftCode();
            try {
                await env.DB.prepare(`INSERT INTO plus_gifts(code,duration_days,created_by,created_at,source,gift_message)
          VALUES(?,?,?,?,?,'')`)
                    .bind(candidate, PLUS_DIAMOND_WEEK_DAYS, user.id, now, 'diamonds_week_gift').run();
                code = candidate;
                break;
            }
            catch (error) {
                const message = String(error?.message || error).toLowerCase();
                if (message.includes('unique') || message.includes('constraint'))
                    continue;
                throw error;
            }
        }
        if (!code)
            throw new Error('Could not create a unique Plus gift code');
        await env.DB.batch([
            env.DB.prepare('INSERT INTO diamond_transactions(id,user_id,amount,kind,notes,created_at) VALUES(?,?,?,?,?,?)')
                .bind(prefixedId('dia'), user.id, -PLUS_DIAMOND_WEEK_COST, 'plus_week_gift_purchase', `${PLUS_DIAMOND_WEEK_DAYS}-day Orbyte Plus gift`, now),
            env.DB.prepare('INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at) VALUES(?,?,?,?,?,?)')
                .bind(prefixedId('act'), user.id, 'plus_diamond_week_gift_purchase', user.id, `${PLUS_DIAMOND_WEEK_DAYS} day gift · ${PLUS_DIAMOND_WEEK_COST} Diamonds`, now),
        ]);
    }
    catch (error) {
        if (code) {
            try {
                await env.DB.prepare('DELETE FROM plus_gifts WHERE code=? AND created_by=? AND redeemed_at IS NULL').bind(code, user.id).run();
            }
            catch { }
        }
        try {
            await env.DB.prepare('UPDATE users SET diamonds=COALESCE(diamonds,0)+? WHERE id=?').bind(PLUS_DIAMOND_WEEK_COST, user.id).run();
        }
        catch { }
        throw error;
    }
    const origin = primaryFrontendOrigin(env).replace(/\/$/, '');
    return json({
        ok: true,
        cost: PLUS_DIAMOND_WEEK_COST,
        balance: Math.max(0, Number(debit.diamonds || 0)),
        gift: {
            code,
            duration_days: PLUS_DIAMOND_WEEK_DAYS,
            duration_label: '1 week',
            url: `${origin}/gifts/${encodeURIComponent(code)}`,
            monthly_diamonds_included: false
        }
    }, 201, { 'Cache-Control': 'no-store' });
}

async function createSellAuthPlusPurchase(request, env, user) {
    await ensurePlusPurchaseSchema(env.DB);
    const config = sellAuthPlusConfig(env);
    if (!config.configured)
        return json({
            error: 'SellAuth checkout is not configured yet',
            code: 'SELLAUTH_NOT_CONFIGURED',
            checkout_mode: 'embedded_link',
            storefront_url: config.storefrontUrl,
            missing: {
                webhook_secret: !Boolean(config.webhookSecret),
                plans: config.plans.filter(plan => !plan.productId || !plan.variantId).map(plan => ({
                    months: plan.months,
                    product_id: !plan.productId,
                    variant_id: !plan.variantId
                }))
            }
        }, 503);
    const allowed = await checkRateLimit(env.DB, `plus-checkout:${user.id}`, 8, 10 * 60 * 1000);
    if (!allowed)
        return json({ error: 'Too many checkout attempts. Try again in a few minutes.' }, 429);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const months = Number(body.duration_months || 0);
    if (![1, 3, 12].includes(months))
        return json({ error: 'Choose 1, 3, or 12 months' }, 400);
    const intent = String(body.intent || 'self').toLowerCase();
    if (!['self', 'gift'].includes(intent))
        return json({ error: 'Choose whether this is for you or a gift' }, 400);
    const email = String(body.email || '').trim().toLowerCase();
    if (!isEmail(email))
        return json({ error: 'Enter a valid email address' }, 400);
    const plus = await getPlusStatus(env.DB, user.id);
    if (intent === 'self' && plus.active && plus.expires_at === null) {
        return json({ error: 'This account already has permanent Orbyte Plus. You can still buy a gift.' }, 409);
    }
    const plan = config.plans.find(item => item.months === months);
    if (!plan?.productId || !plan?.variantId) {
        return json({ error: 'This Plus duration is missing its SellAuth product or variant ID' }, 503);
    }
    await env.DB.prepare(`UPDATE plus_purchases SET status='replaced',updated_at=?
    WHERE (user_id=? OR lower(email)=?)
      AND product_id=? AND variant_id=? AND status='pending'`)
        .bind(Date.now(), user.id, email, String(plan.productId), String(plan.variantId)).run();
    const now = Date.now();
    const id = prefixedId('plusbuy');
    const sellAuthEmail = sellAuthReceiptEmail(env, id, email);
    const checkoutUrl = buildSellAuthCheckoutLink(config, plan, sellAuthEmail);
    const embedUrl = buildSellAuthProductEmbedUrl(config, plan, sellAuthEmail);
    await env.DB.prepare(`INSERT INTO plus_purchases(
    id,user_id,intent,duration_months,product_id,variant_id,email,sellauth_email,status,
    checkout_url,created_at,updated_at
  ) VALUES(?,?,?,?,?,?,?,?,'pending',?,?,?)`)
        .bind(id, user.id, intent, months, String(plan.productId), String(plan.variantId), email, sellAuthEmail, checkoutUrl, now, now).run();
    return json({
        purchase_id: id,
        checkout_url: checkoutUrl,
        embed_url: embedUrl,
        checkout_mode: 'product_embed',
        intent,
        duration_months: months,
        match_email: email,
        status: 'pending',
        note: 'SellAuth checkout is opened by Orbyte. Orbyte Plus activation/gift confirmation is sent through the configured Google Apps Script relay.'
    }, 201);
}

async function getSellAuthPlusPurchase(env, user, purchaseId) {
    await ensurePlusPurchaseSchema(env.DB);
    let row = await env.DB.prepare('SELECT * FROM plus_purchases WHERE id=? AND user_id=? LIMIT 1')
        .bind(String(purchaseId || ''), user.id).first();
    if (!row)
        return json({ error: 'Purchase not found' }, 404);
    if (['pending', 'paid', 'processing'].includes(row.status)) {
        row = await reconcileSellAuthPlusPurchase(env, row);
        row = await env.DB.prepare('SELECT * FROM plus_purchases WHERE id=? AND user_id=? LIMIT 1')
            .bind(row.id, user.id).first();
    }
    let plus = null, monthly = null;
    if (row.status === 'fulfilled' && row.intent === 'self') {
        plus = await getPlusStatus(env.DB, user.id);
        monthly = await syncPlusMonthlyRewards(env.DB, user.id, plus);
    }
    const result = publicPlusPurchase(row, plus, monthly);
    if (result?.gift_code) {
        const origin = primaryFrontendOrigin(env).replace(/\/$/, '');
        result.gift_url = `${origin}/gifts/${encodeURIComponent(result.gift_code)}`;
    }
    return json({ purchase: result }, 200, { 'Cache-Control': 'no-store' });
}

async function handleSellAuthPlusWebhook(request, env, providedSecret) {
    const config = sellAuthPlusConfig(env);
    if (!config.webhookSecret || !timingSafeEqual(String(providedSecret || ''), config.webhookSecret)) {
        return json({ error: 'Not found' }, 404);
    }
    await ensurePlusPurchaseSchema(env.DB);
    const payload = await readJson(request);
    if (!payload)
        return json({ error: 'Invalid JSON' }, 400);
    let verified = payload;
    let apiVerified = false;
    const invoiceId = sellAuthInvoiceId(payload);
    if (invoiceId && config.apiVerificationConfigured) {
        try {
            const fetched = await fetchSellAuthInvoice(env, invoiceId);
            if (sellAuthInvoicePaid(fetched)) {
                verified = fetched;
                apiVerified = true;
            }
        }
        catch (error) {
            console.warn('SellAuth invoice verification unavailable; using Dynamic Delivery signal', invoiceId, String(error?.message || error));
        }
    }
    let purchase = await findSellAuthPurchaseForPayload(env, verified);
    if (!purchase)
        purchase = await findSellAuthPurchaseForPayload(env, payload);
    if (!purchase) {
        console.warn('SellAuth Dynamic Delivery could not be matched', {
            invoice_id: invoiceId || null,
            email: sellAuthEmail(payload) || null,
            product: sellAuthProductIdentity(payload)
        });
        return json({
            ok: false,
            error: 'Orbyte could not match this paid item to a pending Plus checkout. Make sure the same email was used in Orbyte and SellAuth.',
            code: 'PLUS_PURCHASE_NOT_MATCHED'
        }, 409);
    }
    const identity = sellAuthProductIdentity(payload);
    if (identity.productId && String(identity.productId) !== String(purchase.product_id)) {
        return json({ error: 'Product mismatch' }, 409);
    }
    if (identity.variantId && String(identity.variantId) !== String(purchase.variant_id)) {
        return json({ error: 'Variant mismatch' }, 409);
    }
    const incomingInvoiceId = sellAuthInvoiceId(verified) || sellAuthInvoiceId(payload);
    const incomingReference = String(sellAuthDeepValue(payload, ['reference', 'reference_id', 'unique_id', 'uid', 'data.reference', 'data.reference_id', 'data.unique_id', 'data.uid']) || '').trim().slice(0, 180);
    await env.DB.prepare(`UPDATE plus_purchases SET
    sellauth_invoice_id=COALESCE(sellauth_invoice_id,?),
    sellauth_reference=CASE WHEN COALESCE(sellauth_reference,'')='' THEN ? ELSE sellauth_reference END,
    status=CASE WHEN status='pending' THEN 'paid' ELSE status END,
    paid_at=COALESCE(paid_at,?),
    updated_at=?
    WHERE id=?`)
        .bind(incomingInvoiceId || null, incomingReference || '', Date.now(), Date.now(), purchase.id).run();
    purchase = await env.DB.prepare('SELECT * FROM plus_purchases WHERE id=? LIMIT 1').bind(purchase.id).first();
    const fulfilled = await fulfillSellAuthPlusPurchase(env, purchase, verified);
    return json({
        ok: true,
        message: fulfilled?.intent === 'gift'
            ? 'Your Orbyte Plus gift has been generated. Return to Orbyte to copy the code.'
            : 'Orbyte Plus has been activated. Return to Orbyte to see your benefits.',
        purchase_id: fulfilled?.id || purchase.id,
        status: fulfilled?.status || 'fulfilled',
        api_verified: apiVerified
    });
}

async function getPlusStatus(db, userId) {
    try {
        const row = await db.prepare(`SELECT tier,expires_at,source,started_at,updated_at FROM user_entitlements WHERE user_id=? LIMIT 1`).bind(userId).first();
        const active = Boolean(row?.tier === 'plus' && (!row.expires_at || Number(row.expires_at) > Date.now()));
        const source = active ? String(row?.source || 'manual') : 'none';
        const monthlyEligible = active && !isDiamondWeekSource(source);
        return {
            active, tier: active ? 'plus' : 'none', expires_at: active ? (row.expires_at || null) : null, source: active ? source : null,
            started_at: active ? (Number(row.started_at || row.updated_at || 0) || null) : null,
            attachment_limit: active ? 50 * 1024 * 1024 : 25 * 1024 * 1024,
            emoji_limit: 50, monthly_diamonds: monthlyEligible ? PLUS_MONTHLY_DIAMONDS : 0, advanced_themes: active, subscriber_badge: active,
            screen_share_unlimited: active, custom_call_background: active, custom_profile_background: active, referral_invite_reward: active ? DIAMOND_REFERRAL_PLUS_SIGNUP_REWARD : DIAMOND_REFERRAL_SIGNUP_REWARD
        };
    }
    catch (error) {
        if (String(error?.message || error).toLowerCase().includes('no such table'))
            return { active: false, tier: 'none', expires_at: null, source: null, started_at: null, attachment_limit: 25 * 1024 * 1024, emoji_limit: 50, monthly_diamonds: 0, advanced_themes: false, subscriber_badge: false, screen_share_unlimited: false, custom_call_background: false, custom_profile_background: false, referral_invite_reward: DIAMOND_REFERRAL_SIGNUP_REWARD };
        throw error;
    }
}

async function attachmentLimitForUser(db, userId) {
    const plus = await getPlusStatus(db, userId);
    return Number(plus.attachment_limit || 25 * 1024 * 1024);
}

async function getPlusOverview(env, user) {
    let plus = await getPlusStatus(env.DB, user.id);
    const monthly = await syncPlusMonthlyRewards(env.DB, user.id, plus);
    plus = await getPlusStatus(env.DB, user.id);
    const wallet = await env.DB.prepare('SELECT diamonds FROM users WHERE id=? LIMIT 1').bind(user.id).first();
    return json({
        plus,
        diamond_balance: Math.max(0, Number(wallet?.diamonds || 0)),
        diamond_week: { available: !plus.active, gift_available: true, cost: PLUS_DIAMOND_WEEK_COST, days: PLUS_DIAMOND_WEEK_DAYS, label: '7 days of Plus', monthly_diamonds_included: false },
        checkout_url: PLUS_CHECKOUT_URL,
        native_checkout: true,
        checkout_mode: 'hosted_link',
        headline: 'Enjoy Orbyte? Support Orbyte and get extra benefits!',
        perks: [
            '50 Diamonds every subscription month',
            '50 MB message file uploads',
            'Advanced custom app themes',
            'Orbyte Plus subscriber badge',
            'Screen sharing without an Orbyte-imposed FPS or resolution cap',
            'Custom call background image',
            'Custom full-profile background image',
            '12 Diamonds per successful friend invite instead of 10'
        ],
        comparison: [
            { perk: 'Screen sharing', free: '45 fps / 1080p', plus: 'No Orbyte-imposed FPS/resolution limit' },
            { perk: 'Call background', free: 'Default', plus: 'Custom image or default' },
            { perk: 'Diamonds for inviting friends', free: '10 / invite', plus: '12 / invite' }
        ],
        monthly_reward: { amount: Number(plus.monthly_diamonds || 0), next_at: monthly.next_reward_at || null, awarded_now: Number(monthly.awarded || 0), balance: monthly.balance ?? Math.max(0, Number(wallet?.diamonds || 0)) }
    });
}

async function adminUpdateUserPlus(request, env, admin, targetUserId) {
    if (targetUserId === SYSTEM_USER_ID)
        return json({ error: 'The Orbyte system account cannot be modified' }, 403);
    const hierarchy = await guardAccountManagementTarget(env, admin, targetUserId, 'modify');
    if (hierarchy.error)
        return hierarchy.error;
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const active = Boolean(body.active), requestedDays = Number(body.days || 0), days = requestedDays > 0 ? Math.max(1, Math.min(3650, Math.round(requestedDays))) : 0;
    const target = await env.DB.prepare('SELECT id FROM users WHERE id=?').bind(targetUserId).first();
    if (!target)
        return json({ error: 'User not found' }, 404);
    const current = await getPlusStatus(env.DB, targetUserId);
    const now = Date.now(), expiresAt = active && days > 0 ? now + days * 86400000 : null;
    if (active && !current.active)
        await env.DB.prepare('DELETE FROM plus_monthly_rewards WHERE user_id=?').bind(targetUserId).run();
    if (!active)
        await env.DB.prepare('DELETE FROM plus_monthly_rewards WHERE user_id=?').bind(targetUserId).run();
    await env.DB.prepare(`INSERT INTO user_entitlements(user_id,tier,expires_at,source,started_at,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET tier=excluded.tier,expires_at=excluded.expires_at,source=excluded.source,started_at=CASE WHEN excluded.tier='plus' THEN CASE WHEN user_entitlements.tier='plus' THEN COALESCE(user_entitlements.started_at,excluded.started_at) ELSE excluded.started_at END ELSE NULL END,updated_at=excluded.updated_at`).bind(targetUserId, active ? 'plus' : 'none', expiresAt, 'admin', active ? now : null, now).run();
    await env.DB.prepare('INSERT INTO admin_actions(id,admin_id,action,target_user_id,notes,created_at) VALUES(?,?,?,?,?,?)').bind(prefixedId('act'), admin.id, active ? 'plus_grant' : 'plus_revoke', targetUserId, active ? (days > 0 ? `${days} days` : 'permanent manual grant') : 'revoked', now).run();
    const plus = await getPlusStatus(env.DB, targetUserId);
    if (plus.active)
        await syncPlusMonthlyRewards(env.DB, targetUserId, plus);
    return json({ ok: true, plus: await getPlusStatus(env.DB, targetUserId) });
}

async function usersBlocked(db, a, b) {
    if (!a || !b)
        return false;
    try {
        return Boolean(await db.prepare('SELECT 1 FROM user_blocks WHERE (blocker_id=? AND blocked_id=?) OR (blocker_id=? AND blocked_id=?) LIMIT 1').bind(a, b, b, a).first());
    }
    catch (error) {
        if (String(error?.message || error).toLowerCase().includes('no such table'))
            return false;
        throw error;
    }
}

async function getBlockedUsers(db, userId) {
    try {
        const rows = await db.prepare(`SELECT ub.blocked_id AS user_id,ub.created_at,u.username,u.discriminator,u.display_name,u.avatar_url,u.equipped_decoration FROM user_blocks ub JOIN users u ON u.id=ub.blocked_id WHERE ub.blocker_id=? ORDER BY ub.created_at DESC`).bind(userId).all();
        return rows.results || [];
    }
    catch (error) {
        if (String(error?.message || error).toLowerCase().includes('no such table'))
            return [];
        throw error;
    }
}

async function listBlockedUsers(env, user) { return json({ blocked_users: await getBlockedUsers(env.DB, user.id) }); }

async function blockUser(env, user, targetId) {
    targetId = String(targetId || '');
    if (!targetId || targetId === user.id)
        return json({ error: 'Invalid user' }, 400);
    if (targetId === SYSTEM_USER_ID)
        return json({ error: 'The Orbyte system account cannot be blocked' }, 400);
    const target = await env.DB.prepare('SELECT id FROM users WHERE id=?').bind(targetId).first();
    if (!target)
        return json({ error: 'User not found' }, 404);
    const now = Date.now();
    await env.DB.batch([
        env.DB.prepare('INSERT OR IGNORE INTO user_blocks(blocker_id,blocked_id,created_at) VALUES(?,?,?)').bind(user.id, targetId, now),
        env.DB.prepare('DELETE FROM friendships WHERE (requester_id=? AND addressee_id=?) OR (requester_id=? AND addressee_id=?)').bind(user.id, targetId, targetId, user.id),
        env.DB.prepare(`UPDATE call_sessions SET status='ended',ended_at=? WHERE status IN ('ringing','active') AND ((caller_id=? AND callee_id=?) OR (caller_id=? AND callee_id=?))`).bind(now, user.id, targetId, targetId, user.id),
    ]);
    return json({ ok: true, blocked_user_id: targetId });
}

async function unblockUser(env, user, targetId) { await env.DB.prepare('DELETE FROM user_blocks WHERE blocker_id=? AND blocked_id=?').bind(user.id, String(targetId || '')).run(); return json({ ok: true }); }

function normalizeUsername(value) {
    const username = String(value || '').trim();
    if (!/^[A-Za-z0-9_.-]{2,24}$/.test(username))
        return null;
    return username;
}

function normalizeDiscriminator(value) {
    if (value === undefined || value === null || value === '')
        return null;
    const discriminator = String(value).trim();
    return /^\d{4}$/.test(discriminator) ? discriminator : null;
}

function cleanText(value, max, preserveNewlines = false) {
    let text = String(value ?? '').replace(/\0/g, '');
    if (!preserveNewlines)
        text = text.replace(/\s+/g, ' ').trim();
    return text.slice(0, max);
}

function validHex(value) {
    return /^#[0-9a-fA-F]{6}$/.test(String(value || ''));
}

function isEmail(value) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value) && value.length <= 254;
}

async function readJson(request) {
    try {
        const contentLength = Number(request.headers.get('Content-Length') || 0);
        if (Number.isFinite(contentLength) && contentLength > 1024 * 1024)
            return null;
        const text = await request.text();
        if (!text || text.length > 1024 * 1024)
            return null;
        const value = JSON.parse(text);
        return value && typeof value === 'object' && !Array.isArray(value) ? value : null;
    }
    catch {
        return null;
    }
}

function getAuthToken(request) {
    const authorization = request.headers.get('Authorization') || '';
    const match = authorization.match(/^Bearer\s+(.+)$/i);
    if (match)
        return match[1].trim();
    return getCookie(request, 'orbyte_session');
}

function allowedOrigin(request, env) {
    const origin = request.headers.get('Origin');
    if (!origin)
        return null;
    const nativeOrigins = new Set([
        'capacitor://localhost',
        'https://localhost',
        'http://localhost',
        'orbyte://localhost',
    ]);
    if (nativeOrigins.has(origin))
        return origin;
    if (origin === 'null') {
        return /^(1|true|yes)$/i.test(String(env.ALLOW_NULL_ORIGIN || '')) ? origin : null;
    }
    const allowed = new Set([
        'https://orbytechat.pages.dev',
        'https://support.orbytechat.pages.dev',
        'https://suppport.orbytechat.pages.dev',
    ]);
    for (const raw of [env.FRONTEND_ORIGIN, env.SUPPORT_ORIGIN]) {
        for (const value of String(raw || '').split(',')) {
            const clean = value.trim().replace(/\/$/, '');
            if (clean && clean !== '*')
                allowed.add(clean);
        }
    }
    const normalized = origin.replace(/\/$/, '');
    return allowed.has(normalized) ? origin : null;
}

const CAPTCHA_EMOJIS = Object.freeze([
    { emoji: '🐱', description: 'the cat' },
    { emoji: '🐶', description: 'the dog' },
    { emoji: '🦊', description: 'the fox' },
    { emoji: '🐸', description: 'the frog' },
    { emoji: '🐟', description: 'the fish' },
    { emoji: '🍎', description: 'the red apple' },
    { emoji: '🍕', description: 'the pizza' },
    { emoji: '🎂', description: 'the birthday cake' },
    { emoji: '🚗', description: 'the car' },
    { emoji: '🚀', description: 'the rocket' },
    { emoji: '🔑', description: 'the key' },
    { emoji: '🌳', description: 'the tree' },
    { emoji: '☀️', description: 'the sun' },
    { emoji: '🌙', description: 'the moon' },
    { emoji: '⭐', description: 'the star' },
    { emoji: '🎈', description: 'the balloon' },
]);

function captchaHtmlEscape(value) {
    return String(value ?? '').replace(/[&<>"']/g, char => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
    })[char]);
}

function secureRandomIndex(length) {
    if (!Number.isFinite(length) || length <= 1)
        return 0;
    const max = Math.floor(0x100000000 / length) * length;
    const values = new Uint32Array(1);
    do {
        crypto.getRandomValues(values);
    } while (values[0] >= max);
    return values[0] % length;
}

function shuffledCaptchaChoices() {
    const values = [...CAPTCHA_EMOJIS];
    for (let i = values.length - 1; i > 0; i -= 1) {
        const j = secureRandomIndex(i + 1);
        [values[i], values[j]] = [values[j], values[i]];
    }
    return values.slice(0, 3);
}

async function ensureCaptchaSchema(db) {
    if (!db)
        throw new Error('Captcha database is unavailable');
    if (!captchaSchemaPromise) {
        captchaSchemaPromise = (async () => {
            await db.prepare(`CREATE TABLE IF NOT EXISTS captcha_challenges (
        id TEXT PRIMARY KEY,
        action TEXT NOT NULL,
        answer_hash TEXT NOT NULL,
        token_hash TEXT,
        attempts INTEGER NOT NULL DEFAULT 0,
        expires_at INTEGER NOT NULL,
        verified_at INTEGER,
        consumed_at INTEGER,
        created_at INTEGER NOT NULL
      )`).run();
            await db.prepare('CREATE INDEX IF NOT EXISTS idx_captcha_challenges_expires ON captcha_challenges(expires_at)').run();
            await db.prepare('CREATE INDEX IF NOT EXISTS idx_captcha_challenges_token ON captcha_challenges(token_hash)').run();
            return true;
        })().catch(error => { captchaSchemaPromise = null; throw error; });
    }
    return captchaSchemaPromise;
}

async function serveCaptchaPage(request, env, url) {
    const theme = url.searchParams.get('theme') === 'light' ? 'light' : 'dark';
    const action = String(url.searchParams.get('action') || 'protected_action')
        .toLowerCase().replace(/[^a-z0-9_-]/g, '').slice(0, 32) || 'protected_action';
    if (!env.DB) {
        return new Response('<!doctype html><meta name="viewport" content="width=device-width"><p>Captcha database is unavailable.</p>', {
            status: 503,
            headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' },
        });
    }
    try {
        await ensureCaptchaSchema(env.DB);
    }
    catch (error) {
        console.error('Could not prepare captcha schema', error);
        return new Response('<!doctype html><meta name="viewport" content="width=device-width"><p>Human verification is temporarily unavailable.</p>', {
            status: 503,
            headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' },
        });
    }
    const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
    try {
        const allowed = await checkRateLimit(env.DB, `captcha-create:${ip}`, 60, 10 * 60 * 1000);
        if (!allowed) {
            return new Response('<!doctype html><meta name="viewport" content="width=device-width"><p>Too many verification requests. Try again shortly.</p>', {
                status: 429,
                headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', 'Referrer-Policy': 'no-referrer' },
            });
        }
    }
    catch (error) {
        console.warn('Captcha challenge rate limiter unavailable', error);
    }
    const choices = shuffledCaptchaChoices();
    const answer = choices[secureRandomIndex(choices.length)];
    const challengeId = prefixedId('cap');
    const now = Date.now();
    const expiresAt = now + 5 * 60 * 1000;
    const answerHash = await sha256(`${challengeId}:${answer.emoji}`);
    try {
        await env.DB.batch([
            env.DB.prepare('DELETE FROM captcha_challenges WHERE expires_at < ? OR (consumed_at IS NOT NULL AND consumed_at < ?)').bind(now - 60000, now - 24 * 60 * 60 * 1000),
            env.DB.prepare(`INSERT INTO captcha_challenges (id,action,answer_hash,attempts,expires_at,created_at) VALUES (?,?,?,0,?,?)`).bind(challengeId, action, answerHash, expiresAt, now),
        ]);
    }
    catch (error) {
        console.error('Could not create emoji captcha', error);
        return new Response('<!doctype html><meta name="viewport" content="width=device-width"><p>Captcha setup is incomplete. Run the v2.9.0 migration.</p>', {
            status: 503,
            headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' },
        });
    }
    const foreground = theme === 'light' ? '#1e1f22' : '#f2f3f5';
    const background = theme === 'light' ? '#ffffff' : '#1e1f22';
    const border = theme === 'light' ? '#d6d9df' : '#3f4147';
    const muted = theme === 'light' ? '#5c5f66' : '#b5bac1';
    const optionsHtml = choices.map(choice => `<button class="choice" type="button" data-choice="${captchaHtmlEscape(choice.emoji)}" aria-label="${captchaHtmlEscape(choice.description)}">${captchaHtmlEscape(choice.emoji)}</button>`).join('');
    const verifyUrl = new URL('/api/captcha/verify', request.url).href;
    const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><meta name="color-scheme" content="${theme}"><title>Human verification</title><style>*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:transparent;color:${foreground};font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{min-height:230px;display:grid;place-items:center;padding:12px}.card{width:min(100%,360px);padding:16px;border:1px solid ${border};border-radius:16px;background:${background};box-shadow:0 12px 32px #0003}.title{font-size:16px;font-weight:850;margin-bottom:4px}.sub{font-size:12px;line-height:1.45;color:${muted}}.prompt{margin:14px 0 12px;font-size:14px}.choices{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.choice{min-width:0;height:70px;border:1px solid ${border};border-radius:14px;background:${theme === 'light' ? '#f2f3f5' : '#2b2d31'};font-size:36px;cursor:pointer;transition:transform .12s,border-color .12s,background .12s}.choice:active{transform:scale(.95)}.choice:hover,.choice:focus-visible{border-color:#5865f2;outline:none;background:${theme === 'light' ? '#e9eaff' : '#343751'}}.choice:disabled{opacity:.55;cursor:wait}.status{min-height:18px;margin-top:11px;color:${muted};font-size:12px;text-align:center}.status.bad{color:#ff767b}.status.good{color:#57f287}</style></head><body><div class="wrap"><main class="card"><div class="title">Confirm you are human</div><div class="sub">Choose the emoji that matches the description.</div><div class="prompt">Select <strong>${captchaHtmlEscape(answer.description)}</strong></div><div class="choices">${optionsHtml}</div><div id="status" class="status"></div></main></div><script>const action=${JSON.stringify(action)},challengeId=${JSON.stringify(challengeId)},verifyUrl=${JSON.stringify(verifyUrl)};const status=document.getElementById('status');function send(type,extra){parent.postMessage(Object.assign({type,action},extra||{}),'*')}async function choose(choice){document.querySelectorAll('.choice').forEach(button=>button.disabled=true);status.className='status';status.textContent='Checking…';try{const response=await fetch(verifyUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenge_id:challengeId,choice})});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'That was not the requested emoji.');status.className='status good';status.textContent='Verified!';send('orbyte-captcha-success',{token:data.token});}catch(error){status.className='status bad';status.textContent=error.message||'Try another challenge.';setTimeout(()=>location.reload(),850)}}document.querySelectorAll('.choice').forEach(button=>button.addEventListener('click',()=>choose(button.dataset.choice)))</script></body></html>`;
    return new Response(html, {
        headers: {
            'Content-Type': 'text/html; charset=utf-8',
            'Cache-Control': 'no-store',
            'X-Content-Type-Options': 'nosniff',
            'Referrer-Policy': 'no-referrer',
            'Content-Security-Policy': "default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; form-action 'none';",
        },
    });
}

async function verifyEmojiCaptcha(request, env) {
    await ensureCaptchaSchema(env.DB);
    const body = await readJson(request);
    const challengeId = String(body?.challenge_id || '').trim();
    const choice = String(body?.choice || '').trim();
    if (!challengeId || challengeId.length > 96 || !choice || choice.length > 16) {
        return json({ error: 'Invalid captcha response', code: 'CAPTCHA_INVALID' }, 400);
    }
    const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
    const now = Date.now();
    const row = await env.DB.prepare(`SELECT id,action,answer_hash,attempts,expires_at,verified_at,consumed_at FROM captcha_challenges WHERE id=? LIMIT 1`).bind(challengeId).first();
    if (!row || row.expires_at <= now || row.consumed_at || row.verified_at || Number(row.attempts || 0) >= 1) {
        return json({ error: 'This captcha expired. Try a new challenge.', code: 'CAPTCHA_EXPIRED' }, 400);
    }
    const correct = timingSafeEqual(await sha256(`${challengeId}:${choice}`), String(row.answer_hash || ''));
    if (!correct) {
        await env.DB.prepare('UPDATE captcha_challenges SET attempts=attempts+1,consumed_at=? WHERE id=? AND consumed_at IS NULL').bind(now, challengeId).run();
        return json({ error: 'That emoji does not match the description.', code: 'CAPTCHA_INCORRECT' }, 400);
    }
    const token = randomBase64Url(32);
    const tokenHash = await sha256(token);
    const result = await env.DB.prepare(`UPDATE captcha_challenges SET token_hash=?,verified_at=? WHERE id=? AND consumed_at IS NULL AND verified_at IS NULL AND expires_at>?`).bind(tokenHash, now, challengeId, now).run();
    if (!Number(result.meta?.changes || 0))
        return json({ error: 'This captcha expired. Try again.', code: 'CAPTCHA_EXPIRED' }, 400);
    return json({ ok: true, token, action: row.action });
}

async function requireCaptcha(request, env, token, expectedAction) {
    try {
        await ensureCaptchaSchema(env.DB);
    }
    catch (error) {
        console.error('Emoji captcha schema preparation failed', error);
        return json({ error: 'Human verification is temporarily unavailable.', code: 'CAPTCHA_NOT_CONFIGURED' }, 503);
    }
    const responseToken = String(token || '').trim();
    if (!responseToken || responseToken.length > 256) {
        return json({ error: 'Complete the emoji verification first.', code: 'CAPTCHA_REQUIRED' }, 400);
    }
    const now = Date.now();
    let result;
    try {
        result = await env.DB.prepare(`UPDATE captcha_challenges SET consumed_at=? WHERE token_hash=? AND action=? AND verified_at IS NOT NULL AND consumed_at IS NULL AND expires_at>?`).bind(now, await sha256(responseToken), String(expectedAction), now).run();
    }
    catch (error) {
        console.error('Emoji captcha validation failed', error);
        return json({ error: 'Captcha setup is incomplete. Run the v2.9.0 migration.', code: 'CAPTCHA_NOT_CONFIGURED' }, 503);
    }
    if (!Number(result.meta?.changes || 0)) {
        return json({ error: 'Human verification failed, expired, or was already used. Try again.', code: 'CAPTCHA_FAILED' }, 400);
    }
    return null;
}

function corsPreflight(request, env) {
    const pathname = new URL(request.url).pathname;
    const isPublicApi = pathname.startsWith('/api/public/');
    const origin = isPublicApi ? '*' : allowedOrigin(request, env);
    if (!origin)
        return new Response('Origin not allowed', { status: 403 });
    return new Response(null, {
        status: 204,
        headers: {
            'Access-Control-Allow-Origin': origin,
            'Access-Control-Allow-Methods': 'GET, POST, PATCH, DELETE, PUT, OPTIONS',
            'Access-Control-Allow-Headers': 'Authorization, Content-Type, X-Orbyte-Startup-Attempt, X-Orbyte-Transfer-Key',
            'Access-Control-Max-Age': '86400',
            'Vary': 'Origin',
        },
    });
}

function withCors(response, request, env) {
    const pathname = new URL(request.url).pathname;
    const isPublicApi = pathname.startsWith('/api/public/');
    const origin = isPublicApi ? '*' : allowedOrigin(request, env);
    const headers = new Headers(response.headers);
    headers.set('X-Content-Type-Options', 'nosniff');
    headers.set('Referrer-Policy', 'no-referrer');
    if (pathname === '/captcha') {
        headers.delete('X-Frame-Options');
    }
    else {
        headers.set('X-Frame-Options', 'DENY');
    }
    headers.set('Permissions-Policy', 'geolocation=(), payment=(), usb=(), serial=()');
    if (!origin) {
        return new Response(response.body, {
            status: response.status,
            statusText: response.statusText,
            headers,
        });
    }
    headers.set('Access-Control-Allow-Origin', origin);
    if (isPublicApi)
        headers.set('Cross-Origin-Resource-Policy', 'cross-origin');
    headers.set('Access-Control-Allow-Methods', 'GET, POST, PATCH, DELETE, PUT, OPTIONS');
    headers.set('Access-Control-Allow-Headers', 'Authorization, Content-Type, X-Orbyte-Startup-Attempt, X-Orbyte-Transfer-Key');
    headers.append('Vary', 'Origin');
    return new Response(response.body, {
        status: response.status,
        statusText: response.statusText,
        headers,
    });
}

function json(data, status = 200, extraHeaders = {}) {
    return new Response(JSON.stringify(data), {
        status,
        headers: {
            'Content-Type': 'application/json; charset=utf-8',
            'Cache-Control': 'no-store',
            'X-Content-Type-Options': 'nosniff',
            ...extraHeaders,
        },
    });
}

function getCookie(request, name) {
    const cookies = request.headers.get('Cookie') || '';
    for (const part of cookies.split(';')) {
        const [key, ...rest] = part.trim().split('=');
        if (key === name)
            return rest.join('=');
    }
    return null;
}

function prefixedId(prefix) {
    return `${prefix}_${crypto.randomUUID().replace(/-/g, '')}`;
}

function randomBase64(length) {
    const bytes = crypto.getRandomValues(new Uint8Array(length));
    return bytesToBase64(bytes);
}

function randomBase64Url(length) {
    return randomBase64(length).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

function bytesToBase64(bytes) {
    let binary = '';
    for (const byte of bytes)
        binary += String.fromCharCode(byte);
    return btoa(binary);
}

function base64ToBytes(base64) {
    const binary = atob(base64);
    return Uint8Array.from(binary, char => char.charCodeAt(0));
}

async function adminPasswordToolHash(request, env, owner) {
    if (!isDatabaseOwner(owner))
        return json({ error: 'Only the database owner can use password tools' }, 403);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const plaintext = String(body.plaintext ?? body.password ?? '');
    if (!plaintext.length)
        return json({ error: 'Enter plaintext to hash' }, 400);
    if (plaintext.length > 512)
        return json({ error: 'Plaintext is too long' }, 400);
    const salt = randomBase64(16);
    const hash = await hashPassword(plaintext, salt);
    return json({ ok: true, algorithm: 'PBKDF2-SHA-256', iterations: 100000, salt, hash }, 200, { 'Cache-Control': 'no-store' });
}

async function adminPasswordToolVerify(request, env, owner) {
    if (!isDatabaseOwner(owner))
        return json({ error: 'Only the database owner can use password tools' }, 403);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const plaintext = String(body.plaintext ?? body.password ?? '');
    const salt = String(body.salt || '').trim();
    const hash = String(body.hash || '').trim();
    if (!plaintext || !salt || !hash)
        return json({ error: 'Plaintext, salt, and hash are required' }, 400);
    if (plaintext.length > 512 || salt.length > 256 || hash.length > 256)
        return json({ error: 'Input is too long' }, 400);
    try {
        const match = await verifyPassword(plaintext, salt, hash);
        return json({ ok: true, match }, 200, { 'Cache-Control': 'no-store' });
    }
    catch {
        return json({ error: 'Invalid salt or hash format' }, 400, { 'Cache-Control': 'no-store' });
    }
}

async function hashPassword(password, saltBase64) {
    const key = await crypto.subtle.importKey('raw', encoder.encode(password), 'PBKDF2', false, ['deriveBits']);
    const bits = await crypto.subtle.deriveBits({
        name: 'PBKDF2',
        hash: 'SHA-256',
        salt: base64ToBytes(saltBase64),
        iterations: 100000,
    }, key, 256);
    return bytesToBase64(new Uint8Array(bits));
}

async function verifyPassword(password, salt, expectedHash) {
    const actual = await hashPassword(password, salt);
    return timingSafeEqual(actual, expectedHash);
}

function timingSafeEqual(a, b) {
    if (a.length !== b.length)
        return false;
    let result = 0;
    for (let i = 0; i < a.length; i++)
        result |= a.charCodeAt(i) ^ b.charCodeAt(i);
    return result === 0;
}

async function sha256(value) {
    const digest = await crypto.subtle.digest('SHA-256', encoder.encode(value));
    return Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
}

function accountSafetyFromUser(user) {
    const limitationMask = Number(user?.limitation_mask || 0);
    const limitationsUntil = Number(user?.limitation_next_expiry || 0) || null;
    return {
        standing_level: Number(user?.standing_level || 0),
        standing_next_expiry: Number(user?.standing_next_expiry || 0) || null,
        limitation_mask: limitationMask,
        limitations_until: limitationsUntil,
        limitation_next_expiry: limitationsUntil,
        active_limitations: accountRestrictionRows(limitationMask, limitationsUntil),
    };
}

function canonicalSafetyEnvelope(user, violations, now = Date.now()) {
    const rows = Array.isArray(violations) ? violations : [];
    const active = rows.filter(row => {
        const status = String(row?.status || 'active').toLowerCase();
        const expiresAt = Number(row?.expires_at || 0);
        return !['expired', 'overturned', 'reversed'].includes(status)
            && (!expiresAt || expiresAt > now);
    });
    const expired = rows.filter(row => !active.includes(row));
    let standingLevel = 0;
    let standingNextExpiry = null;
    for (const row of active) {
        const action = String(row?.action || '').toLowerCase();
        const affectsStanding = row?.affects_standing !== false && action !== 'warning';
        if (!affectsStanding)
            continue;
        if (['ban', 'permanent_suspension', 'suspension'].includes(action)) {
            standingLevel = 4;
        }
        else {
            const severity = String(row?.severity || 'low').toLowerCase();
            if (severity === 'critical')
                standingLevel = Math.max(standingLevel, 3);
            else if (severity === 'high')
                standingLevel = Math.max(standingLevel, 2);
            else
                standingLevel = Math.max(standingLevel, 1);
        }
        const expiresAt = Number(row?.expires_at || 0);
        if (expiresAt > now && (!standingNextExpiry || expiresAt < standingNextExpiry)) {
            standingNextExpiry = expiresAt;
        }
    }
    const accountStatus = String(user?.account_status || '').toLowerCase();
    if (accountStatus === 'banned')
        standingLevel = 4;
    else if (accountStatus === 'suspended')
        standingLevel = Math.max(standingLevel, 3);
    const baseSafety = accountSafetyFromUser(user);
    const revision = rows.reduce((max, row) => Math.max(max, Number(row?.created_at || 0), Number(row?.reversed_at || 0), Number(row?.expires_at || 0)), 0) || now;
    return {
        account_safety: {
            ...baseSafety,
            standing_level: standingLevel,
            standing_next_expiry: standingNextExpiry,
        },
        active_violation_count: active.length,
        expired_violation_count: expired.length,
        safety_revision: revision,
        server_time: now,
        partial: false,
    };
}

function accountHasLimit(user, bit, now = Date.now()) {
    const mask = Number(user?.limitation_mask || 0);
    const until = Number(user?.limitation_next_expiry || 0);
    return Boolean(mask & bit) && (!until || until > now);
}

function accountLimitResponse(user, code, error) {
    return json({
        error,
        code,
        until: Number(user?.limitation_next_expiry || 0) || null,
        account_safety: accountSafetyFromUser(user),
    }, 403);
}

function parseAccountRestrictionMask(values) {
    const list = Array.isArray(values)
        ? values
        : typeof values === 'string'
            ? values.split(',')
            : [];
    const set = new Set(list.map(value => String(value || '').trim().toLowerCase()));
    return (set.has('send_messages') ? 1 : 0)
        | (set.has('server_access') || set.has('servers') ? 2 : 0)
        | (set.has('file_uploads') || set.has('uploads') ? 4 : 0);
}

function accountRestrictionRows(mask, until) {
    const rows = [];
    if (Number(mask || 0) & 1) {
        rows.push({ type: 'send_messages', title: 'You cannot send messages', until: until || null });
    }
    if (Number(mask || 0) & 2) {
        rows.push({ type: 'server_access', title: 'You cannot join or create servers', until: until || null });
    }
    if (Number(mask || 0) & 4) {
        rows.push({ type: 'file_uploads', title: 'You cannot upload files', detail: 'You can still send text messages.', until: until || null });
    }
    return rows;
}

function accountRestrictionSummary(mask, until) {
    const ending = until ? ` until ${new Date(until).toISOString()}` : '';
    return accountRestrictionRows(mask, until).map(row => {
        const extra = row.detail ? ` ${row.detail}` : '';
        return `• ${row.title}${ending}.${extra}`;
    }).join('\n');
}

async function refreshExpiredAccountState(env, user) {
    const now = Date.now();
    const limitationDue = Number(user?.limitation_next_expiry || 0) > 0
        && Number(user.limitation_next_expiry) <= now;
    const standingDue = Number(user?.standing_next_expiry || 0) > 0
        && Number(user.standing_next_expiry) <= now;
    if (!limitationDue && !standingDue)
        return user;
    await expireUserSafetyState(env.DB, user.id, now);
    const refreshed = await env.DB.prepare(`
    SELECT limitation_mask, limitation_next_expiry, standing_level, standing_next_expiry
    FROM users WHERE id = ? LIMIT 1
  `).bind(user.id).first();
    if (refreshed)
        Object.assign(user, refreshed);
    return user;
}

async function expireUserSafetyState(db, userId, now = Date.now()) {
    await db.batch([
        db.prepare(`
      UPDATE violations
      SET status = 'expired'
      WHERE user_id = ?
        AND status IN ('active', 'appealed')
        AND expires_at IS NOT NULL
        AND expires_at <= ?
    `).bind(userId, now),
        db.prepare(`
      UPDATE account_limitations
      SET status = 'expired', updated_at = ?
      WHERE user_id = ? AND status = 'active' AND expires_at <= ?
    `).bind(now, userId, now),
    ]);
    await recomputeUserSafetyCache(db, userId, now);
}

async function recomputeUserSafetyCache(db, userId, now = Date.now()) {
    await db.prepare(`
    UPDATE users
    SET
      limitation_mask = COALESCE((
        SELECT COALESCE(MAX(limitation_mask & 1), 0)
             + COALESCE(MAX(limitation_mask & 2), 0)
             + COALESCE(MAX(limitation_mask & 4), 0)
        FROM account_limitations
        WHERE user_id = users.id AND status = 'active' AND expires_at > ?
      ), 0),
      limitation_next_expiry = (
        SELECT MIN(expires_at)
        FROM account_limitations
        WHERE user_id = users.id AND status = 'active' AND expires_at > ?
      ),
      standing_level = COALESCE((
        SELECT MAX(CASE
          WHEN action = 'ban' THEN 4
          WHEN severity = 'critical' THEN 3
          WHEN severity = 'high' THEN 2
          WHEN severity IN ('medium', 'low') THEN 1
          ELSE 0 END)
        FROM violations
        WHERE user_id = users.id
          AND status IN ('active', 'appealed')
          AND COALESCE(action, '') <> 'warning'
          AND (expires_at IS NULL OR expires_at > ?)
      ), 0),
      standing_next_expiry = (
        SELECT MIN(expires_at)
        FROM violations
        WHERE user_id = users.id
          AND status IN ('active', 'appealed')
          AND COALESCE(action, '') <> 'warning'
          AND expires_at IS NOT NULL
          AND expires_at > ?
      )
    WHERE id = ?
  `).bind(now, now, now, now, userId).run();
}

function decorateSafetyViolation(violation, appeal, now = Date.now()) {
    const rawStatus = String(violation.status || 'active').toLowerCase();
    const expiredByTime = Number(violation.expires_at || 0) > 0
        && Number(violation.expires_at) <= now;
    const reversed = rawStatus === 'overturned' || rawStatus === 'reversed';
    const expired = reversed || rawStatus === 'expired' || expiredByTime;
    const restrictionUntil = Number(violation.restriction_until || 0) || null;
    const baseAction = String(violation.action || 'warning').toLowerCase();
    const displayAction = ['ban', 'suspension'].includes(baseAction)
        ? baseAction
        : Number(violation.restriction_mask || 0) ? 'account_limitation' : baseAction;
    return {
        ...violation,
        action: displayAction,
        status: reversed ? 'overturned' : expired ? 'expired' : violation.status,
        display_status: reversed ? 'reversed' : expired ? 'expired' : rawStatus,
        bucket: expired ? 'expired' : 'active',
        affects_standing: !expired && String(violation.action || '') !== 'warning',
        limitations: accountRestrictionRows(Number(violation.restriction_mask || 0), restrictionUntil),
        appeal: appeal || null,
    };
}

async function enrichLegacySafetyEvidence(env, violations, userId) {
    const rows = (violations || []).filter(item => item?.report_id).slice(0, 25);
    if (!rows.length)
        return violations;
    for (const item of rows) {
        try {
            const enriched = await buildViolationEvidenceSnapshot(env, item.report_id, userId, '');
            if (enriched)
                item.evidence_text = enriched;
        }
        catch (error) {
            console.warn('Could not enrich legacy safety evidence', item.id, error);
        }
    }
    return violations;
}

async function getSafetyDataV3(env, user, includeReports = true) {
    await refreshExpiredAccountState(env, user);
    const requests = [
        env.DB.prepare(`
      SELECT id, report_id, violation_type, severity, reason, action, status,
             expires_at, restriction_mask, restriction_until, suspension_until, reversed_at,
             evidence_text, moderator_note, content_removed, removed_content_type,
             removed_content_id, content_removed_at, created_at
      FROM violations
      WHERE user_id = ?
      ORDER BY created_at DESC
      LIMIT 100
    `).bind(user.id).all(),
        env.DB.prepare(`
      SELECT a.id, a.violation_id, a.reason, a.status, a.resolution,
             a.created_at, a.updated_at,
             v.violation_type, v.severity,
             CASE WHEN v.action IN ('ban','suspension') THEN v.action
                  WHEN COALESCE(v.restriction_mask, 0) > 0 THEN 'account_limitation'
                  ELSE v.action END AS action
      FROM violation_appeals a
      JOIN violations v ON v.id = a.violation_id
      WHERE a.user_id = ?
      ORDER BY a.created_at DESC
      LIMIT 100
    `).bind(user.id).all(),
    ];
    if (includeReports) {
        requests.push(env.DB.prepare(`
      SELECT id, target_type, target_id, reason, details, status, resolution,
             created_at, updated_at
      FROM reports
      WHERE reporter_id = ?
      ORDER BY created_at DESC
      LIMIT 100
    `).bind(user.id).all());
    }
    const [violations, appeals, reports] = await Promise.all(requests);
    const appealRows = appeals.results || [];
    const appealByViolation = new Map(appealRows.map(appeal => [appeal.violation_id, appeal]));
    const now = Date.now();
    const decoratedViolations = (violations.results || []).map(violation => decorateSafetyViolation(violation, appealByViolation.get(violation.id), now));
    await enrichLegacySafetyEvidence(env, decoratedViolations, user.id);
    return {
        reports: reports?.results || [],
        violations: decoratedViolations,
        appeals: appealRows,
        ...canonicalSafetyEnvelope(user, decoratedViolations, now),
    };
}

async function applyBatchedReadReceipts(db, userId, reads) {
    const now = Date.now();
    const channels = [...new Set((reads?.channels || []).map(String).filter(Boolean))].slice(0, 20);
    const dms = [...new Set((reads?.dms || []).map(String).filter(Boolean))].slice(0, 20);
    const servers = [...new Set((reads?.servers || []).map(String).filter(Boolean))].slice(0, 10);
    const statements = [];
    for (const channelId of channels) {
        statements.push(db.prepare(`
      INSERT INTO channel_read_states (channel_id, user_id, last_read_at)
      SELECT c.id, ?, ?
      FROM channels c
      JOIN server_members sm ON sm.server_id = c.server_id AND sm.user_id = ?
      WHERE c.id = ?
      ON CONFLICT(channel_id, user_id) DO UPDATE SET last_read_at = excluded.last_read_at
    `).bind(userId, now, userId, channelId));
        statements.push(db.prepare(`
      UPDATE notifications SET read_at = ?
      WHERE user_id = ? AND channel_id = ? AND read_at IS NULL
    `).bind(now, userId, channelId));
    }
    for (const dmId of dms) {
        statements.push(db.prepare(`
      INSERT INTO dm_read_states (conversation_id, user_id, last_read_at)
      SELECT ?, ?, ?
      WHERE EXISTS (
        SELECT 1 FROM dm_participants WHERE conversation_id = ? AND user_id = ?
      )
      ON CONFLICT(conversation_id, user_id) DO UPDATE SET last_read_at = excluded.last_read_at
    `).bind(dmId, userId, now, dmId, userId));
        statements.push(db.prepare(`
      UPDATE notifications SET read_at = ?
      WHERE user_id = ? AND dm_id = ? AND read_at IS NULL
    `).bind(now, userId, dmId));
    }
    for (const serverId of servers) {
        statements.push(db.prepare(`
      UPDATE notifications SET read_at = ?
      WHERE user_id = ? AND server_id = ? AND read_at IS NULL
    `).bind(now, userId, serverId));
        statements.push(db.prepare(`
      INSERT INTO channel_read_states (channel_id, user_id, last_read_at)
      SELECT c.id, ?, ?
      FROM channels c
      JOIN server_members sm ON sm.server_id = c.server_id AND sm.user_id = ?
      WHERE c.server_id = ?
      ON CONFLICT(channel_id, user_id) DO UPDATE SET last_read_at = excluded.last_read_at
    `).bind(userId, now, userId, serverId));
    }
    if (statements.length)
        await db.batch(statements);
}

async function compactSyncState(request, env, user) {
    const body = await readJson(request) || {};
    const now = Date.now();
    await env.DB.batch([
        env.DB.prepare(`
      INSERT INTO user_presence(user_id, last_seen_at, status)
      VALUES (?, ?, 'online')
      ON CONFLICT(user_id) DO UPDATE SET last_seen_at = excluded.last_seen_at, status = 'online'
    `).bind(user.id, now),
        env.DB.prepare('DELETE FROM typing_states WHERE expires_at < ?').bind(now),
    ]);
    await applyBatchedReadReceipts(env.DB, user.id, body.reads || {});
    const rawViews = Array.isArray(body.views) ? body.views.slice(0, 3) : [];
    const updates = [];
    const seen = new Set();
    for (const raw of rawViews) {
        const kind = raw?.kind === 'dm' ? 'dm' : raw?.kind === 'channel' ? 'channel' : '';
        const id = String(raw?.id || '').slice(0, 128);
        const after = Math.max(0, Number(raw?.after || 0) || 0);
        const key = `${kind}:${id}`;
        if (!kind || !id || seen.has(key))
            continue;
        seen.add(key);
        if (kind === 'channel') {
            if (!(await hasChannelPermission(env.DB, user.id, id, PERMISSIONS.VIEW_CHANNEL)))
                continue;
            const channel = await env.DB.prepare('SELECT type FROM channels WHERE id = ? LIMIT 1').bind(id).first();
            if (!channel || channel.type === 'voice')
                continue;
            updates.push({ kind, id, messages: await queryChannelMessagesAfter(env.DB, id, after) });
        }
        else {
            if (!(await isDmParticipant(env.DB, user.id, id)))
                continue;
            updates.push({ kind, id, messages: await queryDmMessagesAfter(env.DB, id, after) });
        }
    }
    const response = {
        ok: true,
        server_time: Date.now(),
        updates,
        account_safety: accountSafetyFromUser(user),
    };
    if (body.include_notifications) {
        response.notifications = await getUnreadNotifications(env.DB, user.id, 30);
        response.message_requests = await getMessageRequests(env.DB, user.id);
    }
    if (body.include_calls) {
        response.incoming_calls = await getIncomingCallsData(env.DB, user.id);
    }
    return json(response);
}

async function scheduledSafetyMaintenance(env) {
    if (!env.DB)
        return;
    const now = Date.now();
    await ensureMinimumAgeSchema(env.DB);
    await restrictKnownUnderageAccounts(env, 100);
    await cleanupExpiredMinimumAgeEmails(env.DB, now);
    await runForcedUsernameMigrationMaintenance(env, { notificationBatch: 20, migrationBatch: 50 });
    const affected = await env.DB.prepare(`
    SELECT user_id FROM violations
    WHERE status IN ('active', 'appealed')
      AND expires_at IS NOT NULL
      AND expires_at <= ?
    UNION
    SELECT user_id FROM account_limitations
    WHERE status = 'active' AND expires_at <= ?
    LIMIT 500
  `).bind(now, now).all();
    const userIds = [...new Set((affected.results || []).map(row => row.user_id).filter(Boolean))];
    await env.DB.batch([
        env.DB.prepare(`
      UPDATE violations SET status = 'expired'
      WHERE status IN ('active', 'appealed')
        AND expires_at IS NOT NULL
        AND expires_at <= ?
    `).bind(now),
        env.DB.prepare(`
      UPDATE account_limitations SET status = 'expired', updated_at = ?
      WHERE status = 'active' AND expires_at <= ?
    `).bind(now, now),
        env.DB.prepare(`
      UPDATE users SET account_status = 'active', suspension_until = NULL
      WHERE account_status = 'suspended'
        AND suspension_until IS NOT NULL
        AND suspension_until <= ?
    `).bind(now),
    ]);
    for (const userId of userIds) {
        await recomputeUserSafetyCache(env.DB, userId, now);
    }
}

