function perfBase64Url(bytes) {
    let binary = '';
    const input = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
    for (let offset = 0; offset < input.length; offset += 0x8000)
        binary += String.fromCharCode(...input.subarray(offset, offset + 0x8000));
    return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

function perfBase64UrlDecode(value) {
    const base64 = String(value || '').replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(String(value || '').length / 4) * 4, '=');
    const binary = atob(base64);
    return Uint8Array.from(binary, ch => ch.charCodeAt(0));
}

async function perfHmac(secret, value) {
    const key = await crypto.subtle.importKey('raw', encoder.encode(String(secret)), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
    return perfBase64Url(await crypto.subtle.sign('HMAC', key, encoder.encode(String(value))));
}

