async function perfQueryChunks(db, values, build, chunkSize = 70) {
    const output = [];
    for (let offset = 0; offset < values.length; offset += chunkSize) {
        const chunk = values.slice(offset, offset + chunkSize);
        const result = await build(chunk);
        output.push(...(result.results || []));
    }
    return output;
}

async function perfVisibleChannels(db, userId, channels) {
    const serverIds = [...new Set((channels || []).map(row => String(row.server_id || '')).filter(Boolean))];
    if (!serverIds.length)
        return [];
    const canAccessAgeRestricted = await userCanAccessAgeRestrictedChannels(db, userId);
    const memberships = await perfQueryChunks(db, serverIds, chunk => db.prepare(`SELECT server_id,role FROM server_members WHERE user_id=? AND server_id IN (${chunk.map(() => '?').join(',')})`).bind(userId, ...chunk).all());
    const membershipMap = new Map(memberships.map(row => [String(row.server_id), String(row.role || 'member')]));
    const roleRows = await perfQueryChunks(db, serverIds, chunk => db.prepare(`SELECT sr.server_id,sr.id,sr.permissions,sr.is_default FROM server_roles sr LEFT JOIN server_member_roles smr ON smr.role_id=sr.id AND smr.server_id=sr.server_id AND smr.user_id=? WHERE sr.server_id IN (${chunk.map(() => '?').join(',')}) AND (sr.is_default=1 OR smr.user_id IS NOT NULL)`).bind(userId, ...chunk).all());
    const permissionByServer = new Map(), everyoneByServer = new Map(), assignedByServer = new Map();
    for (const role of roleRows) {
        const sid = String(role.server_id), id = String(role.id);
        permissionByServer.set(sid, Number(permissionByServer.get(sid) || 0) | Number(role.permissions || 0));
        if (Number(role.is_default || 0) === 1)
            everyoneByServer.set(sid, id);
        else {
            if (!assignedByServer.has(sid))
                assignedByServer.set(sid, new Set());
            assignedByServer.get(sid).add(id);
        }
    }
    const overwriteRows = await perfQueryChunks(db, serverIds, chunk => db.prepare(`SELECT o.channel_id,o.target_type,o.target_id,o.allow_permissions,o.deny_permissions FROM channel_permission_overwrites o JOIN channels c ON c.id=o.channel_id WHERE c.server_id IN (${chunk.map(() => '?').join(',')})`).bind(...chunk).all());
    const overwritesByChannel = new Map();
    for (const row of overwriteRows) {
        const cid = String(row.channel_id);
        if (!overwritesByChannel.has(cid))
            overwritesByChannel.set(cid, []);
        overwritesByChannel.get(cid).push(row);
    }
    return (channels || []).filter(channel => {
        if (Number(channel.age_restricted || 0) === 1 && !canAccessAgeRestricted)
            return false;
        const sid = String(channel.server_id), membership = membershipMap.get(sid);
        if (!membership)
            return false;
        if (membership === 'owner')
            return true;
        let permissions = Number(permissionByServer.get(sid) || 0);
        if (permissions & PERMISSIONS.ADMINISTRATOR)
            return true;
        const rows = overwritesByChannel.get(String(channel.id)) || [], everyoneId = everyoneByServer.get(sid), assigned = assignedByServer.get(sid) || new Set();
        const everyone = rows.find(row => row.target_type === 'role' && String(row.target_id) === everyoneId);
        if (everyone) {
            permissions &= ~Number(everyone.deny_permissions || 0);
            permissions |= Number(everyone.allow_permissions || 0);
        }
        let roleDeny = 0, roleAllow = 0;
        for (const row of rows) {
            if (row.target_type !== 'role')
                continue;
            const id = String(row.target_id);
            if (id === everyoneId || !assigned.has(id))
                continue;
            roleDeny |= Number(row.deny_permissions || 0);
            roleAllow |= Number(row.allow_permissions || 0);
        }
        permissions &= ~roleDeny;
        permissions |= roleAllow;
        const member = rows.find(row => row.target_type === 'member' && String(row.target_id) === String(userId));
        if (member) {
            permissions &= ~Number(member.deny_permissions || 0);
            permissions |= Number(member.allow_permissions || 0);
        }
        return Boolean(permissions & PERMISSIONS.VIEW_CHANNEL);
    });
}

async function performanceCorePayload(env, user) {
    const t0 = Date.now();
    const serversPromise = env.DB.prepare(`SELECT s.id,s.name,s.icon_url,s.banner_url,s.owner_id,s.server_tag,s.server_tag_badge,sm.role AS member_role,sm.joined_at,COALESCE(sns.level,'mentions') AS notification_level FROM servers s JOIN server_members sm ON sm.server_id=s.id LEFT JOIN server_notification_settings sns ON sns.server_id=s.id AND sns.user_id=? WHERE sm.user_id=? ORDER BY sm.joined_at`).bind(user.id, user.id).all();
    const channelsPromise = env.DB.prepare(`SELECT c.id,c.server_id,c.name,CASE WHEN COALESCE(c.channel_kind,'')!='' THEN c.channel_kind ELSE c.type END AS type,c.position,c.created_at,ccl.category_id,COALESCE(c.age_restricted,0) AS age_restricted,sm.joined_at,COALESCE(crs.last_read_at,0) AS last_read_at FROM channels c JOIN server_members sm ON sm.server_id=c.server_id LEFT JOIN channel_category_links ccl ON ccl.channel_id=c.id LEFT JOIN channel_read_states crs ON crs.channel_id=c.id AND crs.user_id=? WHERE sm.user_id=? ORDER BY c.server_id,COALESCE(ccl.category_id,''),c.position,c.created_at`).bind(user.id, user.id).all();
    const categoriesPromise = env.DB.prepare(`SELECT cc.id,cc.server_id,cc.name,cc.position,cc.created_at FROM channel_categories cc JOIN server_members sm ON sm.server_id=cc.server_id WHERE sm.user_id=? ORDER BY cc.server_id,cc.position,cc.created_at`).bind(user.id).all();
    const activityPromise = env.DB.prepare(`SELECT m.channel_id,MAX(m.created_at) AS last_message_at FROM messages m JOIN channels c ON c.id=m.channel_id JOIN server_members sm ON sm.server_id=c.server_id AND sm.user_id=? WHERE m.deleted_at IS NULL AND m.user_id!=? GROUP BY m.channel_id`).bind(user.id, user.id).all();
    const unreadPromise = env.DB.prepare(`SELECT server_id,channel_id,COUNT(*) AS unread_count,SUM(CASE WHEN type IN ('mention','role','everyone') THEN 1 ELSE 0 END) AS mention_count FROM notifications WHERE user_id=? AND read_at IS NULL GROUP BY server_id,channel_id`).bind(user.id).all();
    const onboardingPromise = env.DB.prepare(`SELECT sos.server_id FROM server_onboarding_settings sos JOIN server_members sm ON sm.server_id=sos.server_id AND sm.user_id=? WHERE sos.enabled=1 AND NOT EXISTS(SELECT 1 FROM server_onboarding_completions soc WHERE soc.server_id=sos.server_id AND soc.user_id=?)`).bind(user.id, user.id).all();
    const [serversResult, channelsResult, categoriesResult, activityResult, unreadResult, onboardingResult, friends, dms, messageRequests, blockedUsers, plus, notifications, me] = await Promise.all([
        serversPromise, channelsPromise, categoriesPromise, activityPromise, unreadPromise, onboardingPromise,
        getFriendData(env.DB, user.id), getDmList(env.DB, user.id), getMessageRequests(env.DB, user.id), getBlockedUsers(env.DB, user.id), getPlusStatus(env.DB, user.id), getUnreadNotifications(env.DB, user.id, 20), enrichedPublicUser(env.DB, user, true)
    ]);
    const plusReward = await syncPlusMonthlyRewards(env.DB, user.id, plus);
    if (plusReward?.balance !== undefined && me)
        me.diamonds = Number(plusReward.balance || 0);
    const visibleChannels = await perfVisibleChannels(env.DB, user.id, channelsResult.results || []);
    const visibleIds = new Set(visibleChannels.map(row => String(row.id)));
    const activity = new Map((activityResult.results || []).map(row => [String(row.channel_id), Number(row.last_message_at || 0)]));
    const unreadByChannel = new Map(), unreadByServer = new Map();
    for (const row of unreadResult.results || []) {
        if (row.channel_id)
            unreadByChannel.set(String(row.channel_id), row);
        if (row.server_id) {
            const sid = String(row.server_id), prev = unreadByServer.get(sid) || { unread_count: 0, mention_count: 0 };
            prev.unread_count += Number(row.unread_count || 0);
            prev.mention_count += Number(row.mention_count || 0);
            unreadByServer.set(sid, prev);
        }
    }
    for (const channel of visibleChannels) {
        const n = unreadByChannel.get(String(channel.id)) || {};
        const lastMessageAt = Number(activity.get(String(channel.id)) || 0);
        const lastReadAt = Math.max(Number(channel.last_read_at || 0), Number(channel.joined_at || 0));
        channel.last_message_at = lastMessageAt;
        channel.last_read_at = lastReadAt;
        channel.has_unread = lastMessageAt > lastReadAt ? 1 : 0;
        channel.mention_count = Number(n.mention_count || 0);
        delete channel.joined_at;
    }
    const onboarding = new Set((onboardingResult.results || []).map(row => String(row.server_id)));
    const servers = serversResult.results || [];
    for (const server of servers) {
        const sid = String(server.id), n = unreadByServer.get(sid) || {};
        const serverChannels = visibleChannels.filter(c => String(c.server_id) === sid);
        server.has_unread = serverChannels.some(c => Number(c.has_unread || 0)) ? 1 : 0;
        server.unread_count = Number(n.unread_count || 0);
        server.mention_count = Number(n.mention_count || 0);
        server.onboarding_required = onboarding.has(sid);
        delete server.joined_at;
    }
    const visibleCategories = await filterVisibleCategories(env.DB, user.id, categoriesResult.results || [], visibleChannels);
    me.plus = plus;
    me.support_active = await hasSupportRank(env, user.id);
    if (me.support_active && !me.badges.includes('support'))
        me.badges.push('support');
    await attachLegalStatus(env.DB, user.id, me);
    const activityIds = [user.id, ...friends.friends.map(item => item.user_id), ...dms.flatMap(dm => [dm.user_id, ...(dm.participants || []).map(p => p.user_id)])].filter(Boolean);
    const activities = await getActivitiesForUsers(env.DB, activityIds);
    const ownActivity = activities[String(user.id)];
    if (ownActivity) {
        me.activity_type = ownActivity.type;
        me.activity_name = ownActivity.name;
        me.activity_started_at = ownActivity.started_at;
        me.activity_expires_at = ownActivity.expires_at;
    }
    return { ok: true, core_version: 1, server_time: Date.now(), me, servers, channels: visibleChannels, categories: visibleCategories, friends: friends.friends, friend_requests: friends.requests, sent_friend_requests: friends.sent_requests, blocked_users: blockedUsers, plus, dms, message_requests: messageRequests, notifications, activities, account_safety: accountSafetyFromUser(user), performance: { core_ms: Date.now() - t0 } };
}

async function performanceCoreBootstrap(env, user, ctx) {
    const started = Date.now();
    const payload = await performanceCorePayload(env, user);
    const background = Promise.resolve().then(async () => {
        try {
            await ensureByteAccount(env.DB);
            await ensureWelcomeSystemDm(env.DB, user);
            await sendUsernameMigrationNotice(env, user, ctx);
        }
        catch (error) {
            console.warn('Deferred startup setup failed', error);
        }
        try {
            await env.DB.prepare(`INSERT INTO user_presence(user_id,last_seen_at,status)
        VALUES(?,?,'online')
        ON CONFLICT(user_id) DO UPDATE SET
          last_seen_at=excluded.last_seen_at,status='online'`)
                .bind(user.id, Date.now()).run();
        }
        catch { }
    });
    if (ctx?.waitUntil)
        ctx.waitUntil(background);
    else
        background.catch(() => { });
    return json(payload, 200, {
        'Cache-Control': 'private, no-store',
        'Server-Timing': `core;dur=${Date.now() - started}`
    });
}

async function fastLiveView(request, env, user) {
    const body = await readJson(request) || {};
    const kind = body.kind === 'dm' ? 'dm' : body.kind === 'channel' ? 'channel' : '';
    const id = String(body.id || body.target_id || '').slice(0, 128);
    const after = Math.max(0, Number(body.after || 0) || 0);
    if (!kind || !id)
        return json({ error: 'Missing live view', code: 'LIVE_VIEW_UNAVAILABLE' }, 400);
    if (kind === 'channel') {
        if (!(await hasChannelPermission(env.DB, user.id, id, PERMISSIONS.VIEW_CHANNEL)))
            return json({ error: 'Channel not found' }, 404);
    }
    else if (!(await isDmParticipant(env.DB, user.id, id))) {
        return json({ error: 'DM not found' }, 404);
    }
    const now = Date.now();
    let latest = 0;
    if (kind === 'channel') {
        const head = await env.DB.prepare(`
      SELECT
        MAX(COALESCE(created_at,0)) AS newest_created,
        MAX(COALESCE(edited_at,0)) AS newest_edited
      FROM messages
      WHERE channel_id=? AND deleted_at IS NULL
    `).bind(id).first();
        latest = Math.max(Number(head?.newest_created || 0), Number(head?.newest_edited || 0));
    }
    else {
        const head = await env.DB.prepare(`
      SELECT
        MAX(COALESCE(created_at,0)) AS newest_created,
        MAX(COALESCE(edited_at,0)) AS newest_edited
      FROM dm_messages
      WHERE conversation_id=? AND deleted_at IS NULL
    `).bind(id).first();
        latest = Math.max(Number(head?.newest_created || 0), Number(head?.newest_edited || 0));
    }
    const typingRows = await env.DB.prepare(`
    SELECT t.kind,t.target_id,t.user_id,u.display_name,u.username,t.expires_at
    FROM typing_states t
    JOIN users u ON u.id=t.user_id
    WHERE t.kind=? AND t.target_id=? AND t.user_id!=? AND t.expires_at>?
    ORDER BY t.expires_at DESC
    LIMIT 8
  `).bind(kind, id, user.id, now).all();
    let messages = [];
    if (latest > after && latest > 0) {
        messages = kind === 'channel'
            ? await queryChannelMessagesAfter(env.DB, id, after)
            : await queryDmMessagesAfter(env.DB, id, after);
    }
    return json({
        ok: true,
        kind,
        id,
        latest,
        messages,
        typing: typingRows.results || [],
        server_time: now
    }, 200, {
        'Cache-Control': 'private, no-store',
        'Server-Timing': `live;dur=${Date.now() - now}`
    });
}

async function cursorSyncState(request, env, user) {
    const body = await readJson(request) || {}, now = Date.now(), cursor = Math.max(0, Number(body.cursor || 0) || 0);
    await env.DB.batch([env.DB.prepare(`INSERT INTO user_presence(user_id,last_seen_at,status) VALUES(?,?,'online') ON CONFLICT(user_id) DO UPDATE SET last_seen_at=excluded.last_seen_at,status='online'`).bind(user.id, now), env.DB.prepare('DELETE FROM typing_states WHERE expires_at<?').bind(now), env.DB.prepare('DELETE FROM user_activities WHERE expires_at<?').bind(now)]);
    await applyBatchedReadReceipts(env.DB, user.id, body.reads || {});
    const rawViews = Array.isArray(body.views) ? body.views.slice(0, 8) : [], updates = [], typing = [];
    for (const raw of rawViews) {
        const kind = raw?.kind === 'dm' ? 'dm' : raw?.kind === 'channel' ? 'channel' : '', id = String(raw?.id || '').slice(0, 128), after = Math.max(0, Number(raw?.after || 0) || 0);
        if (!kind || !id)
            continue;
        if (kind === 'channel') {
            if (!(await hasChannelPermission(env.DB, user.id, id, PERMISSIONS.VIEW_CHANNEL)))
                continue;
            updates.push({ kind, id, messages: await queryChannelMessagesAfter(env.DB, id, after) });
        }
        else {
            if (!(await isDmParticipant(env.DB, user.id, id)))
                continue;
            updates.push({ kind, id, messages: await queryDmMessagesAfter(env.DB, id, after) });
        }
        const tr = await env.DB.prepare(`SELECT t.kind,t.target_id,t.user_id,u.display_name,u.username,t.expires_at FROM typing_states t JOIN users u ON u.id=t.user_id WHERE t.kind=? AND t.target_id=? AND t.user_id!=? AND t.expires_at>? LIMIT 8`).bind(kind, id, user.id, now).all();
        typing.push(...(tr.results || []));
    }
    let response = { ok: true, cursor: now, previous_cursor: cursor, server_time: now, updates, typing, account_safety: accountSafetyFromUser(user) };
    if (body.include_core)
        response = { ...response, ...await performanceCorePayload(env, user), cursor: now, previous_cursor: cursor, updates, typing };
    else if (body.include_social) {
        const social = await getFriendData(env.DB, user.id);
        Object.assign(response, { friends: social.friends, friend_requests: social.requests, sent_friend_requests: social.sent_requests, blocked_users: await getBlockedUsers(env.DB, user.id), dms: await getDmList(env.DB, user.id), message_requests: await getMessageRequests(env.DB, user.id) });
    }
    if (body.include_notifications) {
        response.notifications = await getUnreadNotifications(env.DB, user.id, 30);
        response.message_requests = response.message_requests || await getMessageRequests(env.DB, user.id);
    }
    if (body.include_calls)
        response.incoming_calls = await getIncomingCallsData(env.DB, user.id);
    return json(response, 200, { 'Cache-Control': 'no-store', 'Server-Timing': `sync;dur=${Date.now() - now}` });
}

function byteLooksLikeActionRequest(prompt) { return /\b(create|delete|remove|close|rename|add|invite|send|make)\b[\s\S]{0,60}\b(server|channel|group|dm|friend|message|role|account)\b/i.test(String(prompt || '')) || /\bcalculate|what time|time in\b/i.test(String(prompt || '')); }

function parseWorkersAiStreamLine(line) {
    const text = String(line || '').trim();
    if (!text.startsWith('data:'))
        return '';
    const data = text.slice(5).trim();
    if (!data || data === '[DONE]')
        return '';
    try {
        const parsed = JSON.parse(data);
        return String(parsed.response ?? parsed.token ?? parsed.choices?.[0]?.delta?.content ?? parsed.choices?.[0]?.text ?? '');
    }
    catch {
        return '';
    }
}

