async function getTwoFactorRow(db, userId) { await ensureR180SecuritySchema(db); return db.prepare('SELECT * FROM user_two_factor WHERE user_id=? LIMIT 1').bind(userId).first(); }

async function getTwoFactorSettings(env, user) { await ensureR180SecuritySchema(env.DB); const row = await getTwoFactorRow(env.DB, user.id); const count = await env.DB.prepare('SELECT COUNT(*) AS total FROM two_factor_backup_codes WHERE user_id=? AND used_at IS NULL').bind(user.id).first(); return json({ email_enabled: Number(row?.email_enabled || 0) === 1, email_verified: Number(user.email_verified || 0) === 1, masked_email: maskEmail(user.email || ''), backup_codes_remaining: Number(count?.total || 0) }, 200, { 'Cache-Control': 'no-store' }); }

async function verifyCurrentPassword(request, user) { const body = await readJson(request); if (!body)
    return { error: json({ error: 'Invalid JSON' }, 400) }; const password = String(body.password || ''); if (!password)
    return { error: json({ error: 'Enter your current password' }, 400) }; if (!(await verifyPassword(password, user.password_salt, user.password_hash)))
    return { error: json({ error: 'Current password is incorrect' }, 403) }; return { body }; }

function randomBackupCode() { const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; let out = 'ORBY-'; for (let i = 0; i < 8; i++) {
    if (i === 4)
        out += '-';
    out += alphabet[Math.floor(Math.random() * alphabet.length)];
} return out; }

async function replaceBackupCodes(env, userId) { await ensureR180SecuritySchema(env.DB); const now = Date.now(), codes = Array.from({ length: 8 }, randomBackupCode), statements = [env.DB.prepare('DELETE FROM two_factor_backup_codes WHERE user_id=?').bind(userId)]; for (const code of codes) {
    statements.push(env.DB.prepare('INSERT INTO two_factor_backup_codes(id,user_id,code_hash,used_at,created_at) VALUES(?,?,?,NULL,?)').bind(prefixedId('2fab'), userId, await sha256(`${userId}:${code.toUpperCase()}`), now));
} await env.DB.batch(statements); return codes; }

async function enableEmailTwoFactor(request, env, user) { await ensureR180SecuritySchema(env.DB); if (!user.email || !Number(user.email_verified || 0))
    return json({ error: 'Link and verify an email before enabling email 2FA' }, 409); const checked = await verifyCurrentPassword(request, user); if (checked.error)
    return checked.error; const now = Date.now(); await env.DB.prepare(`INSERT INTO user_two_factor(user_id,email_enabled,created_at,updated_at) VALUES(?,1,?,?) ON CONFLICT(user_id) DO UPDATE SET email_enabled=1,updated_at=excluded.updated_at`).bind(user.id, now, now).run(); const codes = await replaceBackupCodes(env, user.id); return json({ ok: true, email_enabled: true, backup_codes: codes, warning: 'Save these backup codes now. Each code can be used once.' }, 200, { 'Cache-Control': 'no-store' }); }

async function disableEmailTwoFactor(request, env, user) { await ensureR180SecuritySchema(env.DB); const checked = await verifyCurrentPassword(request, user); if (checked.error)
    return checked.error; const now = Date.now(); await env.DB.batch([env.DB.prepare(`INSERT INTO user_two_factor(user_id,email_enabled,created_at,updated_at) VALUES(?,0,?,?) ON CONFLICT(user_id) DO UPDATE SET email_enabled=0,updated_at=excluded.updated_at`).bind(user.id, now, now), env.DB.prepare('DELETE FROM two_factor_challenges WHERE user_id=?').bind(user.id)]); return json({ ok: true, email_enabled: false }); }

async function regenerateTwoFactorBackupCodes(request, env, user) { const checked = await verifyCurrentPassword(request, user); if (checked.error)
    return checked.error; const row = await getTwoFactorRow(env.DB, user.id); if (!Number(row?.email_enabled || 0))
    return json({ error: 'Enable email 2FA first' }, 409); const codes = await replaceBackupCodes(env, user.id); return json({ ok: true, backup_codes: codes, warning: 'Your old backup codes no longer work.' }, 200, { 'Cache-Control': 'no-store' }); }

async function createEmailTwoFactorChallenge(env, user, deviceId) { await ensureR180SecuritySchema(env.DB); const now = Date.now(), id = prefixedId('2fa'), code = String(Math.floor(100000 + Math.random() * 900000)), hash = await sha256(`${id}:${user.id}:${code}`); await env.DB.batch([env.DB.prepare('DELETE FROM two_factor_challenges WHERE user_id=? AND expires_at<?').bind(user.id, now), env.DB.prepare('INSERT INTO two_factor_challenges(id,user_id,code_hash,device_id,attempts,expires_at,created_at) VALUES(?,?,?,?,0,?,?)').bind(id, user.id, hash, deviceId, now + 10 * 60 * 1000, now)]); await sendAppsScriptEmail(env, { type: 'two_factor_code', to: String(user.email).trim().toLowerCase(), display_name: user.display_name || user.username || 'Orbyte user', code, expires_minutes: 10 }); const count = await env.DB.prepare('SELECT COUNT(*) AS total FROM two_factor_backup_codes WHERE user_id=? AND used_at IS NULL').bind(user.id).first(); return { id, backup_codes_available: Number(count?.total || 0) > 0 }; }

async function verifyLoginTwoFactor(request, env, ctx) { await ensureR180SecuritySchema(env.DB); const body = await readJson(request); if (!body)
    return json({ error: 'Invalid JSON' }, 400); const id = String(body.challenge_id || '').trim(), code = String(body.code || '').trim().toUpperCase(), deviceId = normalizeSecurityDeviceId(body.device_id, request); if (!id || !code)
    return json({ error: 'Enter your verification code' }, 400); const row = await env.DB.prepare(`SELECT c.*,u.* FROM two_factor_challenges c JOIN users u ON u.id=c.user_id WHERE c.id=? LIMIT 1`).bind(id).first(); if (!row || Number(row.expires_at) <= Date.now())
    return json({ error: 'This verification request expired. Log in again.', code: 'TWO_FACTOR_EXPIRED' }, 410); if (await isSuspiciousActivitySuspension(env.DB, row.user_id))
    return json({ error: 'Your account has been suspended until you confirm your identity.', code: 'SUSPICIOUS_ACTIVITY_DISABLED', recovery_required: true }, 403); let valid = false, backupId = ''; if (/^\d{6}$/.test(code)) {
    valid = (await sha256(`${id}:${row.user_id}:${code}`)) === row.code_hash;
}
else {
    const b = await env.DB.prepare('SELECT id FROM two_factor_backup_codes WHERE user_id=? AND code_hash=? AND used_at IS NULL LIMIT 1').bind(row.user_id, await sha256(`${row.user_id}:${code}`)).first();
    if (b) {
        valid = true;
        backupId = b.id;
    }
} if (!valid) {
    await env.DB.prepare('UPDATE two_factor_challenges SET attempts=attempts+1 WHERE id=?').bind(id).run();
    await recordSecurityAttempt(env, row, deviceId || row.device_id || 'unknown', 'two_factor');
    return json({ error: 'That code is not valid.', code: 'TWO_FACTOR_INVALID' }, 401);
} const now = Date.now(), statements = [env.DB.prepare('DELETE FROM two_factor_challenges WHERE id=?').bind(id)]; if (backupId)
    statements.push(env.DB.prepare('UPDATE two_factor_backup_codes SET used_at=? WHERE id=?').bind(now, backupId)); await env.DB.batch(statements); const session = await createSession(env.DB, row.user_id, request); return json({ ok: true, token: session.token, account_status: row.account_status, restricted: hasActiveAccountRestriction(row) }, 200, { 'Cache-Control': 'no-store' }); }

async function recordSecurityAttempt(env, user, deviceId, kind) { await ensureR180SecuritySchema(env.DB); if (!user?.id || !user.email || !Number(user.email_verified || 0))
    return; const now = Date.now(), cleanKind = ['login_password', 'two_factor', 'client_pin'].includes(kind) ? kind : 'client_pin', cleanDevice = String(deviceId || 'unknown').slice(0, 160); await env.DB.prepare('INSERT INTO security_attempts(id,user_id,device_id,kind,created_at) VALUES(?,?,?,?,?)').bind(prefixedId('secat'), user.id, cleanDevice, cleanKind, now).run(); await env.DB.prepare('DELETE FROM security_attempts WHERE created_at<?').bind(now - 24 * 60 * 60 * 1000).run(); const row = await env.DB.prepare('SELECT COUNT(*) AS total FROM security_attempts WHERE user_id=? AND device_id=? AND kind=? AND created_at>=?').bind(user.id, cleanDevice, cleanKind, now - 10 * 60 * 1000).first(); if (Number(row?.total || 0) >= 10)
    await suspendForSuspiciousActivity(env, user, `Too many invalid ${cleanKind === 'two_factor' ? 'verification code' : cleanKind === 'client_pin' ? 'app PIN' : 'login'} attempts were detected from one device.`); }

async function recordClientSecurityFailure(request, env, user) { const body = await readJson(request) || {}; if (String(body.kind || '') !== 'pin')
    return json({ error: 'Unsupported security event' }, 400); const device = normalizeSecurityDeviceId(body.device_id, request); await recordSecurityAttempt(env, user, device, 'client_pin'); return json({ ok: true }); }

async function isSuspiciousActivitySuspension(db, userId) { await ensureR180SecuritySchema(db); const row = await db.prepare(`SELECT 1 FROM violations WHERE user_id=? AND violation_type='Suspicious activity' AND status='active' LIMIT 1`).bind(userId).first(); return Boolean(row); }

async function suspendForSuspiciousActivity(env, user, reason) { await ensureR180SecuritySchema(env.DB); if (!user?.id || !user.email || !Number(user.email_verified || 0))
    return false; if (await isSuspiciousActivitySuspension(env.DB, user.id))
    return true; const now = Date.now(), vio = prefixedId('vio'), rawToken = randomBase64Url(32), tokenHash = await sha256(rawToken), recoveryId = prefixedId('secrec'), origin = primaryFrontendOrigin(env).replace(/\/$/, ''); const actionUrl = `${origin}/?security-recovery=${encodeURIComponent(rawToken)}`; await env.DB.batch([env.DB.prepare(`INSERT INTO violations(id,user_id,report_id,violation_type,severity,reason,action,evidence_text,moderator_note,status,expires_at,restriction_mask,restriction_until,suspension_until,content_removed,reversed_at,created_by,created_at) VALUES(?,?,NULL,'Suspicious activity','critical',?,'suspension',?,'','active',NULL,0,NULL,NULL,0,NULL,?,?)`).bind(vio, user.id, 'This violation affects your account standing until you confirm your identity.', reason, SYSTEM_USER_ID, now), env.DB.prepare(`UPDATE users SET account_status='suspended',suspension_until=NULL WHERE id=?`).bind(user.id), env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(user.id), env.DB.prepare('DELETE FROM security_recovery_tokens WHERE user_id=? AND used_at IS NULL').bind(user.id), env.DB.prepare(`INSERT INTO security_recovery_tokens(id,user_id,token_hash,reason,expires_at,used_at,created_at) VALUES(?,?,?,?,?,NULL,?)`).bind(recoveryId, user.id, tokenHash, reason, now + 24 * 60 * 60 * 1000, now)]); await sendAppsScriptEmail(env, { type: 'suspicious_activity', to: String(user.email).trim().toLowerCase(), display_name: user.display_name || user.username || 'Orbyte user', reason, action_url: actionUrl, expires_hours: 24 }); return true; }

function isScamPhishingReportReason(category, subcategory) { return /scam|phish/i.test(`${category || ''} ${subcategory || ''}`); }

async function reportTargetUserId(db, targetType, targetId) { if (targetType === 'user')
    return targetId; if (targetType === 'message') {
    let row = await db.prepare('SELECT user_id FROM messages WHERE id=? LIMIT 1').bind(targetId).first();
    if (!row)
        row = await db.prepare('SELECT user_id FROM dm_messages WHERE id=? LIMIT 1').bind(targetId).first();
    return row?.user_id || '';
} return ''; }

async function maybeSuspendReportedAccountForScamPhishing(env, { reportId, reporterId, targetType, targetId }) { await ensureR180SecuritySchema(env.DB); const targetUserId = await reportTargetUserId(env.DB, targetType, targetId); if (!targetUserId || targetUserId === reporterId)
    return false; const target = await env.DB.prepare('SELECT * FROM users WHERE id=? LIMIT 1').bind(targetUserId).first(); if (!target?.email || !Number(target.email_verified || 0))
    return false; const recent = await env.DB.prepare(`SELECT COUNT(DISTINCT reporter_id) AS reporters FROM reports WHERE created_at>=? AND reporter_id!=? AND ((target_type='user' AND target_id=?) OR (target_type='message' AND target_id IN (SELECT id FROM messages WHERE user_id=? UNION SELECT id FROM dm_messages WHERE user_id=?))) AND (lower(reason) LIKE '%scam%' OR lower(reason) LIKE '%phish%' OR lower(details) LIKE '%scam%' OR lower(details) LIKE '%phish%')`).bind(Date.now() - 15 * 60 * 1000, targetUserId, targetUserId, targetUserId, targetUserId).first(); if (Number(recent?.reporters || 0) >= 2) {
    return suspendForSuspiciousActivity(env, target, 'Multiple independent scam/phishing reports were received in a short period.');
} return false; }

async function getSuspiciousRecovery(env, rawToken) { await ensureR180SecuritySchema(env.DB); const hash = await sha256(String(rawToken || '')), row = await env.DB.prepare(`SELECT r.*,u.display_name,u.username FROM security_recovery_tokens r JOIN users u ON u.id=r.user_id WHERE r.token_hash=? AND r.used_at IS NULL LIMIT 1`).bind(hash).first(); if (!row || Number(row.expires_at) <= Date.now())
    return json({ error: 'This recovery link is invalid or expired' }, 410, { 'Cache-Control': 'no-store' }); return json({ ok: true, display_name: row.display_name || row.username || 'Orbyte user', reason: row.reason, expires_at: row.expires_at }, 200, { 'Cache-Control': 'no-store' }); }

async function completeSuspiciousRecovery(request, env, rawToken) { await ensureR180SecuritySchema(env.DB); const body = await readJson(request); if (!body)
    return json({ error: 'Invalid JSON' }, 400); const password = String(body.new_password || ''); if (password.length < 8 || password.length > 128)
    return json({ error: 'Use a password between 8 and 128 characters' }, 400); const hash = await sha256(String(rawToken || '')), row = await env.DB.prepare(`SELECT r.*,u.* FROM security_recovery_tokens r JOIN users u ON u.id=r.user_id WHERE r.token_hash=? AND r.used_at IS NULL LIMIT 1`).bind(hash).first(); if (!row || Number(row.expires_at) <= Date.now())
    return json({ error: 'This recovery link is invalid or expired' }, 410); const salt = randomBase64(16), passwordHash = await hashPassword(password, salt), now = Date.now(); await env.DB.batch([env.DB.prepare('UPDATE users SET password_hash=?,password_salt=?,account_status=\'active\',suspension_until=NULL WHERE id=?').bind(passwordHash, salt, row.user_id), env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(row.user_id), env.DB.prepare(`UPDATE violations SET status='expired',expires_at=? WHERE user_id=? AND violation_type='Suspicious activity' AND status='active'`).bind(now, row.user_id), env.DB.prepare('UPDATE security_recovery_tokens SET used_at=? WHERE id=?').bind(now, row.id), env.DB.prepare('DELETE FROM security_attempts WHERE user_id=?').bind(row.user_id)]); try {
    await sendAppsScriptEmail(env, { type: 'password_changed', to: String(row.email || '').trim().toLowerCase(), display_name: row.display_name || row.username || 'Orbyte user' });
}
catch { } return json({ ok: true, message: 'Your password was changed and your account was re-enabled.' }, 200, { 'Cache-Control': 'no-store' }); }

let accountEmailRecoverySchemaReady = null;

async function ensureAccountEmailRecoverySchema(db) {
    if (accountEmailRecoverySchemaReady)
        return accountEmailRecoverySchemaReady;
    accountEmailRecoverySchemaReady = (async () => {
        await db.batch([
            db.prepare(`CREATE TABLE IF NOT EXISTS account_email_recovery_tokens (
        id TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        token_hash TEXT NOT NULL UNIQUE,
        previous_email TEXT NOT NULL,
        new_email TEXT NOT NULL,
        expires_at INTEGER NOT NULL,
        used_at INTEGER,
        invalidated_at INTEGER,
        invalidated_reason TEXT,
        created_at INTEGER NOT NULL
      )`),
            db.prepare(`CREATE INDEX IF NOT EXISTS idx_account_email_recovery_user
        ON account_email_recovery_tokens(user_id,created_at DESC)`),
            db.prepare(`CREATE INDEX IF NOT EXISTS idx_account_email_recovery_previous_email
        ON account_email_recovery_tokens(previous_email,expires_at)`),
            db.prepare(`CREATE TABLE IF NOT EXISTS session_devices (
        token_hash TEXT PRIMARY KEY,
        user_id TEXT NOT NULL,
        device_name TEXT NOT NULL DEFAULT '',
        user_agent TEXT NOT NULL DEFAULT '',
        created_at INTEGER NOT NULL
      )`),
        ]);
    })().catch(error => { accountEmailRecoverySchemaReady = null; throw error; });
    return accountEmailRecoverySchemaReady;
}

async function accountEmailRecoveryRow(env, rawToken) {
    await ensureAccountEmailRecoverySchema(env.DB);
    const token = String(rawToken || '').trim();
    if (!token || token.length > 256)
        return null;
    const tokenHash = await sha256(token);
    return env.DB.prepare(`
    SELECT r.*,u.username,u.discriminator,u.display_name,u.email AS current_email,u.email_verified
    FROM account_email_recovery_tokens r
    JOIN users u ON u.id=r.user_id
    WHERE r.token_hash=?
    LIMIT 1
  `).bind(tokenHash).first();
}

function accountRecoveryUnavailable(row) {
    if (!row)
        return 'invalid';
    if (row.used_at)
        return 'used';
    if (row.invalidated_at)
        return 'invalidated';
    if (Number(row.expires_at || 0) <= Date.now())
        return 'expired';
    return '';
}

async function getAccountEmailRecovery(env, rawToken) {
    const row = await accountEmailRecoveryRow(env, rawToken);
    const unavailable = accountRecoveryUnavailable(row);
    if (unavailable) {
        const messages = {
            used: 'This account recovery link has already been used.',
            invalidated: 'This account recovery link is no longer valid.',
            expired: 'This account recovery link has expired.',
            invalid: 'This account recovery link is invalid.',
        };
        return json({ error: messages[unavailable], code: `ACCOUNT_RECOVERY_${unavailable.toUpperCase()}` }, 410, { 'Cache-Control': 'no-store' });
    }
    return json({
        ok: true,
        display_name: row.display_name || row.username || 'Orbyte user',
        previous_email: maskEmail(row.previous_email || ''),
        current_email: maskEmail(row.current_email || row.new_email || ''),
        expires_at: Number(row.expires_at || 0),
        actions: [
            'restore_previous_email',
            'reset_password',
            'disable_two_factor',
            'logout_all_sessions',
            'invalidate_newer_recovery_links',
        ],
    }, 200, { 'Cache-Control': 'no-store' });
}

async function completeAccountEmailRecovery(request, env, rawToken) {
    await ensureAccountEmailRecoverySchema(env.DB);
    await ensureR180SecuritySchema(env.DB);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    const password = String(body.new_password || '');
    if (password.length < 8 || password.length > 128) {
        return json({ error: 'Use a password between 8 and 128 characters' }, 400);
    }
    const row = await accountEmailRecoveryRow(env, rawToken);
    const unavailable = accountRecoveryUnavailable(row);
    if (unavailable)
        return json({ error: 'This account recovery link is invalid, expired, or already used', code: 'ACCOUNT_RECOVERY_UNAVAILABLE' }, 410, { 'Cache-Control': 'no-store' });
    const conflict = await env.DB.prepare(`
    SELECT id FROM users
    WHERE email=? COLLATE NOCASE AND email_verified=1 AND id!=?
    LIMIT 1
  `).bind(row.previous_email, row.user_id).first();
    if (conflict)
        return json({
            error: 'Your previous email is currently linked to another account. Contact Orbyte Support.',
            code: 'RECOVERY_EMAIL_CONFLICT'
        }, 409, { 'Cache-Control': 'no-store' });
    const now = Date.now();
    const salt = randomBase64(16);
    const passwordHash = await hashPassword(password, salt);
    await env.DB.batch([
        env.DB.prepare(`UPDATE users SET email=?,email_verified=1,password_hash=?,password_salt=? WHERE id=?`)
            .bind(String(row.previous_email).trim().toLowerCase(), passwordHash, salt, row.user_id),
        env.DB.prepare('DELETE FROM sessions WHERE user_id=?').bind(row.user_id),
        env.DB.prepare('DELETE FROM session_devices WHERE user_id=?').bind(row.user_id),
        env.DB.prepare('DELETE FROM email_verifications WHERE user_id=?').bind(row.user_id),
        env.DB.prepare('DELETE FROM password_reset_codes WHERE user_id=?').bind(row.user_id),
        env.DB.prepare('DELETE FROM two_factor_challenges WHERE user_id=?').bind(row.user_id),
        env.DB.prepare('DELETE FROM two_factor_backup_codes WHERE user_id=?').bind(row.user_id),
        env.DB.prepare(`INSERT INTO user_two_factor(user_id,email_enabled,created_at,updated_at)
      VALUES(?,0,?,?)
      ON CONFLICT(user_id) DO UPDATE SET email_enabled=0,updated_at=excluded.updated_at`)
            .bind(row.user_id, now, now),
        env.DB.prepare('UPDATE account_email_recovery_tokens SET used_at=? WHERE id=?').bind(now, row.id),
        env.DB.prepare(`UPDATE account_email_recovery_tokens
      SET invalidated_at=?,invalidated_reason='older_recovery_used'
      WHERE user_id=? AND created_at>? AND used_at IS NULL AND invalidated_at IS NULL`)
            .bind(now, row.user_id, Number(row.created_at || 0)),
    ]);
    try {
        await sendAppsScriptEmail(env, {
            type: 'account_recovered',
            to: String(row.previous_email).trim().toLowerCase(),
            username: row.username || '',
            discriminator: row.discriminator || '',
            display_name: row.display_name || row.username || 'Orbyte user',
            subject: 'Your Orbyte account was recovered',
            heading: 'Your Orbyte account is secure again',
            message: 'Your previous email was restored, your password was changed, two-factor authentication was disabled, and all existing sessions were signed out.',
        });
    }
    catch (error) {
        console.warn('Could not send account recovered confirmation email', row.user_id, error);
    }
    return json({
        ok: true,
        message: 'Your account was recovered. Your previous email was restored and every existing session was signed out.',
        email: maskEmail(row.previous_email || ''),
        login_required: true,
    }, 200, { 'Cache-Control': 'no-store' });
}

const ORBYTE_COSMETIC_TYPES = new Set(['avatar_decoration', 'profile_effect', 'nameplate']);

let orbyteProfileFeatureSchemaReady = false;

function obCorsHeaders(extra = {}) {
    return {
        'access-control-allow-origin': '*',
        'access-control-allow-headers': 'authorization, content-type',
        'access-control-allow-methods': 'GET, POST, PUT, PATCH, DELETE, OPTIONS',
        'access-control-max-age': '86400',
        ...extra
    };
}

function obJson(data, status = 200) {
    return new Response(JSON.stringify(data), {
        status,
        headers: obCorsHeaders({
            'content-type': 'application/json; charset=utf-8',
            'cache-control': 'no-store'
        })
    });
}

async function obReadJson(request) {
    try {
        return await request.json();
    }
    catch {
        return {};
    }
}

function obRole(user) {
    return String(user?.role || user?.account_role || '').toLowerCase();
}

function obRequireUser(user) {
    if (!user?.id)
        throw Object.assign(new Error('Authentication required'), { status: 401 });
    return user;
}

function obRequireAdmin(user) {
    obRequireUser(user);
    if (!['owner', 'admin'].includes(obRole(user))) {
        throw Object.assign(new Error('Administrator access required'), { status: 403 });
    }
    return user;
}

function obNow() { return Date.now(); }

function obId(prefix) { return `${prefix}_${crypto.randomUUID().replace(/-/g, '')}`; }

async function ensureOrbyteProfileFeatureSchema(env) {
    if (orbyteProfileFeatureSchemaReady)
        return;
    const db = env.DB;
    if (!db)
        throw new Error('D1 binding env.DB is missing');
    await db.batch([
        db.prepare(`CREATE TABLE IF NOT EXISTS user_profile_statuses (
      user_id TEXT PRIMARY KEY,
      status_text TEXT NOT NULL,
      expires_at INTEGER,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    )`),
        db.prepare(`CREATE TABLE IF NOT EXISTS profile_cosmetics (
      id TEXT PRIMARY KEY,
      type TEXT NOT NULL,
      name TEXT NOT NULL,
      description TEXT NOT NULL DEFAULT '',
      price INTEGER NOT NULL DEFAULT 0,
      rarity TEXT NOT NULL DEFAULT 'standard',
      definition_json TEXT NOT NULL,
      published INTEGER NOT NULL DEFAULT 1,
      created_by TEXT,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL,
      archived_at INTEGER
    )`),
        db.prepare(`CREATE TABLE IF NOT EXISTS user_profile_cosmetics (
      user_id TEXT NOT NULL,
      cosmetic_id TEXT NOT NULL,
      purchased_at INTEGER NOT NULL,
      PRIMARY KEY (user_id, cosmetic_id)
    )`),
        db.prepare(`CREATE TABLE IF NOT EXISTS user_profile_cosmetic_loadout (
      user_id TEXT PRIMARY KEY,
      avatar_decoration_id TEXT,
      profile_effect_id TEXT,
      nameplate_id TEXT,
      updated_at INTEGER NOT NULL
    )`),
        db.prepare(`CREATE INDEX IF NOT EXISTS idx_profile_cosmetics_store ON profile_cosmetics (published, type, updated_at)`),
        db.prepare(`CREATE INDEX IF NOT EXISTS idx_user_profile_cosmetics_user ON user_profile_cosmetics (user_id)`)
    ]);
    orbyteProfileFeatureSchemaReady = true;
}

function parseCosmeticRow(row) {
    if (!row)
        return null;
    let definition = {};
    try {
        definition = JSON.parse(row.definition_json || '{}');
    }
    catch { }
    return {
        id: row.id,
        type: row.type,
        name: row.name,
        description: row.description || '',
        price: Number(row.price || 0),
        rarity: row.rarity || 'standard',
        definition,
        published: Number(row.published || 0),
        created_by: row.created_by || null,
        created_at: Number(row.created_at || 0),
        updated_at: Number(row.updated_at || 0)
    };
}

function validateDefinition(type, input) {
    if (!ORBYTE_COSMETIC_TYPES.has(type))
        throw Object.assign(new Error('Invalid cosmetic type'), { status: 400 });
    const defaults = type === 'avatar_decoration' ? [128, 128] : type === 'nameplate' ? [360, 64] : [320, 420];
    const def = input && typeof input === 'object' ? structuredClone(input) : {};
    def.version = 1;
    def.type = type;
    def.width = Math.max(8, Math.min(1024, Number(def.width || defaults[0])));
    def.height = Math.max(8, Math.min(1024, Number(def.height || defaults[1])));
    def.loop = def.loop !== false;
    if (!Array.isArray(def.frames) || !def.frames.length)
        def.frames = [{ duration: 250, objects: [] }];
    if (def.frames.length > 120)
        throw Object.assign(new Error('A cosmetic can have at most 120 animation frames'), { status: 400 });
    let objectCount = 0;
    def.frames = def.frames.map(frame => {
        const objects = Array.isArray(frame?.objects) ? frame.objects : [];
        objectCount += objects.length;
        return {
            duration: Math.max(40, Math.min(5000, Number(frame?.duration || 250))),
            objects: objects.map(obj => ({
                id: String(obj?.id || '').slice(0, 60),
                type: ['pixel', 'rect', 'ellipse', 'line'].includes(String(obj?.type)) ? String(obj.type) : 'rect',
                x: Number(obj?.x || 0), y: Number(obj?.y || 0),
                w: Number(obj?.w ?? 1), h: Number(obj?.h ?? 1),
                rotation: Math.max(-3600, Math.min(3600, Number(obj?.rotation || 0))),
                opacity: Math.max(0, Math.min(1, Number(obj?.opacity ?? 1))),
                stroke_width: Math.max(1, Math.min(64, Number(obj?.stroke_width || 1))),
                color: /^#[0-9a-f]{6}$/i.test(String(obj?.color || '')) ? String(obj.color) : '#ffffff',
                hidden: Boolean(obj?.hidden)
            }))
        };
    });
    if (objectCount > 15000)
        throw Object.assign(new Error('This cosmetic has too many objects'), { status: 400 });
    const raw = JSON.stringify(def);
    if (raw.length > 600000)
        throw Object.assign(new Error('Cosmetic definition is too large'), { status: 413 });
    return { definition: def, raw };
}

async function getLoadout(env, userId) {
    const row = await env.DB.prepare(`SELECT avatar_decoration_id, profile_effect_id, nameplate_id, updated_at
    FROM user_profile_cosmetic_loadout WHERE user_id = ?`).bind(userId).first();
    return row || { avatar_decoration_id: null, profile_effect_id: null, nameplate_id: null, updated_at: 0 };
}

async function readDiamondBalance(env, userId) {
    const row = await env.DB.prepare('SELECT COALESCE(diamonds, 0) AS diamonds FROM users WHERE id = ?').bind(userId).first();
    if (!row)
        throw Object.assign(new Error('User not found'), { status: 404 });
    return Number(row.diamonds || 0);
}

async function debitDiamonds(env, userId, amount) {
    const result = await env.DB.prepare(`UPDATE users SET diamonds = COALESCE(diamonds,0) - ?
    WHERE id = ? AND COALESCE(diamonds,0) >= ?`).bind(amount, userId, amount).run();
    if (!Number(result?.meta?.changes || 0))
        throw Object.assign(new Error('Not enough Diamonds'), { status: 400 });
}

async function refundDiamonds(env, userId, amount) {
    if (amount <= 0)
        return;
    await env.DB.prepare('UPDATE users SET diamonds = COALESCE(diamonds,0) + ? WHERE id = ?').bind(amount, userId).run();
}

async function handleStatusRoutes(request, env, user, url) {
    const method = request.method.toUpperCase();
    if (url.pathname === '/api/status') {
        const me = obRequireUser(user);
        if (method === 'GET') {
            const row = await env.DB.prepare('SELECT user_id, status_text AS text, expires_at, updated_at FROM user_profile_statuses WHERE user_id = ?').bind(me.id).first();
            if (row && row.expires_at && Number(row.expires_at) <= obNow()) {
                await env.DB.prepare('DELETE FROM user_profile_statuses WHERE user_id = ?').bind(me.id).run();
                return obJson({ status: null });
            }
            return obJson({ status: row || null });
        }
        if (method === 'PUT') {
            const body = await obReadJson(request);
            const text = String(body.text || '').trim();
            if (!text)
                throw Object.assign(new Error('Status cannot be empty'), { status: 400 });
            if (text.length > 180)
                throw Object.assign(new Error('Status must be 180 characters or less'), { status: 400 });
            let expiresAt = body.expires_at == null ? null : Number(body.expires_at);
            if (expiresAt != null && (!Number.isFinite(expiresAt) || expiresAt <= obNow()))
                throw Object.assign(new Error('Choose a future expiration time'), { status: 400 });
            const t = obNow();
            await env.DB.prepare(`INSERT INTO user_profile_statuses (user_id,status_text,expires_at,created_at,updated_at)
        VALUES (?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET status_text=excluded.status_text, expires_at=excluded.expires_at, updated_at=excluded.updated_at`)
                .bind(me.id, text, expiresAt, t, t).run();
            return obJson({ status: { user_id: me.id, text, expires_at: expiresAt, updated_at: t } });
        }
        if (method === 'DELETE') {
            await env.DB.prepare('DELETE FROM user_profile_statuses WHERE user_id = ?').bind(me.id).run();
            return obJson({ ok: true });
        }
        return obJson({ error: 'Method not allowed' }, 405);
    }
    const match = url.pathname.match(/^\/api\/status\/([^/]+)$/);
    if (match && method === 'GET') {
        const targetId = decodeURIComponent(match[1]);
        const row = await env.DB.prepare('SELECT user_id, status_text AS text, expires_at, updated_at FROM user_profile_statuses WHERE user_id = ?').bind(targetId).first();
        if (row && row.expires_at && Number(row.expires_at) <= obNow()) {
            await env.DB.prepare('DELETE FROM user_profile_statuses WHERE user_id = ?').bind(targetId).run();
            return obJson({ status: null });
        }
        return obJson({ status: row || null });
    }
    return null;
}

async function handlePublicCosmeticRoutes(request, env, user, url) {
    const method = request.method.toUpperCase();
    if (url.pathname === '/api/cosmetics/catalog' && method === 'GET') {
        const result = await env.DB.prepare(`SELECT * FROM profile_cosmetics WHERE published = 1 AND archived_at IS NULL ORDER BY updated_at DESC`).all();
        return obJson({ catalog: (result.results || []).map(parseCosmeticRow) });
    }
    if (url.pathname === '/api/cosmetics/loadouts' && method === 'GET') {
        const ids = [...new Set(String(url.searchParams.get('ids') || '').split(',').map(x => x.trim()).filter(Boolean))].slice(0, 100);
        if (!ids.length)
            return obJson({ loadouts: {} });
        const placeholders = ids.map(() => '?').join(',');
        const result = await env.DB.prepare(`SELECT user_id, avatar_decoration_id, profile_effect_id, nameplate_id, updated_at
      FROM user_profile_cosmetic_loadout WHERE user_id IN (${placeholders})`).bind(...ids).all();
        const map = Object.fromEntries(ids.map(id => [id, { avatar_decoration_id: null, profile_effect_id: null, nameplate_id: null, updated_at: 0 }]));
        for (const row of result.results || [])
            map[row.user_id] = row;
        return obJson({ loadouts: map });
    }
    if (url.pathname === '/api/cosmetics/me' && method === 'GET') {
        const me = obRequireUser(user);
        const [balance, catalogResult, ownedResult, loadout] = await Promise.all([
            readDiamondBalance(env, me.id),
            env.DB.prepare(`SELECT * FROM profile_cosmetics WHERE published = 1 AND archived_at IS NULL ORDER BY updated_at DESC`).all(),
            env.DB.prepare('SELECT cosmetic_id AS id, purchased_at FROM user_profile_cosmetics WHERE user_id = ? ORDER BY purchased_at DESC').bind(me.id).all(),
            getLoadout(env, me.id)
        ]);
        return obJson({ balance, catalog: (catalogResult.results || []).map(parseCosmeticRow), owned: ownedResult.results || [], loadout });
    }
    if (url.pathname === '/api/cosmetics/purchase' && method === 'POST') {
        const me = obRequireUser(user);
        const body = await obReadJson(request);
        const id = String(body.id || '');
        const productRow = await env.DB.prepare('SELECT * FROM profile_cosmetics WHERE id = ? AND published = 1 AND archived_at IS NULL').bind(id).first();
        if (!productRow)
            throw Object.assign(new Error('Cosmetic is not available'), { status: 404 });
        const existing = await env.DB.prepare('SELECT 1 AS owned FROM user_profile_cosmetics WHERE user_id = ? AND cosmetic_id = ?').bind(me.id, id).first();
        if (existing)
            throw Object.assign(new Error('You already own this cosmetic'), { status: 409 });
        const price = Math.max(0, Number(productRow.price || 0));
        await debitDiamonds(env, me.id, price);
        try {
            await env.DB.prepare('INSERT INTO user_profile_cosmetics (user_id,cosmetic_id,purchased_at) VALUES (?,?,?)').bind(me.id, id, obNow()).run();
            const col = productRow.type === 'avatar_decoration' ? 'avatar_decoration_id' : productRow.type === 'profile_effect' ? 'profile_effect_id' : 'nameplate_id';
            await env.DB.prepare(`INSERT INTO user_profile_cosmetic_loadout (user_id,${col},updated_at) VALUES (?,?,?)
        ON CONFLICT(user_id) DO UPDATE SET ${col}=excluded.${col}, updated_at=excluded.updated_at`).bind(me.id, id, obNow()).run();
        }
        catch (error) {
            await refundDiamonds(env, me.id, price);
            throw error;
        }
        return obJson({ ok: true, balance: await readDiamondBalance(env, me.id), loadout: await getLoadout(env, me.id), cosmetic: parseCosmeticRow(productRow) });
    }
    if (url.pathname === '/api/cosmetics/equip' && method === 'PUT') {
        const me = obRequireUser(user);
        const body = await obReadJson(request);
        const type = String(body.type || '');
        if (!ORBYTE_COSMETIC_TYPES.has(type))
            throw Object.assign(new Error('Invalid cosmetic type'), { status: 400 });
        const id = body.id == null || body.id === '' ? null : String(body.id);
        if (id) {
            const owned = await env.DB.prepare(`SELECT c.id FROM profile_cosmetics c JOIN user_profile_cosmetics o ON o.cosmetic_id=c.id
        WHERE o.user_id=? AND c.id=? AND c.type=? AND c.archived_at IS NULL`).bind(me.id, id, type).first();
            if (!owned)
                throw Object.assign(new Error('You do not own that cosmetic'), { status: 403 });
        }
        const col = type === 'avatar_decoration' ? 'avatar_decoration_id' : type === 'profile_effect' ? 'profile_effect_id' : 'nameplate_id';
        await env.DB.prepare(`INSERT INTO user_profile_cosmetic_loadout (user_id,${col},updated_at) VALUES (?,?,?)
      ON CONFLICT(user_id) DO UPDATE SET ${col}=excluded.${col}, updated_at=excluded.updated_at`).bind(me.id, id, obNow()).run();
        return obJson({ ok: true, loadout: await getLoadout(env, me.id) });
    }
    return null;
}

async function handleAdminCosmeticRoutes(request, env, user, url) {
    const method = request.method.toUpperCase();
    if (!url.pathname.startsWith('/api/admin/cosmetics'))
        return null;
    const admin = obRequireAdmin(user);
    if (url.pathname === '/api/admin/cosmetics' && method === 'GET') {
        const result = await env.DB.prepare('SELECT * FROM profile_cosmetics ORDER BY updated_at DESC').all();
        return obJson({ cosmetics: (result.results || []).map(parseCosmeticRow) });
    }
    if (url.pathname === '/api/admin/cosmetics' && method === 'POST') {
        const body = await obReadJson(request);
        const type = String(body.type || '');
        const name = String(body.name || '').trim().slice(0, 50);
        if (!name)
            throw Object.assign(new Error('Cosmetic name is required'), { status: 400 });
        const { raw } = validateDefinition(type, body.definition);
        const id = obId('cos');
        const t = obNow();
        await env.DB.prepare(`INSERT INTO profile_cosmetics
      (id,type,name,description,price,rarity,definition_json,published,created_by,created_at,updated_at)
      VALUES (?,?,?,?,?,?,?,?,?,?,?)`).bind(id, type, name, String(body.description || '').trim().slice(0, 240), Math.max(0, Math.min(100000, Math.floor(Number(body.price || 0)))), String(body.rarity || 'standard').slice(0, 30), raw, body.published === false ? 0 : 1, admin.id, t, t).run();
        return obJson({ cosmetic: parseCosmeticRow(await env.DB.prepare('SELECT * FROM profile_cosmetics WHERE id=?').bind(id).first()) }, 201);
    }
    const match = url.pathname.match(/^\/api\/admin\/cosmetics\/([^/]+)$/);
    if (!match)
        return obJson({ error: 'Not found' }, 404);
    const id = decodeURIComponent(match[1]);
    const current = await env.DB.prepare('SELECT * FROM profile_cosmetics WHERE id=?').bind(id).first();
    if (!current)
        return obJson({ error: 'Cosmetic not found' }, 404);
    if (method === 'PUT' || method === 'PATCH') {
        const body = await obReadJson(request);
        const type = String(body.type || current.type);
        const name = String(body.name ?? current.name).trim().slice(0, 50);
        if (!name)
            throw Object.assign(new Error('Cosmetic name is required'), { status: 400 });
        const sourceDefinition = body.definition ?? (() => { try {
            return JSON.parse(current.definition_json);
        }
        catch {
            return {};
        } })();
        const { raw } = validateDefinition(type, sourceDefinition);
        const t = obNow();
        await env.DB.prepare(`UPDATE profile_cosmetics SET type=?,name=?,description=?,price=?,rarity=?,definition_json=?,published=?,updated_at=? WHERE id=?`).bind(type, name, String(body.description ?? current.description ?? '').trim().slice(0, 240), Math.max(0, Math.min(100000, Math.floor(Number(body.price ?? current.price ?? 0)))), String(body.rarity ?? current.rarity ?? 'standard').slice(0, 30), raw, body.published == null ? Number(current.published || 0) : (body.published ? 1 : 0), t, id).run();
        return obJson({ cosmetic: parseCosmeticRow(await env.DB.prepare('SELECT * FROM profile_cosmetics WHERE id=?').bind(id).first()) });
    }
    if (method === 'DELETE') {
        await env.DB.prepare('UPDATE profile_cosmetics SET published=0, archived_at=?, updated_at=? WHERE id=?').bind(obNow(), obNow(), id).run();
        return obJson({ ok: true });
    }
    return obJson({ error: 'Method not allowed' }, 405);
}

async function handleOrbyteProfileFeatures(request, env, user = null) {
    try {
        const url = new URL(request.url);
        const relevant = url.pathname === '/api/status' || url.pathname.startsWith('/api/status/') || url.pathname.startsWith('/api/cosmetics/') || url.pathname.startsWith('/api/admin/cosmetics');
        if (!relevant)
            return null;
        if (request.method.toUpperCase() === 'OPTIONS') {
            return new Response(null, { status: 204, headers: obCorsHeaders() });
        }
        await ensureOrbyteProfileFeatureSchema(env);
        let response = await handleAdminCosmeticRoutes(request, env, user, url);
        if (response)
            return response;
        response = await handleStatusRoutes(request, env, user, url);
        if (response)
            return response;
        response = await handlePublicCosmeticRoutes(request, env, user, url);
        if (response)
            return response;
        return null;
    }
    catch (error) {
        console.error('[Orbyte profile features]', error);
        return obJson({ error: error?.message || 'Request failed' }, Number(error?.status || 500));
    }
}

const OAUTH_ACCESS_TTL_MS = 60 * 60 * 1000;

const OAUTH_SUPPORT_ARTICLE_ID = 'art_oauth2_developer_guide';

const OAUTH_SUPPORT_ARTICLE_SLUG = 'oauth2-app-authorization';

const OAUTH_SCOPE_DEFS = Object.freeze({
    'identify': { label: 'View your identity', description: 'Read your Orbyte ID, username, display name, avatar, banner, and public profile information.', risk: 'low' },
    'servers.read': { label: 'See your servers', description: 'Read the servers you belong to and your basic membership and role information.', risk: 'medium' },
    'dm.send': { label: 'Send you direct messages', description: 'Send direct messages to you as this application’s Orbyte bot.', risk: 'medium' },
    'servers.join': { label: 'Join servers for you', description: 'Join your account to servers where this application’s bot is already installed.', risk: 'high' },
    'activity.write': { label: 'Set your activity status', description: 'Set or clear the activity shown on your Orbyte profile.', risk: 'high' },
    'dm.commands': { label: 'Add commands to your DMs', description: 'Make this bot’s enabled slash commands available in your direct messages.', risk: 'medium' },
});

const OAUTH_SUPPORT_MARKDOWN = "# OAuth2 apps and authorization\n\nOrbyte OAuth2 lets a website or service connect to an Orbyte account **without receiving the user's password or normal Orbyte session token**.\n\nAn OAuth app is attached to an Orbyte bot application. The app uses its Client ID and Client Secret to exchange a short-lived authorization code for OAuth access and refresh tokens. Access is limited to the permissions (scopes) that the developer configured and the user approved.\n\n## Before you start\n\nCreate a bot in **Settings → Developer Portal**. Open the bot and find **OAuth2 & Authorization**.\n\nYou will need:\n\n- **Client ID** — the bot application ID. This is public.\n- **Client Secret** — a private credential for your backend. It is shown only when generated or reset.\n- **Redirect URI** — an exact URL on your service where Orbyte sends the user after authorization.\n- **Scopes** — the permissions your app is allowed to request.\n\nNever place your Client Secret in browser JavaScript, a public repository, a mobile app bundle, or any other code users can inspect.\n\n## Available scopes\n\n| Scope | What it allows |\n| --- | --- |\n| `identify` | Read the authorized user's ID, username, display name, avatar, banner, and public profile information. |\n| `servers.read` | Read the servers the authorized user belongs to and their basic membership/role information. |\n| `dm.send` | Send a direct message to the authorized user as your Orbyte bot. |\n| `servers.join` | Join the authorized user to a server where your bot is already installed. Server bans and server join requirements still apply. |\n| `activity.write` | Set or clear the authorized user's activity status. |\n| `dm.commands` | Make your bot's enabled slash commands available in the user's DMs. |\n\nRequest only the permissions your app genuinely needs.\n\n## 1. Configure your application\n\nIn the Developer Portal:\n\n1. Open your bot.\n2. Open **OAuth2 & Authorization**.\n3. Generate a Client Secret and store it securely.\n4. Add one or more Redirect URIs.\n5. Select the permissions your application may request.\n6. Enable OAuth2 and save.\n\nRedirect URIs are matched exactly. Production redirect URIs must use HTTPS. For local development, `http://localhost` and `http://127.0.0.1` are accepted.\n\n## 2. Send the user to Orbyte\n\nOpen this URL in the user's browser:\n\n```text\nhttps://orbytechat.pages.dev/oauth2/authorize\n  ?client_id=YOUR_CLIENT_ID\n  &redirect_uri=https%3A%2F%2Fexample.com%2Forbyte%2Fcallback\n  &response_type=code\n  &scope=identify%20servers.read\n  &state=RANDOM_VALUE\n```\n\nParameters:\n\n- `client_id` — your Client ID.\n- `redirect_uri` — one of your registered Redirect URIs.\n- `response_type` — currently must be `code`.\n- `scope` — a space-separated list of scopes.\n- `state` — a random value created by your app. Store it before redirecting the user and verify it when they return.\n- `code_challenge` — optional PKCE S256 challenge.\n- `code_challenge_method` — use `S256` when a challenge is supplied.\n\nOrbyte shows the user your app name/avatar and every requested permission. Nothing is granted until the user chooses **Authorize**.\n\nIf authorization succeeds, Orbyte redirects to:\n\n```text\nhttps://example.com/orbyte/callback?code=orb_code_...&state=RANDOM_VALUE\n```\n\nIf the user denies access, the callback receives `error=access_denied`.\n\nAuthorization codes expire after **10 minutes**, are single-use, and are bound to the Client ID, exact Redirect URI, scopes, and PKCE challenge used during authorization.\n\n## 3. Exchange the code for tokens\n\nDo this from your **server**, not from frontend JavaScript.\n\n```bash\ncurl -X POST https://chat.kyrylo89.workers.dev/api/oauth2/token \\\n  -H \"Content-Type: application/x-www-form-urlencoded\" \\\n  -d \"grant_type=authorization_code\" \\\n  -d \"client_id=YOUR_CLIENT_ID\" \\\n  -d \"client_secret=YOUR_CLIENT_SECRET\" \\\n  -d \"code=CODE_FROM_CALLBACK\" \\\n  -d \"redirect_uri=https://example.com/orbyte/callback\"\n```\n\nIf you used PKCE, also send:\n\n```text\ncode_verifier=THE_ORIGINAL_CODE_VERIFIER\n```\n\nExample response:\n\n```json\n{\n  \"access_token\": \"orb_oauth_...\",\n  \"token_type\": \"Bearer\",\n  \"expires_in\": 3600,\n  \"refresh_token\": \"orb_refresh_...\",\n  \"scope\": \"identify servers.read\"\n}\n```\n\nAccess tokens last **1 hour**. Refresh tokens last **30 days**.\n\n## 4. Call the OAuth API\n\nSend the OAuth access token as a Bearer token:\n\n```http\nAuthorization: Bearer orb_oauth_...\n```\n\nOAuth access tokens are different from bot tokens and normal Orbyte login/session tokens.\n\n### Get the authorized user\n\nRequires `identify`.\n\n```bash\ncurl https://chat.kyrylo89.workers.dev/api/oauth2/users/@me \\\n  -H \"Authorization: Bearer YOUR_ACCESS_TOKEN\"\n```\n\nExample:\n\n```json\n{\n  \"user\": {\n    \"id\": \"usr_...\",\n    \"username\": \"example\",\n    \"display_name\": \"Example\",\n    \"avatar_url\": \"/media/...\"\n  }\n}\n```\n\nOrbyte OAuth does not give applications the user's password or email address.\n\n### Read the user's servers\n\nRequires `servers.read`.\n\n```bash\ncurl https://chat.kyrylo89.workers.dev/api/oauth2/users/@me/servers \\\n  -H \"Authorization: Bearer YOUR_ACCESS_TOKEN\"\n```\n\nThe response contains servers the user currently belongs to plus basic membership information.\n\n### Send a DM as your bot\n\nRequires `dm.send`.\n\n```bash\ncurl -X POST https://chat.kyrylo89.workers.dev/api/oauth2/users/@me/dm \\\n  -H \"Authorization: Bearer YOUR_ACCESS_TOKEN\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"content\":\"Thanks for connecting your Orbyte account!\"}'\n```\n\nThe message is sent **from the bot attached to your OAuth application**, not from the user.\n\n### Join a server for the user\n\nRequires `servers.join`.\n\n```bash\ncurl -X PUT https://chat.kyrylo89.workers.dev/api/oauth2/users/@me/servers/SERVER_ID \\\n  -H \"Authorization: Bearer YOUR_ACCESS_TOKEN\"\n```\n\nYour bot must already be installed in the target server. Orbyte still enforces server bans, minimum account age, verified-email requirements, account restrictions, and other safety rules.\n\n### Set the user's activity\n\nRequires `activity.write`.\n\n```bash\ncurl -X PUT https://chat.kyrylo89.workers.dev/api/oauth2/users/@me/activity \\\n  -H \"Authorization: Bearer YOUR_ACCESS_TOKEN\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{\"type\":\"playing\",\"name\":\"Example Game\"}'\n```\n\nSupported activity types are `playing`, `listening`, `watching`, and `custom`.\n\nActivity is intentionally short-lived. Apps that want a continuously visible activity should refresh it periodically.\n\nClear it with:\n\n```bash\ncurl -X DELETE https://chat.kyrylo89.workers.dev/api/oauth2/users/@me/activity \\\n  -H \"Authorization: Bearer YOUR_ACCESS_TOKEN\"\n```\n\n## 5. Refresh an access token\n\n```bash\ncurl -X POST https://chat.kyrylo89.workers.dev/api/oauth2/token \\\n  -H \"Content-Type: application/x-www-form-urlencoded\" \\\n  -d \"grant_type=refresh_token\" \\\n  -d \"client_id=YOUR_CLIENT_ID\" \\\n  -d \"client_secret=YOUR_CLIENT_SECRET\" \\\n  -d \"refresh_token=YOUR_REFRESH_TOKEN\"\n```\n\nRefresh tokens are rotated. Save the new refresh token returned by Orbyte and discard the old one.\n\n## 6. Revoke access\n\nYour service can revoke a token:\n\n```bash\ncurl -X POST https://chat.kyrylo89.workers.dev/api/oauth2/revoke \\\n  -H \"Content-Type: application/x-www-form-urlencoded\" \\\n  -d \"client_id=YOUR_CLIENT_ID\" \\\n  -d \"client_secret=YOUR_CLIENT_SECRET\" \\\n  -d \"token=TOKEN_TO_REVOKE\"\n```\n\nUsers can also revoke the application from **Settings → Apps & bots**. Removing an authorized app invalidates its OAuth access and refresh tokens.\n\n## PKCE\n\nOrbyte supports PKCE with SHA-256 (`S256`).\n\nCreate a random `code_verifier`, then send:\n\n```text\ncode_challenge = BASE64URL(SHA256(code_verifier))\ncode_challenge_method = S256\n```\n\nKeep the verifier until token exchange and send it as `code_verifier`.\n\nPKCE protects authorization codes if a redirect is intercepted. In the current Orbyte OAuth flow, confidential applications still authenticate the token exchange with their Client Secret as well.\n\n## Security checklist\n\n- Keep the Client Secret on your server only.\n- Use HTTPS for production callbacks.\n- Use an unpredictable `state` value and verify it after redirect.\n- Prefer PKCE.\n- Register the smallest possible set of Redirect URIs.\n- Ask only for scopes you need.\n- Never log access tokens, refresh tokens, Client Secrets, or authorization codes.\n- Encrypt tokens at rest when possible.\n- Treat `servers.join` and `activity.write` as powerful permissions.\n- Revoke tokens when a user disconnects Orbyte from your service.\n- Never ask a user to paste their normal Orbyte login token into your app.\n\n## Common errors\n\n- `invalid_client` — Client ID/Secret is wrong, OAuth is disabled, or the application no longer exists.\n- `invalid_redirect_uri` — the Redirect URI does not exactly match a registered URI.\n- `invalid_scope` — your authorization URL requested a permission the application owner did not enable.\n- `invalid_grant` — the authorization code/refresh token is invalid, expired, already used, revoked, or the PKCE verifier is wrong.\n- `insufficient_scope` — the access token does not include the permission required by that API endpoint.\n- `access_denied` — the user denied authorization or revoked the app.\n\n## Bot token vs OAuth token\n\nA **bot token** represents your bot and is used with the Bot Gateway.\n\nAn **OAuth access token** represents one user's authorization for one app, limited to approved scopes.\n\nDo not interchange them. A bot token must never be sent to users, and an OAuth token must never be treated as a normal Orbyte account session.\n\n## Need help?\n\nYou can test authorization URLs directly from the Developer Portal. If an OAuth request fails, first check the Client ID, exact Redirect URI, selected scopes, and whether OAuth2 is enabled.\n";

function oauthScopeInfo(scopes) {
    return scopes.map(scope => ({ scope, ...OAUTH_SCOPE_DEFS[scope] })).filter(item => item.label);
}

function parseOAuthScopes(value) {
    if (Array.isArray(value))
        return normalizeOAuthScopes(value);
    try {
        return normalizeOAuthScopes(JSON.parse(String(value || '[]')));
    }
    catch {
        return [];
    }
}

function normalizeOAuthScopes(value) {
    const raw = Array.isArray(value) ? value : String(value || '').split(/\s+/);
    return [...new Set(raw.map(v => String(v || '').trim()).filter(v => Object.prototype.hasOwnProperty.call(OAUTH_SCOPE_DEFS, v)))];
}

function oauthScopesFromInstallFlags(row) {
    const scopes = [];
    if (Number(row?.view_profile || 0))
        scopes.push('identify');
    if (Number(row?.servers_read || 0))
        scopes.push('servers.read');
    if (Number(row?.dm_send || 0))
        scopes.push('dm.send');
    if (Number(row?.join_servers || 0))
        scopes.push('servers.join');
    if (Number(row?.activity_write || 0))
        scopes.push('activity.write');
    if (Number(row?.dm_commands || 0))
        scopes.push('dm.commands');
    return scopes;
}

function oauthInstallFlags(scopes) {
    const set = new Set(normalizeOAuthScopes(scopes));
    return {
        view_profile: set.has('identify') ? 1 : 0,
        servers_read: set.has('servers.read') ? 1 : 0,
        dm_send: set.has('dm.send') ? 1 : 0,
        join_servers: set.has('servers.join') ? 1 : 0,
        activity_write: set.has('activity.write') ? 1 : 0,
        dm_commands: set.has('dm.commands') ? 1 : 0,
    };
}

function safeJsonArray(value) {
    try {
        const parsed = JSON.parse(String(value || '[]'));
        return Array.isArray(parsed) ? parsed : [];
    }
    catch {
        return [];
    }
}

function oauthRedirectUriAllowed(value) {
    const raw = String(value || '').trim();
    if (!raw || raw.length > 1000)
        return false;
    try {
        const url = new URL(raw);
        if (url.username || url.password || url.hash)
            return false;
        if (url.protocol === 'https:')
            return true;
        return url.protocol === 'http:' && ['localhost', '127.0.0.1', '[::1]'].includes(url.hostname);
    }
    catch {
        return false;
    }
}

function normalizeOAuthRedirectUris(values) {
    const list = Array.isArray(values) ? values : String(values || '').split(/\r?\n/);
    const out = [];
    for (const raw of list) {
        const value = String(raw || '').trim();
        if (!value)
            continue;
        if (!oauthRedirectUriAllowed(value))
            throw Object.assign(new Error('Redirect URIs must use HTTPS. HTTP is allowed only for localhost/127.0.0.1.'), { status: 400, code: 'invalid_redirect_uri' });
        if (!out.includes(value))
            out.push(value);
        if (out.length >= 10)
            break;
    }
    return out;
}

function oauthError(error, status = 400, code = 'invalid_request', extra = {}) {
    return json({ error: code, error_description: String(error || 'OAuth request failed'), ...extra }, status);
}

function oauthRedirectWithParams(redirectUri, params) {
    const out = new URL(redirectUri);
    for (const [key, value] of Object.entries(params || {})) {
        if (value !== undefined && value !== null && String(value) !== '')
            out.searchParams.set(key, String(value));
    }
    return out.toString();
}

async function ensureOAuthSupportArticle(db) {
    await ensureSystemAccount(db);
    const existing = await db.prepare('SELECT id FROM support_articles WHERE id=? OR lower(slug)=lower(?) LIMIT 1').bind(OAUTH_SUPPORT_ARTICLE_ID, OAUTH_SUPPORT_ARTICLE_SLUG).first();
    if (existing)
        return;
    const now = Date.now();
    await db.prepare(`INSERT INTO support_articles(id,slug,title,summary,markdown,category,tags_json,cover_url,status,author_id,created_at,updated_at,published_at)
    VALUES(?,?,?,?,?,?,?,'','published',?,?,?,?)`)
        .bind(OAUTH_SUPPORT_ARTICLE_ID, OAUTH_SUPPORT_ARTICLE_SLUG, 'OAuth2 apps and authorization', 'Connect websites and services to Orbyte accounts safely with authorization codes, scoped tokens, bot DMs, server joins, and activity status.', OAUTH_SUPPORT_MARKDOWN, 'Developers', JSON.stringify(['oauth', 'oauth2', 'developers', 'bots', 'api']), SYSTEM_USER_ID, now, now, now).run();
}

async function getOAuthApp(env, clientId) {
    return env.DB.prepare(`SELECT b.*,u.avatar_url,u.banner_image_url,u.username AS bot_username,u.display_name AS bot_display_name
    FROM bot_applications b JOIN users u ON u.id=b.bot_user_id WHERE b.id=? LIMIT 1`).bind(String(clientId || '')).first();
}

function publicOAuthApp(row) {
    return {
        id: String(row.id), client_id: String(row.id), name: row.name || row.bot_display_name || 'Orbyte App',
        description: row.description || '', avatar_url: row.avatar_url || '', bot_user_id: row.bot_user_id,
        oauth_enabled: Boolean(Number(row.oauth_enabled || 0))
    };
}

function oauthRequestFrom(input) {
    const get = name => input instanceof URLSearchParams ? input.get(name) : input?.[name];
    const clientId = String(get('client_id') || '').trim();
    const redirectUri = String(get('redirect_uri') || '').trim();
    const responseType = String(get('response_type') || 'code').trim();
    const requestedScopes = [...new Set(String(get('scope') || '').split(/\s+/).map(v => v.trim()).filter(Boolean))];
    const scopes = normalizeOAuthScopes(requestedScopes);
    const unknownScopes = requestedScopes.filter(scope => !Object.prototype.hasOwnProperty.call(OAUTH_SCOPE_DEFS, scope));
    const state = String(get('state') || '').slice(0, 1000);
    const challenge = String(get('code_challenge') || '').trim().slice(0, 256);
    const method = String(get('code_challenge_method') || '').trim().toUpperCase();
    return { clientId, redirectUri, responseType, scopes, unknownScopes, state, challenge, method };
}

async function validateOAuthAuthorizeRequest(env, input) {
    const req = oauthRequestFrom(input);
    if (!req.clientId)
        return { error: oauthError('client_id is required', 400, 'invalid_request') };
    const app = await getOAuthApp(env, req.clientId);
    if (!app || !Number(app.oauth_enabled || 0))
        return { error: oauthError('OAuth is not enabled for this application', 400, 'invalid_client') };
    if (!app.oauth_secret_hash)
        return { error: oauthError('This application has not configured a Client Secret yet', 400, 'invalid_client') };
    if (req.responseType !== 'code')
        return { error: oauthError('Only response_type=code is supported', 400, 'unsupported_response_type') };
    if (req.unknownScopes.length)
        return { error: oauthError(`Unknown scope: ${req.unknownScopes[0]}`, 400, 'invalid_scope', { invalid_scopes: req.unknownScopes }) };
    const redirects = safeJsonArray(app.oauth_redirect_uris_json).map(String);
    if (!req.redirectUri || !redirects.includes(req.redirectUri))
        return { error: oauthError('redirect_uri does not exactly match a registered URI', 400, 'invalid_redirect_uri') };
    if (!req.scopes.length)
        return { error: oauthError('At least one scope is required', 400, 'invalid_scope') };
    const allowed = new Set(parseOAuthScopes(app.oauth_allowed_scopes_json));
    const denied = req.scopes.filter(scope => !allowed.has(scope));
    if (denied.length)
        return { error: oauthError(`The application is not allowed to request: ${denied.join(', ')}`, 400, 'invalid_scope', { invalid_scopes: denied }) };
    if (req.challenge) {
        if (req.method !== 'S256')
            return { error: oauthError('Only PKCE code_challenge_method=S256 is supported', 400, 'invalid_request') };
        if (!/^[A-Za-z0-9_-]{43,128}$/.test(req.challenge))
            return { error: oauthError('Invalid PKCE code_challenge', 400, 'invalid_request') };
    }
    else if (req.method) {
        return { error: oauthError('code_challenge_method requires code_challenge', 400, 'invalid_request') };
    }
    return { app, req };
}

async function oauthAuthorizePreview(env, url) {
    const validated = await validateOAuthAuthorizeRequest(env, url.searchParams);
    if (validated.error)
        return validated.error;
    const { app, req } = validated;
    return json({
        app: publicOAuthApp(app),
        redirect_uri: req.redirectUri,
        state: req.state,
        scopes: req.scopes,
        permissions: oauthScopeInfo(req.scopes),
        pkce: Boolean(req.challenge),
        response_type: 'code'
    }, 200, { 'Cache-Control': 'no-store' });
}

async function oauthAuthorizeDecision(request, env, user) {
    const body = await readJson(request);
    if (!body)
        return oauthError('Invalid JSON', 400, 'invalid_request');
    const validated = await validateOAuthAuthorizeRequest(env, body);
    if (validated.error)
        return validated.error;
    const { app, req } = validated;
    if (body.approve === false) {
        return json({ ok: false, approved: false, redirect_url: oauthRedirectWithParams(req.redirectUri, { error: 'access_denied', error_description: 'The user denied access', state: req.state }) });
    }
    const code = `orb_code_${randomBase64Url(32)}`, now = Date.now(), flags = oauthInstallFlags(req.scopes);
    await env.DB.batch([
        env.DB.prepare(`INSERT INTO oauth_authorization_codes(code_hash,app_id,user_id,redirect_uri,scopes_json,code_challenge,code_challenge_method,expires_at,used_at,created_at)
      VALUES(?,?,?,?,?,?,?,?,NULL,?)`).bind(await sha256(code), app.id, user.id, req.redirectUri, JSON.stringify(req.scopes), req.challenge || '', req.method || '', now + 10 * 60 * 1000, now),
        env.DB.prepare(`INSERT INTO account_bot_installs(user_id,bot_id,view_profile,join_servers,dm_commands,dm_send,servers_read,activity_write,oauth_scopes_json,authorized_via_oauth,enabled,added_at,updated_at)
      VALUES(?,?,?,?,?,?,?,?,?,1,1,?,?)
      ON CONFLICT(user_id,bot_id) DO UPDATE SET view_profile=excluded.view_profile,join_servers=excluded.join_servers,dm_commands=excluded.dm_commands,
      dm_send=excluded.dm_send,servers_read=excluded.servers_read,activity_write=excluded.activity_write,oauth_scopes_json=excluded.oauth_scopes_json,
      authorized_via_oauth=1,enabled=1,updated_at=excluded.updated_at`)
            .bind(user.id, app.id, flags.view_profile, flags.join_servers, flags.dm_commands, flags.dm_send, flags.servers_read, flags.activity_write, JSON.stringify(req.scopes), now, now)
    ]);
    return json({ ok: true, approved: true, redirect_url: oauthRedirectWithParams(req.redirectUri, { code, state: req.state }) });
}

async function readOAuthBody(request) {
    const type = String(request.headers.get('Content-Type') || '').toLowerCase();
    if (type.includes('application/x-www-form-urlencoded')) {
        const params = new URLSearchParams(await request.text());
        return Object.fromEntries(params.entries());
    }
    if (type.includes('application/json'))
        return await request.json().catch(() => ({}));
    const raw = await request.text();
    try {
        return JSON.parse(raw);
    }
    catch {
        return Object.fromEntries(new URLSearchParams(raw).entries());
    }
}

function decodeBasicOAuth(request) {
    const auth = String(request.headers.get('Authorization') || '');
    if (!/^Basic\s+/i.test(auth))
        return null;
    try {
        const decoded = atob(auth.replace(/^Basic\s+/i, ''));
        const split = decoded.indexOf(':');
        if (split < 0)
            return null;
        return { client_id: decoded.slice(0, split), client_secret: decoded.slice(split + 1) };
    }
    catch {
        return null;
    }
}

async function verifyOAuthClient(env, request, body) {
    const basic = decodeBasicOAuth(request);
    const clientId = String(basic?.client_id || body?.client_id || '').trim();
    const secret = String(basic?.client_secret || body?.client_secret || '');
    if (!clientId || !secret)
        return null;
    const app = await getOAuthApp(env, clientId);
    if (!app || !Number(app.oauth_enabled || 0) || !app.oauth_secret_hash)
        return null;
    if (!timingSafeEqual(await sha256(secret), String(app.oauth_secret_hash)))
        return null;
    return app;
}

async function pkceS256(verifier) {
    const digest = await crypto.subtle.digest('SHA-256', encoder.encode(String(verifier || '')));
    return bytesToBase64Url(digest);
}

async function issueOAuthTokens(db, appId, userId, scopes) {
    const access = `orb_oauth_${randomBase64Url(36)}`, refresh = `orb_refresh_${randomBase64Url(42)}`, now = Date.now();
    await db.batch([
        db.prepare(`INSERT INTO oauth_access_tokens(token_hash,app_id,user_id,scopes_json,expires_at,created_at,revoked_at) VALUES(?,?,?,?,?,?,NULL)`)
            .bind(await sha256(access), appId, userId, JSON.stringify(scopes), now + OAUTH_ACCESS_TTL_MS, now),
        db.prepare(`INSERT INTO oauth_refresh_tokens(token_hash,app_id,user_id,scopes_json,expires_at,created_at,revoked_at) VALUES(?,?,?,?,?,?,NULL)`)
            .bind(await sha256(refresh), appId, userId, JSON.stringify(scopes), now + 30 * 24 * 60 * 60 * 1000, now),
    ]);
    return { access_token: access, token_type: 'Bearer', expires_in: Math.floor(OAUTH_ACCESS_TTL_MS / 1000), refresh_token: refresh, scope: scopes.join(' ') };
}

async function oauthTokenEndpoint(request, env) {
    const body = await readOAuthBody(request);
    const app = await verifyOAuthClient(env, request, body);
    if (!app)
        return oauthError('Client authentication failed', 401, 'invalid_client');
    const grant = String(body.grant_type || '').trim();
    if (grant === 'authorization_code') {
        const rawCode = String(body.code || '').trim(), redirectUri = String(body.redirect_uri || '').trim();
        if (!rawCode || !redirectUri)
            return oauthError('code and redirect_uri are required', 400, 'invalid_request');
        const row = await env.DB.prepare(`SELECT * FROM oauth_authorization_codes WHERE code_hash=? AND app_id=? LIMIT 1`).bind(await sha256(rawCode), app.id).first();
        if (!row || row.used_at || Number(row.expires_at || 0) <= Date.now() || String(row.redirect_uri) !== redirectUri)
            return oauthError('Authorization code is invalid, expired, already used, or redirect_uri changed', 400, 'invalid_grant');
        if (row.code_challenge) {
            const verifier = String(body.code_verifier || '');
            if (!verifier || !/^[A-Za-z0-9._~-]{43,128}$/.test(verifier))
                return oauthError('A valid PKCE code_verifier is required', 400, 'invalid_grant');
            if (!timingSafeEqual(await pkceS256(verifier), String(row.code_challenge)))
                return oauthError('PKCE verification failed', 400, 'invalid_grant');
        }
        const install = await env.DB.prepare('SELECT enabled,authorized_via_oauth,oauth_scopes_json FROM account_bot_installs WHERE user_id=? AND bot_id=? LIMIT 1').bind(row.user_id, app.id).first();
        const codeScopes = parseOAuthScopes(row.scopes_json), currentScopes = new Set(parseOAuthScopes(install?.oauth_scopes_json));
        if (!install || !Number(install.enabled || 0) || !Number(install.authorized_via_oauth || 0) || codeScopes.some(scope => !currentScopes.has(scope)))
            return oauthError('The user revoked or changed this authorization', 400, 'invalid_grant');
        const used = await env.DB.prepare('UPDATE oauth_authorization_codes SET used_at=? WHERE code_hash=? AND used_at IS NULL AND expires_at>?').bind(Date.now(), row.code_hash, Date.now()).run();
        if (!Number(used.meta?.changes || 0))
            return oauthError('Authorization code was already used', 400, 'invalid_grant');
        return json(await issueOAuthTokens(env.DB, app.id, row.user_id, codeScopes));
    }
    if (grant === 'refresh_token') {
        const raw = String(body.refresh_token || '').trim();
        if (!raw)
            return oauthError('refresh_token is required', 400, 'invalid_request');
        const row = await env.DB.prepare(`SELECT * FROM oauth_refresh_tokens WHERE token_hash=? AND app_id=? AND revoked_at IS NULL LIMIT 1`).bind(await sha256(raw), app.id).first();
        if (!row || Number(row.expires_at || 0) <= Date.now())
            return oauthError('Refresh token is invalid, expired, or revoked', 400, 'invalid_grant');
        const install = await env.DB.prepare('SELECT enabled,authorized_via_oauth,oauth_scopes_json FROM account_bot_installs WHERE user_id=? AND bot_id=? LIMIT 1').bind(row.user_id, app.id).first();
        if (!install || !Number(install.enabled || 0) || !Number(install.authorized_via_oauth || 0))
            return oauthError('The user revoked this application', 400, 'invalid_grant');
        const current = new Set(parseOAuthScopes(install.oauth_scopes_json)), original = parseOAuthScopes(row.scopes_json), scopes = original.filter(scope => current.has(scope));
        if (!scopes.length)
            return oauthError('The user revoked all permissions for this application', 400, 'invalid_grant');
        await env.DB.prepare('UPDATE oauth_refresh_tokens SET revoked_at=? WHERE token_hash=? AND revoked_at IS NULL').bind(Date.now(), row.token_hash).run();
        return json(await issueOAuthTokens(env.DB, app.id, row.user_id, scopes));
    }
    return oauthError('Supported grant types are authorization_code and refresh_token', 400, 'unsupported_grant_type');
}

async function oauthRevokeEndpoint(request, env) {
    const body = await readOAuthBody(request), app = await verifyOAuthClient(env, request, body);
    if (!app)
        return oauthError('Client authentication failed', 401, 'invalid_client');
    const token = String(body.token || '').trim();
    if (!token)
        return json({ ok: true });
    const hash = await sha256(token), now = Date.now();
    await env.DB.batch([
        env.DB.prepare('UPDATE oauth_access_tokens SET revoked_at=? WHERE token_hash=? AND app_id=? AND revoked_at IS NULL').bind(now, hash, app.id),
        env.DB.prepare('UPDATE oauth_refresh_tokens SET revoked_at=? WHERE token_hash=? AND app_id=? AND revoked_at IS NULL').bind(now, hash, app.id)
    ]);
    return json({ ok: true });
}

async function revokeOAuthForAppUser(db, appId, userId) {
    const now = Date.now();
    await db.batch([
        db.prepare('UPDATE oauth_access_tokens SET revoked_at=? WHERE app_id=? AND user_id=? AND revoked_at IS NULL').bind(now, appId, userId),
        db.prepare('UPDATE oauth_refresh_tokens SET revoked_at=? WHERE app_id=? AND user_id=? AND revoked_at IS NULL').bind(now, appId, userId),
        db.prepare('DELETE FROM oauth_authorization_codes WHERE app_id=? AND user_id=?').bind(appId, userId)
    ]);
}

function oauthScopeStillGranted(install, scope) {
    if (scope === 'identify')
        return Number(install.view_profile || 0) === 1;
    if (scope === 'servers.read')
        return Number(install.servers_read || 0) === 1;
    if (scope === 'dm.send')
        return Number(install.dm_send || 0) === 1;
    if (scope === 'servers.join')
        return Number(install.join_servers || 0) === 1;
    if (scope === 'activity.write')
        return Number(install.activity_write || 0) === 1;
    if (scope === 'dm.commands')
        return Number(install.dm_commands || 0) === 1;
    return false;
}

async function requireOAuthAccessToken(request, env, requiredScope = '') {
    const auth = String(request.headers.get('Authorization') || ''), match = auth.match(/^Bearer\s+(.+)$/i);
    if (!match)
        return oauthError('OAuth Bearer token required', 401, 'invalid_token');
    const raw = String(match[1] || '').trim();
    if (!raw.startsWith('orb_oauth_'))
        return oauthError('Invalid OAuth access token', 401, 'invalid_token');
    const row = await env.DB.prepare(`SELECT t.*,u.*,b.name AS oauth_app_name,b.bot_user_id,
      i.enabled AS oauth_install_enabled,i.authorized_via_oauth,i.view_profile,i.join_servers,i.dm_commands,i.dm_send,i.servers_read,i.activity_write,i.oauth_scopes_json
    FROM oauth_access_tokens t
    JOIN users u ON u.id=t.user_id
    JOIN bot_applications b ON b.id=t.app_id
    JOIN account_bot_installs i ON i.user_id=t.user_id AND i.bot_id=t.app_id
    WHERE t.token_hash=? AND t.revoked_at IS NULL LIMIT 1`).bind(await sha256(raw)).first();
    if (!row || Number(row.expires_at || 0) <= Date.now())
        return oauthError('OAuth access token is expired or invalid', 401, 'invalid_token');
    if (!Number(row.oauth_install_enabled || 0) || !Number(row.authorized_via_oauth || 0))
        return oauthError('The user revoked this application', 401, 'invalid_token');
    if (hasActiveAccountRestriction(row))
        return oauthError('The authorized Orbyte account is currently restricted', 403, 'access_denied');
    const scopes = parseOAuthScopes(row.scopes_json);
    if (requiredScope && (!scopes.includes(requiredScope) || !oauthScopeStillGranted(row, requiredScope)))
        return oauthError(`This endpoint requires ${requiredScope}`, 403, 'insufficient_scope', { required_scope: requiredScope });
    return { app_id: row.app_id, app_name: row.oauth_app_name, bot_user_id: row.bot_user_id, user: row, scopes };
}

function oauthPublicUser(user) {
    return {
        id: String(user.id || ''), username: user.username || '', display_name: user.display_name || user.username || '',
        avatar_url: user.avatar_url || '', banner_image_url: user.banner_image_url || '', about: user.about || '',
        badges: parseJsonArray(user.badges), created_at: Number(user.created_at || 0)
    };
}

async function oauthGetMe(env, oauth) { return json({ user: oauthPublicUser(oauth.user), scope: oauth.scopes.join(' ') }); }

async function oauthListServers(env, oauth) {
    const [rows, roleRows] = await Promise.all([
        env.DB.prepare(`SELECT s.id,s.name,s.icon_url,s.banner_url,s.owner_id,sm.role AS member_role,sm.joined_at
      FROM server_members sm JOIN servers s ON s.id=sm.server_id WHERE sm.user_id=? ORDER BY sm.joined_at DESC LIMIT 250`).bind(oauth.user.id).all(),
        env.DB.prepare(`SELECT mr.server_id,r.id,r.name,r.color,r.position FROM server_member_roles mr JOIN server_roles r ON r.id=mr.role_id
      WHERE mr.user_id=? ORDER BY mr.server_id,r.position DESC LIMIT 2000`).bind(oauth.user.id).all().catch(() => ({ results: [] }))
    ]);
    const byServer = new Map();
    for (const role of roleRows.results || []) {
        const key = String(role.server_id);
        if (!byServer.has(key))
            byServer.set(key, []);
        byServer.get(key).push({ id: role.id, name: role.name, color: role.color, position: Number(role.position || 0) });
    }
    return json({ user: oauthPublicUser(oauth.user), servers: (rows.results || []).map(row => ({ ...row, roles: byServer.get(String(row.id)) || [] })) });
}

async function oauthFindOrCreateBotDm(env, oauth) {
    const userId = String(oauth.user.id), botUserId = String(oauth.bot_user_id);
    let existing = await env.DB.prepare(`SELECT d.id FROM dm_conversations d
    JOIN dm_participants a ON a.conversation_id=d.id AND a.user_id=?
    JOIN dm_participants b ON b.conversation_id=d.id AND b.user_id=?
    WHERE (SELECT COUNT(*) FROM dm_participants p WHERE p.conversation_id=d.id)=2 AND COALESCE(d.kind,'direct')='direct' LIMIT 1`)
        .bind(userId, botUserId).first();
    if (existing) {
        await reopenDmFor(env.DB, existing.id, [userId, botUserId]);
        return existing.id;
    }
    const id = prefixedId('dm'), now = Date.now(), flags = await getByteFeatureFlags(env.DB);
    if (flags.groupDms) {
        await env.DB.batch([
            env.DB.prepare("INSERT INTO dm_conversations(id,created_at,updated_at,kind,owner_id) VALUES(?,?,?,'direct',NULL)").bind(id, now, now),
            env.DB.prepare('INSERT INTO dm_participants(conversation_id,user_id,joined_at,added_by,closed_at) VALUES(?,?,?,?,NULL)').bind(id, userId, now, userId),
            env.DB.prepare('INSERT INTO dm_participants(conversation_id,user_id,joined_at,added_by,closed_at) VALUES(?,?,?,?,NULL)').bind(id, botUserId, now, userId)
        ]);
    }
    else {
        await env.DB.batch([
            env.DB.prepare('INSERT INTO dm_conversations(id,created_at,updated_at) VALUES(?,?,?)').bind(id, now, now),
            env.DB.prepare('INSERT INTO dm_participants(conversation_id,user_id,joined_at) VALUES(?,?,?)').bind(id, userId, now),
            env.DB.prepare('INSERT INTO dm_participants(conversation_id,user_id,joined_at) VALUES(?,?,?)').bind(id, botUserId, now)
        ]);
    }
    return id;
}

async function oauthSendDm(request, env, oauth) {
    const body = await readJson(request) || {}, content = cleanText(body.content || '', 2000, true).trim();
    if (!content)
        return oauthError('content is required', 400, 'invalid_request');
    const dmId = await oauthFindOrCreateBotDm(env, oauth), now = Date.now(), messageId = prefixedId('dmsg');
    const botUser = await env.DB.prepare('SELECT id,username,display_name,avatar_url FROM users WHERE id=?').bind(oauth.bot_user_id).first();
    if (!botUser)
        return oauthError('The application bot account no longer exists', 404, 'invalid_client');
    await env.DB.batch([
        env.DB.prepare('INSERT INTO dm_messages(id,conversation_id,user_id,content,created_at) VALUES(?,?,?,?,?)').bind(messageId, dmId, oauth.bot_user_id, content, now),
        env.DB.prepare('UPDATE dm_conversations SET updated_at=? WHERE id=?').bind(now, dmId),
        env.DB.prepare(`INSERT OR IGNORE INTO notifications(id,user_id,type,actor_id,dm_id,message_id,title,body,created_at) VALUES(?,?,?,?,?,?,?,?,?)`)
            .bind(prefixedId('ntf'), oauth.user.id, 'dm', oauth.bot_user_id, dmId, messageId, botUser.display_name || botUser.username || oauth.app_name, notificationBody(content), now)
    ]);
    try {
        await realtimeEmit(env, [oauth.user.id], { type: 'message.created', kind: 'dm', target_id: dmId, message: { id: messageId, conversation_id: dmId, user_id: oauth.bot_user_id, content, created_at: now, username: botUser.username, display_name: botUser.display_name, avatar_url: botUser.avatar_url || '' } });
    }
    catch { }
    return json({ ok: true, conversation_id: dmId, message: { id: messageId, content, created_at: now, author: { id: oauth.bot_user_id, username: botUser.username, display_name: botUser.display_name, avatar_url: botUser.avatar_url || '' } } }, 201);
}

async function oauthJoinServer(env, oauth, serverId) {
    if (isYoungTeen(oauth.user))
        return oauthError('Teen Safety Mode does not allow apps to join public servers for this account', 403, 'access_denied');
    if (accountHasLimit(oauth.user, 2))
        return accountLimitResponse(oauth.user, 'SERVER_ACCESS_LIMITED', 'Joining servers is temporarily limited on this account');
    const botInstalled = await env.DB.prepare('SELECT 1 FROM bot_server_installs WHERE bot_id=? AND server_id=? LIMIT 1').bind(oauth.app_id, serverId).first();
    if (!botInstalled)
        return oauthError('This app can only join you to a server where its bot is already installed', 403, 'bot_not_in_server');
    const server = await env.DB.prepare('SELECT id,name FROM servers WHERE id=? LIMIT 1').bind(serverId).first();
    if (!server)
        return oauthError('Server not found', 404, 'server_not_found');
    if (await isServerBanned(env.DB, serverId, oauth.user.id))
        return oauthError('You are banned from this server', 403, 'server_banned');
    const existing = await isServerMember(env.DB, oauth.user.id, serverId);
    if (!existing) {
        const failure = await serverJoinRequirementFailure(env.DB, oauth.user, serverId);
        if (failure)
            return json(failure, 403);
    }
    const now = Date.now();
    await env.DB.prepare("INSERT OR IGNORE INTO server_members(server_id,user_id,role,joined_at) VALUES (?,?,'member',?)").bind(serverId, oauth.user.id, now).run();
    const onboarding = await env.DB.prepare('SELECT enabled FROM server_onboarding_settings WHERE server_id=?').bind(serverId).first();
    return json({ ok: true, server: { id: server.id, name: server.name }, already_member: Boolean(existing), onboarding_required: Boolean(onboarding?.enabled && !existing) });
}

async function oauthSetActivity(request, env, oauth) {
    const body = await readJson(request) || {}, type = ACTIVITY_TYPES.has(String(body.type || '').toLowerCase()) ? String(body.type).toLowerCase() : 'playing';
    const name = cleanText(body.name || '', 64, true).replace(/[\r\n]+/g, ' ').trim();
    if (!name)
        return oauthError('Activity name is required', 400, 'invalid_request');
    const now = Date.now(), requestedStart = Number(body.started_at || now), startedAt = Number.isFinite(requestedStart) ? Math.max(now - 7 * 86400000, Math.min(now, requestedStart)) : now;
    const previous = await getActivityForUser(env.DB, oauth.user.id), same = previous && previous.type === type && previous.name === name, effectiveStart = same ? previous.started_at : startedAt;
    await env.DB.prepare(`INSERT INTO user_activities(user_id,activity_type,activity_name,started_at,updated_at,expires_at) VALUES(?,?,?,?,?,?)
    ON CONFLICT(user_id) DO UPDATE SET activity_type=excluded.activity_type,activity_name=excluded.activity_name,
    started_at=CASE WHEN user_activities.activity_type=excluded.activity_type AND user_activities.activity_name=excluded.activity_name THEN user_activities.started_at ELSE excluded.started_at END,
    updated_at=excluded.updated_at,expires_at=excluded.expires_at`).bind(oauth.user.id, type, name, effectiveStart, now, now + ACTIVITY_TTL_MS).run();
    const activity = { type, name, started_at: effectiveStart, updated_at: now, expires_at: now + ACTIVITY_TTL_MS };
    if (!same) {
        try {
            await realtimeEmit(env, await activityRealtimeAudience(env.DB, oauth.user.id), { type: 'activity.updated', user_id: oauth.user.id, activity });
        }
        catch { }
    }
    return json({ ok: true, activity });
}

async function oauthClearActivity(env, oauth) {
    const previous = await getActivityForUser(env.DB, oauth.user.id);
    await env.DB.prepare('DELETE FROM user_activities WHERE user_id=?').bind(oauth.user.id).run().catch(() => { });
    if (previous) {
        try {
            await realtimeEmit(env, await activityRealtimeAudience(env.DB, oauth.user.id), { type: 'activity.updated', user_id: oauth.user.id, activity: null });
        }
        catch { }
    }
    return json({ ok: true, activity: null });
}

async function getDeveloperOAuthConfig(env, user, botId) {
    try {
        await ensureOAuthSupportArticle(env.DB);
    }
    catch { }
    const bot = await ownedBot(env, user, botId);
    if (!bot)
        return json({ error: 'Bot not found' }, 404);
    return json({
        client_id: bot.id,
        enabled: Boolean(Number(bot.oauth_enabled || 0)),
        redirect_uris: safeJsonArray(bot.oauth_redirect_uris_json).map(String),
        allowed_scopes: parseOAuthScopes(bot.oauth_allowed_scopes_json),
        secret_configured: Boolean(bot.oauth_secret_hash),
        secret_hint: bot.oauth_secret_hint || '',
        scopes: Object.entries(OAUTH_SCOPE_DEFS).map(([scope, meta]) => ({ scope, ...meta })),
        authorize_url: 'https://orbytechat.pages.dev/oauth2/authorize',
        token_url: 'https://chat.kyrylo89.workers.dev/api/oauth2/token',
        revoke_url: 'https://chat.kyrylo89.workers.dev/api/oauth2/revoke',
        docs_url: 'https://support.orbytechat.pages.dev/articles/' + OAUTH_SUPPORT_ARTICLE_SLUG
    });
}

async function updateDeveloperOAuthConfig(request, env, user, botId) {
    const bot = await ownedBot(env, user, botId);
    if (!bot)
        return json({ error: 'Bot not found' }, 404);
    const body = await readJson(request);
    if (!body)
        return json({ error: 'Invalid JSON' }, 400);
    let redirects, scopes;
    try {
        redirects = normalizeOAuthRedirectUris(body.redirect_uris ?? safeJsonArray(bot.oauth_redirect_uris_json));
    }
    catch (error) {
        return oauthError(error.message, error.status || 400, error.code || 'invalid_redirect_uri');
    }
    const rawScopes = Array.isArray(body.allowed_scopes) ? body.allowed_scopes : parseOAuthScopes(bot.oauth_allowed_scopes_json);
    const unknown = rawScopes.map(String).filter(scope => !Object.prototype.hasOwnProperty.call(OAUTH_SCOPE_DEFS, scope));
    if (unknown.length)
        return oauthError(`Unknown scope: ${unknown[0]}`, 400, 'invalid_scope');
    scopes = normalizeOAuthScopes(rawScopes);
    const enabled = body.enabled === undefined ? Boolean(Number(bot.oauth_enabled || 0)) : Boolean(body.enabled);
    if (enabled && !redirects.length)
        return oauthError('Add at least one redirect URI before enabling OAuth', 400, 'invalid_redirect_uri');
    if (enabled && !scopes.length)
        return oauthError('Select at least one allowed scope before enabling OAuth', 400, 'invalid_scope');
    const changed = Boolean(Number(bot.oauth_enabled || 0)) !== enabled ||
        JSON.stringify(safeJsonArray(bot.oauth_redirect_uris_json).map(String)) !== JSON.stringify(redirects) ||
        JSON.stringify(parseOAuthScopes(bot.oauth_allowed_scopes_json)) !== JSON.stringify(scopes);
    const now = Date.now();
    await env.DB.prepare('UPDATE bot_applications SET oauth_enabled=?,oauth_redirect_uris_json=?,oauth_allowed_scopes_json=?,updated_at=? WHERE id=?')
        .bind(enabled ? 1 : 0, JSON.stringify(redirects), JSON.stringify(scopes), now, botId).run();
    if (changed) {
        await env.DB.batch([
            env.DB.prepare('UPDATE oauth_access_tokens SET revoked_at=? WHERE app_id=? AND revoked_at IS NULL').bind(now, botId),
            env.DB.prepare('UPDATE oauth_refresh_tokens SET revoked_at=? WHERE app_id=? AND revoked_at IS NULL').bind(now, botId),
            env.DB.prepare('DELETE FROM oauth_authorization_codes WHERE app_id=?').bind(botId)
        ]);
    }
    const response = await getDeveloperOAuthConfig(env, user, botId);
    if (!changed)
        return response;
    const data = await response.json();
    return json({ ...data, reauthorization_required: true });
}

async function resetDeveloperOAuthSecret(env, user, botId) {
    const bot = await ownedBot(env, user, botId);
    if (!bot)
        return json({ error: 'Bot not found' }, 404);
    const secret = `orb_client_${randomBase64Url(42)}`, hint = secret.slice(-8), now = Date.now();
    await env.DB.prepare('UPDATE bot_applications SET oauth_secret_hash=?,oauth_secret_hint=?,updated_at=? WHERE id=?').bind(await sha256(secret), hint, now, botId).run();
    await env.DB.batch([
        env.DB.prepare('UPDATE oauth_access_tokens SET revoked_at=? WHERE app_id=? AND revoked_at IS NULL').bind(now, botId),
        env.DB.prepare('UPDATE oauth_refresh_tokens SET revoked_at=? WHERE app_id=? AND revoked_at IS NULL').bind(now, botId),
        env.DB.prepare('DELETE FROM oauth_authorization_codes WHERE app_id=?').bind(botId)
    ]);
    return json({ ok: true, client_id: botId, client_secret: secret, secret_hint: hint, warning: 'Copy this Client Secret now. Orbyte will not show it again.' });
}
